package com.malfoid;

import java.io.IOException;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import net.runelite.client.util.Filepath;

/** Small scoped rolling log. No filesystem operations occur in the tick pipeline. */
final class SessionLog
{
    private static final long MAX_BYTES = 256 * 1024;
    private final ArrayBlockingQueue<String> pending = new ArrayBlockingQueue<>(256);
    private final Filepath file;
    private final Filepath previous;
    private final Consumer<Throwable> onFailure;
    private final ScheduledFuture<?> pump;
    private volatile boolean broken;

    SessionLog(Filepath directory, ScheduledExecutorService executor, Consumer<Throwable> onFailure)
        throws IOException
    {
        directory.createDirectories();
        this.file = directory.joinSegment("malfoid.log");
        this.previous = directory.joinSegment("malfoid.previous.log");
        this.onFailure = onFailure;
        pump = executor.scheduleWithFixedDelay(this::flush, 1, 2, TimeUnit.SECONDS);
    }

    void record(String text)
    {
        String safe = text.replace('\r', ' ').replace('\n', ' ');
        if (safe.length() > 700)
        {
            safe = safe.substring(0, 700);
        }
        String line = Instant.now() + " " + safe + "\n";
        if (!pending.offer(line))
        {
            pending.poll();
            pending.offer(line);
        }
    }

    synchronized void flush()
    {
        if (broken || pending.isEmpty())
        {
            return;
        }
        StringBuilder batch = new StringBuilder();
        String line;
        while ((line = pending.poll()) != null)
        {
            batch.append(line);
        }
        try
        {
            if (file.exists() && file.size() >= MAX_BYTES)
            {
                file.moveTo(previous, StandardCopyOption.REPLACE_EXISTING);
            }
            file.write(batch.toString(), StandardOpenOption.CREATE, StandardOpenOption.APPEND);
        }
        catch (Throwable failure)
        {
            broken = true;
            onFailure.accept(failure);
        }
    }

    void close(ScheduledExecutorService executor)
    {
        pump.cancel(false);
        executor.execute(this::flush);
    }
}

package com.malfoid.asset;

import com.malfoid.presence.OtherPlayerPolicy;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

/** Copies at most 256 active-view actor positions; incomplete samples apply no soft occupancy assumptions. */
final class ActorOccupancy
{
    static final class Snapshot
    {
        final boolean[] occupied = new boolean[169];
        final int playerX, playerY;
        int otherPlayers;
        boolean ignoresOtherPlayers;
        boolean complete = true;
        Snapshot(int playerX, int playerY) { this.playerX = playerX; this.playerY = playerY; }
        boolean occupied(int x, int y)
        {
            int dx = x - playerX + 6, dy = y - playerY + 6;
            return complete && dx >= 0 && dy >= 0 && dx < 13 && dy < 13 && occupied[dy * 13 + dx];
        }
    }

    private ActorOccupancy() {}

    static Snapshot sample(Client client, WorldView view, Player local, int x, int y)
    {
        Snapshot result = new Snapshot(x, y);
        boolean ignorePlayers = OtherPlayerPolicy.ignoreOtherPlayers(client);
        result.ignoresOtherPlayers = ignorePlayers;
        if (!ignorePlayers && view.players() == null || view.npcs() == null)
        {
            result.complete = false;
            return result;
        }
        int inspected = 0;
        if (!ignorePlayers)
        {
            for (Player player : view.players())
            {
                if (inspected++ >= 256)
                {
                    result.complete = false;
                    return result;
                }
                if (player != local && copy(player, view, result)) result.otherPlayers++;
            }
        }
        for (NPC npc : view.npcs())
        {
            if (inspected++ >= 256)
            {
                result.complete = false;
                return result;
            }
            copy(npc, view, result);
        }
        copy(client.getFollower(), view, result);
        return result;
    }

    private static boolean copy(Actor actor, WorldView view, Snapshot result)
    {
        if (actor == null) return false;
        LocalPoint point = actor.getLocalLocation();
        if (point == null)
        {
            result.complete = false;
            return false;
        }
        if (point.getWorldView() != view.getId()) return false;
        int dx = point.getSceneX() - result.playerX + 6, dy = point.getSceneY() - result.playerY + 6;
        if (dx < 0 || dy < 0 || dx >= 13 || dy >= 13) return false;
        result.occupied[dy * 13 + dx] = true;
        return true;
    }
}

package com.malfoid.asset;

import java.awt.Shape;
import java.awt.geom.Area;
import java.awt.Rectangle;
import net.runelite.api.Client;
import net.runelite.api.Perspective;

/** The pinned public NPC clickbox recipe, called only on a right-click menu opening. */
final class ClickboxAdapter
{
    private ClickboxAdapter() {}

    static Shape get(Client client, NativeActor.PlacementSnapshot placement)
    {
        if (placement == null)
        {
            return null;
        }
        Shape box = Perspective.getClickbox(client, placement.getWorldView(), placement.getModel(), placement.getOrientation(),
            placement.getLocation().getX(), placement.getLocation().getY(), placement.getDrawZ());
        if (box == null)
        {
            return null;
        }
        Area clipped = new Area(box);
        clipped.intersect(new Area(new Rectangle(client.getViewportXOffset(), client.getViewportYOffset(),
            client.getViewportWidth(), client.getViewportHeight())));
        return clipped.isEmpty() ? null : clipped;
    }
}

