package com.malfoid.asset;

import com.google.gson.Gson;
import com.malfoid.motion.WholeBoundsVisibility;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.security.DigestInputStream;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.zip.GZIPInputStream;

/** The approved, immutable offline bake; no authoring files are read at runtime. */
final class NativeAsset
{
    static final String RESOURCE = "/com/malfoid/model/Malfoid.native.json.gz";
    static final String SHA256 = "fba96d4078af689be666edfe7e7c87f4cbc4c6472048b80c88b264e052dfc12f";
    static final int MAX_SAMPLES = 204;
    final int vertexCount;
    final int triangleCount;
    final float feetOffsetModelUnits;
    final float[] baseVertices;
    final int[] faces;
    final int[] faceHsl;
    final int[] faceShadeModes;
    final byte[] facePriorities;
    final Map<String, Clip> clips;
    final WholeBoundsVisibility.Bounds unionBounds;

    static final class Clip
    {
        final int samplePeriodClientCycles;
        final int durationClientCycles;
        final boolean loop;
        final float[][] samples;

        private Clip(ClipData source)
        {
            samplePeriodClientCycles = source.samplePeriodClientCycles;
            durationClientCycles = source.durationClientCycles;
            loop = source.loop;
            samples = source.samples;
        }
    }

    private static final class ClipData
    {
        int samplePeriodClientCycles;
        int durationClientCycles;
        boolean loop;
        float[][] samples;
    }

    private static final class Data
    {
        int schemaVersion;
        String assetRevision;
        int vertexCount;
        int triangleCount;
        float feetOffsetModelUnits;
        float[] baseVertices;
        int[] faces;
        int[] faceHsl;
        int[] faceShadeModes;
        byte[] facePriorities;
        Map<String, ClipData> clips;
    }

    private NativeAsset(Data data)
    {
        require(data != null && data.schemaVersion == 1
            && ("claude07".equals(data.assetRevision) || "claude08".equals(data.assetRevision) || "claude09".equals(data.assetRevision)
                || "claude10".equals(data.assetRevision)), "asset identity");
        require(data.vertexCount == 716 && data.triangleCount == 1100, "asset counts");
        vertexCount = data.vertexCount;
        triangleCount = data.triangleCount;
        require(Float.isFinite(data.feetOffsetModelUnits) && Math.abs(data.feetOffsetModelUnits) <= 16, "feet offset");
        feetOffsetModelUnits = data.feetOffsetModelUnits;
        require(data.faces != null && data.faces.length == triangleCount * 3, "face indices length");
        require(data.faceHsl != null && data.faceHsl.length == triangleCount, "face HSL length");
        require(data.faceShadeModes != null && data.faceShadeModes.length == triangleCount, "shade mask length");
        require(data.facePriorities != null && data.facePriorities.length == triangleCount, "priorities length");
        faces = data.faces;
        faceHsl = data.faceHsl;
        faceShadeModes = data.faceShadeModes;
        facePriorities = data.facePriorities;
        boolean[] used = new boolean[vertexCount];
        int smooth = 0;
        for (int i = 0; i < triangleCount; i++)
        {
            for (int j = 0; j < 3; j++)
            {
                int vertex = faces[i * 3 + j];
                require(vertex >= 0 && vertex < vertexCount, "face index range");
                used[vertex] = true;
            }
            require(faceHsl[i] >= 0 && faceHsl[i] <= 65535, "HSL range");
            require(faceShadeModes[i] == 0 || faceShadeModes[i] == 1, "shade mode");
            require(facePriorities[i] == 0, "claude07 face priority");
            smooth += faceShadeModes[i];
        }
        require(smooth == 437, "claude07 shading identity");
        for (boolean present : used)
        {
            require(present, "unused vertex");
        }
        baseVertices = data.baseVertices;
        validatePose(baseVertices);
        // Three clips; or those and the two of Addendum G; or those five and the five emotes of her own (H.6).
        require(data.clips != null && (data.clips.size() == 3 || data.clips.size() == 5 || data.clips.size() == 10), "clip set");
        Map<String, Clip> loaded = new LinkedHashMap<>();
        int samples = 0;
        String[] names = data.clips.size() == 3 ? new String[]{"IDLE", "WALK", "RUN"}
            : data.clips.size() == 5 ? new String[]{"IDLE", "WALK", "RUN", "CROSS_ARMS", "IMPATIENT"}
            : new String[]{"IDLE", "WALK", "RUN", "CROSS_ARMS", "IMPATIENT", "COWER", "PEER", "HANDS_ON_HIPS", "HAIR_FLICK", "STOMP"};
        for (String name : names)
        {
            ClipData clip = data.clips.get(name);
            require(clip != null && clip.samples != null && clip.samples.length > 0, "missing " + name);
            GesturePlayback.Gesture gesture = null;
            for (GesturePlayback.Gesture known : GesturePlayback.Gesture.values()) { if (known.clip.equals(name)) { gesture = known; } }
            require(clip.samplePeriodClientCycles == 2 && clip.durationClientCycles == 2 * clip.samples.length
                && clip.loop == !("CROSS_ARMS".equals(name) || gesture != null),
                "clip timing " + name);
            int expected = gesture != null ? gesture.samples
                : "IDLE".equals(name) ? 50 : "WALK".equals(name) ? 30 : "CROSS_ARMS".equals(name) ? 10 : 20;
            require(clip.samples.length == expected, "clip samples " + name);
            for (float[] pose : clip.samples)
            {
                validatePose(pose);
            }
            samples += clip.samples.length;
            loaded.put(name, new Clip(clip));
        }
        // 1.25 MiB while there were at most 130 samples; 2 MiB since the emotes of her own (H.6).
        require(samples <= MAX_SAMPLES && 12L * vertexCount * (1L + samples) <= 2097152L, "pose payload budget");
        clips = Collections.unmodifiableMap(loaded);
        double[] minimum = {Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY};
        double[] maximum = {Double.NEGATIVE_INFINITY, Double.NEGATIVE_INFINITY, Double.NEGATIVE_INFINITY};
        accumulateBounds(baseVertices, minimum, maximum);
        for (Clip clip : clips.values())
        {
            for (float[] pose : clip.samples) accumulateBounds(pose, minimum, maximum);
        }
        unionBounds = new WholeBoundsVisibility.Bounds(minimum[0] - 2, minimum[1] - 2, minimum[2] - 2,
            maximum[0] + 2, maximum[1] + 2, maximum[2] + 2);
    }

    static NativeAsset load(Gson gson) throws IOException
    {
        try
        {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            Data data;
            InputStream resource = NativeAsset.class.getResourceAsStream(RESOURCE);
            if (resource == null)
            {
                throw new IOException("Missing bundled Malfoid model");
            }
            try (DigestInputStream compressed = new DigestInputStream(resource, digest);
                 InputStreamReader reader = new InputStreamReader(new GZIPInputStream(compressed), StandardCharsets.UTF_8))
            {
                data = gson.fromJson(reader, Data.class);
                while (reader.read() != -1)
                {
                    // Consume the gzip trailer before checking the compressed resource hash.
                }
            }
            StringBuilder hash = new StringBuilder(64);
            for (byte value : digest.digest())
            {
                hash.append(String.format("%02x", value & 255));
            }
            require(SHA256.contentEquals(hash), "bundled model SHA-256");
            return new NativeAsset(data);
        }
        catch (NoSuchAlgorithmException ex)
        {
            throw new IOException(ex);
        }
    }

    /** Validate a supplied bake for offline acceptance; runtime loading remains hash-pinned above. */
    static NativeAsset decode(Gson gson, Reader reader)
    {
        return new NativeAsset(gson.fromJson(reader, Data.class));
    }

    private void validatePose(float[] pose)
    {
        require(pose != null && pose.length == vertexCount * 3, "pose coordinates length");
        for (float coordinate : pose)
        {
            require(Float.isFinite(coordinate) && Math.abs(coordinate) <= 512, "pose coordinate range");
        }
        for (int i = 0; i < triangleCount; i++)
        {
            int a = faces[i * 3] * 3, b = faces[i * 3 + 1] * 3, c = faces[i * 3 + 2] * 3;
            double ux = pose[b] - pose[a], uy = pose[b + 1] - pose[a + 1], uz = pose[b + 2] - pose[a + 2];
            double vx = pose[c] - pose[a], vy = pose[c + 1] - pose[a + 1], vz = pose[c + 2] - pose[a + 2];
            double nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
            require(nx * nx + ny * ny + nz * nz > 1.0e-12, "collapsed pose triangle");
        }
    }

    private static void accumulateBounds(float[] pose, double[] minimum, double[] maximum)
    {
        for (int i = 0; i < pose.length; i++)
        {
            int axis = i % 3;
            minimum[axis] = Math.min(minimum[axis], pose[i]);
            maximum[axis] = Math.max(maximum[axis], pose[i]);
        }
    }

    private static void require(boolean condition, String field)
    {
        if (!condition)
        {
            throw new IllegalArgumentException("Invalid Malfoid " + field);
        }
    }
}

package com.malfoid.asset;

import com.malfoid.motion.WholeBoundsVisibility;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;

/** A finite, client-thread-only preparation pump using public native model APIs. */
final class NativePoseBank
{
    private static final long DONOR_TIMEOUT_NANOS = 15_000_000_000L;
    private final Client client;
    private final NativeAsset asset;
    private final int heightPercent;
    private final float heightScale;
    private final WholeBoundsVisibility.Bounds bounds;
    private final List<ModelData> primitives = new ArrayList<>();
    private final List<ModelData> groups = new ArrayList<>();
    private final List<float[]> samples = new ArrayList<>();
    private final Model[] models;
    private ModelData basic, priority, transparent, padding, template;
    private boolean compacted, initialized;
    private int primitiveIndex, groupCursor, poseIndex;
    private int lastCycle = Integer.MIN_VALUE;
    private long started, readyAt;
    private long maxChunkNanos;
    private long[] donorHashes;
    private byte[] sharedPriorities;

    NativePoseBank(Client client, NativeAsset asset)
    {
        this(client, asset, 100);
    }

    NativePoseBank(Client client, NativeAsset asset, int heightPercent)
    {
        require(heightPercent >= 90 && heightPercent <= 110, "Height setting range");
        this.client = client;
        this.asset = asset;
        this.heightPercent = heightPercent;
        heightScale = heightPercent / 100f;
        WholeBoundsVisibility.Bounds original = asset.unionBounds;
        bounds = heightPercent == 100 ? original : new WholeBoundsVisibility.Bounds(
            original.minX * heightScale, 6 + (original.minY - 6) * heightScale, original.minZ * heightScale,
            original.maxX * heightScale, 6 + (original.maxY - 6) * heightScale, original.maxZ * heightScale);
        samples.add(asset.baseVertices);
        for (NativeAsset.Clip clip : asset.clips.values())
        {
            samples.addAll(Arrays.asList(clip.samples));
        }
        models = new Model[samples.size()];
    }

    void advance(int cycle)
    {
        if (lastCycle == cycle || isReady())
        {
            return;
        }
        lastCycle = cycle;
        long begin = System.nanoTime();
        if (started == 0)
        {
            started = begin;
        }
        try
        {
            prepareChunk(begin);
        }
        finally
        {
            maxChunkNanos = Math.max(maxChunkNanos, System.nanoTime() - begin);
        }
    }

    private void prepareChunk(long now)
    {
        if (basic == null)
        {
            ModelData b = client.loadModelData(823), p = client.loadModelData(6733), t = client.loadModelData(18871);
            if (b == null || p == null || t == null)
            {
                if (now - started >= DONOR_TIMEOUT_NANOS)
                {
                    throw new IllegalStateException("Malfoid native model donors unavailable after 15 seconds");
                }
                return;
            }
            require(b.getVerticesCount() == 3 && b.getFaceCount() == 1 && p.getVerticesCount() == 6
                && p.getFaceCount() == 2 && t.getVerticesCount() == 3 && t.getFaceCount() == 1, "cache donor counts");
            basic = b;
            priority = p;
            transparent = t;
            donorHashes = new long[]{fingerprint(b), fingerprint(p), fingerprint(t)};
            return;
        }
        int primitiveCount = asset.triangleCount - 1;
        if (primitiveIndex < primitiveCount)
        {
            int limit = padding == null ? 16 : 256;
            for (int i = 0; i < limit && primitiveIndex < primitiveCount; i++, primitiveIndex++)
            {
                primitives.add(primitive(primitiveIndex));
            }
            return;
        }
        if (groupCursor < primitives.size())
        {
            int end = Math.min(primitives.size(), groupCursor + 48);
            groups.add(client.mergeModels(primitives.subList(groupCursor, end).toArray(new ModelData[0])));
            groupCursor = end;
            return;
        }
        if (template == null)
        {
            template = client.mergeModels(groups.toArray(new ModelData[0]));
            requireCounts(template);
            for (ModelData donor : new ModelData[]{basic, priority, transparent})
            {
                require(template.getFaceIndices1() != donor.getFaceIndices1()
                    && template.getFaceIndices2() != donor.getFaceIndices2()
                    && template.getFaceIndices3() != donor.getFaceIndices3(), "template topology ownership");
                require(template.getFaceColors() != donor.getFaceColors()
                    && (template.getFaceTransparencies() == null || template.getFaceTransparencies() != donor.getFaceTransparencies())
                    && (template.getFaceTextures() == null || template.getFaceTextures() != donor.getFaceTextures()),
                    "template appearance ownership");
            }
            groups.clear();
            primitives.clear();
            return;
        }
        if (!compacted)
        {
            // Compact only allocator geometry. Merging authored coincident vertices would reindex the face order.
            template = client.mergeModels(new ModelData[]{template});
            requireCounts(template);
            require(template.getVerticesX().length == asset.vertexCount, "template coordinate capacity");
            compacted = true;
            return;
        }
        if (!initialized)
        {
            for (int i = 0; i < asset.triangleCount; i++)
            {
                template.getFaceIndices1()[i] = asset.faces[i * 3];
                template.getFaceIndices2()[i] = asset.faces[i * 3 + 1];
                template.getFaceIndices3()[i] = asset.faces[i * 3 + 2];
                template.getFaceColors()[i] = (short) asset.faceHsl[i];
            }
            if (template.getFaceTextures() != null)
            {
                Arrays.fill(template.getFaceTextures(), (short) -1);
            }
            if (template.getFaceTransparencies() != null)
            {
                Arrays.fill(template.getFaceTransparencies(), (byte) 0);
            }
            initialized = true;
            return;
        }
        models[poseIndex] = importPose(samples.get(poseIndex));
        poseIndex++;
        if (poseIndex == models.length)
        {
            require(fingerprint(basic) == donorHashes[0] && fingerprint(priority) == donorHashes[1]
                && fingerprint(transparent) == donorHashes[2], "unchanged cache donors");
            readyAt = System.nanoTime();
            // Native models retain only the finite immutable arrays they use.
            basic = priority = transparent = padding = template = null;
            samples.clear();
        }
    }

    private ModelData primitive(int index)
    {
        boolean triple = (asset.vertexCount - 3) % 2 != 0;
        int pairStart = triple ? 3 : 2;
        int pairEnd = pairStart + (asset.vertexCount - 3 - (triple ? 3 : 0)) / 2;
        if (index >= pairEnd && padding != null)
        {
            return padding;
        }
        ModelData source = index == 0 ? priority : index == 1 ? transparent : basic;
        ModelData result = source.shallowCopy().cloneVertices();
        float[] x = result.getVerticesX(), y = result.getVerticesY(), z = result.getVerticesZ();
        for (int i = 0; i < x.length; i++)
        {
            int anchor = i % 3;
            x[i] = anchor == 2 ? 1 : 0;
            y[i] = 0;
            z[i] = anchor == 1 ? 1 : 0;
        }
        if (triple && index == 2)
        {
            for (int i = 0; i < 3; i++)
            {
                x[i] = 2;
                y[i] = i;
                z[i] = 2;
            }
        }
        else if (index >= pairStart && index < pairEnd)
        {
            x[1] = x[2] = index + 1;
            y[1] = 1;
            y[2] = 2;
            z[1] = z[2] = 2;
        }
        if (index >= pairEnd)
        {
            padding = result;
        }
        return result;
    }

    private Model importPose(float[] coordinates)
    {
        ModelData data = template.shallowCopy().cloneVertices();
        requireCounts(data);
        require(data.getVerticesX() != template.getVerticesX() && data.getVerticesY() != template.getVerticesY()
            && data.getVerticesZ() != template.getVerticesZ(), "independent pose vertices");
        for (int i = 0; i < asset.vertexCount; i++)
        {
            data.getVerticesX()[i] = scaledCoordinate(coordinates[i * 3], false);
            data.getVerticesY()[i] = scaledCoordinate(coordinates[i * 3 + 1], true);
            data.getVerticesZ()[i] = scaledCoordinate(coordinates[i * 3 + 2], false);
        }
        Model model = data.light(64, 850, -30, -50, -30);
        require(model != null && model.getVerticesCount() == asset.vertexCount && model.getFaceCount() == asset.triangleCount,
            "lit model counts");
        for (int i = 0; i < asset.vertexCount; i++)
        {
            require(model.getVerticesX()[i] == scaledCoordinate(coordinates[i * 3], false)
                && model.getVerticesY()[i] == scaledCoordinate(coordinates[i * 3 + 1], true)
                && model.getVerticesZ()[i] == scaledCoordinate(coordinates[i * 3 + 2], false), "native float coordinates");
        }
        for (int i = 0; i < asset.triangleCount; i++)
        {
            require(model.getFaceIndices1()[i] == asset.faces[i * 3] && model.getFaceIndices2()[i] == asset.faces[i * 3 + 1]
                && model.getFaceIndices3()[i] == asset.faces[i * 3 + 2], "native face order");
        }
        require(model.getFaceColors1() != null && model.getFaceColors2() != null && model.getFaceColors3() != null
            && model.getFaceColors1().length >= asset.triangleCount && model.getFaceColors2().length >= asset.triangleCount
            && model.getFaceColors3().length >= asset.triangleCount, "lit color arrays");
        byte[] priorities = model.getFaceRenderPriorities();
        require(priorities != null && priorities.length >= asset.triangleCount, "native priority array");
        if (sharedPriorities == null)
        {
            System.arraycopy(asset.facePriorities, 0, priorities, 0, asset.triangleCount);
            sharedPriorities = priorities;
        }
        require(priorities == sharedPriorities && Arrays.equals(priorities, asset.facePriorities), "immutable priorities");
        for (int i = 0; i < poseIndex; i++)
        {
            Model prior = models[i];
            require(prior.getVerticesX() != model.getVerticesX() && prior.getVerticesY() != model.getVerticesY()
                && prior.getVerticesZ() != model.getVerticesZ(), "pose isolation");
            require(prior.getFaceColors1() != model.getFaceColors1() && prior.getFaceColors2() != model.getFaceColors2()
                && prior.getFaceColors3() != model.getFaceColors3(), "pose color isolation");
            if (model.getVertexNormalsX() != null && prior.getVertexNormalsX() != null)
            {
                require(prior.getVertexNormalsX() != model.getVertexNormalsX()
                    && prior.getVertexNormalsY() != model.getVertexNormalsY()
                    && prior.getVertexNormalsZ() != model.getVertexNormalsZ(), "pose normal isolation");
            }
        }
        rewriteShading(model);
        int smoothFaces = 0;
        for (int face = 0; face < asset.triangleCount; face++)
        {
            require(model.getFaceColors1()[face] >= 2 && model.getFaceColors1()[face] <= 65535
                && model.getFaceColors2()[face] >= 2 && model.getFaceColors2()[face] <= 65535, "native lit color range");
            if (asset.faceShadeModes[face] == 1)
            {
                smoothFaces++;
                require(model.getFaceColors3()[face] >= 2 && model.getFaceColors3()[face] <= 65535, "smooth face sentinel");
            }
            else
            {
                require(model.getFaceColors3()[face] == -1 && model.getFaceColors1()[face] == model.getFaceColors2()[face],
                    "flat face sentinel");
            }
        }
        require(smoothFaces == 437, "approved smooth face count");
        model.calculateBoundsCylinder();
        return model;
    }

    private void rewriteShading(Model model)
    {
        float[] x = model.getVerticesX(), y = model.getVerticesY(), z = model.getVerticesZ();
        int[] a = model.getFaceIndices1(), b = model.getFaceIndices2(), c = model.getFaceIndices3();
        double[] nx = new double[asset.vertexCount], ny = new double[asset.vertexCount], nz = new double[asset.vertexCount];
        int[] count = new int[asset.vertexCount];
        for (int face = 0; face < asset.triangleCount; face++)
        {
            if (asset.faceShadeModes[face] == 0)
            {
                continue;
            }
            int va = a[face], vb = b[face], vc = c[face];
            double ux = x[vb] - x[va], uy = y[vb] - y[va], uz = z[vb] - z[va];
            double vx = x[vc] - x[va], vy = y[vc] - y[va], vz = z[vc] - z[va];
            double fx = uy * vz - uz * vy, fy = uz * vx - ux * vz, fz = ux * vy - uy * vx;
            double scale = 256 / Math.sqrt(fx * fx + fy * fy + fz * fz);
            nx[va] += fx * scale; nx[vb] += fx * scale; nx[vc] += fx * scale;
            ny[va] += fy * scale; ny[vb] += fy * scale; ny[vc] += fy * scale;
            nz[va] += fz * scale; nz[vb] += fz * scale; nz[vc] += fz * scale;
            count[va]++; count[vb]++; count[vc]++;
        }
        for (int face = 0; face < asset.triangleCount; face++)
        {
            int va = a[face], vb = b[face], vc = c[face];
            int hsl = asset.faceHsl[face];
            if (asset.faceShadeModes[face] == 1)
            {
                model.getFaceColors1()[face] = shade(hsl, 64 + (-30 * nx[va] - 50 * ny[va] - 30 * nz[va]) / (215 * count[va]));
                model.getFaceColors2()[face] = shade(hsl, 64 + (-30 * nx[vb] - 50 * ny[vb] - 30 * nz[vb]) / (215 * count[vb]));
                model.getFaceColors3()[face] = shade(hsl, 64 + (-30 * nx[vc] - 50 * ny[vc] - 30 * nz[vc]) / (215 * count[vc]));
            }
            else
            {
                double ux = x[vb] - x[va], uy = y[vb] - y[va], uz = z[vb] - z[va];
                double vx = x[vc] - x[va], vy = y[vc] - y[va], vz = z[vc] - z[va];
                double fx = uy * vz - uz * vy, fy = uz * vx - ux * vz, fz = ux * vy - uy * vx;
                double brightness = 64 + (-30 * fx - 50 * fy - 30 * fz) * 256 / (322 * Math.sqrt(fx * fx + fy * fy + fz * fz));
                int color = shade(hsl, brightness);
                model.getFaceColors1()[face] = model.getFaceColors2()[face] = color;
                model.getFaceColors3()[face] = -1;
            }
        }
    }

    private static int shade(int hsl, double brightness)
    {
        return (hsl & 65408) | Math.max(2, Math.min(126, (int) ((hsl & 127) * brightness / 128)));
    }

    private float scaledCoordinate(float coordinate, boolean vertical)
    {
        if (heightPercent == 100)
        {
            return coordinate;
        }
        return vertical ? 6 + (coordinate - 6) * heightScale : coordinate * heightScale;
    }

    Model pose(String name, int cycle)
    {
        NativeAsset.Clip clip = asset.clips.get(name);
        int offset = 1;
        for (String clipName : asset.clips.keySet())
        {
            if (clipName.equals(name))
            {
                break;
            }
            offset += asset.clips.get(clipName).samples.length;
        }
        int phase = clip.loop ? Math.floorMod(cycle, clip.durationClientCycles)
            : Math.max(0, Math.min(cycle, clip.durationClientCycles - 1));
        return models[offset + phase / clip.samplePeriodClientCycles];
    }

    boolean isReady() { return readyAt != 0; }
    int heightPercent() { return heightPercent; }
    WholeBoundsVisibility.Bounds bounds() { return bounds; }
    Model preparedModel(int index) { return index >= 0 && index < poseIndex ? models[index] : null; }
    int preparedCount() { return poseIndex; }
    int poseCount() { return models.length - 1; }
    double maxChunkMillis() { return maxChunkNanos / 1_000_000d; }
    double readyMillis() { return readyAt == 0 ? 0 : (readyAt - started) / 1_000_000d; }

    private void requireCounts(ModelData model)
    {
        require(model != null && model.getVerticesCount() == asset.vertexCount && model.getFaceCount() == asset.triangleCount,
            "native allocation counts");
    }

    private static long fingerprint(ModelData model)
    {
        long hash = Arrays.hashCode(model.getVerticesX());
        hash = hash * 31 + Arrays.hashCode(model.getVerticesY());
        hash = hash * 31 + Arrays.hashCode(model.getVerticesZ());
        hash = hash * 31 + Arrays.hashCode(model.getFaceIndices1());
        hash = hash * 31 + Arrays.hashCode(model.getFaceIndices2());
        hash = hash * 31 + Arrays.hashCode(model.getFaceIndices3());
        hash = hash * 31 + Arrays.hashCode(model.getFaceColors());
        hash = hash * 31 + Arrays.hashCode(model.getFaceTextures());
        return hash * 31 + Arrays.hashCode(model.getFaceTransparencies());
    }

    private static void require(boolean condition, String reason)
    {
        if (!condition)
        {
            throw new IllegalStateException("Malfoid " + reason + " verification failed");
        }
    }
}

package com.malfoid.asset;

/** Pure playback of the authored clips, with no pose interpolation or facing changes. */
public final class PosturePlayback
{
    public enum Posture { STANDING, ARMS_FOLDED, IMPATIENT }
    private enum Phase { STANDING, FOLDING, FOLDED, IMPATIENT, UNFOLDING }

    private final boolean emotes;
    private Posture requested = Posture.STANDING;
    private Phase phase = Phase.STANDING;
    private int phaseCycle, lastCycle = Integer.MIN_VALUE, transitionSample;
    private int loopReleaseCycle = Integer.MIN_VALUE;
    private String clip = "IDLE";
    private int sample;
    private boolean moving, running, loopStarted, impatientEnded;
    private int loopStartCycle = Integer.MIN_VALUE, impatientEndCycle = Integer.MIN_VALUE;

    public PosturePlayback(boolean emotes)
    {
        this.emotes = emotes;
    }

    public void request(Posture posture, int clientCycle)
    {
        advance(clientCycle, moving, running);
        if (!emotes || moving) return;
        requested = posture;
        if (phase == Phase.IMPATIENT)
        {
            int elapsed = Math.max(0, clientCycle - phaseCycle);
            loopReleaseCycle = posture == Posture.IMPATIENT ? Integer.MIN_VALUE
                : phaseCycle + Math.max(1, (elapsed + 39) / 40) * 40;
        }
        if (phase == Phase.STANDING && posture != Posture.STANDING)
        {
            begin(Phase.FOLDING, clientCycle, 0);
        }
        else if (phase == Phase.FOLDING && posture == Posture.STANDING)
        {
            begin(Phase.UNFOLDING, clientCycle, sample);
        }
        else if (phase == Phase.UNFOLDING && posture != Posture.STANDING)
        {
            begin(Phase.FOLDING, clientCycle, sample);
        }
        else if (phase == Phase.FOLDED)
        {
            if (posture == Posture.STANDING) begin(Phase.UNFOLDING, clientCycle, 9);
            else if (posture == Posture.IMPATIENT) beginLoop(clientCycle);
        }
        advance(clientCycle, moving, running);
    }

    /** Standing releases leave the loop at its next boundary; locomotion cuts in advance(). */
    public void endImpatient(int clientCycle)
    {
        advance(clientCycle, moving, running);
        if (requested != Posture.IMPATIENT && phase != Phase.IMPATIENT) return;
        if (phase == Phase.FOLDING)
        {
            endLoop(clientCycle);
        }
        request(Posture.STANDING, clientCycle);
    }

    public void advance(int clientCycle, boolean moving, boolean running)
    {
        if (lastCycle == Integer.MIN_VALUE) phaseCycle = clientCycle;
        lastCycle = clientCycle;
        boolean changedMotion = this.moving != moving || moving && this.running != running;
        this.moving = moving;
        this.running = running;
        if (moving)
        {
            if (phase == Phase.IMPATIENT || requested == Posture.IMPATIENT) endLoop(clientCycle);
            requested = Posture.STANDING;
            phase = Phase.STANDING;
            if (changedMotion) phaseCycle = clientCycle;
            select(clientCycle);
            return;
        }
        if (changedMotion) phaseCycle = clientCycle;
        int elapsed = Math.max(0, clientCycle - phaseCycle);
        if (phase == Phase.FOLDING && elapsed >= (10 - transitionSample) * 2)
        {
            int finished = phaseCycle + (10 - transitionSample) * 2;
            if (requested == Posture.IMPATIENT) beginLoop(clientCycle);
            else begin(Phase.FOLDED, finished, 9);
        }
        if (phase == Phase.IMPATIENT && requested != Posture.IMPATIENT
            && loopReleaseCycle != Integer.MIN_VALUE && clientCycle >= loopReleaseCycle)
        {
            endLoop(loopReleaseCycle);
            begin(requested == Posture.STANDING ? Phase.UNFOLDING : Phase.FOLDED, loopReleaseCycle, 9);
        }
        if (phase == Phase.UNFOLDING && clientCycle - phaseCycle >= (transitionSample + 1) * 2)
        {
            begin(Phase.STANDING, phaseCycle + (transitionSample + 1) * 2, 0);
        }
        select(clientCycle);
    }

    public void reset(int clientCycle)
    {
        requested = Posture.STANDING;
        phase = Phase.STANDING;
        phaseCycle = lastCycle = clientCycle;
        transitionSample = sample = 0;
        moving = running = loopStarted = impatientEnded = false;
        loopReleaseCycle = Integer.MIN_VALUE;
        clip = "IDLE";
    }

    public String getClip() { return clip; }
    public int getSample() { return sample; }
    public Posture getPosture()
    {
        return phase == Phase.IMPATIENT ? Posture.IMPATIENT
            : phase == Phase.FOLDED || phase == Phase.UNFOLDING ? Posture.ARMS_FOLDED : Posture.STANDING;
    }
    public boolean isTransitioning() { return phase == Phase.FOLDING || phase == Phase.UNFOLDING; }
    public int getImpatientLoopStartCycle() { return loopStartCycle; }
    public int getImpatientEndCycle() { return impatientEndCycle; }
    public boolean consumeImpatientLoopStart()
    {
        boolean value = loopStarted; loopStarted = false; return value;
    }
    public boolean consumeImpatientEnd()
    {
        boolean value = impatientEnded; impatientEnded = false; return value;
    }

    private void begin(Phase next, int clientCycle, int firstSample)
    {
        phase = next;
        phaseCycle = clientCycle;
        transitionSample = firstSample;
        loopReleaseCycle = Integer.MIN_VALUE;
    }

    private void beginLoop(int clientCycle)
    {
        begin(Phase.IMPATIENT, clientCycle, 0);
        loopStarted = true;
        loopStartCycle = clientCycle;
    }

    private void endLoop(int clientCycle)
    {
        impatientEnded = true;
        impatientEndCycle = clientCycle;
    }

    private void select(int clientCycle)
    {
        int elapsed = Math.max(0, clientCycle - phaseCycle);
        if (moving)
        {
            clip = running ? "RUN" : "WALK";
            sample = elapsed / 2 % (running ? 20 : 30);
        }
        else if (phase == Phase.FOLDING || phase == Phase.UNFOLDING || phase == Phase.FOLDED)
        {
            clip = "CROSS_ARMS";
            sample = phase == Phase.FOLDED ? 9 : phase == Phase.FOLDING
                ? Math.min(9, transitionSample + elapsed / 2) : Math.max(0, transitionSample - elapsed / 2);
        }
        else
        {
            clip = phase == Phase.IMPATIENT ? "IMPATIENT" : "IDLE";
            sample = elapsed / 2 % (phase == Phase.IMPATIENT ? 20 : 50);
        }
    }
}

package com.malfoid.asset;

import com.malfoid.motion.WholeBoundsVisibility;
import net.runelite.api.Client;

/** Camera-space math follows the public stock Perspective CPU/GPU projection convention. */
final class WholeBoundsAdapter
{
    private WholeBoundsAdapter() {}

    static WholeBoundsVisibility.Visibility classify(Client client, NativeActor.PlacementSnapshot placement,
        WholeBoundsVisibility.Bounds bounds)
    {
        if (placement == null || !placement.getWorldView().isTopLevel())
        {
            // Moving subviews remain absent until their separate native placement/projection gate passes.
            return WholeBoundsVisibility.Visibility.UNKNOWN;
        }
        boolean gpu = client.isGpu();
        double cameraX = gpu ? client.getCameraFpX() : client.getCameraX();
        double cameraY = gpu ? client.getCameraFpY() : client.getCameraY();
        double cameraZ = gpu ? client.getCameraFpZ() : client.getCameraZ();
        double yaw = gpu ? client.getCameraFpYaw() : client.getCameraYaw() * Math.PI / 1024;
        double pitch = gpu ? client.getCameraFpPitch() : client.getCameraPitch() * Math.PI / 1024;
        if (!Double.isFinite(cameraX) || !Double.isFinite(cameraY) || !Double.isFinite(cameraZ)
            || !Double.isFinite(yaw) || !Double.isFinite(pitch) || Math.abs(cameraX) > 65536
            || Math.abs(cameraY) > 65536 || Math.abs(cameraZ) > 65536)
        {
            return WholeBoundsVisibility.Visibility.UNKNOWN;
        }
        double yawSin = Math.sin(yaw), yawCos = Math.cos(yaw), pitchSin = Math.sin(pitch), pitchCos = Math.cos(pitch);
        WholeBoundsVisibility.Projector projector = (x, y, z, output) ->
        {
            double fx = x - cameraX, fy = y - cameraY, fz = z - cameraZ;
            double side = fx * yawCos + fy * yawSin;
            double forward = fy * yawCos - fx * yawSin;
            output[0] = side;
            output[1] = fz * pitchCos - forward * pitchSin;
            output[2] = forward * pitchCos + fz * pitchSin;
            return true;
        };
        return WholeBoundsVisibility.classify(bounds, placement.getLocation().getX(), placement.getLocation().getY(),
            placement.getDrawZ(), placement.getOrientation(), projector, client.getViewportXOffset(), client.getViewportYOffset(),
            client.getViewportWidth(), client.getViewportHeight(), client.getScale());
    }
}

package com.malfoid.dialogue;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.malfoid.speech.SceneCandidate;
