/** An indexed literal catalogue. Contract prose and authoring flags are never executed. */
public final class DialogueCatalog
{
    private static final Set<String> EXCLUDED = new HashSet<>(Arrays.asList(
        "M04-04", "M05-01", "M05-02", "M06-03", "M08-01", "M09-01", "M09-02", "M09-03", "M09-04", "M10-04", "M59-G04"));
    private static final Set<String> OUTFIT_SCENARIOS = new HashSet<>(Arrays.asList("M09", "M32", "M33", "M34"));
    private final Map<String, List<DialogueLine>> byScenario;
    private final Map<String, DialogueLine> byId;
    private final Map<String, String> repeatKeys;
    private final Map<String, SubjectBinding> subjects;
    private final int maximumTextKeys;
    private final int maximumInteractionKeys;
    private final Map<String, Integer> silencePercent;
    private final Set<String> runtimeEnabledScenarios;
    private final Map<String, String> livingWorldFamilies;

    private DialogueCatalog(Map<String, List<DialogueLine>> byScenario, Map<String, DialogueLine> byId,
        Map<String, String> repeatKeys, Map<String, SubjectBinding> subjects, int maximumTextKeys, int maximumInteractionKeys,
        Map<String, Integer> silencePercent, Set<String> runtimeEnabledScenarios)
    {
        this(byScenario, byId, repeatKeys, subjects, maximumTextKeys, maximumInteractionKeys,
            silencePercent, runtimeEnabledScenarios, Collections.emptyMap());
    }

    private DialogueCatalog(Map<String, List<DialogueLine>> byScenario, Map<String, DialogueLine> byId,
        Map<String, String> repeatKeys, Map<String, SubjectBinding> subjects, int maximumTextKeys, int maximumInteractionKeys,
        Map<String, Integer> silencePercent, Set<String> runtimeEnabledScenarios, Map<String, String> livingWorldFamilies)
    {
        this.byScenario = byScenario;
        this.byId = Collections.unmodifiableMap(byId);
        this.repeatKeys = Collections.unmodifiableMap(repeatKeys);
        this.subjects = Collections.unmodifiableMap(subjects);
        this.maximumTextKeys = maximumTextKeys;
        this.maximumInteractionKeys = maximumInteractionKeys;
        this.silencePercent = Collections.unmodifiableMap(silencePercent);
        this.runtimeEnabledScenarios = Collections.unmodifiableSet(runtimeEnabledScenarios);
        this.livingWorldFamilies = Collections.unmodifiableMap(livingWorldFamilies);
    }

    public static DialogueCatalog load(Class<?> resourceOwner) throws IOException
    {
        return load(resourceOwner, null);
    }

    public static DialogueCatalog load(Class<?> resourceOwner, Gson gson) throws IOException
    {
        try (InputStream in = resourceOwner.getResourceAsStream("/com/malfoid/dialogue.json"))
        {
            if (in == null)
            {
                throw new IOException("Missing bundled /com/malfoid/dialogue.json");
            }
            return read(in, gson);
        }
    }

    public static DialogueCatalog read(InputStream input) throws IOException
    {
        return read(input, null);
    }

    public static DialogueCatalog read(InputStream input, Gson gson) throws IOException
    {
        try
        {
            InputStreamReader reader = new InputStreamReader(input, StandardCharsets.UTF_8);
            JsonObject root = gson == null ? new JsonParser().parse(reader).getAsJsonObject() : gson.fromJson(reader, JsonObject.class);
            require(root.get("schemaVersion").getAsInt() == 1, "Unsupported dialogue schema");
            Set<String> registry = new HashSet<>();
            for (JsonElement id : root.getAsJsonArray("registry"))
            {
                require(registry.add(id.getAsString()), "Duplicate scenario ID");
            }
            Map<String, String> repeatKeys = new HashMap<>();
            JsonObject policy = root.getAsJsonObject("speechGuardPolicy");
            require(policy.getAsJsonObject("repeatCooldownSeconds").get("minimumInclusive").getAsInt() == 30
                && policy.getAsJsonObject("repeatCooldownSeconds").get("maximumInclusive").getAsInt() == 60,
                "Unexpected repeat policy");
            Set<String> uniqueKeys = new HashSet<>();
            for (Map.Entry<String, JsonElement> entry : policy.getAsJsonObject("interactionRepeatKeys").entrySet())
            {
                require(registry.contains(entry.getKey()), "Unknown reactive scenario");
                String key = entry.getValue().isJsonNull() ? null : entry.getValue().getAsString();
                repeatKeys.put(entry.getKey(), key);
                if (key != null)
                {
                    uniqueKeys.add(key);
                }
            }
            require(uniqueKeys.size() <= policy.get("maximumInteractionKeys").getAsInt(), "Repeat guard capacity exceeded");
            Map<String, SubjectBinding> subjects = new HashMap<>();
            for (Map.Entry<String, JsonElement> entry : root.getAsJsonObject("situationSpeechPolicy").getAsJsonObject("byLogicalKey").entrySet())
            {
                JsonObject value = entry.getValue().getAsJsonObject();
                JsonObject binding = value.getAsJsonObject("subjectBinding");
                require(uniqueKeys.contains(entry.getKey()), "Unknown situation key");
                subjects.put(entry.getKey(), new SubjectBinding(entry.getKey(), "MOMENT".equals(value.get("repeatClass").getAsString()), binding));
            }
            require(subjects.keySet().equals(uniqueKeys), "Missing situation classification");
            Set<String> runtimeEnabledScenarios = new HashSet<>();
            for (JsonElement id : root.getAsJsonArray("runtimeEnabledScenarios"))
            {
                require(registry.contains(id.getAsString()), "Unknown runtime-enabled scenario");
                runtimeEnabledScenarios.add(id.getAsString());
                SubjectBinding subject = subjects.get(repeatKeys.get(id.getAsString()));
                require(subject == null || subject.hasRuntimeExtractor(), "Enabled scenario needs typed subject extractor");
            }
            Map<String, Integer> silencePercent = new HashMap<>();
            for (Map.Entry<String, JsonElement> entry : root.getAsJsonObject("silencePercentByScenario").entrySet())
            {
                int percent = entry.getValue().getAsInt();
                require(registry.contains(entry.getKey()) && percent >= 0 && percent <= 100, "Invalid silent branch");
                silencePercent.put(entry.getKey(), percent);
            }
            Map<String, DialogueLine> byId = new HashMap<>();
            Map<String, List<DialogueLine>> byScenario = new HashMap<>();
            Set<String> enabledTextKeys = new HashSet<>();
            for (JsonElement element : root.getAsJsonArray("entries"))
            {
                JsonObject entry = element.getAsJsonObject();
                String id = entry.get("id").getAsString();
                String scenario = entry.get("scenario").getAsString();
                String text = entry.get("text").getAsString();
                String status = entry.get("status").getAsString();
                require(registry.contains(scenario), "Unknown scenario: " + scenario);
                require("enabled".equals(status) || "disabled".equals(status), "Unknown entry status");
                boolean enabled = "enabled".equals(status);
                validateText(text);
                require(!enabled || !EXCLUDED.contains(id), "Enabled excluded line: " + id);
                validateOwnerAndOutfitLine(id, scenario, text, enabled);
                Map<String, String> conditions = new HashMap<>();
                for (Map.Entry<String, JsonElement> condition : entry.getAsJsonObject("conditions").entrySet())
                {
                    validateCondition(id, scenario, condition.getKey(), condition.getValue());
                    conditions.put(condition.getKey(), condition.getValue().getAsString());
                }
                String presentation = entry.get("presentation").getAsString();
                require("OVERHEAD".equals(presentation) || "LOCAL_EXAMINE".equals(presentation)
                    || "LOCAL_NOTICE".equals(presentation), "Unknown presentation");
                DialogueLine line = new DialogueLine(id, scenario, text, entry.get("emotion").getAsString(), conditions, enabled, presentation);
                require(byId.put(id, line) == null, "Duplicate line ID: " + id);
                byScenario.computeIfAbsent(scenario, ignored -> new ArrayList<>()).add(line);
                if (enabled && line.isOverhead())
                {
                    enabledTextKeys.add(line.getNormalizedText());
                }
            }
            require(enabledTextKeys.size() <= policy.get("maximumTextKeys").getAsInt(), "Text guard capacity exceeded");
            byScenario.replaceAll((key, value) -> Collections.unmodifiableList(value));
            return new DialogueCatalog(Collections.unmodifiableMap(byScenario), byId, repeatKeys, subjects,
                policy.get("maximumTextKeys").getAsInt(), policy.get("maximumInteractionKeys").getAsInt(), silencePercent, runtimeEnabledScenarios);
        }
        catch (IllegalArgumentException | IllegalStateException | NullPointerException e)
        {
            throw new IOException("Invalid bundled dialogue: " + e.getMessage(), e);
        }
    }

    public List<DialogueLine> getLines(String scenario)
    {
        return byScenario.getOrDefault(scenario, Collections.emptyList());
    }

    /** Addendum F remains one exact resource; no second authored list is maintained. */
    public DialogueCatalog withLivingWorld(LivingWorldData data)
    {
        Map<String, List<DialogueLine>> lines = new HashMap<>(byScenario);
        Map<String, DialogueLine> ids = new HashMap<>(byId);
        Map<String, String> keys = new HashMap<>(repeatKeys);
        Map<String, SubjectBinding> bindings = new HashMap<>(subjects);
        Set<String> enabled = new HashSet<>(runtimeEnabledScenarios);
        Map<String, String> families = new HashMap<>(livingWorldFamilies);
        Set<String> oldTexts = new HashSet<>(), newTexts = new HashSet<>();
        for (DialogueLine line : byId.values())
        {
            if (line.isEnabled() && line.isOverhead()) { oldTexts.add(line.getNormalizedText()); }
        }
        Set<String> newKeys = new HashSet<>();
        addLivingWorldGroups(data.places, "PLACE", lines, ids, keys, bindings, enabled, families, newTexts, newKeys);
        addLivingWorldGroups(data.placeKinds, "PLACE", lines, ids, keys, bindings, enabled, families, newTexts, newKeys);
        addLivingWorldGroups(data.creatures, "CREATURE", lines, ids, keys, bindings, enabled, families, newTexts, newKeys);
        addLivingWorldGroups(data.scenery, "SCENERY", lines, ids, keys, bindings, enabled, families, newTexts, newKeys);
        addLivingWorldGroups(data.moments, "MOMENT", lines, ids, keys, bindings, enabled, families, newTexts, newKeys);
        newTexts.removeAll(oldTexts);
        newKeys.removeAll(subjects.keySet());
        return new DialogueCatalog(Collections.unmodifiableMap(lines), ids, keys, bindings,
            maximumTextKeys + newTexts.size(), maximumInteractionKeys + newKeys.size(),
            new HashMap<>(silencePercent), enabled, families);
    }

    private static void addLivingWorldGroups(List<? extends LivingWorldData.Group> groups, String family,
        Map<String, List<DialogueLine>> scenarios, Map<String, DialogueLine> ids, Map<String, String> keys,
        Map<String, SubjectBinding> bindings, Set<String> enabled, Map<String, String> families,
        Set<String> textKeys, Set<String> interactionKeys)
    {
        for (LivingWorldData.Group group : groups)
        {
            // E.5's F01/F02 speech belongs to the higher-priority base E.9 catalogue.
            if (group.lines.isEmpty()) { continue; }
            require(!scenarios.containsKey(group.id) && !families.containsKey(group.id), "Duplicate living-world scenario");
            List<DialogueLine> lines = new ArrayList<>();
            for (LivingWorldData.Line authored : group.lines)
            {
                validateText(authored.text);
                DialogueLine line = new DialogueLine(authored.id, group.id, authored.text, authored.emotion,
                    Collections.emptyMap(), true, "OVERHEAD");
                require(ids.put(authored.id, line) == null, "Duplicate living-world line ID");
                lines.add(line); textKeys.add(line.getNormalizedText());
            }
            String key = "PLACE".equals(family) ? "W-PLACE"
                : group instanceof LivingWorldData.Moment ? ((LivingWorldData.Moment) group).logicalKey : group.id;
            scenarios.put(group.id, Collections.unmodifiableList(lines)); keys.put(group.id, key);
            enabled.add(group.id); families.put(group.id, family); interactionKeys.add(key);
            JsonObject binding = new JsonObject(); binding.addProperty("type", "NOT_APPLICABLE");
            bindings.put(key, new SubjectBinding(key, true, binding));
        }
    }

    public boolean isLivingWorldScenario(String scenario) { return livingWorldFamilies.containsKey(scenario); }
    public String livingWorldFamily(String scenario) { return livingWorldFamilies.get(scenario); }

    public DialogueLine getLine(String id) { return byId.get(id); }
    public int size() { return byId.size(); }
    public String repeatKey(String scenario) { return repeatKeys.get(scenario); }
    public boolean isReactive(String scenario) { return repeatKeys.containsKey(scenario) && repeatKeys.get(scenario) != null; }
    public boolean isRuntimeScenarioEnabled(String scenario) { return runtimeEnabledScenarios.contains(scenario); }
    public int getMaximumTextKeys() { return maximumTextKeys; }
    public int getMaximumInteractionKeys() { return maximumInteractionKeys; }
    public int getSilencePercent(String scenario) { return silencePercent.getOrDefault(scenario, 0); }

    public List<String> getApprovedExamineTexts()
    {
        List<String> result = new ArrayList<>();
        for (DialogueLine line : getLines("U02"))
        {
            if (line.isEnabled())
            {
                result.add(line.getText());
            }
        }
        return Collections.unmodifiableList(result);
    }

    public String getLocalText(String id)
    {
        DialogueLine line = byId.get(id);
        return line != null && line.isEnabled() && !line.isOverhead() ? line.getText() : null;
    }

    /** Null means unknown typed subject; moments need no fingerprint. */
    public Long situationFingerprint(String scenario, Map<String, String> facts)
    {
        if (additionalIndex(scenario) != 0) { return null; }
        String logicalKey = repeatKey(scenario);
        SubjectBinding binding = subjects.get(logicalKey);
        if (binding == null || binding.moment)
        {
            return null;
        }
        String subject = binding.subject(facts);
        if (subject == null)
        {
            return null;
        }
        return fingerprint(logicalKey, subject);
    }

    /** New contracts use their immutable source context, never presentation strings as evidence. */
    public Long situationFingerprint(SceneCandidate candidate)
    {
        return situationFingerprint(candidate.getScenarioId(), candidate.getConditionFacts());
    }

    /** Original ownership only. The observer separately proves current first-paint validity. */
    public boolean hasValidOriginalContext(SceneCandidate candidate)
    {
        com.malfoid.scenario.PersonalMilestones.Proof proof = candidate.getMilestone();
        return additionalIndex(candidate.getScenarioId()) == 0 ? proof == null
            : proof != null && (proof.ruleIndex == 142 || proof.ruleIndex == 147) && proof.owns(candidate);
    }

    private static int additionalIndex(String scenario)
    {
        if (scenario == null || !scenario.startsWith("M")) { return 0; }
        try
        {
            int value = Integer.parseInt(scenario.substring(1));
            return value >= 71 && value <= 170 ? value : 0;
        }
        catch (NumberFormatException ignored) { return 0; }
    }

    private static Long fingerprint(String logicalKey, String subject)
    {
        if (subject == null) { return null; }
        long hash = 0xcbf29ce484222325L;
        for (byte value : (logicalKey + "\u0000" + subject).getBytes(StandardCharsets.UTF_8))
        {
            hash ^= value & 255;
            hash *= 0x100000001b3L;
        }
        return hash;
    }

    public boolean isSituation(String scenario)
    {
        SubjectBinding binding = subjects.get(repeatKey(scenario));
        return binding != null && !binding.moment;
    }

    public static String normalizeText(String text)
    {
        String normalized = Normalizer.normalize(text, Normalizer.Form.NFC).toLowerCase(Locale.ROOT);
        StringBuilder result = new StringBuilder();
        boolean space = false;
        for (int offset = 0; offset < normalized.length();)
        {
            int codePoint = normalized.codePointAt(offset);
            offset += Character.charCount(codePoint);
            if (Character.isWhitespace(codePoint) || Character.isSpaceChar(codePoint))
            {
                space = result.length() > 0;
            }
            else
            {
                if (space)
                {
                    result.append(' ');
                }
                result.appendCodePoint(codePoint);
                space = false;
            }
        }
        return result.toString();
    }

    private static void validateText(String text)
    {
        require(!normalizeText(text).isEmpty() && text.codePointCount(0, text.length()) <= 180, "Invalid line length");
        require(text.indexOf('<') < 0 && text.indexOf('>') < 0, "Markup in line");
        for (int offset = 0; offset < text.length();)
        {
            int cp = text.codePointAt(offset);
            offset += Character.charCount(cp);
            require(!Character.isISOControl(cp) && cp != 0xfffd, "Control or invalid character in line");
        }
    }

    private static void validateCondition(String id, String scenario, String name, JsonElement value)
    {
        require(value.isJsonPrimitive(), "Nonprimitive dialogue condition");
        boolean valid = false;
        switch (name)
        {
            case "newRealLevel": valid = "M04".equals(scenario) && value.getAsJsonPrimitive().isNumber() && value.getAsInt() == 99; break;
            case "skill": valid = "M06".equals(scenario) && value.getAsJsonPrimitive().isString()
                && Arrays.asList("FISHING", "WOODCUTTING", "MINING").contains(value.getAsString()); break;
            case "itemPossessionConfirmed": valid = "M05-05".equals(id) && value.getAsJsonPrimitive().isBoolean() && value.getAsBoolean(); break;
            case "objectKind": valid = "M08".equals(scenario) && value.getAsJsonPrimitive().isString()
                && Arrays.asList("TREE", "FOUNTAIN").contains(value.getAsString()); break;
            case "parentSpeechVisibleAtDeparture": valid = ("M07-04".equals(id) || "M07-05".equals(id))
                && value.getAsJsonPrimitive().isBoolean() && value.getAsBoolean(); break;
            case "changedSlot": valid = "M09".equals(scenario) && value.getAsJsonPrimitive().isString() && "CAPE".equals(value.getAsString()); break;
            case "recentReunionWithinTicks": valid = "M10".equals(scenario) && value.getAsJsonPrimitive().isNumber() && value.getAsInt() == 100; break;
            case "talkStreak": valid = "U01".equals(scenario) && value.getAsJsonPrimitive().isNumber() && value.getAsInt() >= 1 && value.getAsInt() <= 3; break;
            case "playerHpAtMostPercent": valid = "U01".equals(scenario) && value.getAsJsonPrimitive().isNumber() && value.getAsInt() == 25; break;
            case "combatConfirmed":
            case "localNight": valid = "U01".equals(scenario) && value.getAsJsonPrimitive().isBoolean() && value.getAsBoolean(); break;
            default: break;
        }
        require(valid, "Unsupported condition " + name + " for " + id);
    }

    private static void validateOwnerAndOutfitLine(String id, String scenario, String text, boolean enabled)
    {
        if ("M09-H01".equals(id))
        {
            require("M09".equals(scenario) && "Hmph.".equals(text), "Changed owner line: " + id);
        }
        else if ("M09-H02".equals(id))
        {
            require("M09".equals(scenario) && "...Hmph.".equals(text), "Changed owner line: " + id);
        }
        else if ("F03-01".equals(id))
        {
            require("F03".equals(scenario) && "Where are you taking me, Potter?!".equals(text), "Changed owner line: " + id);
        }
        if (enabled && "M09".equals(scenario))
        {
            require(Arrays.asList("M09-05", "M09-H01", "M09-H02", "M09-T01", "M09-T02", "M09-T03").contains(id), "Unreviewed outfit line: " + id);
        }
        if (enabled && OUTFIT_SCENARIOS.contains(scenario))
        {
            String lower = text.toLowerCase(Locale.ROOT);
            for (String word : new String[] {"ensemble", "attire", "headpiece", "garment", "wardrobe", "overhaul", "triumphant"})
            {
                require(!lower.contains(word), "Withdrawn outfit wording: " + id);
            }
        }
    }

    private static void require(boolean condition, String message)
    {
        if (!condition)
        {
            throw new IllegalArgumentException(message);
        }
    }

    private static final class SubjectBinding
    {
        private final String logicalKey;
        private final boolean moment;
        private final String type;
        private final String fixedSubject;

        private SubjectBinding(String logicalKey, boolean moment, JsonObject binding)
        {
            this.logicalKey = logicalKey;
            this.moment = moment;
            this.type = binding.get("type").getAsString();
            JsonElement values = binding.has("itemIds") ? binding.get("itemIds") : binding.get("skills");
            this.fixedSubject = values == null ? null : values.toString();
            require(Arrays.asList("NOT_APPLICABLE", "ACTUAL_REGION", "ACTUAL_REGION_AND_SELECTED_SKILL",
                "QUALIFYING_NPC_RESOLVED_NAME", "FOUR_SLOT_EQUIPMENT_IDS", "MATCHED_HEAD_ITEM_ID",
                "NAMED_PREDICATE_ITEM_ID_SET", "ANCHOR_BAG_ITEM_ID_SET", "SELECTED_COMBAT_SKILL_SET",
                "SELECTED_PRIMARY_SKILL", "FIXED_SKILL_SET", "CURRENT_OBJECT_KIND", "UNIT",
                "NOT_APPLICABLE").contains(type), "Unknown subject binding");
        }

        private boolean hasRuntimeExtractor()
        {
            return moment || !"NOT_APPLICABLE".equals(type);
        }

        private String subject(Map<String, String> facts)
        {
            switch (type)
            {
                case "UNIT": return "UNIT";
                case "NAMED_PREDICATE_ITEM_ID_SET":
                case "FIXED_SKILL_SET": return fixedSubject;
                case "ACTUAL_REGION": return knownInteger(facts.get("actualRegion"), false);
                case "ACTUAL_REGION_AND_SELECTED_SKILL":
                    String region = knownInteger(facts.get("actualRegion"), false);
                    String skill = knownSkill(facts.get("skill"));
                    return region == null || skill == null ? null : region + ":" + skill;
                case "QUALIFYING_NPC_RESOLVED_NAME":
                    String name = known(facts.get("npcResolvedName"));
                    return name == null ? null : known(normalizeText(name.replaceAll("<[^>]*>", "")));
                case "FOUR_SLOT_EQUIPMENT_IDS": return integerList(facts.get("equipmentIds"), 4, false, true);
                case "MATCHED_HEAD_ITEM_ID": return knownInteger(facts.get("matchedHeadItemId"), false);
                case "ANCHOR_BAG_ITEM_ID_SET": return integerList(facts.get("anchorBagItemIds"), -1, true, false);
                case "SELECTED_COMBAT_SKILL_SET": return skillSet(facts.getOrDefault("selectedCombatSkills", facts.get("skillSet")));
                case "SELECTED_PRIMARY_SKILL": return knownSkill(facts.get("skill"));
                case "CURRENT_OBJECT_KIND":
                    String kind = facts.get("objectKind");
                    return "TREE".equals(kind) || "FOUNTAIN".equals(kind) ? kind : null;
                default: return null;
            }
        }

        private static String known(String value)
        {
            return value == null || value.trim().isEmpty() || "UNKNOWN".equals(value) ? null : value;
        }

        private static String knownInteger(String value, boolean allowEmpty)
        {
            try
            {
                int number = Integer.parseInt(value);
                return number >= (allowEmpty ? -1 : 0) ? Integer.toString(number) : null;
            }
            catch (NumberFormatException ignored)
            {
                return null;
            }
        }

        private static String knownSkill(String value)
        {
            try { return Skill.valueOf(value).name(); }
            catch (IllegalArgumentException | NullPointerException ignored) { return null; }
        }

        private static String integerList(String value, int count, boolean sortedDistinct, boolean allowEmpty)
        {
            if (known(value) == null) { return null; }
            String[] parts = value.split(",", -1);
            if (count >= 0 && parts.length != count || parts.length > 28) { return null; }
            List<String> canonical = new ArrayList<>();
            TreeSet<Integer> sorted = new TreeSet<>();
            for (String part : parts)
            {
                String item = knownInteger(part.trim(), allowEmpty);
                if (item == null) { return null; }
                if (sortedDistinct) { sorted.add(Integer.parseInt(item)); }
                else { canonical.add(item); }
            }
            if (sortedDistinct)
            {
                for (Integer item : sorted) { canonical.add(item.toString()); }
            }
            return String.join(",", canonical);
        }

        private static String skillSet(String value)
        {
            if (known(value) == null) { return null; }
            TreeSet<Skill> skills = new TreeSet<>();
            for (String part : value.split(",", -1))
            {
                String skill = knownSkill(part.trim());
                if (skill == null) { return null; }
                skills.add(Skill.valueOf(skill));
            }
            if (skills.size() != 3) { return null; }
            List<String> names = new ArrayList<>();
            for (Skill skill : skills) { names.add(skill.name()); }
            return String.join(",", names);
        }
    }
}

package com.malfoid.dialogue;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

public final class DialogueLine
{
    private final String id;
    private final String scenario;
    private final String text;
    private final String emotion;
    private final String normalizedText;
    private final Map<String, String> conditions;
    private final boolean enabled;
    private final String presentation;

    DialogueLine(String id, String scenario, String text, Map<String, String> conditions,
        boolean enabled, String presentation)
    {
        this(id, scenario, text, "QUIET", conditions, enabled, presentation);
    }

    DialogueLine(String id, String scenario, String text, String emotion, Map<String, String> conditions,
        boolean enabled, String presentation)
    {
        this.id = id;
        this.scenario = scenario;
        this.text = text;
        this.emotion = emotion;
        this.normalizedText = DialogueCatalog.normalizeText(text);
        this.conditions = Collections.unmodifiableMap(new HashMap<>(conditions));
        this.enabled = enabled;
        this.presentation = presentation;
    }

    public String getId() { return id; }
    public String getScenario() { return scenario; }
    public String getText() { return text; }
    public String getEmotion() { return emotion; }
    public String getNormalizedText() { return normalizedText; }
    public Map<String, String> getConditions() { return conditions; }
    public boolean isEnabled() { return enabled; }
    public boolean isOverhead() { return "OVERHEAD".equals(presentation); }

    public boolean matches(Map<String, String> facts)
    {
        for (Map.Entry<String, String> condition : conditions.entrySet())
        {
            String actual = facts.get(condition.getKey());
            if (actual == null && "newRealLevel".equals(condition.getKey()))
            {
                actual = facts.get("newLevel");
            }
            if ("recentReunionWithinTicks".equals(condition.getKey())
                || "playerHpAtMostPercent".equals(condition.getKey()))
            {
                if (actual == null || !isWithin(actual, condition.getValue()))
                {
                    return false;
                }
            }
            else if (!condition.getValue().equals(actual))
            {
                return false;
            }
        }
        return true;
    }

    private static boolean isWithin(String actual, String bound)
    {
        try
        {
            int value = Integer.parseInt(actual);
            return value >= 0 && value <= Integer.parseInt(bound);
        }
        catch (NumberFormatException ignored)
        {
            return false;
        }
    }
}

package com.malfoid.interaction;

import java.util.UUID;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import com.malfoid.presence.PresenceController;
import com.malfoid.presence.PresenceReason;

/** Only local Examine and N01-N05 use the chatbox. No player chat or network action is issued. */
public final class ChatNotices
{
	// Exactly the helper's pinned 1.13.1 suppression set, not a guessed island boundary.
	private static final int[] TUTORIAL_REGIONS = {12336, 12335, 12592, 12080, 12079, 12436};
	private final Client client;
	private final ChatMessageManager messages;
	private final ConfigManager configManager;
	private final NoticeLedger ledger = new NoticeLedger("malfoid-local-" + UUID.randomUUID());
	private int examineIndex;
	private boolean present;

	@Inject
	public ChatNotices(Client client, ChatMessageManager messages, ConfigManager configManager)
	{
		this.client = client;
		this.messages = messages;
		this.configManager = configManager;
	}

	public void onPresence(PresenceController.Decision decision)
	{
		present = decision.isPresent();
		if (decision.isPresent() && !introShown())
		{
			ledger.request(NoticeLedger.Notice.N01);
		}
		if (decision.getReason() == PresenceReason.MODEL_UNAVAILABLE)
		{
			onModelUnavailable();
		}
		else if (decision.getReason() == PresenceReason.PLAYER_COMBAT)
		{
			ledger.request(NoticeLedger.Notice.N04);
		}
		else if (decision.getReason() == PresenceReason.ABOARD)
		{
			ledger.request(NoticeLedger.Notice.N05);
		}
	}

	public void onDismiss() { present = false; ledger.request(NoticeLedger.Notice.N02); }
	public void onModelUnavailable() { present = false; ledger.request(NoticeLedger.Notice.N03); }

	public void flush()
	{
		boolean tutorial = isTutorial();
		if (tutorial)
		{
			ledger.deferTutorialIntro();
		}
		boolean eligible = client.getGameState() == GameState.LOGGED_IN
			&& client.getLocalPlayer() != null && !tutorial;
		for (NoticeLedger.Delivery delivery; (delivery = ledger.next(eligible, introShown(), present)) != null; )
		{
			messages.queue(QueuedMessage.builder().type(ChatMessageType.GAMEMESSAGE)
				.runeLiteFormattedMessage(delivery.getNotice().getText())
				.sender(delivery.getSender()).build());
		}
	}

	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() == ChatMessageType.GAMEMESSAGE
			&& ledger.acknowledgeIntro(event.getSender(), event.getMessage()))
		{
			configManager.setConfiguration("malfoid", "introShown", true);
		}
	}

	public void examine(String[] approvedTexts)
	{
		if (approvedTexts == null || approvedTexts.length == 0
			|| client.getGameState() != GameState.LOGGED_IN || isTutorial())
		{
			return;
		}
		String text = approvedTexts[examineIndex % approvedTexts.length];
		if (text == null || text.isEmpty())
		{
			return;
		}
		examineIndex = (examineIndex + 1) % approvedTexts.length;
		messages.queue(QueuedMessage.builder().type(ChatMessageType.NPC_EXAMINE)
			.runeLiteFormattedMessage(text).build());
	}

	public void resetSession()
	{
		ledger.resetSession();
		examineIndex = 0;
		present = false;
	}

	private boolean introShown()
	{
		return Boolean.TRUE.equals(configManager.getConfiguration("malfoid", "introShown", Boolean.class));
	}

	private boolean isTutorial()
	{
		Player player = client.getLocalPlayer();
		if (player == null || player.getWorldLocation() == null)
		{
			return false;
		}
		int region = player.getWorldLocation().getRegionID();
		for (int blockedRegion : TUTORIAL_REGIONS)
		{
			if (region == blockedRegion)
			{
				return true;
			}
		}
		return false;
	}
}

package com.malfoid.interaction;

import java.awt.Rectangle;
import java.awt.Shape;
import java.util.Objects;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import javax.inject.Inject;
import com.malfoid.asset.NativeActor;
import com.malfoid.presence.PresenceController;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Point;
import net.runelite.api.Player;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/** Preferred MenuOpened-only local controls. No mouse/key listeners or menu-default changes. */
public final class MalfoidMenu
{
	private static final String TARGET = "<col=ffff00>Malfoid";
	private static final int[] INTERFACE_HIT_WIDGETS = {
		InterfaceID.Inventory.ITEMS, InterfaceID.InventoryNoops.ITEMS, InterfaceID.Chatbox.UNIVERSE,
		InterfaceID.ChatLeft.UNIVERSE, InterfaceID.ChatRight.UNIVERSE, InterfaceID.Chatmenu.UNIVERSE,
		InterfaceID.Messagebox.UNIVERSE, InterfaceID.Objectbox.UNIVERSE, InterfaceID.Bankmain.UNIVERSE,
		InterfaceID.BankDepositbox.UNIVERSE, InterfaceID.BankpinKeypad.UNIVERSE,
		InterfaceID.Trademain.UNIVERSE, InterfaceID.Tradeconfirm.UNIVERSE, InterfaceID.GeOffers.UNIVERSE,
		InterfaceID.Shopmain.UNIVERSE, InterfaceID.Skillmulti.UNIVERSE, InterfaceID.Worldmap.UNIVERSE
	};
	private final Client client;
	private Consumer<Throwable> failureHandler;
	private Consumer<PresenceController.Decision> absenceHandler;

	@Inject
	public MalfoidMenu(Client client)
	{
		this.client = client;
	}

	public void setFailureHandler(Consumer<Throwable> failureHandler)
	{
		this.failureHandler = Objects.requireNonNull(failureHandler);
	}

	public void setAbsenceHandler(Consumer<PresenceController.Decision> absenceHandler)
	{
		this.absenceHandler = Objects.requireNonNull(absenceHandler);
	}

	public void onMenuOpened(MenuOpened event, NativeActor actor, PresenceController presence,
		long generation, LongSupplier currentGeneration, Runnable talk, Runnable dismiss, Runnable examine)
	{
		if (failureHandler == null)
		{
			return;
		}
		NativeActor.PlacementSnapshot snapshot = actor.getPlacementSnapshot();
		if (!permitsLocalControls(presence) || !placementCurrent(snapshot))
		{
			return;
		}
		Point mouse = client.getMouseCanvasPosition();
		MenuEntry[] entries = event.getMenuEntries();
		if (mouse == null || entries == null)
		{
			return;
		}
		boolean hasWalk = false;
		boolean widgetEntry = false;
		for (MenuEntry entry : entries)
		{
			if (entry == null)
			{
				continue;
			}
			hasWalk |= entry.getType() == MenuAction.WALK;
			widgetEntry |= entry.getWidget() != null;
			if (entry.getType() == MenuAction.RUNELITE && TARGET.equals(entry.getTarget())
				&& ("Talk-to".equals(entry.getOption()) || "Dismiss".equals(entry.getOption())
					|| "Examine".equals(entry.getOption())))
			{
				return;
			}
		}
		Rectangle viewport = new Rectangle(client.getViewportXOffset(), client.getViewportYOffset(),
			client.getViewportWidth(), client.getViewportHeight());
		if (!hasWalk || widgetEntry || interfaceHit(mouse) || !viewport.contains(mouse.getX(), mouse.getY()))
		{
			return;
		}
		Shape clickbox = actor.getClickbox();
		if (!MenuPolicy.mayOpen(true, true, hasWalk, false, mouse.getX(), mouse.getY(), viewport, clickbox))
		{
			return;
		}
		MenuPolicy.Lease lease = new MenuPolicy.Lease(generation, presence.getSceneGeneration(),
			presence.getPresenceEpoch(), snapshot.getPlacementGeneration());
		Menu menu = client.getMenu();
		// The array is bottom-to-top. Repeated index 1 insertion leaves Cancel at zero.
		add(menu, "Talk-to", snapshot, lease, actor, presence, currentGeneration, talk);
		add(menu, "Dismiss", snapshot, lease, actor, presence, currentGeneration, dismiss);
		add(menu, "Examine", snapshot, lease, actor, presence, currentGeneration, examine);
	}

	private void add(Menu menu, String option, NativeActor.PlacementSnapshot opened,
		MenuPolicy.Lease lease, NativeActor actor, PresenceController presence,
		LongSupplier generation, Runnable command)
	{
		Consumer<Throwable> onFailure = failureHandler;
		menu.createMenuEntry(1).setOption(option).setTarget(TARGET).setType(MenuAction.RUNELITE)
			.setWorldViewId(opened.getWorldViewId()).onClick(entry ->
			{
				try
				{
					NativeActor.PlacementSnapshot current = actor.getPlacementSnapshot();
					if (permitsLocalControls(presence) && placementCurrent(current) && current.getWorldView() == opened.getWorldView()
						&& current.getScene() == opened.getScene()
						&& current.getPlane() == opened.getPlane()
						&& lease.isCurrent(generation.getAsLong(), presence.getSceneGeneration(),
							presence.getPresenceEpoch(), current.getPlacementGeneration(), presence.isPresent()))
					{
						command.run();
					}
				}
				catch (Throwable failure)
				{
					onFailure.accept(failure);
				}
			});
	}

	private boolean permitsLocalControls(PresenceController presence)
	{
		boolean wasPresent = presence.isPresent();
		boolean permitted = presence.permitsLocalControls();
		if (wasPresent && !permitted && !presence.isPresent() && absenceHandler != null)
		{
			absenceHandler.accept(presence.getDecision());
		}
		return permitted;
	}

	private boolean placementCurrent(NativeActor.PlacementSnapshot snapshot)
	{
		Player player = client.getLocalPlayer();
		return snapshot != null && client.getGameState() == GameState.LOGGED_IN && player != null
			&& player.getWorldView() == snapshot.getWorldView()
			&& snapshot.getWorldView().getScene() == snapshot.getScene()
			&& snapshot.getWorldView().getPlane() == snapshot.getPlane();
	}

	private boolean interfaceHit(Point mouse)
	{
		for (int id : INTERFACE_HIT_WIDGETS)
		{
			Widget widget = client.getWidget(id);
			if (widget != null && !widget.isHidden())
			{
				Rectangle bounds = widget.getBounds();
				if (bounds != null && bounds.contains(mouse.getX(), mouse.getY()))
				{
					return true;
				}
			}
		}
		return false;
	}
}

package com.malfoid.interaction;

import java.awt.Rectangle;
import java.awt.Shape;

/** Shared eligibility/identity checks; no menu construction runs on hover or ordinary left-click. */
final class MenuPolicy
{
	static boolean mayOpen(boolean present, boolean hasPlacement, boolean hasWalk,
		boolean interfaceHit, int mouseX, int mouseY, Rectangle viewport, Shape clickbox)
	{
		return present && hasPlacement && hasWalk && !interfaceHit && viewport != null
			&& viewport.contains(mouseX, mouseY) && clickbox != null && clickbox.contains(mouseX, mouseY);
	}

	static final class Lease
	{
		private final long session;
		private final long scene;
		private final long epoch;
		private final long placement;

		Lease(long session, long scene, long epoch, long placement)
		{
			this.session = session;
			this.scene = scene;
			this.epoch = epoch;
			this.placement = placement;
		}

		boolean isCurrent(long session, long scene, long epoch, long placement, boolean present)
		{
			return present && this.session == session && this.scene == scene && this.epoch == epoch
				&& this.placement == placement;
		}
	}
}

package com.malfoid.interaction;

import java.util.ArrayDeque;
import java.util.EnumSet;
import java.util.Queue;

/** Bounded local-notice state; only the issued intro's receipt can consume the persisted flag. */
final class NoticeLedger
{
	enum Notice
	{
		N01("Malfoid is with you. Right-click her to talk, examine or dismiss her. You can hide her any time in the Malfoid plugin settings."),
		N02("Malfoid will wait for you. Tick Show Malfoid in the Malfoid plugin settings to bring her back."),
		N03("Malfoid can't appear on this client right now. She'll try again next time you log in."),
		N04("Malfoid steps away while you fight other players. She'll be back when it's over."),
		N05("Malfoid waits on land while you're aboard. She'll rejoin you when you step off.");

		private final String text;
		Notice(String text) { this.text = text; }
		String getText() { return text; }
	}

	static final class Delivery
	{
		private final Notice notice;
		private final String sender;
		Delivery(Notice notice, String sender) { this.notice = notice; this.sender = sender; }
		Notice getNotice() { return notice; }
		String getSender() { return sender; }
	}

	private final String prefix;
	private final EnumSet<Notice> requested = EnumSet.noneOf(Notice.class);
	private final Queue<Notice> pending = new ArrayDeque<>();
	private long session;
	private long serial;
	private Delivery issuedIntro;

	NoticeLedger(String prefix)
	{
		this.prefix = prefix;
	}

	void request(Notice notice)
	{
		if (requested.add(notice))
		{
			pending.add(notice);
		}
	}

	Delivery next(boolean eligible, boolean introShown, boolean present)
	{
		if (!eligible)
		{
			return null;
		}
		for (int remaining = pending.size(); remaining > 0; remaining--)
		{
			Notice notice = pending.remove();
			if (notice == Notice.N01 && introShown)
			{
				continue;
			}
			if (notice == Notice.N01 && !present)
			{
				pending.add(notice);
				continue;
			}
			Delivery delivery = new Delivery(notice, prefix + ":" + session + ":" + ++serial);
			if (notice == Notice.N01)
			{
				issuedIntro = delivery;
			}
			return delivery;
		}
		return null;
	}

	boolean acknowledgeIntro(String sender, String text)
	{
		if (issuedIntro != null && issuedIntro.sender.equals(sender)
			&& issuedIntro.notice.text.equals(text))
		{
			issuedIntro = null;
			return true;
		}
		return false;
	}

	void deferTutorialIntro()
	{
		if (issuedIntro != null)
		{
			pending.add(Notice.N01);
			issuedIntro = null;
		}
	}

	void resetSession()
	{
		session++;
		requested.clear();
		pending.clear();
		issuedIntro = null;
	}
}

package com.malfoid.interaction;

import java.util.ArrayDeque;
import java.util.Deque;

/** U01 request etiquette. Coalesced requests never extend or increment the streak. */
public final class TalkState
{
	private final Deque<Long> accepted = new ArrayDeque<>(4);
	private long lastAccepted = -1;
	private boolean turnAway;

	/** Returns zero for a coalesced request, 1-3 for a speaking pool, or 4 for silent turn-away. */
	public int accept(long tick)
	{
		if (lastAccepted >= 0 && tick - lastAccepted < 2)
		{
			return 0;
		}
		if (turnAway && tick - lastAccepted >= 50)
		{
			turnAway = false;
			accepted.clear();
		}
		lastAccepted = tick;
		if (turnAway)
		{
			return 4;
		}
		while (!accepted.isEmpty() && accepted.peekFirst() < tick - 20)
		{
			accepted.removeFirst();
		}
		int streak = Math.min(4, accepted.size() + 1);
		accepted.addLast(tick);
		turnAway = streak == 4;
		return streak;
	}

	public void reset()
	{
		accepted.clear();
		lastAccepted = -1;
		turnAway = false;
	}
}

package com.malfoid.motion;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;

/** Copied creature facts and the E.5 near/ending state; contains no client objects. */
public final class CreatureAwareness
{
    public enum Behaviour { AFRAID, WARY, DISGUST, FOND, WIZARD, NONE }
    private static final Pattern TAGS = Pattern.compile("<[^>]*>");

    public static final class Classification
    {
        public final String groupId;
        public final int priority, minPlayerDistance, maxPlayerDistance;
        public final Behaviour behaviour;
        public Classification(String groupId, int priority, Behaviour behaviour, int minimum, int maximum)
        {
            this.groupId = groupId; this.priority = priority; this.behaviour = behaviour;
            minPlayerDistance = minimum; maxPlayerDistance = maximum;
        }
        public boolean keepsAway() { return behaviour == Behaviour.AFRAID || behaviour == Behaviour.WARY; }
    }

    public static final class Creature
    {
        public final String key, name;
        public final Classification classification;
        public final int combatLevel, worldX, worldY, plane, size;
        public Creature(String key, Classification classification, String name, int level, int x, int y, int plane)
        {
            this(key, classification, name, level, x, y, plane, 1);
        }
        /** (x, y) is its south-west tile; it stands on `size` tiles each way. */
        public Creature(String key, Classification classification, String name, int level, int x, int y, int plane, int size)
        {
            this.key = key; this.classification = classification; this.name = name; combatLevel = level;
            worldX = x; worldY = y; this.plane = plane; this.size = Math.max(1, size);
        }
        /** Tiles from (x, y) to the nearest tile it stands on. */
        public int distance(int x, int y)
        {
            return MotionMath.footprintDistance(x, y, worldX, worldY, worldX + size - 1, worldY + size - 1);
        }
    }

    public static final class Sample
    {
        public final long tick;
        public final int worldViewId, baseX, baseY, plane;
        public final boolean known;
        public final List<Creature> creatures;
        public Sample(long tick, int view, int baseX, int baseY, int plane, boolean known, List<Creature> creatures)
        {
            this.tick = tick; worldViewId = view; this.baseX = baseX; this.baseY = baseY; this.plane = plane;
            this.known = known; this.creatures = Collections.unmodifiableList(new ArrayList<>(creatures));
        }
    }

    private Creature target, beginCreature;
    private long beginTick = -1, lastTick = Long.MIN_VALUE;
    private int quietTicks, view, baseX, baseY, plane;
    private boolean known, endedKeepingAway;

    public void commit(Sample sample, int actorX, int actorY)
    {
        endedKeepingAway = false;
        if (sample.tick == lastTick) { return; }
        boolean contiguous = lastTick != Long.MIN_VALUE && sample.tick == lastTick + 1
            && sample.worldViewId == view && sample.baseX == baseX && sample.baseY == baseY && sample.plane == plane;
        if (lastTick != Long.MIN_VALUE && (sample.worldViewId != view || sample.baseX != baseX
            || sample.baseY != baseY || sample.plane != plane)) { reset(); }
        else if (!contiguous) { quietTicks = 0; }
        lastTick = sample.tick; view = sample.worldViewId; baseX = sample.baseX; baseY = sample.baseY; plane = sample.plane;
        known = sample.known;
        if (!known) { quietTicks = 0; return; }
        Creature near = nearest(sample, actorX, actorY, 6, null);
        Creature retained = isKeepingAway() ? nearest(sample, actorX, actorY, 8, target.classification.groupId) : null;
        if (isKeepingAway())
        {
            if (near != null && near.classification.keepsAway()
                && priority(near) < priority(target)) { quietTicks = 0; }
            else if (retained != null) { target = retained; quietTicks = 0; return; }
            else if (++quietTicks < 5) { return; }
        }
        if (near != null)
        {
            boolean wasKeepingAway = isKeepingAway();
            if (target == null || !sameFamily(target.classification.groupId, near.classification.groupId))
            {
                beginTick = sample.tick; beginCreature = near;
            }
            target = near; quietTicks = 0;
            endedKeepingAway = wasKeepingAway && !isKeepingAway();
        }
        else if (isKeepingAway())
        {
            target = beginCreature = null; beginTick = -1; endedKeepingAway = true;
        }
        else { target = beginCreature = null; beginTick = -1; quietTicks = 0; }
    }

    private static Creature nearest(Sample sample, int x, int y, int radius, String group)
    {
        Creature best = null;
        for (Creature creature : sample.creatures)
        {
            if (creature.plane != sample.plane || creature.distance(x, y) > radius
                || group != null && !sameFamily(group, creature.classification.groupId)) { continue; }
            if (best == null || priority(creature) < priority(best)
                || priority(creature) == priority(best)
                    && (creature.distance(x, y) < best.distance(x, y)
                        || creature.distance(x, y) == best.distance(x, y) && creature.key.compareTo(best.key) < 0)) { best = creature; }
        }
        return best;
    }

    public Creature getTarget() { return target; }
    public Creature getBeginCreature() { return beginCreature; }
    public String getGroupId() { return target == null ? null : target.classification.groupId; }
    public long getBeginTick() { return beginTick; }
    public boolean isKnown() { return known; }
    public boolean isKeepingAway() { return target != null && target.classification.keepsAway(); }
    public boolean didEndKeepingAway() { return endedKeepingAway; }
    public int getQuietTicks() { return quietTicks; }
    public void reset() { target = beginCreature = null; beginTick = -1; lastTick = Long.MIN_VALUE; quietTicks = 0; known = endedKeepingAway = false; }

    public static boolean isE5(String group) { return "F01".equals(group) || "F02".equals(group); }
    private static boolean sameFamily(String first, String second)
    {
        return first.equals(second) || isE5(first) && isE5(second);
    }
    private static int priority(Creature creature)
    {
        // E.5 wins over F's table ordering: distance selects the nearest rat or beast.
        return isE5(creature.classification.groupId) ? 0 : creature.classification.priority;
    }

    public static String normalizeName(String name)
    {
        return name == null ? "" : TAGS.matcher(name).replaceAll("").trim().toLowerCase(Locale.ROOT);
    }
    /** E.5 fallback only. The full group classifier uses its pinned living-world data. */
    public static Classification classifyFear(String name, Integer combatLevel)
    {
        if (name.equals("rat") || name.endsWith(" rat") || name.endsWith("-rat"))
        {
            return new Classification("F01", 0, Behaviour.AFRAID, 1, 2);
        }
        if (name.equals("wolf") || name.equals("werewolf") || name.endsWith(" wolf")
            || name.equals("bear") || name.endsWith(" bear") || name.equals("hellhound")
            || name.equals("scorpion") || name.endsWith(" scorpion") || name.equals("snake") || name.endsWith(" snake")
            || name.equals("crocodile") || name.endsWith(" crocodile") || name.equals("bat") || name.endsWith(" bat")
            || name.equals("spider") || name.endsWith(" spider")
            || name.equals("jackal") || name.equals("guard dog") || name.equals("wild dog") || name.equals("terror dog")
            || name.equals("shadow hound") || name.equals("jaguar") || name.equals("spined larupia")
            || name.equals("horned graahk") || name.equals("sabre-toothed kyatt"))
        {
            return new Classification("F02", 2, Behaviour.AFRAID, 1, 2);
        }
        return null;
    }

    /** The player lies between this tile and the creature, subject to a legal route. */
    public static boolean farSide(int x, int y, int playerX, int playerY, int creatureX, int creatureY)
    {
        return (long) (x - playerX) * (playerX - creatureX) + (long) (y - playerY) * (playerY - creatureY) > 0;
    }
}

