/** Bounded committed-tick evidence for cosmetic recovery and blocked-route backoff. */
public final class RecoveryPolicy
{
    private int offScreenTicks, blockedTicks, ineffectivePlans;
    private long lastRelocation = Long.MIN_VALUE;
    private long planNotBefore, retryAt;

    public void commit(int separation, WholeBoundsVisibility.Visibility visibility, boolean routeProgress,
        boolean confirmedBlocked, boolean destinationNearPlayer, boolean intervalKnown)
    {
        if (!intervalKnown)
        {
            offScreenTicks = blockedTicks = ineffectivePlans = 0;
            planNotBefore = retryAt = 0;
            return;
        }
        offScreenTicks = separation >= 12 && visibility == WholeBoundsVisibility.Visibility.OFF_SCREEN
            ? Math.min(5, offScreenTicks + 1) : 0;
        if (routeProgress)
        {
            blockedTicks = ineffectivePlans = 0;
            planNotBefore = retryAt = 0;
        }
        else
        {
            blockedTicks = confirmedBlocked && destinationNearPlayer ? Math.min(50, blockedTicks + 1) : 0;
        }
    }

    public void recordPlan(long tick, boolean ineffective, boolean reachableRefreshedDestination)
    {
        if (reachableRefreshedDestination)
        {
            ineffectivePlans = blockedTicks = 0;
            planNotBefore = retryAt = 0;
        }
        else if (ineffective)
        {
            ineffectivePlans = Math.min(3, ineffectivePlans + 1);
            if (ineffectivePlans >= 3)
            {
                planNotBefore = tick + 5;
                retryAt = tick + 30;
            }
        }
    }

    public boolean mayPlan(long tick, boolean meaningfulChange)
    {
        return tick >= planNotBefore && (ineffectivePlans < 3 || meaningfulChange || tick >= retryAt);
    }

    public boolean offScreenEligible(long tick, int separation)
    {
        return cooldownPassed(tick) && separation >= 12 && offScreenTicks >= 5
            && (ineffectivePlans >= 3 || separation >= 16);
    }

    public boolean stuckEligible(long tick)
    {
        return cooldownPassed(tick) && blockedTicks >= 50;
    }

    public boolean confirmOrigin(WholeBoundsVisibility.Visibility current, boolean stuckRecovery)
    {
        if (stuckRecovery)
        {
            return true;
        }
        if (current != WholeBoundsVisibility.Visibility.OFF_SCREEN)
        {
            offScreenTicks = 0;
            return false;
        }
        return true;
    }

    public void relocated(long tick)
    {
        lastRelocation = tick;
        offScreenTicks = blockedTicks = ineffectivePlans = 0;
        planNotBefore = retryAt = 0;
    }

    private boolean cooldownPassed(long tick)
    {
        return lastRelocation == Long.MIN_VALUE || tick - lastRelocation >= 60;
    }

    public void reset()
    {
        offScreenTicks = blockedTicks = ineffectivePlans = 0;
        planNotBefore = retryAt = 0;
        lastRelocation = Long.MIN_VALUE;
    }

    public int getOffScreenTicks() { return offScreenTicks; }
    public int getBlockedTicks() { return blockedTicks; }
    public int getIneffectivePlans() { return ineffectivePlans; }
    public long getPlanNotBefore() { return planNotBefore; }
    public long getRetryAt() { return retryAt; }
}

package com.malfoid.motion;

/** Small fixed courtesy multipliers, applied only at an existing movement decision. */
public final class RestingRules
{
    private RestingRules() {}

    public static double refine(double score, boolean inPlayerFacingCone, boolean groundItems,
        boolean knownRoofMismatch, int traversableExits)
    {
        if (inPlayerFacingCone) score *= .2;
        if (groundItems) score *= .2;
        if (knownRoofMismatch) score *= .3;
        if (traversableExits >= 0 && traversableExits <= 2) score *= .3;
        return score;
    }
}

package com.malfoid.motion;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;

/** The render clock follows adjacent segments; it never advances again on GameTick. */
public final class RouteMotion
{
    private final ArrayDeque<RoutePlanner.Node> route = new ArrayDeque<>();
    private RoutePlanner.Node completed;
    private RoutePlanner.Node target;
    private int progress;
    private int segmentCycles;
    private int lastCycle;
    private double x, y;
    private boolean running, blocked;
    private long completedEdges;

    public void place(int tileX, int tileY, int cycle)
    {
        clear();
        completed = new RoutePlanner.Node(tileX, tileY);
        x = tileX * 128 + 64;
        y = tileY * 128 + 64;
        lastCycle = cycle;
    }

    public void setRoute(List<RoutePlanner.Node> steps, boolean run)
    {
        route.clear();
        route.addAll(steps);
        running = run;
        blocked = false;
    }

    public void stop()
    {
        // A committed short segment finishes before a stop or changed destination takes effect.
        route.clear();
    }

    /** A pace change applies to the next edge, while the committed edge keeps its original duration. */
    public void setRunning(boolean run)
    {
        running = run;
    }

    public void advance(int cycle, RoutePlanner.Collision collision)
    {
        if (completed == null || cycle == lastCycle)
        {
            return;
        }
        lastCycle = cycle;
        // A stall never accumulates a jump across unvalidated segments.
        if (target == null)
        {
            RoutePlanner.Node next = route.peekFirst();
            if (next == null)
            {
                return;
            }
            int dx = next.x - completed.x, dy = next.y - completed.y;
            if (Math.abs(dx) > 1 || Math.abs(dy) > 1 || (dx == 0 && dy == 0)
                || collision == null || !collision.isLegal(next.x, next.y)
                || !collision.canTravel(completed.x, completed.y, dx, dy))
            {
                blocked = true;
                route.clear();
                return;
            }
            target = route.removeFirst();
            progress = 0;
            segmentCycles = running ? 15 : 30;
        }
        progress++;
        double fraction = Math.min(1d, (double) progress / segmentCycles);
        x = (completed.x + (target.x - completed.x) * fraction) * 128 + 64;
        y = (completed.y + (target.y - completed.y) * fraction) * 128 + 64;
        if (progress >= segmentCycles)
        {
            completed = target;
            target = null;
            progress = 0;
            completedEdges++;
        }
    }

    public RoutePlanner.Node planningNode() { return target == null ? completed : target; }
    /** The steps not yet begun, in order, from planningNode(). */
    public List<RoutePlanner.Node> remainingSteps() { return new ArrayList<>(route); }
    public RoutePlanner.Node completedNode() { return completed; }
    public RoutePlanner.Node destinationNode() { return route.isEmpty() ? planningNode() : route.peekLast(); }
    public boolean isMoving() { return target != null || !route.isEmpty(); }
    public boolean isSegmentInFlight() { return target != null; }
    public RoutePlanner.Node nextUnenteredNode() { return target == null ? route.peekFirst() : null; }
    public boolean isRunning() { return target != null ? segmentCycles == 15 : running; }
    public boolean isBlocked() { return blocked; }
    public double getX() { return x; }
    public double getY() { return y; }
    public long getCompletedEdges() { return completedEdges; }
    public int getBearing()
    {
        if (target != null)
        {
            return MotionMath.bearing(target.x - completed.x, target.y - completed.y);
        }
        RoutePlanner.Node next = route.peekFirst();
        return next == null || completed == null ? 0 : MotionMath.bearing(next.x - completed.x, next.y - completed.y);
    }

    public void clear()
    {
        route.clear();
        completed = target = null;
        progress = 0;
        blocked = false;
    }
}

package com.malfoid.motion;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/** One bounded reachable expansion can choose a scored endpoint or a nearer frontier. */
public final class RoutePlanner
{
    public static final int RADIUS = 12;
    public static final int MAX_CELLS = 625;
    public static final int MAX_STEPS = 24;
    private static final int WIDTH = RADIUS * 2 + 1;
    private static final int[] DX = {0, -1, 0, 1, -1, -1, 1, 1};
    private static final int[] DY = {-1, 0, 1, 0, -1, 1, 1, -1};
    private final int[] queue = new int[MAX_CELLS];
    private final int[] predecessor = new int[MAX_CELLS];
    private final int[] depth = new int[MAX_CELLS];

    public interface Collision
    {
        boolean isLegal(int x, int y);
        boolean canTravel(int x, int y, int dx, int dy);
    }

    public interface Goal
    {
        /** Negative means unsuitable. Higher scores are preferred. */
        double score(int x, int y, int steps);
        /** Lower means closer to an unreachable or out-of-window target. */
        int distance(int x, int y);
        /** Expensive courtesy checks run only on the eight best reachable candidates. */
        default double refineScore(int x, int y, int steps, double score) { return score; }
    }

    public static final class Node
    {
        public final int x, y;
        public Node(int x, int y) { this.x = x; this.y = y; }
        @Override public boolean equals(Object other)
        {
            return other instanceof Node && x == ((Node) other).x && y == ((Node) other).y;
        }
        @Override public int hashCode() { return x * 31 + y; }
    }

    public enum Status { AT_GOAL, ROUTE, FRONTIER, BLOCKED, BUDGET_EXHAUSTED, SCENE_UNAVAILABLE }

    public static final class Result
    {
        public final Status status;
        public final List<Node> steps;
        public final int visited;
        public final boolean searchLimited;
        private Result(Status status, List<Node> steps, int visited, boolean searchLimited)
        {
            this.status = status;
            this.steps = Collections.unmodifiableList(steps);
            this.visited = visited;
            this.searchLimited = searchLimited;
        }
    }

    public Result plan(Collision collision, Node start, Goal goal)
    {
        if (collision == null || !collision.isLegal(start.x, start.y))
        {
            return new Result(Status.SCENE_UNAVAILABLE, Collections.emptyList(), 0, false);
        }
        Arrays.fill(predecessor, -2);
        int root = RADIUS * WIDTH + RADIUS;
        queue[0] = root;
        predecessor[root] = -1;
        depth[root] = 0;
        int head = 0, tail = 1, best = -1, frontier = root;
        int[] candidates = new int[8];
        double[] scores = new double[8];
        Arrays.fill(candidates, -1);
        Arrays.fill(scores, -1);
        boolean limited = false;
        int frontierDistance = goal.distance(start.x, start.y);
        while (head < tail)
        {
            int cell = queue[head++];
            int x = start.x + cell % WIDTH - RADIUS;
            int y = start.y + cell / WIDTH - RADIUS;
            double score = goal.score(x, y, depth[cell]);
            if (score >= 0)
            {
                for (int rank = 0; rank < candidates.length; rank++)
                {
                    if (score > scores[rank])
                    {
                        for (int lower = candidates.length - 1; lower > rank; lower--)
                        {
                            candidates[lower] = candidates[lower - 1];
                            scores[lower] = scores[lower - 1];
                        }
                        candidates[rank] = cell;
                        scores[rank] = score;
                        break;
                    }
                }
            }
            int distance = goal.distance(x, y);
            if (distance < frontierDistance)
            {
                frontier = cell;
                frontierDistance = distance;
            }
            for (int direction = 0; direction < 8; direction++)
            {
                int cx = cell % WIDTH + DX[direction], cy = cell / WIDTH + DY[direction];
                if (cx < 0 || cy < 0 || cx >= WIDTH || cy >= WIDTH)
                {
                    if (collision.isLegal(x + DX[direction], y + DY[direction])
                        && collision.canTravel(x, y, DX[direction], DY[direction]))
                    {
                        limited = true;
                    }
                    continue;
                }
                int next = cy * WIDTH + cx;
                if (predecessor[next] != -2 || !collision.isLegal(x + DX[direction], y + DY[direction])
                    || !collision.canTravel(x, y, DX[direction], DY[direction]))
                {
                    continue;
                }
                if (depth[cell] == MAX_STEPS)
                {
                    limited = true;
                    continue;
                }
                predecessor[next] = cell;
                depth[next] = depth[cell] + 1;
                queue[tail++] = next;
            }
        }
        double bestScore = -1;
        for (int rank = 0; rank < candidates.length && candidates[rank] >= 0; rank++)
        {
            int cell = candidates[rank];
            double refined = goal.refineScore(start.x + cell % WIDTH - RADIUS, start.y + cell / WIDTH - RADIUS,
                depth[cell], scores[rank]);
            if (refined >= 0 && refined > bestScore)
            {
                best = cell;
                bestScore = refined;
            }
        }
        boolean reached = best >= 0;
        int target = reached ? best : frontier;
        List<Node> steps = new ArrayList<>();
        for (int cell = target; predecessor[cell] >= 0; cell = predecessor[cell])
        {
            steps.add(new Node(start.x + cell % WIDTH - RADIUS, start.y + cell / WIDTH - RADIUS));
        }
        Collections.reverse(steps);
        Status status = reached ? (steps.isEmpty() ? Status.AT_GOAL : Status.ROUTE)
            : steps.isEmpty() ? limited ? Status.BUDGET_EXHAUSTED : Status.BLOCKED : Status.FRONTIER;
        return new Result(status, steps, tail, limited);
    }
}

package com.malfoid.motion;

import net.runelite.api.CollisionData;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldArea;

/** Guards every public collision-helper read, including diagonal side tiles. */
public final class SceneCollision implements RoutePlanner.Collision
{
    private final WorldView view;
    private final int plane;
    private final int[][] flags;
    private final int blockedX, blockedY;
    private final boolean complete;

    public SceneCollision(WorldView view, int plane, int blockedX, int blockedY)
    {
        this.view = view;
        this.plane = plane;
        this.blockedX = blockedX;
        this.blockedY = blockedY;
        CollisionData[] maps = view == null ? null : view.getCollisionMaps();
        flags = maps != null && plane >= 0 && plane < maps.length && maps[plane] != null ? maps[plane].getFlags() : null;
        complete = view != null && completeShape(flags, view.getSizeX(), view.getSizeY());
    }

    private static boolean completeShape(int[][] flags, int width, int height)
    {
        if (flags == null || width <= 0 || height <= 0 || flags.length < width) return false;
        for (int x = 0; x < width; x++)
        {
            if (flags[x] == null || flags[x].length < height) return false;
        }
        return true;
    }

    public boolean isAvailable() { return complete && view.getPlane() == plane; }

    public boolean contains(int x, int y)
    {
        return isAvailable() && x >= 0 && y >= 0 && x < view.getSizeX() && y < view.getSizeY()
            && x < flags.length && flags[x] != null && y < flags[x].length;
    }

    @Override public boolean isLegal(int x, int y)
    {
        return contains(x, y) && (flags[x][y] & CollisionDataFlag.BLOCK_MOVEMENT_FULL) == 0
            && (x != blockedX || y != blockedY);
    }

    @Override public boolean canTravel(int x, int y, int dx, int dy)
    {
        if ((dx == 0 && dy == 0) || Math.abs(dx) > 1 || Math.abs(dy) > 1
            || !contains(x, y) || !isLegal(x + dx, y + dy))
        {
            return false;
        }
        if (dx != 0 && dy != 0 && (!contains(x + dx, y) || !contains(x, y + dy)))
        {
            return false;
        }
        return new WorldArea(view.getBaseX() + x, view.getBaseY() + y, 1, 1, plane)
            .canTravelInDirection(view, dx, dy);
    }

    /** Missing cells are unknown, rather than evidence that a previously legal edge became blocked. */
    public boolean hasEdgeData(int x, int y, int dx, int dy)
    {
        return Math.abs(dx) <= 1 && Math.abs(dy) <= 1 && (dx != 0 || dy != 0)
            && contains(x, y) && contains(x + dx, y + dy)
            && (dx == 0 || dy == 0 || contains(x + dx, y) && contains(x, y + dy));
    }

    public int neighborhoodFingerprint(int x, int y)
    {
        int hash = 1;
        for (int dx = -1; dx <= 1; dx++)
        {
            for (int dy = -1; dy <= 1; dy++)
            {
                hash = 31 * hash + (contains(x + dx, y + dy) ? flags[x + dx][y + dy] : -1);
            }
        }
        return hash;
    }
}

package com.malfoid.motion;

/** Conservative projection of the complete pose-bank union, rather than only a foot or head anchor. */
public final class WholeBoundsVisibility
{
    public enum Visibility { UNKNOWN, VISIBLE, OFF_SCREEN }

    public interface Projector
    {
        /** Outputs camera x, camera y and depth for scene x, scene y and vertical z. */
        boolean project(double x, double y, double z, double[] output);
    }

    public static final class Bounds
    {
        public final double minX, minY, minZ, maxX, maxY, maxZ;
        public Bounds(double minX, double minY, double minZ, double maxX, double maxY, double maxZ)
        {
            this.minX = minX; this.minY = minY; this.minZ = minZ;
            this.maxX = maxX; this.maxY = maxY; this.maxZ = maxZ;
        }
    }

    private WholeBoundsVisibility() {}

    public static Visibility classify(Bounds bounds, double sceneX, double sceneY, double drawZ, int orientation,
        Projector projector, int viewportX, int viewportY, int width, int height, int scale)
    {
        if (bounds == null || projector == null || width <= 0 || height <= 0 || scale <= 0
            || !Double.isFinite(sceneX) || !Double.isFinite(sceneY) || !Double.isFinite(drawZ))
        {
            return Visibility.UNKNOWN;
        }
        double radians = (orientation & 2047) * Math.PI / 1024;
        double sin = Math.sin(radians), cos = Math.cos(radians);
        double minCanvasX = Double.POSITIVE_INFINITY, minCanvasY = Double.POSITIVE_INFINITY;
        double maxCanvasX = Double.NEGATIVE_INFINITY, maxCanvasY = Double.NEGATIVE_INFINITY;
        int inFront = 0;
        double[] projection = new double[3];
        for (int corner = 0; corner < 8; corner++)
        {
            double x = (corner & 1) == 0 ? bounds.minX : bounds.maxX;
            double y = (corner & 2) == 0 ? bounds.minY : bounds.maxY;
            double z = (corner & 4) == 0 ? bounds.minZ : bounds.maxZ;
            if (!projector.project(sceneX + x * cos + z * sin, sceneY + z * cos - x * sin, drawZ + y, projection)
                || !Double.isFinite(projection[0]) || !Double.isFinite(projection[1]) || !Double.isFinite(projection[2]))
            {
                return Visibility.UNKNOWN;
            }
            if (projection[2] < 50)
            {
                continue;
            }
            inFront++;
            double canvasX = viewportX + width / 2d + projection[0] * scale / projection[2];
            double canvasY = viewportY + height / 2d + projection[1] * scale / projection[2];
            if (!Double.isFinite(canvasX) || !Double.isFinite(canvasY))
            {
                return Visibility.UNKNOWN;
            }
            minCanvasX = Math.min(minCanvasX, canvasX);
            maxCanvasX = Math.max(maxCanvasX, canvasX);
            minCanvasY = Math.min(minCanvasY, canvasY);
            maxCanvasY = Math.max(maxCanvasY, canvasY);
        }
        if (inFront == 0)
        {
            return Visibility.OFF_SCREEN;
        }
        if (inFront != 8)
        {
            // Near-plane crossings can expose a clipped face even when every projected corner is outside.
            return Visibility.UNKNOWN;
        }
        // The bank union is already padded in model space; retain a screen margin for native rounding.
        return maxCanvasX < viewportX - 4 || minCanvasX > viewportX + width + 4
            || maxCanvasY < viewportY - 4 || minCanvasY > viewportY + height + 4
            ? Visibility.OFF_SCREEN : Visibility.VISIBLE;
    }
}

package com.malfoid.presence;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Immutable bounded client-thread copy. Rendering never dereferences a live widget. */
public final class ModalOcclusionSnapshot
{
	public static final int MAX_ROOTS = 16;
	public static final ModalOcclusionSnapshot CLEAR = new ModalOcclusionSnapshot(true, Collections.emptyList());
	public static final ModalOcclusionSnapshot UNKNOWN = new ModalOcclusionSnapshot(false, Collections.emptyList());
	private final boolean known;
	private final List<Rectangle> bounds;

	public ModalOcclusionSnapshot(boolean known, List<Rectangle> copiedBounds)
	{
		List<Rectangle> copy = new ArrayList<>();
		boolean valid = known && copiedBounds != null && copiedBounds.size() <= MAX_ROOTS;
		if (valid)
		{
			for (Rectangle rectangle : copiedBounds)
			{
				if (!validBounds(rectangle)) { valid = false; break; }
				copy.add(new Rectangle(rectangle));
			}
		}
		this.known = valid;
		bounds = valid ? Collections.unmodifiableList(copy) : Collections.emptyList();
	}
	public boolean isKnown() { return known; }

	/** Unknown or invalid queried pixel geometry cannot authorize a first paint. */
	public boolean intersects(Rectangle canvasBounds)
	{
		if (!known || !validBounds(canvasBounds)) { return true; }
		for (Rectangle rectangle : bounds) { if (rectangle.intersects(canvasBounds)) { return true; } }
		return false;
	}
	/** For inspection/tests only. Renderers can call intersects without making further copies. */
	public List<Rectangle> getBounds()
	{
		List<Rectangle> copy = new ArrayList<>(bounds.size());
		for (Rectangle rectangle : bounds) { copy.add(new Rectangle(rectangle)); }
		return Collections.unmodifiableList(copy);
	}
	static boolean validBounds(Rectangle rectangle)
	{
		return rectangle != null && rectangle.width > 0 && rectangle.height > 0
			&& (long) rectangle.x + rectangle.width <= Integer.MAX_VALUE && (long) rectangle.y + rectangle.height <= Integer.MAX_VALUE;
	}
}

package com.malfoid.presence;

import java.util.EnumSet;
import net.runelite.api.Client;
import net.runelite.api.WorldType;
import net.runelite.api.gameval.VarbitID;

/** E.4: world/zone signals alone decide whether cosmetic behaviour may read other players. */
public final class OtherPlayerPolicy
{
	private OtherPlayerPolicy() { }

	public static boolean ignoreOtherPlayers(Client client)
	{
		EnumSet<WorldType> types = client.getWorldType();
		return client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 1
			|| types != null && WorldType.isPvpWorld(types);
	}
}

package com.malfoid.presence;

import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.util.Text;

/** E.4 combat evidence only. No opponent identity, position, count, gear or actions are retained. */
final class PlayerCombat
{
	private final Client client;
	private long lastCommit = -1, lastEvidenceTick = -1, lastIncomingTargetTick = -1;
	private long quietCompletedTick = -1;
	private int quietTicks;
	private boolean active;

	PlayerCombat(Client client) { this.client = client; }

	boolean onMenuOptionClicked(MenuOptionClicked event, long tick)
	{
		Player local = localPlayer();
		MenuEntry entry = event == null ? null : event.getMenuEntry();
		String option = entry == null ? null : entry.getOption();
		if (local == null || option == null || !"Attack".equalsIgnoreCase(Text.removeTags(option).trim())
			|| !isPlayerOption(entry.getType())) { return false; }
		Player target = entry.getPlayer();
		return target != null && target != local && evidence(tick);
	}

	boolean onHitsplatApplied(HitsplatApplied event, long tick)
	{
		Player local = localPlayer();
		Actor actor = event == null ? null : event.getActor();
		Hitsplat hit = event == null ? null : event.getHitsplat();
		if (local == null || actor == null || hit == null) { return false; }
		if (actor != local && actor instanceof Player && hit.isMine()) { return evidence(tick); }
		if (actor != local) { return false; }
		sampleIncomingTarget(local, tick);
		return lastIncomingTargetTick >= 0 && tick >= lastIncomingTargetTick
			&& tick - lastIncomingTargetTick <= 2 && evidence(tick);
	}

	void onInteractingChanged(InteractingChanged event, long tick)
	{
		Player local = localPlayer();
		if (local != null && event != null && event.getSource() instanceof Player
			&& event.getSource() != local && event.getTarget() == local)
		{
			lastIncomingTargetTick = Math.max(lastIncomingTargetTick, tick);
		}
	}

	/** The hundredth evidence-free commit completes the wait; normal stability starts afterwards. */
	boolean commit(long tick)
	{
		Player local = localPlayer();
		Boolean incoming = local == null ? null : sampleIncomingTarget(local, tick);
		if (tick > lastCommit)
		{
			lastCommit = tick;
			if (active && local != null && incoming != null && tick > lastEvidenceTick)
			{
				quietTicks = Math.min(100, quietTicks + 1);
				if (quietTicks == 100 && quietCompletedTick < 0) { quietCompletedTick = tick; }
			}
		}
		return isActive();
	}

	/** Inspection rechecks current targets during stability, but cannot advance the quiet interval. */
	boolean isActive()
	{
		if (!active) { return false; }
		if (quietTicks < 100 || lastCommit <= quietCompletedTick) { return true; }
		Player local = localPlayer();
		Boolean incoming = local == null ? null : sampleIncomingTarget(local, lastCommit);
		return incoming == null || incoming || local.getInteracting() instanceof Player;
	}

	void returned() { active = false; }

	void invalidateScene() { lastIncomingTargetTick = -1; }

	void reset()
	{
		lastCommit = lastEvidenceTick = lastIncomingTargetTick = -1;
		quietCompletedTick = -1;
		quietTicks = 0; active = false;
	}

	private boolean evidence(long tick)
	{
		lastEvidenceTick = Math.max(lastEvidenceTick, tick);
		quietTicks = 0; quietCompletedTick = -1; active = true;
		return true;
	}

	private Player localPlayer()
	{
		return client.getGameState() == GameState.LOGGED_IN ? client.getLocalPlayer() : null;
	}

	/** These target relations are the only permitted other-player reads, for evidence and return. */
	private Boolean sampleIncomingTarget(Player local, long tick)
	{
		WorldView view = local.getWorldView();
		Iterable<? extends Player> players = view == null ? null : view.players();
		if (players == null) { return null; }
		for (Player other : players)
		{
			if (other != null && other != local && other.getInteracting() == local)
			{
				lastIncomingTargetTick = Math.max(lastIncomingTargetTick, tick);
				return true;
			}
		}
		return false;
	}

	private static boolean isPlayerOption(MenuAction action)
	{
		return action == MenuAction.PLAYER_FIRST_OPTION || action == MenuAction.PLAYER_SECOND_OPTION
			|| action == MenuAction.PLAYER_THIRD_OPTION || action == MenuAction.PLAYER_FOURTH_OPTION
			|| action == MenuAction.PLAYER_FIFTH_OPTION || action == MenuAction.PLAYER_SIXTH_OPTION
			|| action == MenuAction.PLAYER_SEVENTH_OPTION || action == MenuAction.PLAYER_EIGHTH_OPTION;
	}
}

