/** Scene-local combat histories contain copied facts, never actors or inferred kill credit. */
final class CombatExpansionRules
{
	private static final Skill[] FIELDS = {Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.RANGED, Skill.MAGIC};
	private final Deque<Incoming> incoming = new ArrayDeque<>();
	private final Deque<DeathRecord> deaths = new ArrayDeque<>();
	private final EnumMap<Skill, FieldGain> fields = new EnumMap<>(Skill.class);
	private Engagement engagement;
	private ReturnSequence returning;
	private QuietArm quiet, issuedQuiet;
	private long continuityEpoch, engagementEpoch, activityEpoch, hpEpoch, levelEpoch, evidenceEpoch, sequenceDataEpoch, quietEpoch;
	private long lastHitId = -1, lastDeathId = -1, overflowUntil = -1;
	private long lastTick = -1, session, scene, presence;
	private ScenarioSnapshot last;
	private boolean fieldsHandled;

	List<SceneCandidate> close(ScenarioSnapshot f, ScenarioSnapshot prior, ScenarioBatch batch, List<SkillDelta> deltas,
		CombatState combat, long lastDamage, ExpandedScenarioRules.Factory factory)
	{
		List<SceneCandidate> out = new ArrayList<>();
		if (!complete(f) || batch.localDeath || batch.targetChangesUnknown || combat == CombatState.UNKNOWN)
		{
			reset(); return out;
		}
		if (last != null && (f.tick != lastTick + 1 || f.sessionGeneration != session || f.sceneRevision != scene
			|| f.presentSinceTick != presence || f.player.distance(last.player) > 2)) { reset(); }
		last = f; lastTick = f.tick; session = f.sessionGeneration; scene = f.sceneRevision; presence = f.presentSinceTick;
		List<Hit> hits = freshHits(batch.hits);
		List<NpcDeath> reportedDeaths = freshDeaths(batch.npcDeaths);
		boolean localPositive = false, freshEvidence = false, heavy = false;
		for (Hit hit : hits)
		{
			if (hit.local && hit.amount > 0) { localPositive = true; }
			if ((hit.local || hit.mine && hit.npcKey != null) && DamageTypes.combat(hit.type)) { freshEvidence = true; }
			if (hit.local && hit.amount > 0 && DamageTypes.hpDamage(hit.type)
				&& hit.amount >= DamageTypes.largeHitThreshold(f.realHp)) { heavy = true; }
		}
		if (freshEvidence || localPositive) { evidenceEpoch++; }
		if (localPositive || prior != null && prior.currentHp != f.currentHp) { hpEpoch++; }
		boolean selectedLevel = false, changedCombatLevel = false, knownFields = prior != null;
		for (SkillDelta delta : deltas)
		{
			if (delta.delta > 0 && delta.newLevel > delta.oldLevel && batch.witnessedSkills.contains(delta.skill)) { selectedLevel = true; }
			if (supported(delta.skill) && delta.newLevel != delta.oldLevel) { changedCombatLevel = true; }
		}
		for (Skill skill : FIELDS)
		{
			knownFields &= prior != null && prior.xp(skill) >= 0 && prior.level(skill) > 0 && f.xp(skill) >= 0 && f.level(skill) > 0;
		}
		if (selectedLevel || changedCombatLevel || !knownFields) { levelEpoch++; fields.clear(); }
		boolean emergency = f.emergencySceneActive || heavy;
		if (engagement != null)
		{
			for (Hit hit : hits)
			{
				if (hit.local && hit.witnessed && hit.amount > 0 && DamageTypes.hpDamage(hit.type)) { engagement.injuryId = hit.id; }
			}
		}
		boolean same = sameLiveTarget(prior, f) && batch.localTargetChanges.isEmpty() && !batch.engagementInterrupted;
		boolean directSwitch = prior != null && live(prior) && live(f) && !prior.target.key.equals(f.target.key)
			&& batch.localTargetChanges.size() == 1 && f.target.key.equals(batch.localTargetChanges.get(0));
		if (!same) { engagementEpoch++; incoming.clear(); overflowUntil = -1; fields.clear(); fieldsHandled = false; }

		// A death must use the previous commit's owned evidence, before considering this batch's hits.
		NpcDeath terminal = null;
		if (prior != null && live(prior) && engagement != null && engagement.key.equals(prior.target.key))
		{
			for (NpcDeath death : reportedDeaths)
			{
				if (death.witnessed && engagement.key.equals(death.npcKey)) { terminal = death; break; }
			}
		}
		boolean newConfirmedTarget = live(f) && combat == CombatState.CONFIRMED
			&& (terminal == null || !f.target.key.equals(terminal.npcKey)) && !same;
		if (newConfirmedTarget) { activityEpoch++; }
		boolean freshInteraction = batch.engagementInterrupted || !batch.localTargetChanges.isEmpty();
		if (issuedQuiet != null && (live(f) || f.target != null
			|| combat != CombatState.NO_CONFIRMED_EVIDENCE || freshEvidence || localPositive || freshInteraction || !deficit(f, issuedQuiet)))
		{
			issuedQuiet = null; quietEpoch++;
		}
		if (terminal != null)
		{
			observedDeaths(f, prior, terminal, emergency, newConfirmedTarget, factory, out);
			equalEndpoints(f, terminal, localPositive, emergency, newConfirmedTarget || !terminalTransition(batch, terminal.npcKey), factory, out);
		}

		if (quiet != null) { quietGap(f, combat, lastDamage, freshEvidence || localPositive || freshInteraction, emergency, factory, out); }
		if (engagement != null && f.target == null && prior != null && prior.target != null
			&& engagement.key.equals(prior.target.key) && !emergency && nullTransition(batch))
		{
			if (engagement.span >= 30 && engagement.span <= 120 && engagement.hitTicks.size() >= 6 && !engagement.realHpChanged
				&& engagement.realHp == f.realHp && f.currentHp > 0 && engagement.startHp - f.currentHp >= quarter(f.realHp))
			{
				quietEpoch++;
				quiet = new QuietArm(engagement, f);
			}
		}
		if (!same || terminal != null)
		{
			engagement = null;
		}
		else if (engagement != null)
		{
			engagement.span = Math.min(121, engagement.span + 1);
			if (engagement.realHp != f.realHp) { engagement.realHpChanged = true; }
			if (engagement.realHp != f.realHp || localPositive || engagement.span > 120) { engagement.endpointInvalid = true; }
			engagement.name = f.target.name;
		}

		Hit owned = null;
		if (live(f) && (terminal == null || !f.target.key.equals(terminal.npcKey)))
		{
			for (Hit hit : hits)
			{
				if (ownedPositive(hit, f) && (owned == null || hit.id < owned.id)) { owned = hit; }
			}
			if (owned != null)
			{
				if (engagement == null)
				{
					engagement = new Engagement(f, owned);
					if (!newConfirmedTarget) { activityEpoch++; }
				}
				engagement.record(f.tick);
			}
			if (engagement != null)
			{
				if (localPositive) { engagement.endpointInvalid = true; }
				for (Hit hit : hits)
				{
					if (hit.local && hit.witnessed && hit.amount > 0 && DamageTypes.hpDamage(hit.type)) { engagement.injuryId = hit.id; }
				}
			}
		}
		returnSequence(f, prior, batch, directSwitch, owned, emergency, factory, out);
		coincidence(f, hits, emergency, combat, factory, out);
		combatFields(f, batch, deltas, owned, knownFields && !changedCombatLevel && !selectedLevel, emergency, combat, factory, out);
		return out;
	}

	private void returnSequence(ScenarioSnapshot f, ScenarioSnapshot prior, ScenarioBatch batch, boolean directSwitch,
		Hit owned, boolean emergency, ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		if (f.liveNpcKeys == null)
		{
			returning = null; sequenceDataEpoch++; return;
		}
		for (NpcDeath death : batch.npcDeaths)
		{
			if (returning != null && (returning.a.equals(death.npcKey) || returning.b != null && returning.b.equals(death.npcKey)))
			{
				returning = null; sequenceDataEpoch++;
			}
			if (f.target != null && f.target.key.equals(death.npcKey)) { owned = null; }
		}
		if (returning != null && (f.tick - returning.first.tick >= 20 || !f.liveNpcKeys.contains(returning.a)
			|| returning.b != null && !f.liveNpcKeys.contains(returning.b))) { returning = null; }
		boolean changed = prior == null || !sameLiveTarget(prior, f) || batch.engagementInterrupted || !batch.localTargetChanges.isEmpty();
		if (returning != null && changed)
		{
			if (directSwitch && returning.segment == 0 && returning.a.equals(prior.target.key) && !returning.a.equals(f.target.key))
			{
				returning.b = f.target.key; returning.segment = 1;
			}
			else if (directSwitch && returning.segment == 1 && returning.b.equals(prior.target.key)
				&& returning.a.equals(f.target.key) && returning.second != null) { returning.segment = 2; }
			else { returning = null; }
		}
		if (!live(f) || !f.liveNpcKeys.contains(f.target.key) || owned == null) { return; }
		if (returning == null)
		{
			returning = new ReturnSequence(f.target.key, new OwnedTick(f.tick, owned.id)); return;
		}
		if (returning.segment == 1 && returning.second == null && f.tick > returning.first.tick)
		{
			returning.second = new OwnedTick(f.tick, owned.id);
		}
		else if (returning.segment == 2)
		{
			ReturnSequence sequence = returning; returning = null;
			if (f.tick <= sequence.second.tick || emergency || !settled(f)) { return; }
			Map<String, String> facts = targetFacts(f);
			facts.put("firstNpcKey", sequence.a); facts.put("secondNpcKey", sequence.b);
			facts.put("engagementSequence", sequence.a + "," + sequence.b + "," + sequence.a);
			facts.put("engagementEvidenceTicks", sequence.first.tick + "," + sequence.second.tick + "," + f.tick);
			facts.put("sequenceDataEpoch", Long.toString(sequenceDataEpoch));
			facts.put("engagementEpoch", Long.toString(engagementEpoch));
			out.add(factory.create(f, "M14", 34, 10, "owned:" + owned.id, facts, false, 4));
		}
	}

	private void coincidence(ScenarioSnapshot f, List<Hit> hits, boolean emergency, CombatState combat,
		ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		if (engagement == null || !live(f) || emergency || combat != CombatState.CONFIRMED)
		{
			incoming.clear(); return;
		}
		while (!incoming.isEmpty() && incoming.peekFirst().tick < f.tick - 6) { incoming.removeFirst(); }
		incoming.removeIf(record -> record.realHp != f.realHp);
		List<Incoming> additions = new ArrayList<>();
		for (Hit hit : hits)
		{
			if (hit.local && hit.witnessed && DamageTypes.hpDamage(hit.type) && hit.amount >= 5
				&& hit.amount < DamageTypes.largeHitThreshold(f.realHp)) { additions.add(new Incoming(f.tick, hit.id, hit.amount, f.realHp)); }
		}
		if (f.tick <= overflowUntil) { return; }
		if (incoming.size() + additions.size() > 8)
		{
			incoming.clear(); overflowUntil = f.tick + 6; return;
		}
		Incoming selected = null; Hit outgoing = null;
		for (Hit hit : hits)
		{
			if (!ownedPositive(hit, f)) { continue; }
			for (Incoming record : incoming)
			{
				if (record.tick >= f.tick || record.amount != hit.amount) { continue; }
				if (selected == null || record.amount > selected.amount || record.amount == selected.amount
					&& (record.id < selected.id || record.id == selected.id && hit.id < outgoing.id))
				{
					selected = record; outgoing = hit;
				}
			}
		}
		if (selected != null)
		{
			incoming.remove(selected);
			if (settled(f))
			{
				Map<String, String> facts = targetFacts(f); facts.put("matchingAmount", Integer.toString(selected.amount));
				facts.put("incomingTick", Long.toString(selected.tick)); facts.put("outgoingTick", Long.toString(f.tick));
				facts.put("incomingFactId", Long.toString(selected.id)); facts.put("outgoingFactId", Long.toString(outgoing.id));
				facts.put("engagementEpoch", Long.toString(engagementEpoch)); facts.put("realHp", Integer.toString(f.realHp));
				out.add(factory.create(f, "M15", 38, 10, "owned:" + outgoing.id, facts, false, 4));
			}
		}
		incoming.addAll(additions);
	}

	private void observedDeaths(ScenarioSnapshot f, ScenarioSnapshot prior, NpcDeath death, boolean emergency,
		boolean newTarget, ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		while (!deaths.isEmpty() && deaths.peekFirst().tick < f.tick - 79) { deaths.removeFirst(); }
		long age = f.tick - engagement.lastOwnedTick;
		if (age < 1 || age > 4 || prior.presentSinceTick != f.presentSinceTick) { return; }
		for (DeathRecord record : deaths) { if (record.key.equals(death.npcKey)) { return; } }
		deaths.addLast(new DeathRecord(f.tick, death.id, death.npcKey));
		while (deaths.size() > 3) { deaths.removeFirst(); }
		if (deaths.size() == 3)
		{
			StringBuilder keys = new StringBuilder(), ticks = new StringBuilder();
			for (DeathRecord record : deaths)
			{
				if (keys.length() > 0) { keys.append(','); ticks.append(','); }
				keys.append(record.key); ticks.append(record.tick);
			}
			deaths.clear();
			if (emergency || newTarget || !settled(f)) { return; }
			Map<String, String> facts = baseFacts(f); facts.put("observedEngagedDeaths", "3");
			facts.put("deadNpcKeys", keys.toString()); facts.put("deathTicks", ticks.toString());
			facts.put("terminalDeathFactId", Long.toString(death.id)); facts.put("activityEpoch", Long.toString(activityEpoch));
			out.add(factory.create(f, "M17", 44, 10, "engaged-death:" + death.id, facts, false, 5));
		}
	}

	private void equalEndpoints(ScenarioSnapshot f, NpcDeath death, boolean localPositive, boolean emergency,
		boolean newTarget, ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		long age = f.tick - engagement.lastOwnedTick;
		if (engagement.endpointInvalid || localPositive || engagement.span < 40 || engagement.span > 120
			|| engagement.hitTicks.size() < 8 || age < 1 || age > 2 || engagement.realHp != f.realHp
			|| engagement.startHp != f.currentHp || emergency || newTarget || !settled(f)) { return; }
		Map<String, String> facts = baseFacts(f); facts.put("deadNpcKey", death.npcKey); facts.put("npcResolvedName", engagement.name);
		facts.put("startHp", Integer.toString(engagement.startHp)); facts.put("realHp", Integer.toString(engagement.realHp));
		facts.put("observedEngagementCommits", Integer.toString(engagement.span)); facts.put("terminalDeathFactId", Long.toString(death.id));
		facts.put("activityEpoch", Long.toString(activityEpoch)); facts.put("hpEpoch", Long.toString(hpEpoch));
		out.add(factory.create(f, "M18", 40, 10, "engaged-death:" + death.id, facts, false, 6));
	}

	private void combatFields(ScenarioSnapshot f, ScenarioBatch batch, List<SkillDelta> deltas, Hit owned, boolean known,
		boolean emergency, CombatState combat, ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		if (!known || engagement == null || !live(f) || combat != CombatState.CONFIRMED) { fields.clear(); return; }
		fields.entrySet().removeIf(entry -> entry.getValue().tick < f.tick - 19);
		SkillDelta selected = null; int count = 0;
		for (SkillDelta delta : deltas)
		{
			if (supported(delta.skill) && delta.delta > 0) { selected = delta; count++; }
		}
		if (count != 1 || owned == null || !batch.witnessedSkills.contains(selected.skill) || fieldsHandled) { return; }
		fields.put(selected.skill, new FieldGain(f.tick, selected.skill, selected.delta, owned.id));
		if (fields.size() < 3) { return; }
		fieldsHandled = true;
		if (emergency || !settled(f)) { return; }
		List<FieldGain> selectedFields = new ArrayList<>(fields.values());
		selectedFields.sort(Comparator.comparingLong((FieldGain gain) -> gain.tick).thenComparingInt(gain -> gain.skill.ordinal()));
		selectedFields = new ArrayList<>(selectedFields.subList(0, 3));
		StringBuilder order = new StringBuilder(), ticks = new StringBuilder(), amounts = new StringBuilder(), proofs = new StringBuilder();
		for (FieldGain gain : selectedFields)
		{
			if (order.length() > 0) { order.append(','); ticks.append(','); amounts.append(','); proofs.append(','); }
			order.append(gain.skill.name()); ticks.append(gain.tick); amounts.append(gain.delta); proofs.append(gain.ownedFactId);
		}
		selectedFields.sort(Comparator.comparingInt(gain -> gain.skill.ordinal()));
		StringBuilder subject = new StringBuilder();
		for (FieldGain gain : selectedFields) { if (subject.length() > 0) { subject.append(','); } subject.append(gain.skill.name()); }
		Map<String, String> facts = targetFacts(f); facts.put("skillSet", subject.toString()); facts.put("fieldOrder", order.toString());
		facts.put("gainTicks", ticks.toString()); facts.put("gainDeltas", amounts.toString()); facts.put("gainOwnedFactIds", proofs.toString());
		facts.put("engagementEpoch", Long.toString(engagementEpoch));
		facts.put("levelEpoch", Long.toString(levelEpoch)); facts.put("ownedFactId", Long.toString(owned.id));
		out.add(factory.create(f, "M19", 36, 12, "progress:" + f.tick, facts, false, 5));
	}

	private void quietGap(ScenarioSnapshot f, CombatState combat, long lastDamage, boolean fresh, boolean emergency,
		ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		if (f.tick >= quiet.expires || f.target != null || fresh || emergency || !deficit(f, quiet)) { quiet = null; return; }
		if (f.tick <= quiet.nullTick) { return; }
		if (combat == CombatState.CONFIRMED)
		{
			if (quiet.calm > 0 || f.tick >= quiet.nullTick + 10) { quiet = null; }
			return;
		}
		if (combat != CombatState.NO_CONFIRMED_EVIDENCE || quiet.calm == 0 && f.tick > quiet.nullTick + 10) { quiet = null; return; }
		quiet.calm++;
		if (quiet.calm < 10) { return; }
		QuietArm ready = quiet; quiet = null;
		if (f.tick - lastDamage < 10) { return; }
		issuedQuiet = ready;
		Map<String, String> facts = baseFacts(f); facts.put("startHp", Integer.toString(ready.startHp)); facts.put("endHp", Integer.toString(ready.endHp));
		facts.put("observedHp", Integer.toString(f.currentHp)); facts.put("realHp", Integer.toString(ready.realHp));
		facts.put("nullTick", Long.toString(ready.nullTick)); facts.put("armExpiresTick", Long.toString(ready.nullTick + 20));
		facts.put("calmSnapshots", "10"); facts.put("quietEpoch", Long.toString(quietEpoch)); facts.put("evidenceEpoch", Long.toString(evidenceEpoch));
		String cause = ready.injuryId > 0 ? "injury:" + ready.injuryId : "engagement-end:" + ready.startFactId;
		out.add(factory.create(f, "M20", 55, 12, cause, facts, false, 8));
	}

	boolean stillValid(SceneCandidate candidate, ScenarioSnapshot f, CombatState combat, long lastDamage)
	{
		if (!complete(f) || f.emergencySceneActive || combat == CombatState.UNKNOWN
			|| f.sessionGeneration != candidate.getSessionGeneration() || f.sceneRevision != candidate.getSceneRevision()) { return false; }
		Map<String, String> facts = candidate.getConditionFacts(); String id = candidate.getScenarioId();
		if (!Long.toString(continuityEpoch).equals(facts.get("combatContinuityEpoch"))
			|| !Long.toString(f.presentSinceTick).equals(facts.get("witnessPresenceEpoch"))) { return false; }
		if ("M14".equals(id) || "M15".equals(id) || "M19".equals(id))
		{
			if (!live(f) || combat != CombatState.CONFIRMED || !f.target.key.equals(facts.get("targetKey"))
				|| !f.target.name.equals(facts.get("npcResolvedName")) || !Long.toString(engagementEpoch).equals(facts.get("engagementEpoch"))) { return false; }
			if ("M14".equals(id))
			{
				return f.liveNpcKeys != null && f.liveNpcKeys.contains(facts.get("firstNpcKey"))
					&& f.liveNpcKeys.contains(facts.get("secondNpcKey")) && Long.toString(sequenceDataEpoch).equals(facts.get("sequenceDataEpoch"));
			}
			if ("M15".equals(id)) { return Integer.toString(f.realHp).equals(facts.get("realHp")); }
			return Long.toString(levelEpoch).equals(facts.get("levelEpoch"));
		}
		if ("M17".equals(id) || "M18".equals(id))
		{
			if (!Long.toString(activityEpoch).equals(facts.get("activityEpoch"))) { return false; }
			if (live(f) && combat == CombatState.CONFIRMED && !f.target.key.equals(facts.get("deadNpcKey"))) { return false; }
			return !"M18".equals(id) || Integer.toString(f.currentHp).equals(facts.get("startHp"))
				&& Integer.toString(f.realHp).equals(facts.get("realHp")) && Long.toString(hpEpoch).equals(facts.get("hpEpoch"));
		}
		if ("M20".equals(id))
		{
			return issuedQuiet != null && f.target == null && combat == CombatState.NO_CONFIRMED_EVIDENCE
				&& f.tick - lastDamage >= 10 && deficit(f, issuedQuiet) && Long.toString(quietEpoch).equals(facts.get("quietEpoch"))
				&& Long.toString(evidenceEpoch).equals(facts.get("evidenceEpoch"));
		}
		return false;
	}

	void reset()
	{
		continuityEpoch++; engagementEpoch++; activityEpoch++; quietEpoch++;
		engagement = null; returning = null; quiet = null; issuedQuiet = null;
		incoming.clear(); deaths.clear(); fields.clear(); fieldsHandled = false;
		last = null; lastTick = -1; overflowUntil = -1;
	}
	private List<Hit> freshHits(List<Hit> reported)
	{
		List<Hit> fresh = new ArrayList<>(); Set<Long> unique = new HashSet<>(); long high = lastHitId;
		for (Hit hit : reported)
		{
			if (hit.id > lastHitId && unique.add(hit.id)) { fresh.add(hit); high = Math.max(high, hit.id); }
		}
		lastHitId = high; fresh.sort(Comparator.comparingLong(hit -> hit.id)); return fresh;
	}
	private List<NpcDeath> freshDeaths(List<NpcDeath> reported)
	{
		List<NpcDeath> fresh = new ArrayList<>(); Set<String> unique = new HashSet<>(); long high = lastDeathId;
		for (NpcDeath death : reported)
		{
			if (death.id > lastDeathId) { high = Math.max(high, death.id); }
			if (death.id > lastDeathId && death.npcKey != null && unique.add(death.npcKey)) { fresh.add(death); high = Math.max(high, death.id); }
		}
		lastDeathId = high; fresh.sort(Comparator.comparingLong(death -> death.id)); return fresh;
	}
	private static boolean complete(ScenarioSnapshot f)
	{
		return f != null && f.valid && f.present && !f.dead && f.player != null && f.currentHp > 0 && f.realHp > 0
			&& !f.targetUnknown && (f.target == null || f.target.key != null && f.target.name != null && !f.target.name.trim().isEmpty());
	}
	private static boolean live(ScenarioSnapshot f) { return f != null && f.target != null && f.target.alive && f.target.key != null && f.target.name != null; }
	private static boolean sameLiveTarget(ScenarioSnapshot a, ScenarioSnapshot b) { return live(a) && live(b) && a.target.key.equals(b.target.key); }
	private static boolean settled(ScenarioSnapshot f) { return f.tick - f.presentSinceTick >= 10; }
	private static boolean ownedPositive(Hit hit, ScenarioSnapshot f)
	{
		return hit.mine && hit.witnessed && !hit.local && f.target.key.equals(hit.npcKey) && hit.amount > 0 && DamageTypes.hpDamage(hit.type);
	}
	private static boolean nullTransition(ScenarioBatch batch)
	{
		return !batch.targetChangesUnknown && (batch.localTargetChanges.isEmpty() && !batch.engagementInterrupted
			|| batch.localTargetChanges.size() == 1 && batch.localTargetChanges.get(0) == null);
	}
	private static boolean terminalTransition(ScenarioBatch batch, String key)
	{
		return batch.localTargetChanges.isEmpty() && !batch.engagementInterrupted || batch.localTargetChanges.size() == 1
			&& (batch.localTargetChanges.get(0) == null || key.equals(batch.localTargetChanges.get(0)));
	}
	private static int quarter(int hp) { return (hp + 3) / 4; }
	private static boolean deficit(ScenarioSnapshot f, QuietArm arm) { return f.realHp == arm.realHp && f.currentHp > 0 && arm.startHp - f.currentHp >= quarter(f.realHp); }
	private static boolean supported(Skill skill)
	{
		for (Skill field : FIELDS) { if (field == skill) { return true; } } return false;
	}
	private Map<String, String> baseFacts(ScenarioSnapshot f)
	{
		Map<String, String> facts = new HashMap<>(); facts.put("actualRegion", Integer.toString(f.player.region()));
		facts.put("combatContinuityEpoch", Long.toString(continuityEpoch)); facts.put("witnessPresenceEpoch", Long.toString(f.presentSinceTick)); return facts;
	}
	private Map<String, String> targetFacts(ScenarioSnapshot f)
	{
		Map<String, String> facts = baseFacts(f); facts.put("targetKey", f.target.key); facts.put("npcResolvedName", f.target.name); return facts;
	}
	private static final class OwnedTick
	{
		final long tick, id;
		OwnedTick(long tick, long id) { this.tick = tick; this.id = id; }
	}
	private static final class ReturnSequence
	{
		final String a; final OwnedTick first; String b; OwnedTick second; int segment;
		ReturnSequence(String a, OwnedTick first) { this.a = a; this.first = first; }
	}
	private static final class Incoming
	{
		final long tick, id; final int amount, realHp;
		Incoming(long tick, long id, int amount, int realHp) { this.tick = tick; this.id = id; this.amount = amount; this.realHp = realHp; }
	}
	private static final class DeathRecord
	{
		final long tick, id; final String key;
		DeathRecord(long tick, long id, String key) { this.tick = tick; this.id = id; this.key = key; }
	}
	private static final class FieldGain
	{
		final long tick, delta, ownedFactId; final Skill skill;
		FieldGain(long tick, Skill skill, long delta, long ownedFactId) { this.tick = tick; this.skill = skill; this.delta = delta; this.ownedFactId = ownedFactId; }
	}
	private static final class Engagement
	{
		final String key; final int startHp, realHp; final long startFactId;
		final Deque<Long> hitTicks = new ArrayDeque<>();
		String name; int span = 1; boolean endpointInvalid, realHpChanged; long lastOwnedTick, injuryId;
		Engagement(ScenarioSnapshot f, Hit hit)
		{
			key = f.target.key; name = f.target.name; startHp = f.currentHp; realHp = f.realHp; startFactId = hit.id;
			endpointInvalid = startHp < (3L * realHp + 3) / 4;
		}
		void record(long tick)
		{
			lastOwnedTick = tick;
			if (hitTicks.isEmpty() || hitTicks.peekLast() != tick) { hitTicks.addLast(tick); }
			while (hitTicks.size() > 8) { hitTicks.removeFirst(); }
		}
	}
	private static final class QuietArm
	{
		final int startHp, endHp, realHp; final long nullTick, startFactId, injuryId, expires; int calm;
		QuietArm(Engagement engagement, ScenarioSnapshot f)
		{
			startHp = engagement.startHp; endHp = f.currentHp; realHp = engagement.realHp; nullTick = f.tick;
			expires = f.tick + 20; startFactId = engagement.startFactId; injuryId = engagement.injuryId;
		}
	}
}

package com.malfoid.scenario;

import net.runelite.api.HitsplatID;

/** Audited ordinary-HP whitelist. Poise and damage-over-time are deliberately excluded. */
public final class DamageTypes
{
	private DamageTypes() { }
	public static boolean hpDamage(int type)
	{
		switch (type)
		{
			case HitsplatID.DAMAGE_ME: case HitsplatID.DAMAGE_OTHER:
			case HitsplatID.DAMAGE_ME_CYAN: case HitsplatID.DAMAGE_OTHER_CYAN:
			case HitsplatID.DAMAGE_ME_YELLOW: case HitsplatID.DAMAGE_OTHER_YELLOW:
			case HitsplatID.DAMAGE_ME_ORANGE: case HitsplatID.DAMAGE_OTHER_ORANGE:
			case HitsplatID.DAMAGE_ME_WHITE: case HitsplatID.DAMAGE_OTHER_WHITE:
			case HitsplatID.DAMAGE_MAX_ME: case HitsplatID.DAMAGE_MAX_ME_CYAN:
			case HitsplatID.DAMAGE_MAX_ME_YELLOW: case HitsplatID.DAMAGE_MAX_ME_ORANGE:
			case HitsplatID.DAMAGE_MAX_ME_WHITE:
				return true;
			default: return false;
		}
	}
	public static boolean combat(int type) { return hpDamage(type) || type == HitsplatID.BLOCK_ME || type == HitsplatID.BLOCK_OTHER; }
	public static int largeHitThreshold(int hp) { return hp <= 0 ? Integer.MAX_VALUE : (int) ((7L * hp + 9) / 10); }
}

package com.malfoid.scenario;

import com.malfoid.scenario.ScenarioRules.CombatState;
import com.malfoid.scenario.ScenarioRules.SkillDelta;
import com.malfoid.speech.SceneCandidate;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.AnimationID;

/** Silent A.9 reactions to witnessed committed animation transitions. */
final class EmoteRules
{
	private static final int[] ANIMATIONS = {
		AnimationID.EMOTE_WAVE, AnimationID.EMOTE_BECKON, AnimationID.EMOTE_BOW,
		AnimationID.EMOTE_DANCE, AnimationID.EMOTE_BLOW_KISS
	};
	private static final int[] HOLDS = {3, 5, 3, 4, 6};
	private final long[] nextEmoteTick = new long[ANIMATIONS.length];
	private long nextGlobalTick = Long.MIN_VALUE;
	private long session = Long.MIN_VALUE, scene = Long.MIN_VALUE, lastTick = Long.MIN_VALUE;
	private boolean baseline;
	private String committedCause;

	EmoteRules()
	{
		Arrays.fill(nextEmoteTick, Long.MIN_VALUE);
	}

	List<SceneCandidate> close(ScenarioSnapshot f, ScenarioSnapshot prior, ScenarioBatch batch,
		List<SkillDelta> deltas, CombatState combat, long lastDamage, ExpandedScenarioRules.Factory factory)
	{
		if (session != f.sessionGeneration)
		{
			resetSession(); session = f.sessionGeneration; scene = f.sceneRevision;
		}
		if (scene != f.sceneRevision) { reset(); scene = f.sceneRevision; }
		if (f.tick <= lastTick) { return Collections.emptyList(); }
		boolean hadBaseline = baseline;
		lastTick = f.tick;
		baseline = f.valid && f.player != null && f.animation >= -1;
		if (!hadBaseline || prior == null || !prior.valid || !prior.present || !f.present
			|| prior.player == null || prior.animation < -1 || f.tick - prior.tick != 1
			|| prior.sessionGeneration != f.sessionGeneration || prior.sceneRevision != f.sceneRevision
			|| prior.presentSinceTick != f.presentSinceTick || f.animation == prior.animation)
		{
			return Collections.emptyList();
		}
		int emote = index(f.animation);
		if (emote < 0 || batch.localDeath || !safe(f, combat) || !cooldownReady(emote, f.tick))
		{
			return Collections.emptyList();
		}
		Map<String, String> facts = new HashMap<>();
		facts.put("emoteAnimation", Integer.toString(f.animation));
		facts.put("witnessPresenceEpoch", Long.toString(f.presentSinceTick));
		String cause = "emote:" + f.sessionGeneration + ":" + f.sceneRevision + ":" + f.tick + ":" + f.animation;
		return Collections.singletonList(factory.create(f, "E01", 40, 12, cause, facts, true, HOLDS[emote]));
	}

	/** Called only for a matching validated motion arrival, never candidate creation. */
	boolean arrived(SceneCandidate candidate, ScenarioSnapshot f, CombatState combat, long lastDamage)
	{
		if (!continuationValid(candidate, f, combat, lastDamage)
			|| candidate.getCausalToken().equals(committedCause)) { return false; }
		int emote = index(candidate.getConditionFacts().get("emoteAnimation"));
		nextEmoteTick[emote] = f.tick + 20;
		nextGlobalTick = f.tick + 10;
		committedCause = candidate.getCausalToken();
		return true;
	}

	boolean continuationValid(SceneCandidate candidate, ScenarioSnapshot f, CombatState combat, long lastDamage)
	{
		if (!"E01".equals(candidate.getScenarioId()) || !candidate.isIntentionalSilent() || !safe(f, combat)
			|| candidate.getSessionGeneration() != f.sessionGeneration || candidate.getSceneRevision() != f.sceneRevision
			|| candidate.getCreatedTick() > f.tick || candidate.getCreatedTick() < f.presentSinceTick
			|| !Long.toString(f.presentSinceTick).equals(candidate.getConditionFacts().get("witnessPresenceEpoch")))
		{
			return false;
		}
		int emote = index(candidate.getConditionFacts().get("emoteAnimation"));
		return emote >= 0 && (candidate.getCausalToken().equals(committedCause) || cooldownReady(emote, f.tick));
	}

	/** Scene/presence invalidation clears occurrence continuity, preserving session cooldowns. */
	void reset()
	{
		lastTick = Long.MIN_VALUE; baseline = false; committedCause = null;
	}
	void resetSession()
	{
		Arrays.fill(nextEmoteTick, Long.MIN_VALUE); nextGlobalTick = Long.MIN_VALUE;
		session = Long.MIN_VALUE; scene = Long.MIN_VALUE; reset();
	}

	private boolean cooldownReady(int emote, long tick)
	{
		return tick >= nextGlobalTick && tick >= nextEmoteTick[emote];
	}

	private static boolean safe(ScenarioSnapshot f, CombatState combat)
	{
		return f != null && f.valid && f.present && !f.dead && f.currentHp > 0 && !f.emergencySceneActive
			&& f.player != null && f.companion != null && f.player.distance(f.companion) <= 8
			&& combat != null && combat != CombatState.CONFIRMED;
	}

	private static int index(int animation)
	{
		for (int i = 0; i < ANIMATIONS.length; i++) { if (ANIMATIONS[i] == animation) { return i; } }
		return -1;
	}
	private static int index(String animation)
	{
		for (int i = 0; i < ANIMATIONS.length; i++) { if (Integer.toString(ANIMATIONS[i]).equals(animation)) { return i; } }
		return -1;
	}
}

package com.malfoid.scenario;

import com.malfoid.scenario.ScenarioBatch.Hit;
import com.malfoid.scenario.ScenarioRules.CombatState;
import com.malfoid.scenario.ScenarioRules.SkillDelta;
import com.malfoid.speech.SceneCandidate;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Deque;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.HitsplatID;
import net.runelite.api.Skill;

/** Explicit, bounded implementations of catalogue predicates; prose is never executed. */
final class ExpandedScenarioRules
{
	interface Factory
	{
		SceneCandidate create(ScenarioSnapshot frame, String id, int priority, int life, String cause, Map<String, String> facts, boolean silent, int hold);
	}
	private final Deque<Long> blocked = new ArrayDeque<>();
	private final Deque<NumberTick> climbing = new ArrayDeque<>();
	private final Deque<GainTick> alternating = new ArrayDeque<>(), fletching = new ArrayDeque<>(), sampler = new ArrayDeque<>(), farming = new ArrayDeque<>();
	private final Deque<Long> cookingHat = new ArrayDeque<>(), firemakingItems = new ArrayDeque<>(), cookingQuartet = new ArrayDeque<>(), fishingQuantities = new ArrayDeque<>();
	private final Relation headSpare = new Relation(), cabbageHat = new Relation();
	private int fishingQuantityStable;
	private long injuryTick = -1, injuryId;
	private int injuryReal, lowWater, recoveryStable, oneHpSamples;

	List<SceneCandidate> close(ScenarioSnapshot f, ScenarioSnapshot prior, ScenarioBatch batch, List<SkillDelta> deltas,
		CombatState combat, long lastDamage, Factory factory)
	{
		List<SceneCandidate> out = new ArrayList<>();
		injury(f, batch, lastDamage, factory, out);
		combatNumbers(f, batch, factory, out);
		if (combat != CombatState.NO_CONFIRMED_EVIDENCE)
		{
			resetSkills(); resetItems(); return out;
		}
		skills(f, deltas, factory, out);
		items(f, prior, deltas, factory, out);
		return out;
	}

	private void injury(ScenarioSnapshot f, ScenarioBatch batch, long lastDamage, Factory factory, List<SceneCandidate> out)
	{
		Hit damage = null;
		for (Hit hit : batch.hits)
		{
			if (hit.local && hit.witnessed && hit.amount > 0 && DamageTypes.hpDamage(hit.type))
			{
				if (damage == null || hit.id < damage.id) { damage = hit; }
			}
		}
		if (damage != null)
		{
			injuryTick = f.tick; injuryId = damage.id; injuryReal = f.realHp; lowWater = f.currentHp;
			recoveryStable = 0; oneHpSamples = f.currentHp == 1 ? 1 : 0;
			if ((f.realHp < 20 || f.currentHp > 3L * f.realHp / 10) && f.currentHp != 1) { injuryTick = -1; }
			return;
		}
		if (injuryTick < 0) { return; }
		if (f.realHp != injuryReal || f.tick - injuryTick > 20) { injuryTick = -1; return; }
		if (f.currentHp == 1 && f.tick - injuryTick <= 2) { oneHpSamples++; } else { oneHpSamples = 0; }
		if (oneHpSamples == 3 && f.directorIdle)
		{
			out.add(factory.create(f, "M12", 85, 6, "injury:" + injuryId, region(f), false, 4)); oneHpSamples = 0; injuryTick = -1; return;
		}
		lowWater = Math.min(lowWater, f.currentHp);
		boolean threshold = f.realHp >= 20 && f.currentHp >= (f.realHp + 1) / 2 && f.currentHp - lowWater >= (f.realHp + 4) / 5 && f.tick - lastDamage >= 4;
		recoveryStable = threshold ? recoveryStable + 1 : 0;
		if (recoveryStable >= 2 && f.directorIdle)
		{
			Map<String, String> facts = region(f); facts.put("lowWater", Integer.toString(lowWater)); facts.put("observedHp", Integer.toString(f.currentHp));
			out.add(factory.create(f, "M11", 60, 10, "injury:" + injuryId, facts, false, 6)); injuryTick = -1;
		}
	}

	private void combatNumbers(ScenarioSnapshot f, ScenarioBatch batch, Factory factory, List<SceneCandidate> out)
	{
		if (f.target == null || !f.target.alive || f.target.name == null) { resetEngagement(); return; }
		while (!blocked.isEmpty() && blocked.peekFirst() < f.tick - 11) { blocked.removeFirst(); }
		int positiveCount = 0, blockCount = 0, largest = 0; long positiveId = 0; boolean otherOwned = false;
		for (Hit hit : batch.hits)
		{
			if (!hit.mine || !hit.witnessed || !f.target.key.equals(hit.npcKey)) { continue; }
			if (DamageTypes.hpDamage(hit.type) && hit.amount > 0)
			{
				positiveCount++; if (hit.amount > largest) { largest = hit.amount; positiveId = hit.id; }
			}
			else if (hit.type == HitsplatID.BLOCK_ME && hit.amount == 0) { blockCount++; }
			else { otherOwned = true; }
		}
		if (positiveCount > 0)
		{
			if (!"Chicken".equalsIgnoreCase(f.target.name) && blocked.size() >= 3)
			{
				Map<String, String> facts = target(f); facts.put("ownedDamage", Integer.toString(largest));
				out.add(factory.create(f, "M13", 32, 10, "owned:" + positiveId, facts, false, 4));
			}
			blocked.clear();
		}
		if (blockCount > 0 && positiveCount == 0) { blocked.addLast(f.tick); while (blocked.size() > 3) { blocked.removeFirst(); } }
		if (blockCount > 0 || positiveCount > 1 || otherOwned) { climbing.clear(); }
		else if (positiveCount == 1)
		{
			while (!climbing.isEmpty() && climbing.peekFirst().tick < f.tick - 19) { climbing.removeFirst(); }
			climbing.addLast(new NumberTick(f.tick, largest)); while (climbing.size() > 4) { climbing.removeFirst(); }
			if (climbing.size() == 4)
			{
				int priorNumber = -1; boolean increasing = true;
				for (NumberTick number : climbing) { if (number.amount <= priorNumber) { increasing = false; } priorNumber = number.amount; }
				if (increasing)
				{
					Map<String, String> facts = target(f); facts.put("ownedDamage", Integer.toString(largest));
					out.add(factory.create(f, "M16", 42, 10, "owned:" + positiveId, facts, false, 5)); climbing.clear();
				}
			}
		}
	}

	private void skills(ScenarioSnapshot f, List<SkillDelta> deltas, Factory factory, List<SceneCandidate> out)
	{
		SkillDelta selectedAlternate = null, selectedSampler = null, farm = null, fish = null, fletch = null;
		int alternateCount = 0, samplerCount = 0;
		boolean anyLevel = false;
		for (SkillDelta delta : deltas)
		{
			if (delta.newLevel != delta.oldLevel)
			{
				anyLevel = true;
				if (delta.skill == Skill.CONSTRUCTION || delta.skill == Skill.FARMING) { alternating.clear(); }
				if (delta.skill == Skill.COOKING || delta.skill == Skill.FISHING || delta.skill == Skill.FIREMAKING) { sampler.clear(); }
				if (delta.skill == Skill.FLETCHING) { fletching.clear(); }
				if (delta.skill == Skill.FARMING) { farming.clear(); }
			}
			if (delta.delta <= 0 || delta.newLevel != delta.oldLevel) { continue; }
			if (delta.skill == Skill.CONSTRUCTION || delta.skill == Skill.FARMING) { alternateCount++; selectedAlternate = delta; }
			if (delta.skill == Skill.COOKING || delta.skill == Skill.FISHING || delta.skill == Skill.FIREMAKING) { samplerCount++; selectedSampler = delta; }
			if (delta.skill == Skill.FARMING) { farm = delta; }
			if (delta.skill == Skill.FISHING) { fish = delta; }
			if (delta.skill == Skill.FLETCHING) { fletch = delta; }
		}
		prune(alternating, f.tick - 59); prune(sampler, f.tick - 59); prune(farming, f.tick - 59); prune(fletching, f.tick - 119);
		if (alternateCount > 1) { alternating.clear(); }
		else if (selectedAlternate != null)
		{
			GainTick last = alternating.peekLast();
			if (last != null && last.skill == selectedAlternate.skill) { alternating.clear(); }
			alternating.addLast(new GainTick(f.tick, selectedAlternate.skill, selectedAlternate.delta));
			if (alternating.size() >= 6)
			{
				Map<String, String> facts = region(f); facts.put("skillSet", "CONSTRUCTION,FARMING");
				out.add(factory.create(f, "M21", 30, 12, "skill-alternation:" + f.tick, facts, false, 5)); alternating.clear();
			}
		}
		if (fletch != null && fletch.oldLevel == 99)
		{
			fletching.addLast(new GainTick(f.tick, Skill.FLETCHING, fletch.delta));
			long sum = 0; for (GainTick gain : fletching) { sum += gain.delta; }
			if (fletching.size() >= 10 && sum >= 1000)
			{
				Map<String, String> facts = region(f); facts.put("skillSet", "FLETCHING"); facts.put("xpDelta", Long.toString(sum));
				out.add(factory.create(f, "M23", 28, 12, "post99:" + f.tick, facts, false, 6)); fletching.clear();
			}
		}
		if (samplerCount > 1) { sampler.clear(); }
		else if (selectedSampler != null)
		{
			long count = 0; for (GainTick gain : sampler) { if (gain.skill == selectedSampler.skill) { count++; } }
			if (count < 2) { sampler.addLast(new GainTick(f.tick, selectedSampler.skill, selectedSampler.delta)); }
			if (sampler.size() == 6)
			{
				Map<String, String> facts = region(f); facts.put("skillSet", "COOKING,FISHING,FIREMAKING");
				out.add(factory.create(f, "M26", 27, 12, "skill-sampler:" + f.tick, facts, false, 5)); sampler.clear();
			}
		}
		if (fish != null && fish.oldXp < 1_000_000 && fish.newXp >= 1_000_000 && !anyLevel)
		{
			Map<String, String> facts = region(f); facts.put("skill", "FISHING"); facts.put("xpTotal", Integer.toString(fish.newXp));
			out.add(factory.create(f, "M28", 40, 12, "xp-million:" + f.tick, facts, false, 6));
		}
		if (farm != null)
		{
			long sum = 0; for (GainTick gain : farming) { sum += gain.delta; }
			if (farming.size() == 3 && farm.delta >= 1000 && farm.delta >= sum * 5)
			{
				Map<String, String> facts = region(f); facts.put("skillSet", "FARMING"); facts.put("xpDelta", Long.toString(farm.delta));
				out.add(factory.create(f, "M29", 32, 12, "farming-progress:" + f.tick, facts, false, 5)); farming.clear();
			}
			else { farming.addLast(new GainTick(f.tick, Skill.FARMING, farm.delta)); while (farming.size() > 3) { farming.removeFirst(); } }
		}
	}

	private void items(ScenarioSnapshot f, ScenarioSnapshot prior, List<SkillDelta> deltas, Factory factory, List<SceneCandidate> out)
	{
		if (prior == null || !prior.present || f.inventoryBlocked || prior.inventoryBlocked || !f.inventoryKnown() || !prior.inventoryKnown())
		{
			resetItems(); return;
		}
		int[] worn = f.equipment(), priorWorn = prior.equipment();
		if (worn == null || priorWorn == null) { resetItems(); return; }
		boolean relation = worn[0] >= 0 && f.itemCount(worn[0]) >= 1;
		if (headSpare.observe(relation, Integer.toString(worn[0])))
		{
			Map<String, String> facts = region(f); facts.put("matchedHeadItemId", Integer.toString(worn[0]));
			out.add(factory.create(f, "M35", 22, 12, "spare-hat:" + f.tick, facts, false, 6));
		}
		if (cabbageHat.observe(worn[0] == 1949 && f.occupiedSlots(1965) >= 20, "1949,1965"))
		{
			Map<String, String> facts = region(f); facts.put("namedItemIds", "1949,1965");
			out.add(factory.create(f, "M37", 24, 12, "cabbage-hat:" + f.tick, facts, false, 5));
		}
		boolean hatBurnt = worn[0] == 1949 && f.itemCount(7954) > 0;
		boolean fireItems = f.itemCount(590) > 0 && f.itemCount(592) > 0;
		boolean quartet = quartet(f);
		boolean fishQuantity = f.itemCount(314) == 1 && f.itemCount(313) >= 1000;
		fishingQuantityStable = fishQuantity ? Math.min(5, fishingQuantityStable + 1) : 0;
		pruneTicks(cookingHat, f.tick - 59); pruneTicks(firemakingItems, f.tick - 59);
		pruneTicks(cookingQuartet, f.tick - 59); pruneTicks(fishingQuantities, f.tick - 119);
		for (SkillDelta delta : deltas)
		{
			if (delta.delta <= 0) { continue; }
			if (delta.skill == Skill.COOKING) { addTick(cookingHat, f.tick, 3); if (quartet) { addTick(cookingQuartet, f.tick, 6); } }
			if (delta.skill == Skill.FIREMAKING && fireItems) { addTick(firemakingItems, f.tick, 10); }
			if (delta.skill == Skill.FISHING && fishQuantity) { addTick(fishingQuantities, f.tick, 10); }
		}
		if (hatBurnt && priorWorn[0] == 1949 && prior.itemCount(7954) > 0 && qualifies(cookingHat, 3, f.tick))
		{
			offerItem(f, factory, out, "M36", 23, "1949,7954", 5); cookingHat.clear();
		}
		if (fireItems && prior.itemCount(590) > 0 && prior.itemCount(592) > 0 && qualifies(firemakingItems, 10, f.tick))
		{
			offerItem(f, factory, out, "M38", 18, "590,592", 5); firemakingItems.clear();
		}
		if (quartet && quartet(prior) && qualifies(cookingQuartet, 6, f.tick))
		{
			offerItem(f, factory, out, "M40", 19, "1925,1931,1935,1980", 5); cookingQuartet.clear();
		}
		if (fishingQuantityStable >= 5 && qualifies(fishingQuantities, 10, f.tick))
		{
			offerItem(f, factory, out, "M42", 20, "313,314", 5); fishingQuantities.clear();
		}
	}
	private static void offerItem(ScenarioSnapshot f, Factory factory, List<SceneCandidate> out, String id, int priority, String subject, int hold)
	{
		Map<String, String> facts = region(f); facts.put("namedItemIds", subject);
		out.add(factory.create(f, id, priority, 12, "items-progress:" + id + ":" + f.tick, facts, false, hold));
	}
	private static boolean quartet(ScenarioSnapshot f)
	{
		return f.itemCount(1925) > 0 && f.itemCount(1931) > 0 && f.itemCount(1935) > 0 && f.itemCount(1980) > 0;
	}
	private static boolean qualifies(Deque<Long> ticks, int size, long now) { return ticks.size() >= size && now - ticks.peekLast() <= 5; }
	private static void pruneTicks(Deque<Long> ticks, long oldest) { while (!ticks.isEmpty() && ticks.peekFirst() < oldest) { ticks.removeFirst(); } }
	private static void addTick(Deque<Long> ticks, long tick, int cap)
	{
		if (ticks.isEmpty() || ticks.peekLast() != tick) { ticks.addLast(tick); }
		while (ticks.size() > cap) { ticks.removeFirst(); }
	}
	boolean stillValid(SceneCandidate c, ScenarioSnapshot f)
	{
		String id = c.getScenarioId(); Map<String, String> facts = c.getConditionFacts();
		if ("M11".equals(id)) { return f.currentHp >= (f.realHp + 1) / 2; }
		if ("M12".equals(id)) { return f.currentHp == 1; }
		if ("M13".equals(id) || "M16".equals(id))
		{
			return f.target != null && f.target.alive && f.target.key.equals(facts.get("targetKey")) && f.target.name.equals(facts.get("npcResolvedName"));
		}
		if (id.matches("M(3[5-9]|4[0-2])"))
		{
			if (!f.inventoryKnown() || f.inventoryBlocked) { return false; }
			if ("M36".equals(id)) { int[] worn = f.equipment(); return worn != null && worn[0] == 1949 && f.itemCount(7954) > 0; }
			if ("M37".equals(id)) { int[] worn = f.equipment(); return worn != null && worn[0] == 1949 && f.occupiedSlots(1965) >= 20; }
			String ids = facts.get("namedItemIds");
			if (ids != null) { for (String value : ids.split(",")) { if (f.itemCount(Integer.parseInt(value)) <= 0) { return false; } } }
			if ("M42".equals(id)) { return f.itemCount(314) == 1 && f.itemCount(313) >= 1000; }
			if ("M35".equals(id))
			{
				int item = Integer.parseInt(facts.get("matchedHeadItemId")); int[] worn = f.equipment();
				return worn != null && worn[0] == item && f.itemCount(item) >= 1;
			}
		}
		return true;
	}
	void reset()
	{
		resetEngagement(); resetSkills(); resetItems(); injuryTick = -1; recoveryStable = 0; oneHpSamples = 0;
	}
	void resetEngagement() { blocked.clear(); climbing.clear(); }
	private void resetSkills() { alternating.clear(); fletching.clear(); sampler.clear(); farming.clear(); }
	private void resetItems()
	{
		headSpare.reset(); cabbageHat.reset(); cookingHat.clear(); firemakingItems.clear(); cookingQuartet.clear(); fishingQuantities.clear(); fishingQuantityStable = 0;
	}
	private static void prune(Deque<GainTick> entries, long oldest) { while (!entries.isEmpty() && entries.peekFirst().tick < oldest) { entries.removeFirst(); } }
	private static Map<String, String> region(ScenarioSnapshot f)
	{
		Map<String, String> facts = new HashMap<>(); facts.put("actualRegion", Integer.toString(f.player.region())); return facts;
	}
	private static Map<String, String> target(ScenarioSnapshot f)
	{
		Map<String, String> facts = region(f); facts.put("targetKey", f.target.key); facts.put("npcResolvedName", f.target.name);
		if (f.target.position != null) { facts.put("targetX", Integer.toString(f.target.position.x)); facts.put("targetY", Integer.toString(f.target.position.y)); }
		return facts;
	}
	private static final class GainTick
	{
		final long tick, delta; final Skill skill;
		GainTick(long tick, Skill skill, long delta) { this.tick = tick; this.skill = skill; this.delta = delta; }
	}
	private static final class NumberTick
	{
		final long tick; final int amount;
		NumberTick(long tick, int amount) { this.tick = tick; this.amount = amount; }
	}
	private static final class Relation
	{
		boolean baselined, armed, priorTrue; int falseTicks, trueTicks; String subject;
		boolean observe(boolean relation, String currentSubject)
		{
			if (!baselined) { baselined = true; priorTrue = relation; subject = currentSubject; return false; }
			if (!relation)
			{
				falseTicks = Math.min(5, falseTicks + 1); trueTicks = 0; priorTrue = false;
				if (falseTicks >= 5) { armed = true; }
				return false;
			}
			if (!priorTrue || !currentSubject.equals(subject)) { trueTicks = 0; subject = currentSubject; }
			priorTrue = true; falseTicks = 0;
			if (!armed) { return false; }
			trueTicks++;
			if (trueTicks >= 10) { armed = false; trueTicks = 0; return true; }
			return false;
		}
		void reset() { baselined = false; armed = false; priorTrue = false; falseTicks = 0; trueTicks = 0; subject = null; }
	}
}

package com.malfoid.scenario;

import com.malfoid.motion.CreatureAwareness;
import com.malfoid.motion.CreatureAwareness.Creature;
import com.malfoid.motion.CreatureAwareness.Sample;
import com.malfoid.speech.SceneCandidate;
import java.util.HashMap;
import java.util.Map;

/** One copied E.5 speech opportunity at the beginning of a continuous fear episode. */
final class FearRules
{
	private Sample sample;
	private Creature beginCreature;
	private long beginTick = -1, consumedBegin = Long.MIN_VALUE;
	private boolean keepingAway;
	private SceneCandidate issued;

	void observe(Sample sample, CreatureAwareness awareness)
	{
		this.sample = sample;
		beginCreature = awareness.getBeginCreature(); beginTick = awareness.getBeginTick();
		keepingAway = awareness.isKeepingAway();
	}

	SceneCandidate close(ScenarioSnapshot f, ExpandedScenarioRules.Factory factory)
	{
		if (issued != null && !valid(issued, f)) { issued = null; }
		if (sample == null || sample.tick != f.tick || !sample.known || !keepingAway || beginCreature == null
			|| !CreatureAwareness.isE5(beginCreature.classification.groupId) || beginTick == consumedBegin) { return null; }
		consumedBegin = beginTick;
		// A blocked onset is consumed; absence, a cooldown or a later callback cannot replay it.
		if (beginTick != f.tick || !healthy(f) || sample.worldViewId != f.worldViewId || beginCreature.plane != f.companion.plane
			|| beginCreature.distance(f.companion.x, f.companion.y) > 6) { return null; }
		Map<String, String> facts = new HashMap<>();
		facts.put("fearBeginTick", Long.toString(beginTick));
		facts.put("creatureKey", beginCreature.key);
		facts.put("creatureGroup", beginCreature.classification.groupId);
		facts.put("creatureX", Integer.toString(beginCreature.worldX));
		facts.put("creatureY", Integer.toString(beginCreature.worldY));
		facts.put("creaturePlane", Integer.toString(beginCreature.plane));
		facts.put("creatureWorldViewId", Integer.toString(sample.worldViewId));
		facts.put("witnessPresenceEpoch", Long.toString(f.presentSinceTick));
		// E.5 says optional, without another probability. Section 5 guards may refuse this offer.
		// Priority, short deadline and readable length are ordinary presentation defaults for ruling.
		issued = factory.create(f, beginCreature.classification.groupId, 30, 12,
			"fear:" + beginTick + ":" + beginCreature.key, facts, false, 4);
		return issued;
	}

	boolean continuationValid(SceneCandidate candidate, ScenarioSnapshot f)
	{
		return issued == candidate && valid(candidate, f);
	}

	private boolean valid(SceneCandidate candidate, ScenarioSnapshot f)
	{
		return healthy(f) && sample != null && sample.tick == f.tick && sample.known && keepingAway
			&& beginCreature != null && CreatureAwareness.isE5(candidate.getScenarioId())
			&& beginCreature.key.equals(candidate.getConditionFacts().get("creatureKey"))
			&& beginCreature.classification.groupId.equals(candidate.getScenarioId())
			&& Long.toString(beginTick).equals(candidate.getConditionFacts().get("fearBeginTick"))
			&& f.sessionGeneration == candidate.getSessionGeneration() && f.sceneRevision == candidate.getSceneRevision()
			&& sample.worldViewId == f.worldViewId
			&& sourceMatches(candidate, f)
			&& Integer.toString(f.worldViewId).equals(candidate.getConditionFacts().get("creatureWorldViewId"))
			&& Long.toString(f.presentSinceTick).equals(candidate.getConditionFacts().get("witnessPresenceEpoch"));
	}

	private boolean sourceMatches(SceneCandidate candidate, ScenarioSnapshot f)
	{
		for (Creature creature : sample.creatures)
		{
			if (creature.key.equals(candidate.getConditionFacts().get("creatureKey"))
				&& creature.classification.groupId.equals(candidate.getScenarioId())
				&& creature.plane == f.companion.plane && creature.distance(f.companion.x, f.companion.y) <= 6) { return true; }
		}
		return false;
	}

	private static boolean healthy(ScenarioSnapshot f)
	{
		return f != null && f.valid && f.present && !f.userHidden && !f.autoAbsent && !f.dead && f.currentHp > 0
			&& f.player != null && f.companion != null && f.player.plane == f.companion.plane;
	}

	void reset() { issued = null; consumedBegin = Long.MIN_VALUE; }
}

package com.malfoid.scenario;

