	GroundOutcomeProof(long reportId, long reportTick, long originalDeadline, long sessionGeneration,
		long sceneRevision, long presentSinceTick, int itemId, int reportedQuantity, String itemName,
		long reportedValue, boolean currentGroundAvailable, boolean itemPossessionConfirmed,
		long pileIdentity, Position groundPosition)
	{
		this.reportId = reportId; this.reportTick = reportTick; this.originalDeadline = originalDeadline;
		this.sessionGeneration = sessionGeneration; this.sceneRevision = sceneRevision; this.presentSinceTick = presentSinceTick;
		this.itemId = itemId; this.reportedQuantity = reportedQuantity; this.itemName = itemName;
		this.reportedValue = reportedValue; this.currentGroundAvailable = currentGroundAvailable;
		this.itemPossessionConfirmed = itemPossessionConfirmed; this.pileIdentity = pileIdentity; this.groundPosition = groundPosition;
	}
}

package com.malfoid.scenario;

import com.malfoid.scenario.ScenarioBatch.Loot;
import com.malfoid.scenario.ScenarioBatch.Stack;
import com.malfoid.scenario.ScenarioSnapshot.Position;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.TileItem;

/** Bounded C.4 proof state. It issues no scene, cooldown, pickup or provenance claim. */
public final class GroundOutcomeRules
{
	public static final int MAX_EPISODES = 64, MAX_STACKS = 128, MAX_PILES = 256, REPORT_LIFETIME = 12;
	private final Map<Long, Episode> episodes = new LinkedHashMap<>();
	private long sessionGeneration = Long.MIN_VALUE, sceneRevision = Long.MIN_VALUE, presentSinceTick = Long.MIN_VALUE;
	private long lastTick = Long.MIN_VALUE;
	private long reportHighWater = Long.MIN_VALUE;
	private int worldViewId = Integer.MIN_VALUE, plane = Integer.MIN_VALUE;

	/** Only fresh reports are returned; later evidence cannot create a second opportunity. */
	public List<GroundOutcomeProof> close(ScenarioSnapshot frame, List<Loot> reports, List<Pile> currentPiles)
	{
		if (!eligible(frame)) { discardReports(reports); resetScene(); return Collections.emptyList(); }
		if (!scopeMatches(frame))
		{
			resetScene(); sessionGeneration = frame.sessionGeneration; sceneRevision = frame.sceneRevision; presentSinceTick = frame.presentSinceTick;
			worldViewId = frame.worldViewId; plane = frame.player.plane;
		}
		if (frame.tick <= lastTick) { return Collections.emptyList(); }
		lastTick = frame.tick; expire(frame.tick);
		List<GroundOutcomeProof> out = new ArrayList<>();
		if (reports == null || reports.size() > MAX_EPISODES) { return out; }
		List<Loot> ordered = new ArrayList<>(reports);
		ordered.removeIf(report -> report == null);
		ordered.sort(Comparator.comparingLong(report -> report.id));
		for (Loot report : ordered)
		{
			if (report.id <= 0 || report.id <= reportHighWater) { continue; }
			reportHighWater = report.id;
			if (!report.witnessed || report.npcKey == null || report.npcKey.isEmpty()
				|| report.stacks.isEmpty() || report.stacks.size() > MAX_STACKS || episodes.containsKey(report.id)) { continue; }
			List<Stack> sorted = new ArrayList<>(report.stacks);
			if (sorted.stream().anyMatch(stack -> stack == null || stack.id < 0 || stack.quantity <= 0)) { continue; }
			sorted.sort(Comparator.comparingInt((Stack stack) -> stack.id).thenComparingInt(stack -> stack.quantity));
			StringBuilder key = new StringBuilder(report.npcKey);
			Stack selected = null;
			for (Stack stack : sorted)
			{
				key.append('/').append(stack.id).append(':').append(stack.quantity);
				if (stack.total() >= 500_000 && (selected == null || stack.total() > selected.total())) { selected = stack; }
			}
			if (selected == null || duplicate(key.toString(), frame.tick) || episodes.size() >= MAX_EPISODES
				|| frame.tick > Long.MAX_VALUE - REPORT_LIFETIME) { continue; }
			Episode episode = new Episode(report.id, key.toString(), frame, selected);
			Pile matched = uniqueFreshPile(frame, selected, currentPiles);
			if (matched != null && available(frame, episode, matched)) { episode.pileIdentity = matched.identity; }
			episodes.put(report.id, episode);
			out.add(proof(episode, frame, currentPiles, frame.inventoryIds(), frame.inventoryQuantities()));
		}
		return Collections.unmodifiableList(out);
	}

	/** Used immediately before paint, with freshly copied current inventory and a current exact pile identity. */
	public GroundOutcomeProof revalidate(long reportId, ScenarioSnapshot frame, List<Pile> currentPiles,
		int[] currentInventoryIds, int[] currentInventoryQuantities)
	{
		if (!eligible(frame) || !scopeMatches(frame)) { resetScene(); return null; }
		if (frame.tick < lastTick) { return null; }
		expire(frame.tick);
		Episode episode = episodes.get(reportId);
		if (episode == null || episode.settled || frame.tick < episode.reportTick) { return null; }
		return proof(episode, frame, currentPiles, currentInventoryIds, currentInventoryQuantities);
	}

	/** Root commits the parent M05 logical guard separately on first paint or intentional silent arrival. */
	public void settled(long reportId)
	{
		Episode episode = episodes.get(reportId); if (episode != null) { episode.settled = true; }
	}

	long pileIdentity(long reportId)
	{
		Episode episode = episodes.get(reportId); return episode == null || episode.settled ? 0 : episode.pileIdentity;
	}

	/** Same-session absence discards proof without allowing an old report ID to be replayed on return. */
	public void resetScene()
	{
		long highWater = reportHighWater; reset(); reportHighWater = highWater;
	}

	void discardReports(List<Loot> reports)
	{
		if (reports == null || reports.size() > MAX_EPISODES) { return; }
		for (Loot report : reports) { if (report != null && report.id > 0) { reportHighWater = Math.max(reportHighWater, report.id); } }
	}

	public void reset()
	{
		episodes.clear(); sessionGeneration = Long.MIN_VALUE; sceneRevision = Long.MIN_VALUE;
		presentSinceTick = Long.MIN_VALUE; lastTick = Long.MIN_VALUE; reportHighWater = Long.MIN_VALUE;
		worldViewId = Integer.MIN_VALUE; plane = Integer.MIN_VALUE;
	}

	private boolean scopeMatches(ScenarioSnapshot frame)
	{
		return sessionGeneration == frame.sessionGeneration && sceneRevision == frame.sceneRevision && presentSinceTick == frame.presentSinceTick
			&& worldViewId == frame.worldViewId && plane == frame.player.plane;
	}
	private static boolean eligible(ScenarioSnapshot frame)
	{
		return frame != null && frame.valid && frame.present && !frame.userHidden && !frame.autoAbsent && !frame.dead
			&& frame.currentHp > 0 && frame.topLevel && frame.player != null && frame.worldViewId != Integer.MIN_VALUE
			&& frame.tick >= 0 && frame.presentSinceTick >= 0 && frame.tick >= frame.presentSinceTick;
	}
	private void expire(long tick) { episodes.entrySet().removeIf(entry -> tick >= entry.getValue().deadline); }
	private boolean duplicate(String key, long tick)
	{
		for (Episode episode : episodes.values()) { if (tick - episode.reportTick <= 2 && episode.key.equals(key)) { return true; } }
		return false;
	}
	private static Pile uniqueFreshPile(ScenarioSnapshot frame, Stack selected, List<Pile> piles)
	{
		if (piles == null || piles.size() > MAX_PILES) { return null; }
		Pile match = null;
		for (Pile pile : piles)
		{
			if (pile == null || pile.identity <= 0 || pile.itemId != selected.id || pile.spawnQuantity != selected.quantity
				|| pile.spawnTick != frame.tick || !pileScope(frame, pile)) { continue; }
			if (match != null) { return null; }
			match = pile;
		}
		return match;
	}
	private static boolean pileScope(ScenarioSnapshot frame, Pile pile)
	{
		return pile.sessionGeneration == frame.sessionGeneration && pile.sceneRevision == frame.sceneRevision
			&& pile.presentSinceTick == frame.presentSinceTick && pile.worldViewId == frame.worldViewId
			&& pile.position != null && pile.position.plane == frame.player.plane && pile.spawnTick >= frame.presentSinceTick;
	}
	private static boolean available(ScenarioSnapshot frame, Episode episode, Pile pile)
	{
		// visibleTime describes visibility to OTHER players. A current SELF-owned private pile is visible to its owner.
		return !frame.inventoryBlocked && pileScope(frame, pile) && pile.currentlyInTile
			&& pile.itemId == episode.selected.id && pile.spawnQuantity == episode.selected.quantity
			&& pile.quantity == episode.selected.quantity && pile.ownership == TileItem.OWNERSHIP_SELF
			&& pile.serverTick >= 0 && pile.visibleTime >= 0 && pile.despawnTime > pile.serverTick;
	}
	private GroundOutcomeProof proof(Episode episode, ScenarioSnapshot frame, List<Pile> piles, int[] ids, int[] quantities)
	{
		Pile matched = null;
		if (piles != null && piles.size() <= MAX_PILES)
		{
			for (Pile pile : piles)
			{
				if (pile != null && episode.pileIdentity > 0 && pile.identity == episode.pileIdentity)
				{
					if (matched != null) { matched = null; break; }
					matched = pile;
				}
			}
		}
		boolean available = matched != null && available(frame, episode, matched);
		boolean possessed = !frame.inventoryBlocked && exactPossession(episode.selected.id, ids, quantities);
		return new GroundOutcomeProof(episode.id, episode.reportTick, episode.deadline, episode.sessionGeneration,
			episode.sceneRevision, episode.presentSinceTick, episode.selected.id, episode.selected.quantity,
			episode.selected.name == null ? "" : episode.selected.name, episode.selected.total(), available, possessed,
			available ? episode.pileIdentity : 0, available ? matched.position : null);
	}
	private static boolean exactPossession(int itemId, int[] ids, int[] quantities)
	{
		if (ids == null || quantities == null || ids.length != 28 || quantities.length != 28) { return false; }
		boolean found = false;
		for (int i = 0; i < 28; i++)
		{
			if (ids[i] < -1 || quantities[i] < 0 || (ids[i] == -1 && quantities[i] != 0)
				|| (ids[i] >= 0 && quantities[i] <= 0)) { return false; }
			if (ids[i] == itemId && quantities[i] > 0) { found = true; }
		}
		return found;
	}

	/** Copied public API facts only; raw Tile/TileItem references remain inside the adapter. */
	public static final class Pile
	{
		public final long identity, spawnTick, sessionGeneration, sceneRevision, presentSinceTick;
		public final int worldViewId, itemId, spawnQuantity, quantity, ownership, visibleTime, despawnTime, serverTick;
		public final Position position;
		public final boolean privateItem, currentlyInTile;
		public Pile(long identity, long spawnTick, long sessionGeneration, long sceneRevision, long presentSinceTick,
			int worldViewId, Position position, int itemId, int spawnQuantity, int quantity, int ownership,
			int visibleTime, int despawnTime, int serverTick, boolean privateItem, boolean currentlyInTile)
		{
			this.identity = identity; this.spawnTick = spawnTick; this.sessionGeneration = sessionGeneration;
			this.sceneRevision = sceneRevision; this.presentSinceTick = presentSinceTick; this.worldViewId = worldViewId;
			this.position = position; this.itemId = itemId; this.spawnQuantity = spawnQuantity; this.quantity = quantity;
			this.ownership = ownership; this.visibleTime = visibleTime; this.despawnTime = despawnTime;
			this.serverTick = serverTick; this.privateItem = privateItem; this.currentlyInTile = currentlyInTile;
		}
	}
	private static final class Episode
	{
		private final long id, reportTick, deadline, sessionGeneration, sceneRevision, presentSinceTick;
		private final String key;
		private final Stack selected;
		private long pileIdentity;
		private boolean settled;
		private Episode(long id, String key, ScenarioSnapshot frame, Stack selected)
		{
			this.id = id; this.key = key; this.selected = selected; reportTick = frame.tick;
			deadline = frame.tick + REPORT_LIFETIME; sessionGeneration = frame.sessionGeneration;
			sceneRevision = frame.sceneRevision; presentSinceTick = frame.presentSinceTick;
		}
	}
}

package com.malfoid.scenario;

/** Copied context from a director-validated inspection arrival and full hold completion. */
public final class InspectionCompletionRecord
{
	public final String key, category, name;
	public final long completedTick, sessionGeneration, sceneRevision, presentSinceTick;
	InspectionCompletionRecord(ScenarioSnapshot.InspectionTarget object, ScenarioSnapshot frame)
	{
		key = object.key; category = ScenarioRules.objectKind(object.name); name = object.name;
		completedTick = frame.tick; sessionGeneration = frame.sessionGeneration;
		sceneRevision = frame.sceneRevision; presentSinceTick = frame.presentSinceTick;
	}
}

package com.malfoid.scenario;

import com.malfoid.scenario.ScenarioRules.CombatState;
import com.malfoid.scenario.ScenarioRules.SkillDelta;
import com.malfoid.speech.SceneCandidate;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeSet;
import net.runelite.api.Skill;

/** Bounded observations of the copied bag. No inventory change is attributed to an action. */
final class InventoryExpansionRules
{
	private final AnchorWindow cabbage = new AnchorWindow(1965, Skill.FISHING, 90, 10);
	private final AnchorWindow rock = new AnchorWindow(3695, Skill.MINING, 120, 15);
	private final Deque<Long> fullMiningGains = new ArrayDeque<>();
	private final Deque<LayoutTick> arrangements = new ArrayDeque<>();
	private long lastTick = Long.MIN_VALUE, witnessVersion;
	private long latestFishing = Long.MIN_VALUE / 2, latestMining = Long.MIN_VALUE / 2;
	private boolean seeded, eligible, kitArmed, miningHandled;
	private int kitFalse, kitHold, kitMovement, fullTicks, propFullTicks, miningFullTicks;
	private long kitStart = -1, miningStart = -1, headStart = -1, spaceSerial, arrangementSerial, headSerial;
	private String kitLayout, pendingSpace, spaceProof, arrangementProof;
	private String arrangementMultiset, arrangementAnchor, stableArrangement, arrangementIds;
	private String headTuple, headPriorTuple, headProof;
	private boolean headEligible;

	List<SceneCandidate> close(ScenarioSnapshot f, ScenarioSnapshot prior, ScenarioBatch batch,
		List<SkillDelta> deltas, CombatState combat, long lastDamage, ExpandedScenarioRules.Factory factory)
	{
		List<SceneCandidate> out = new ArrayList<>();
		if (f.tick == lastTick) { return out; }
		Bag bag = Bag.from(f), old = Bag.from(prior);
		boolean continuous = prior != null && f.tick == prior.tick + 1
			&& f.sessionGeneration == prior.sessionGeneration && f.sceneRevision == prior.sceneRevision
			&& f.presentSinceTick == prior.presentSinceTick && prior.tick >= f.presentSinceTick
			&& permitted(f) && permitted(prior) && f.player.distance(prior.player) <= 2;
		if (!continuous || bag == null || old == null || combat != CombatState.NO_CONFIRMED_EVIDENCE
			|| f.tick - lastDamage < 10 || (lastTick != Long.MIN_VALUE && f.tick != lastTick + 1))
		{
			reset(); lastTick = f.tick; return out;
		}
		lastTick = f.tick; eligible = true;
		if (!seeded)
		{
			seeded = true; kitArmed = !old.eggKit();
		}
		boolean fishing = positiveGain(f, prior, batch, deltas, Skill.FISHING);
		boolean mining = positiveGain(f, prior, batch, deltas, Skill.MINING);
		if (fishing) { latestFishing = f.tick; }
		if (mining) { latestMining = f.tick; }
		travellingKit(f, prior, bag, factory, out);
		capacity(f, prior, bag, old, mining, factory, out);
		if (knownProgress(f, prior, Skill.FISHING))
		{
			persistent(f, bag, cabbage, fishing, "M41", 20, factory, out);
		}
		else { cabbage.reset(); latestFishing = Long.MIN_VALUE / 2; }
		if (knownProgress(f, prior, Skill.MINING))
		{
			persistent(f, bag, rock, mining, "M49", 21, factory, out);
		}
		else { rock.reset(); latestMining = Long.MIN_VALUE / 2; }
		arrangement(f, bag, old, factory, out);
		if (f.tick - f.presentSinceTick < 10) { out.clear(); }
		return out;
	}

	private static boolean permitted(ScenarioSnapshot f)
	{
		return f != null && f.valid && f.present && !f.userHidden && !f.autoAbsent && !f.dead
			&& f.currentHp > 0 && !f.inventoryBlocked && f.player != null && f.companion != null
			&& f.player.distance(f.companion) < 10;
	}

	private static boolean knownProgress(ScenarioSnapshot f, ScenarioSnapshot prior, Skill skill)
	{
		return f.xp(skill) >= 0 && prior.xp(skill) >= 0 && f.xp(skill) >= prior.xp(skill);
	}

	private static boolean positiveGain(ScenarioSnapshot f, ScenarioSnapshot prior, ScenarioBatch batch,
		List<SkillDelta> deltas, Skill skill)
	{
		if (!batch.witnessedSkills.contains(skill) || !knownProgress(f, prior, skill)) { return false; }
		for (SkillDelta delta : deltas)
		{
			if (delta.skill == skill && delta.delta > 0 && delta.oldXp == prior.xp(skill)
				&& delta.newXp == f.xp(skill)) { return true; }
		}
		return false;
	}

	private void travellingKit(ScenarioSnapshot f, ScenarioSnapshot prior, Bag bag,
		ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		if (!bag.eggKit())
		{
			kitFalse = Math.min(5, kitFalse + 1); kitStart = -1; kitLayout = null;
			kitHold = 0; kitMovement = 0;
			if (kitFalse == 5) { kitArmed = true; }
			return;
		}
		kitFalse = 0;
		if (kitStart >= 0 && !bag.layout.equals(kitLayout))
		{
			kitStart = -1; kitLayout = null; kitArmed = false; return;
		}
		if (kitStart < 0)
		{
			if (!kitArmed) { return; }
			kitStart = f.tick; kitLayout = bag.layout; kitHold = 1; kitMovement = 0;
		}
		else
		{
			if (f.tick - kitStart > 12) { kitArmed = false; return; }
			kitHold = Math.min(10, kitHold + 1);
			kitMovement = Math.min(8, kitMovement + f.player.distance(prior.player));
		}
		if (kitArmed && kitHold == 10 && kitMovement == 8)
		{
			Map<String, String> facts = facts(f); facts.put("namedItemIds", "954,1925,1944");
			facts.put("inventoryLayout", kitLayout); facts.put("kitEpisode", Long.toString(kitStart));
			facts.put("observedMovementTiles", "8");
			out.add(factory.create(f, "M39", 21, 12, "INVENTORY_ODDITIES:movement:" + kitStart, facts, false, 6));
			kitArmed = false;
		}
	}

	private void capacity(ScenarioSnapshot f, ScenarioSnapshot prior, Bag bag, Bag old, boolean mining,
		ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		if (spaceProof != null && !spaceProof.equals(bag.layout)) { spaceProof = null; }
		int previousProps = propFullTicks;
		boolean full = bag.occupied == 28;
		if (full)
		{
			fullTicks = Math.min(30, fullTicks + 1); pendingSpace = null;
		}
		else
		{
			if (pendingSpace != null && bag.occupied == 27 && pendingSpace.equals(bag.layout))
			{
				spaceProof = bag.layout; spaceSerial++;
				Map<String, String> facts = facts(f); facts.put("inventoryLayout", bag.layout);
				facts.put("spaceEpisode", Long.toString(spaceSerial)); facts.put("occupiedSlots", "27");
				out.add(factory.create(f, "M43", 18, 12, "BAG_CAPACITY_REMARK:space:" + f.tick, facts, false, 6));
			}
			pendingSpace = fullTicks == 30 && bag.occupied == 27 ? bag.layout : null;
			fullTicks = 0;
		}
		propFullTicks = bag.fullProps() ? Math.min(30, propFullTicks + 1) : 0;
		int[] equipment = f.equipment(), priorEquipment = prior.equipment();
		if (headProof != null && (!bag.fullProps() || equipment == null || equipment.length != 4
			|| !headProof.equals(equipmentKey(equipment)))) { headProof = null; }
		if (!bag.fullProps() || equipment == null || priorEquipment == null
			|| equipment.length != 4 || priorEquipment.length != 4)
		{
			headEligible = false; headTuple = null;
		}
		else if (!Arrays.equals(equipment, priorEquipment))
		{
			headEligible = previousProps == 30 && old.fullProps() && equipment[0] >= 0
				&& equipment[0] != priorEquipment[0] && equipment[1] == priorEquipment[1]
				&& equipment[2] == priorEquipment[2] && equipment[3] == priorEquipment[3];
			headTuple = equipmentKey(equipment); headPriorTuple = equipmentKey(priorEquipment); headStart = f.tick;
		}
		if (!full || !knownProgress(f, prior, Skill.MINING))
		{
			miningFullTicks = 0; miningStart = -1; miningHandled = false; fullMiningGains.clear(); return;
		}
		if (miningFullTicks == 0) { miningStart = f.tick; }
		miningFullTicks = Math.min(60, miningFullTicks + 1);
		prune(fullMiningGains, f.tick - 59);
		if (mining && !miningHandled) { addTick(fullMiningGains, f.tick, 12); }
		if (!miningHandled && miningFullTicks == 60 && recent(fullMiningGains, 12, f.tick))
		{
			Map<String, String> facts = facts(f); facts.put("fullEpisode", Long.toString(miningStart));
			facts.put("occupiedSlots", "28"); facts.put("skill", "MINING"); facts.put("gainTicks", "12");
			out.add(factory.create(f, "M45", 17, 12, "BAG_CAPACITY_REMARK:full:" + miningStart, facts, false, 8));
			miningHandled = true; fullMiningGains.clear();
		}
	}

	/** Replace the existing M09 opportunity, keeping its source revision, ID and deadline. */
	SceneCandidate decorateOutfit(ScenarioSnapshot f, SceneCandidate base, ExpandedScenarioRules.Factory factory)
	{
		Bag bag = Bag.from(f);
		if (!eligible || f.tick != lastTick || !"M09".equals(base.getScenarioId()) || !headEligible
			|| f.tick != headStart + 1 || bag == null || !bag.fullProps()
			|| !"HEAD".equals(base.getConditionFacts().get("changedSlot"))
			|| !"HEAD".equals(base.getConditionFacts().get("changedSlots"))
			|| !headPriorTuple.equals(base.getConditionFacts().get("priorEquipmentIds"))
			|| !headTuple.equals(base.getConditionFacts().get("equipmentIds"))) { return base; }
		Map<String, String> facts = new HashMap<>(base.getConditionFacts()); facts.putAll(facts(f));
		facts.put("namedItemIds", "952,954"); facts.put("occupiedSlots", "28");
		headProof = headTuple; headSerial++; facts.put("hatEpisode", Long.toString(headSerial));
		return new SceneCandidate(base.getId(), "M44", 27, base.getCreatedTick(), base.getExpiresTick(),
			base.getSessionGeneration(), base.getSceneRevision(), base.getCausalToken(), facts,
			base.isIntentionalSilent(), base.getHoldTicks());
	}

	private void persistent(ScenarioSnapshot f, Bag bag, AnchorWindow window, boolean gain,
		String id, int priority, ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		if (!window.observe(f.tick, bag, gain)) { return; }
		Map<String, String> facts = facts(f); facts.put("namedItemIds", Integer.toString(window.item));
		facts.put("anchorSlot", Integer.toString(window.slot)); facts.put("anchorWitness", Long.toString(window.serial));
		facts.put("skill", window.skill.name()); facts.put("gainTicks", Integer.toString(window.gainCount));
		String terminal = window.changedNow ? "inventory-revision:" + f.tick : "skill-gain:" + window.skill + ":" + f.tick;
		out.add(factory.create(f, id, priority, 12, "PERSISTENT_ODD_PROP:" + terminal, facts, false, 8));
		window.restart(f.tick, bag);
	}

	private void arrangement(ScenarioSnapshot f, Bag bag, Bag old, ExpandedScenarioRules.Factory factory,
		List<SceneCandidate> out)
	{
		if (arrangementProof != null && !arrangementProof.equals(bag.layout)) { arrangementProof = null; }
		String multiset = bag.multiset(-1);
		if (bag.occupied < 8 || bag.distinctIds < 4)
		{
			resetArrangement(); return;
		}
		if (arrangementMultiset == null || !arrangementMultiset.equals(multiset))
		{
			resetArrangement(); arrangementMultiset = multiset; arrangementAnchor = bag.layout;
			stableArrangement = bag.layout; arrangementIds = bag.itemIds; return;
		}
		while (!arrangements.isEmpty() && arrangements.peekFirst().tick < f.tick - 99) { arrangements.removeFirst(); }
		if (bag.layout.equals(stableArrangement) || !bag.layout.equals(old.layout)) { return; }
		stableArrangement = bag.layout;
		if (bag.layout.equals(arrangementAnchor)) { return; }
		for (LayoutTick layout : arrangements) { if (layout.key.equals(bag.layout)) { return; } }
		arrangements.addLast(new LayoutTick(f.tick, bag.layout));
		while (arrangements.size() > 3) { arrangements.removeFirst(); }
		if (arrangements.size() == 3)
		{
			arrangementProof = bag.layout; arrangementSerial++;
			Map<String, String> facts = facts(f); facts.put("inventoryLayout", bag.layout);
			facts.put("anchorBagMultiset", arrangementMultiset); facts.put("anchorBagItemIds", arrangementIds);
			facts.put("arrangementEpisode", Long.toString(arrangementSerial));
			out.add(factory.create(f, "M46", 16, 12, "INVENTORY_ARRANGEMENT:confirmation:" + f.tick, facts, false, 6));
			arrangements.clear(); arrangementAnchor = bag.layout;
		}
	}

	boolean stillValid(SceneCandidate c, ScenarioSnapshot f)
	{
		return validate(c, f, false);
	}

	boolean continuationValid(SceneCandidate c, ScenarioSnapshot f)
	{
		return validate(c, f, true);
	}

	private boolean validate(SceneCandidate c, ScenarioSnapshot f, boolean continuation)
	{
		String id = c.getScenarioId();
		if (!handles(id)) { return true; }
		Map<String, String> facts = c.getConditionFacts(); Bag bag = Bag.from(f);
		if (!eligible || f.tick != lastTick || !permitted(f) || bag == null
			|| f.sessionGeneration != c.getSessionGeneration() || f.sceneRevision != c.getSceneRevision()
			|| (!continuation && f.tick >= c.getExpiresTick()) || f.tick < c.getCreatedTick()
			|| !Long.toString(witnessVersion).equals(facts.get("inventoryWitnessVersion"))
			|| !Long.toString(f.presentSinceTick).equals(facts.get("witnessPresenceEpoch"))) { return false; }
		if ("M39".equals(id))
		{
			return bag.eggKit() && bag.layout.equals(kitLayout) && bag.layout.equals(facts.get("inventoryLayout"))
				&& Long.toString(kitStart).equals(facts.get("kitEpisode"));
		}
		if ("M41".equals(id) || "M49".equals(id))
		{
			AnchorWindow window = "M41".equals(id) ? cabbage : rock;
			long latest = "M41".equals(id) ? latestFishing : latestMining;
			return window.slot >= 0 && bag.count(window.item) == 1 && bag.ids[window.slot] == window.item
				&& bag.quantities[window.slot] == 1 && Integer.toString(window.slot).equals(facts.get("anchorSlot"))
				&& Long.toString(window.serial).equals(facts.get("anchorWitness")) && f.tick - latest <= 5;
		}
		if ("M43".equals(id))
		{
			return bag.occupied == 27 && bag.layout.equals(spaceProof) && bag.layout.equals(facts.get("inventoryLayout"))
				&& Long.toString(spaceSerial).equals(facts.get("spaceEpisode"));
		}
		if ("M44".equals(id))
		{
			int[] worn = f.equipment();
			return bag.fullProps() && worn != null && worn.length == 4
				&& equipmentKey(worn).equals(headProof) && headProof.equals(facts.get("equipmentIds"))
				&& Long.toString(headSerial).equals(facts.get("hatEpisode"));
		}
		if ("M45".equals(id))
		{
			return bag.occupied == 28 && miningFullTicks == 60 && f.tick - latestMining <= 5
				&& Long.toString(miningStart).equals(facts.get("fullEpisode"));
		}
		return bag.layout.equals(arrangementProof) && bag.layout.equals(facts.get("inventoryLayout"))
			&& bag.multiset(-1).equals(facts.get("anchorBagMultiset"))
			&& Long.toString(arrangementSerial).equals(facts.get("arrangementEpisode"));
	}

	private static boolean handles(String id)
	{
		return "M39".equals(id) || "M41".equals(id) || "M43".equals(id) || "M44".equals(id)
			|| "M45".equals(id) || "M46".equals(id) || "M49".equals(id);
	}

	void reset()
	{
		witnessVersion++; lastTick = Long.MIN_VALUE; eligible = false; seeded = false; kitArmed = false;
		kitFalse = 0; kitHold = 0; kitMovement = 0; fullTicks = 0; propFullTicks = 0; miningFullTicks = 0;
		kitStart = -1; miningStart = -1; headStart = -1; miningHandled = false; headEligible = false;
		kitLayout = null; pendingSpace = null; spaceProof = null; headTuple = null; headPriorTuple = null; headProof = null;
		latestFishing = Long.MIN_VALUE / 2; latestMining = Long.MIN_VALUE / 2;
		fullMiningGains.clear(); cabbage.reset(); rock.reset(); resetArrangement();
	}

	private void resetArrangement()
	{
		arrangements.clear(); arrangementMultiset = null; arrangementAnchor = null;
		stableArrangement = null; arrangementIds = null; arrangementProof = null;
	}
	private Map<String, String> facts(ScenarioSnapshot f)
	{
		Map<String, String> facts = new HashMap<>(); facts.put("actualRegion", Integer.toString(f.player.region()));
		facts.put("inventoryWitnessVersion", Long.toString(witnessVersion));
		facts.put("witnessPresenceEpoch", Long.toString(f.presentSinceTick)); facts.put("witnessedPresent", "true");
		facts.put("occurredTick", Long.toString(f.tick)); return facts;
	}
	private static String equipmentKey(int[] ids) { return ids[0] + "," + ids[1] + "," + ids[2] + "," + ids[3]; }
	private static void addTick(Deque<Long> ticks, long tick, int cap)
	{
		if (ticks.isEmpty() || ticks.peekLast() != tick) { ticks.addLast(tick); }
		while (ticks.size() > cap) { ticks.removeFirst(); }
	}
	private static void prune(Deque<Long> ticks, long oldest)
	{
		while (!ticks.isEmpty() && ticks.peekFirst() < oldest) { ticks.removeFirst(); }
	}
	private static boolean recent(Deque<Long> ticks, int count, long now)
	{
		return ticks.size() == count && now - ticks.peekLast() <= 5;
	}
	private static final class LayoutTick
	{
		final long tick; final String key;
		LayoutTick(long tick, String key) { this.tick = tick; this.key = key; }
	}
	private static final class AnchorWindow
	{
		final int item, duration, gainCount; final Skill skill;
		final Deque<Long> gains = new ArrayDeque<>();
		final List<String> changes = new ArrayList<>(3);
		int slot = -1; long start, serial;
		String baseline, lastMultiset;
		boolean changedNow;
		AnchorWindow(int item, Skill skill, int duration, int gainCount)
		{
			this.item = item; this.skill = skill; this.duration = duration; this.gainCount = gainCount;
		}
		boolean observe(long tick, Bag bag, boolean gain)
		{
			changedNow = false;
			if (bag.count(item) != 1 || (slot >= 0 && (bag.ids[slot] != item || bag.quantities[slot] != 1))) { reset(); }
			if (slot < 0)
			{
				if (bag.count(item) != 1) { return false; }
				for (int i = 0; i < 28; i++) { if (bag.ids[i] == item && bag.quantities[i] == 1) { slot = i; break; } }
				if (slot < 0) { return false; }
				serial++; restart(tick, bag); return false;
			}
			if (tick - start >= duration) { restart(tick, bag); return false; }
			String current = bag.multiset(slot);
			changedNow = !current.equals(lastMultiset);
			if (changedNow && !current.equals(baseline) && !changes.contains(current) && changes.size() < 3) { changes.add(current); }
			lastMultiset = current;
			if (gain) { addTick(gains, tick, gainCount); }
			return changes.size() == 3 && recent(gains, gainCount, tick);
		}
		void restart(long tick, Bag bag)
		{
			start = tick; gains.clear(); changes.clear(); baseline = bag.multiset(slot); lastMultiset = baseline;
		}
		void reset() { if (slot >= 0) { serial++; } slot = -1; gains.clear(); changes.clear(); baseline = null; lastMultiset = null; }
	}
	private static final class Bag
	{
		final int[] ids, quantities;
		final int occupied, distinctIds;
		final String layout, itemIds;
		private Bag(int[] ids, int[] quantities)
		{
			this.ids = ids; this.quantities = quantities; int filled = 0; TreeSet<Integer> distinct = new TreeSet<>();
			for (int i = 0; i < 28; i++) { if (ids[i] >= 0 && quantities[i] > 0) { filled++; distinct.add(ids[i]); } }
			occupied = filled; distinctIds = distinct.size();
			layout = Arrays.toString(ids) + "/" + Arrays.toString(quantities);
			StringBuilder key = new StringBuilder();
			for (int id : distinct) { if (key.length() > 0) { key.append(','); } key.append(id); }
			itemIds = key.toString();
		}
		static Bag from(ScenarioSnapshot f)
		{
			if (f == null || !f.inventoryKnown()) { return null; }
			int[] ids = f.inventoryIds(), quantities = f.inventoryQuantities();
			if (ids == null || quantities == null || ids.length != 28 || quantities.length != 28) { return null; }
			for (int i = 0; i < 28; i++)
			{
				if (!((ids[i] >= 0 && quantities[i] > 0) || (ids[i] == -1 && quantities[i] == 0))) { return null; }
			}
			return new Bag(ids, quantities);
		}
		long count(int item)
		{
			long count = 0; for (int i = 0; i < 28; i++) { if (ids[i] == item) { count += quantities[i]; } } return count;
		}
		boolean eggKit() { return occupied == 3 && count(954) == 1 && count(1925) == 1 && count(1944) == 1; }
		boolean fullProps() { return occupied == 28 && count(952) > 0 && count(954) > 0; }
		String multiset(int excluded)
		{
			long[] pairs = new long[occupied]; int n = 0;
			for (int i = 0; i < 28; i++)
			{
				if (i != excluded && ids[i] >= 0) { pairs[n++] = ((long) ids[i] << 32) | (quantities[i] & 0xffff_ffffL); }
			}
			pairs = Arrays.copyOf(pairs, n); Arrays.sort(pairs); return Arrays.toString(pairs);
		}
	}
}

package com.malfoid.scenario;

import com.malfoid.scenario.ScenarioRules.CombatState;
import com.malfoid.scenario.ScenarioSnapshot.Position;
import com.malfoid.speech.SceneCandidate;
import com.malfoid.speech.SpeechPacket;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.Map;
import java.util.Random;

/** E.7: fifty committed movement records and one decision for each continuous run. */
final class LongRunRules
{
	private final Deque<Integer> movements = new ArrayDeque<>();
	private final Random random;
	private long session = Long.MIN_VALUE, scene, presence, lastTick = Long.MIN_VALUE;
	private long freshFrom = Long.MIN_VALUE, lastSpoken = Long.MIN_VALUE;
	private int view, tiles, stillTicks;
	private Position previous;
	private boolean consumedRun;
	private SceneCandidate issued;

	LongRunRules() { this(new Random()); }
	LongRunRules(Random random) { this.random = random; }

	SceneCandidate close(ScenarioSnapshot f, boolean localDeath, CombatState combat, boolean following,
		ExpandedScenarioRules.Factory factory)
	{
		if (f.sessionGeneration != session) { resetSession(); session = f.sessionGeneration; }
		if (f.tick == lastTick && f.sceneRevision == scene && f.presentSinceTick == presence) { return null; }
		boolean continuous = healthy(f) && previous != null && lastTick != Long.MIN_VALUE
			&& f.tick == lastTick + 1 && f.sceneRevision == scene && f.presentSinceTick == presence
			&& f.worldViewId == view && f.player.distance(previous) <= 2 && !localDeath;
		int movement = continuous ? f.player.distance(previous) : 0;
		lastTick = f.tick; scene = f.sceneRevision; presence = f.presentSinceTick; view = f.worldViewId;
		previous = healthy(f) && !localDeath ? f.player : null;
		if (!continuous)
		{
			invalidateWindow(); freshFrom = f.tick + 1; return null;
		}
		stillTicks = movement == 0 ? Math.min(10, stillTicks + 1) : 0;
		if (consumedRun && stillTicks == 10)
		{
			consumedRun = false; freshFrom = f.tick + 1; issued = null;
		}
		movements.addLast(movement); tiles += movement;
		if (movements.size() > 50) { tiles -= movements.removeFirst(); }
		if (issued != null && !valid(issued, f, combat, following, false)) { issued = null; }
		long windowStart = f.tick - 49;
		if (consumedRun || movements.size() != 50 || tiles < 60 || !ready(f, combat, following)
			|| windowStart < f.presentSinceTick || windowStart < freshFrom
			|| lastSpoken != Long.MIN_VALUE && (f.tick < lastSpoken || f.tick - lastSpoken < 500)) { return null; }
		consumedRun = true;
		// This is the only probability draw. A silent answer consumes this run too.
		if (!random.nextBoolean()) { return null; }
		Map<String, String> facts = new HashMap<>();
		facts.put("runWindowStartTick", Long.toString(windowStart));
		facts.put("runWindowTiles", Integer.toString(tiles));
		facts.put("runWorldViewId", Integer.toString(f.worldViewId));
		facts.put("witnessPresenceEpoch", Long.toString(f.presentSinceTick));
		// E.7 fixes priority and expiry; the four ticks are readable presentation, never a physical hold.
		issued = factory.create(f, "F03", 30, 12, "long-run:" + f.tick, facts, false, 4);
		return issued;
	}

	boolean stillValid(SceneCandidate c, ScenarioSnapshot f, CombatState combat, boolean following)
	{
		return issued != null && issued.getId() == c.getId() && issued.getCausalToken().equals(c.getCausalToken())
			&& valid(c, f, combat, following, true);
	}
	boolean continuationValid(SceneCandidate c, ScenarioSnapshot f, CombatState combat, boolean following)
	{
		return issued != null && issued.getId() == c.getId() && issued.getCausalToken().equals(c.getCausalToken())
			&& valid(c, f, combat, following, false);
	}
	private static boolean valid(SceneCandidate c, ScenarioSnapshot f, CombatState combat, boolean following, boolean deadline)
	{
		return "F03".equals(c.getScenarioId()) && ready(f, combat, following)
			&& f.sessionGeneration == c.getSessionGeneration() && f.sceneRevision == c.getSceneRevision()
			&& Long.toString(f.presentSinceTick).equals(c.getConditionFacts().get("witnessPresenceEpoch"))
			&& Integer.toString(f.worldViewId).equals(c.getConditionFacts().get("runWorldViewId"))
			&& f.tick >= c.getCreatedTick() && (!deadline || f.tick < c.getExpiresTick());
	}
	private static boolean ready(ScenarioSnapshot f, CombatState combat, boolean following)
	{
		return healthy(f) && following && combat != CombatState.CONFIRMED && !f.emergencySceneActive;
	}
	private static boolean healthy(ScenarioSnapshot f)
	{
		return f != null && f.valid && f.present && !f.userHidden && !f.autoAbsent && !f.dead
			&& f.currentHp > 0 && f.player != null && f.companion != null
			&& f.presentSinceTick >= 0 && f.tick >= f.presentSinceTick && f.player.plane == f.companion.plane;
	}

	/** Only a genuine first-paint receipt starts the separate 500-tick timer. */
	void onFirstPaint(SpeechPacket.PaintReceipt receipt)
	{
		if (receipt != null && "F03".equals(receipt.getCandidate().getScenarioId())
			&& receipt.getCandidate().getSessionGeneration() == session)
		{
			lastSpoken = Math.max(lastSpoken, receipt.getPaintedAtTick());
		}
	}
	void invalidateWindow()
	{
		movements.clear(); tiles = stillTicks = 0; issued = null;
	}
	void resetScene()
	{
		invalidateWindow(); previous = null; lastTick = freshFrom = Long.MIN_VALUE;
	}
	void resetSession()
	{
		resetScene(); session = Long.MIN_VALUE; scene = presence = 0; lastSpoken = Long.MIN_VALUE; consumedRun = false;
	}
}

package com.malfoid.scenario;

import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.ChatLineBuffer;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MessageNode;
import net.runelite.api.VarbitComposition;
import net.runelite.api.events.ChatMessage;

/** Two native personal events, with bounded item/task identities and no player chat or client objects retained. */
public final class PersonalMilestones
{
	private static final Pattern COLLECTION = Pattern.compile("New item added to your collection log: <col=ef1020>([^<>@\\p{Cntrl}]{1,96})</col>");
	private static final Pattern ACHIEVEMENT = Pattern.compile("Congratulations, you've completed (an easy|a medium|a hard|an elite|a master|a grandmaster) combat task: @ach_comp@([^<>@\\p{Cntrl}]{1,120})</col>\\.");
	private static final Pattern GRANDMASTER = Pattern.compile("Congratulations, you've completed a grandmaster combat task: @ach_comp@([^<>@\\p{Cntrl}]{1,120})</col> \\(6 points\\)\\.");
	private final Client client;
	private final int[] seen = new int[128];
	private final int[] seenTimestamps = new int[128], seenKinds = new int[128];
	private final String[] seenFacts = new String[128];
	private final List<Proof> pending = new ArrayList<>();
	private final Set<Proof> issued = Collections.newSetFromMap(new IdentityHashMap<>());
	private int seenSize, seenNext;
	private long tick = -1, epoch = -1, serial;
	private long generation = -1, revision = -1;
	private boolean witnessed, overflow;

	PersonalMilestones(Client client) { this.client = client; }

	void beginInterval(long nextTick, long generation, long revision, long presenceEpoch, boolean witness)
	{
		if (this.generation != generation)
		{
			java.util.Arrays.fill(seenFacts, null); seenSize = seenNext = 0;
		}
		if (this.generation != generation || this.revision != revision || epoch != presenceEpoch || witnessed != witness
			|| nextTick != tick && nextTick != tick + 1) { reset(); }
		if (nextTick != tick) { overflow = false; }
		tick = nextTick; this.generation = generation; this.revision = revision; epoch = presenceEpoch; witnessed = witness;
		refresh();
	}

	void onChatMessage(ChatMessage event)
	{
		if (event == null || event.getType() != ChatMessageType.GAMEMESSAGE || generation < 0 || revision < 0) { return; }
		String raw = event.getMessage();
		if (raw == null || raw.length() > 512) { return; }
		Matcher collection = COLLECTION.matcher(raw), achievement = ACHIEVEMENT.matcher(raw), grandmaster = GRANDMASTER.matcher(raw);
		int ruleIndex;
		String display;
		if (collection.matches()) { ruleIndex = 142; display = collection.group(1); }
		else if (achievement.matches())
		{
			ruleIndex = 147; display = achievement.group(2);
		}
		else if (grandmaster.matches()) { ruleIndex = 147; display = grandmaster.group(1); }
		else { return; }
		if (!validDisplay(display, ruleIndex == 142 ? 96 : 120)) { return; }

		MessageNode node = event.getMessageNode();
		if (node == null || node.getType() != event.getType() || node.getTimestamp() != event.getTimestamp() || !raw.equals(node.getValue()))
		{
			reset(); overflow = true; return;
		}
		java.util.Map<Integer, ChatLineBuffer> buffers = client.getChatLineMap();
		ChatLineBuffer buffer = buffers == null ? null : buffers.get(event.getType().getType());
		MessageNode[] lines = buffer == null ? null : buffer.getLines();
		if (lines == null || buffer.getLength() <= 0 || buffer.getLength() > lines.length) { reset(); overflow = true; return; }
		if (lines[0] != node) { return; }
		String fact = achievement.matches() ? achievement.group(1) + ":" + display : display;
		for (int i = 0; i < seenSize; i++)
		{
			if (seen[i] != node.getId()) { continue; }
			if (seenTimestamps[i] != event.getTimestamp() || seenKinds[i] != ruleIndex || !fact.equals(seenFacts[i]))
			{
				reset(); overflow = true;
			}
			return;
		}
		seenTimestamps[seenNext] = event.getTimestamp(); seenKinds[seenNext] = ruleIndex; seenFacts[seenNext] = fact;
		seen[seenNext] = node.getId(); seenNext = (seenNext + 1) % seen.length; seenSize = Math.min(seen.length, seenSize + 1);
		// Even a hidden, settling or suppressed event is consumed; it cannot become a later reaction.
		if (!witnessed || overflow || tick < 0 || tick - epoch < 10 || tick > Long.MAX_VALUE - 20
			|| ruleIndex == 142 && !collectionEnabled()) { return; }
		if (issued.size() >= 16 || serial == Long.MAX_VALUE) { reset(); overflow = true; return; }
		long id = ++serial;
		Proof context = new Proof(ruleIndex, id, tick, generation, revision, epoch);
		pending.add(context); issued.add(context);
	}

	List<Proof> drain()
	{
		refresh();
		List<Proof> result = new ArrayList<>(pending);
		pending.clear();
		return result;
	}

	boolean current(Proof context)
	{
		refresh();
		return witnessed && issued.contains(context) && context.sessionGeneration == generation && context.sceneRevision == revision && context.presenceEpoch == epoch;
	}

	void refresh()
	{
		boolean collectionEnabled = collectionEnabled();
		issued.removeIf(context -> tick >= context.originalDeadline && tick - context.originalDeadline >= 40
			|| context.ruleIndex == 142 && !collectionEnabled);
		pending.removeIf(context -> !issued.contains(context));
	}

	private boolean collectionEnabled()
	{
		VarbitComposition definition = client.getVarbit(11959);
		int[] varps = client.getVarps();
		return definition != null && varps != null && definition.getIndex() >= 0 && definition.getIndex() < varps.length
			&& definition.getLeastSignificantBit() >= 0 && definition.getMostSignificantBit() >= definition.getLeastSignificantBit()
			&& definition.getMostSignificantBit() < 32 && client.getVarbitValue(11959) == 1;
	}

	private static boolean validDisplay(String text, int maximum)
	{
		if (text.trim().isEmpty() || text.codePointCount(0, text.length()) > maximum) { return false; }
		for (int i = 0; i < text.length(); i++)
		{
			char c = text.charAt(i);
			if (Character.isHighSurrogate(c))
			{
				if (++i >= text.length() || !Character.isLowSurrogate(text.charAt(i))) { return false; }
			}
			else if (Character.isLowSurrogate(c)) { return false; }
		}
		return true;
	}

	/** Only this collector can create a proof; consumers receive immutable scalar facts. */
	public static final class Proof
	{
		public final int ruleIndex;
		public final String ruleId;
		public final long sourceSerial, occurrenceTick, originalDeadline, sessionGeneration, sceneRevision, presenceEpoch;
		private Proof(int ruleIndex, long serial, long tick, long generation, long revision, long epoch)
		{
			this.ruleIndex = ruleIndex; ruleId = "M" + ruleIndex; sourceSerial = serial;
			occurrenceTick = tick; originalDeadline = tick + 20;
			sessionGeneration = generation; sceneRevision = revision; presenceEpoch = epoch;
		}
		public boolean owns(com.malfoid.speech.SceneCandidate candidate)
		{
			return ruleId.equals(candidate.getScenarioId()) && sessionGeneration == candidate.getSessionGeneration()
				&& sceneRevision == candidate.getSceneRevision() && originalDeadline == candidate.getExpiresTick()
				&& occurrenceTick <= candidate.getCreatedTick() && presenceEpoch <= occurrenceTick;
		}
	}

	void reset() { pending.clear(); issued.clear(); }
}

package com.malfoid.scenario;

import com.malfoid.motion.MotionObservation;
import com.malfoid.scenario.ExpandedScenarioRules.Factory;
import com.malfoid.scenario.ScenarioRules.CombatState;
import com.malfoid.speech.SceneCandidate;
import com.malfoid.speech.SpeechCancellationReceipt;
import com.malfoid.speech.SpeechCancellationReceipt.Reason;
import com.malfoid.speech.SpeechPacket;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

/** One quiet replacement from resolved OWN execution receipts, never inferred equipment callbacks. */
final class QuietOutfitRules
{
	private final long[] executions = new long[3], cancelledAt = new long[3];
	private long lastExecution, lastPaintToken = -1, lastTick = -1, session = -1, scene = -1, epoch = -1;
	private long tupleFirst = -1;
	private int count, baselines, equalCopies, worldView = Integer.MIN_VALUE, plane = -1;
	private int[] tuple;
	private boolean eligible, receiptsKnown = true;
	private SceneCandidate issued;

	void onCancellation(SpeechCancellationReceipt receipt)
	{
		if (receipt == null) { return; }
		onCancellation(new Cancellation(receipt.getCandidate(), receipt.getExecutionId(), receipt.getCancelledAtTick(),
			receipt.getReason(), receipt.isGenuinePainted(), receipt.isPrePaintAttempt(), true));
	}

	void onCancellation(Cancellation receipt)
	{
		if (receipt == null || receipt.execution <= lastExecution || receipt.execution <= 0) { return; }
		lastExecution = receipt.execution;
		SceneCandidate candidate = receipt.candidate;
		if (candidate == null || !outfit(candidate.getScenarioId()) || candidate.getSessionGeneration() != session
			|| candidate.getSceneRevision() != scene || number(candidate, "witnessPresenceEpoch") != epoch) { return; }
		if (!receipt.ledgerKnown)
		{
			receiptsKnown = false; clearPattern(); issued = null; return;
		}
		if (receipt.genuinePainted) { clearPattern(); issued = null; return; }
		if (!receipt.prePaintAttempt || receipt.reason != Reason.DEPENDENT_OUTFIT_REVISION_CHANGED
			|| !eligible || baselines < 2 || receipt.tick < epoch || receipt.tick < candidate.getCreatedTick()
			|| receipt.tick >= candidate.getExpiresTick()
			|| receipt.tick < lastTick - 79 || receipt.tick > lastTick + 1
			|| !"true".equals(candidate.getConditionFacts().get("witnessedPresent"))
			|| number(candidate, "occurredTick") != candidate.getCreatedTick() || candidate.getCreatedTick() < epoch
			|| !knownTuple(candidate.getConditionFacts().get("equipmentIds"))
			|| number(candidate, "outfitRevision") <= 0
			|| !candidate.getCausalToken().equals("outfit:" + number(candidate, "outfitRevision"))) { return; }
		receiptsKnown = true;
		prune(receipt.tick);
		if (count == 3)
		{
			System.arraycopy(executions, 1, executions, 0, 2);
			System.arraycopy(cancelledAt, 1, cancelledAt, 0, 2); count--;
		}
		executions[count] = receipt.execution; cancelledAt[count] = receipt.tick; count++;
	}

	void onFirstPaint(SpeechPacket.PaintReceipt receipt)
	{
		if (receipt != null) { onFirstPaint(receipt.getCandidate(), receipt.getAdmissionToken(), receipt.getPaintedAtTick(), true); }
	}

	void onFirstPaint(SceneCandidate candidate, long admissionToken, long paintedTick, boolean issuedTokenVerified)
	{
		if (!issuedTokenVerified || candidate == null || admissionToken <= lastPaintToken || admissionToken < 0) { return; }
		lastPaintToken = admissionToken;
		if (outfit(candidate.getScenarioId()) && candidate.getSessionGeneration() == session
			&& candidate.getSceneRevision() == scene && number(candidate, "witnessPresenceEpoch") == epoch
			&& paintedTick >= epoch) { clearPattern(); issued = null; }
	}

	void close(ScenarioSnapshot f, CombatState combat, long lastDamage)
	{
		if (f.tick == lastTick) { return; }
		int[] copied = f.equipment();
		boolean continuous = lastTick >= 0 && f.tick == lastTick + 1 && f.sessionGeneration == session
			&& f.sceneRevision == scene && f.presentSinceTick == epoch && f.worldViewId == worldView
			&& f.player != null && f.player.plane == plane;
		boolean ready = ready(f, copied, combat, lastDamage);
		if (!continuous || !ready)
		{
			reset(); bind(f); lastTick = f.tick; eligible = ready;
			if (ready) { tuple = copied; tupleFirst = f.tick; equalCopies = 1; baselines = 1; }
			return;
		}
		lastTick = f.tick; eligible = true; baselines = Math.min(2, baselines + 1); prune(f.tick);
		if (Arrays.equals(tuple, copied)) { equalCopies = Math.min(2, equalCopies + 1); }
		else { tuple = copied; tupleFirst = f.tick; equalCopies = 1; }
		if (issued != null && (!key(copied).equals(issued.getConditionFacts().get("equipmentIds"))
			|| f.tick > issued.getExpiresTick() + 40)) { issued = null; clearPattern(); }
	}

	SceneCandidate decorate(ScenarioSnapshot f, SceneCandidate base, CombatState combat, long lastDamage, Factory factory)
	{
		if (base == null || !outfit(base.getScenarioId())) { return base; }
		if (!receiptsKnown || !eligible || f.tick != lastTick || baselines < 2 || count != 3 || equalCopies < 2
			|| f.tick <= cancelledAt[2] || tupleFirst < cancelledAt[2] || f.tick - cancelledAt[0] >= 80
			|| !ready(f, f.equipment(), combat, lastDamage) || !ownedCurrent(base, f)
			|| base.getCreatedTick() < cancelledAt[2] || base.getCreatedTick() > f.tick
			|| f.tick >= base.getExpiresTick() || base.isIntentionalSilent()) { return base; }
		Map<String, String> facts = new HashMap<>(base.getConditionFacts());
		facts.put("quietCancellationCount", "3");
		facts.put("quietFirstCancellationTick", Long.toString(cancelledAt[0]));
		facts.put("quietLastCancellationTick", Long.toString(cancelledAt[2]));
		facts.put("quietWorldViewId", Integer.toString(worldView));
		issued = new SceneCandidate(base.getId(), "M47", 29, base.getCreatedTick(), base.getExpiresTick(),
			base.getSessionGeneration(), base.getSceneRevision(), base.getCausalToken(), facts, true, 8);
		clearPattern(); return issued;
	}

	boolean stillValid(SceneCandidate candidate, ScenarioSnapshot f, CombatState combat, long lastDamage)
	{
		return continuationValid(candidate, f, combat, lastDamage) && f.tick < candidate.getExpiresTick();
	}

	boolean continuationValid(SceneCandidate candidate, ScenarioSnapshot f, CombatState combat, long lastDamage)
	{
		return candidate != null && candidate == issued && receiptsKnown && "M47".equals(candidate.getScenarioId())
			&& ready(f, f.equipment(), combat, lastDamage) && ownedCurrent(candidate, f)
			&& f.worldViewId == worldView && f.player.plane == plane && f.presentSinceTick == epoch;
	}

	void reset()
	{
		clearPattern(); tuple = null; issued = null; tupleFirst = -1; lastTick = -1;
		baselines = 0; equalCopies = 0; eligible = false; receiptsKnown = true;
		session = -1; scene = -1; epoch = -1; worldView = Integer.MIN_VALUE; plane = -1;
		// Execution/admission high-water marks survive narrative reset, so consumed receipts cannot return.
	}

	private void bind(ScenarioSnapshot f)
	{
		session = f.sessionGeneration; scene = f.sceneRevision; epoch = f.presentSinceTick; worldView = f.worldViewId;
		plane = f.player == null ? -1 : f.player.plane;
	}
	private void clearPattern() { count = 0; Arrays.fill(executions, 0); Arrays.fill(cancelledAt, 0); }
	private void prune(long tick)
	{
		while (count > 0 && tick - cancelledAt[0] >= 80)
		{
			System.arraycopy(executions, 1, executions, 0, count - 1);
			System.arraycopy(cancelledAt, 1, cancelledAt, 0, count - 1); count--;
			executions[count] = 0; cancelledAt[count] = 0;
		}
	}
	private boolean ownedCurrent(SceneCandidate candidate, ScenarioSnapshot f)
	{
		return candidate.getSessionGeneration() == session && candidate.getSceneRevision() == scene
			&& f.sessionGeneration == session && f.sceneRevision == scene
			&& f.tick >= candidate.getCreatedTick()
			&& "true".equals(candidate.getConditionFacts().get("witnessedPresent"))
			&& number(candidate, "witnessPresenceEpoch") == epoch && number(candidate, "occurredTick") == candidate.getCreatedTick()
			&& candidate.getCreatedTick() >= epoch
			&& number(candidate, "outfitRevision") > 0
			&& candidate.getCausalToken().equals("outfit:" + number(candidate, "outfitRevision"))
			&& key(f.equipment()).equals(candidate.getConditionFacts().get("equipmentIds"));
	}
	private static boolean ready(ScenarioSnapshot f, int[] items, CombatState combat, long lastDamage)
	{
		if (!f.valid || !f.present || f.userHidden || f.autoAbsent || f.dead || f.currentHp <= 0 || f.player == null
			|| f.companion == null || f.player.plane != f.companion.plane || f.worldViewId == Integer.MIN_VALUE
			|| f.presentSinceTick < 0 || f.tick - f.presentSinceTick < 10 || f.tick - lastDamage < 10
			|| combat != CombatState.NO_CONFIRMED_EVIDENCE || f.emergencySceneActive || f.outfitBlocked || f.inventoryBlocked
			|| items == null || items.length != 4) { return false; }
		for (int item : items) { if (item < -1) { return false; } }
		return f.motion == null || f.motion.purpose != MotionObservation.Purpose.CATCHUP
			|| f.motion.known && f.motion.completedTick >= 0;
	}
	private static boolean outfit(String id)
	{
		return "M09".equals(id) || "M31".equals(id) || "M32".equals(id) || "M33".equals(id)
			|| "M34".equals(id) || "M44".equals(id);
	}
	private static String key(int[] items)
	{
		return items == null || items.length != 4 ? "" : items[0] + "," + items[1] + "," + items[2] + "," + items[3];
	}
	private static boolean knownTuple(String fact)
	{
		if (fact == null) { return false; }
		String[] slots = fact.split(",", -1);
		if (slots.length != 4) { return false; }
		try { for (String slot : slots) { if (Integer.parseInt(slot) < -1) { return false; } } }
		catch (NumberFormatException e) { return false; }
		return true;
	}
	private static long number(SceneCandidate candidate, String field)
	{
		try { return Long.parseLong(candidate.getConditionFacts().get(field)); }
		catch (NumberFormatException e) { return -1; }
	}

	/** Copied-input seam; production input comes exclusively from the typed director receipt. */
	static final class Cancellation
	{
		final SceneCandidate candidate;
		final long execution, tick;
		final Reason reason;
		final boolean genuinePainted, prePaintAttempt, ledgerKnown;
		Cancellation(SceneCandidate candidate, long execution, long tick, Reason reason,
			boolean genuinePainted, boolean prePaintAttempt, boolean ledgerKnown)
		{
			this.candidate = candidate; this.execution = execution; this.tick = tick; this.reason = reason;
			this.genuinePainted = genuinePainted; this.prePaintAttempt = prePaintAttempt; this.ledgerKnown = ledgerKnown;
		}
	}
}

