					? !sceneryDefinitionMatches(object, candidate) : ScenarioRules.objectKind(name) == null)
					? SpeechCancellationReceipt.Reason.INSPECTION_TARGET_LOST : null;
			}
			return SpeechCancellationReceipt.Reason.INSPECTION_TARGET_LOST;
		}
		return null;
	}
