	{
		this.approach = approach; this.run = run; minDistance = min; maxDistance = max; holdTicks = hold;
		releaseTicks = release; runBurstMaxTicks = burst; this.facing = facing;
		standWorldX = standX; standWorldY = standY; subjectWorldX = subjectX; subjectWorldY = subjectY;
		this.voluntaryTrip = voluntaryTrip;
		preservesNativeMotion = facing == Facing.NATIVE;
	}
	/** A denied trip keeps the witnessed scene's original deadline; it does not create a later trip. */
	public boolean voluntaryTripAllowed(long tick, long lastActualVoluntaryMovementTick)
	{
		return !voluntaryTrip || lastActualVoluntaryMovementTick < 0
			|| tick >= lastActualVoluntaryMovementTick && tick - lastActualVoluntaryMovementTick >= 100;
	}

	public static ScenePlan forCandidate(SceneCandidate c, int companionDistance, boolean headVisible)
	{
		return forCandidate(c, companionDistance, headVisible, c.isIntentionalSilent());
	}
	public static ScenePlan forCandidate(SceneCandidate c, int companionDistance, boolean headVisible, boolean intentionalSilent)
	{
		return forCandidate(c, companionDistance, headVisible, intentionalSilent, c.getHoldTicks());
	}
	public static ScenePlan forCandidate(SceneCandidate c, int companionDistance, boolean headVisible, boolean intentionalSilent, int executionHoldTicks)
	{
		String id = c.getScenarioId(); Map<String, String> f = c.getConditionFacts();
		if ("F03".equals(id) || com.malfoid.motion.CreatureAwareness.isE5(id))
		{
			return new ScenePlan(false, false, 0, 0, 0, 0, 0, Facing.NATIVE, null, null, null, null, false);
		}
		if ("PLACE".equals(f.get("livingWorld")) || "CREATURE".equals(f.get("livingWorld")))
		{
			return new ScenePlan(false, false, 0, 0, 0, 0, 0, Facing.PLAYER, null, null, null, null, false);
		}
		if ("M01".equals(id)) { return player(true, true, 1, 2, 20, 10, 0); }
		if ("M02".equals(id)) { return player(true, false, 2, 2, 15, 10, 0); }
		if (c.isMilestone99()) { return player(true, true, 1, 2, 8, 0, 0); }
		if ("M05".equals(id)) { return player(true, true, 2, 2, 10, 0, 0); }
		if ("M07".equals(id)) { return player(true, companionDistance >= 8, 2, 3, c.getHoldTicks(), 0, 6); }
		if ("M08".equals(id) || "M69".equals(id) || "SCENERY".equals(f.get("livingWorld")))
		{
			return new ScenePlan(true, false, 0, 0, c.getHoldTicks(), 0, 0, Facing.OBJECT,
				integer(f, "targetX"), integer(f, "targetY"), integer(f, "objectX"), integer(f, "objectY"), true);
		}
		if ("U01".equals(id) && "4".equals(f.get("talkStreak")))
		{
			return new ScenePlan(false, false, 4, 5, 5, 0, 0, Facing.AWAY, null, null, null, null, false);
		}
		if ("E01".equals(id))
		{
			Integer animation = integer(f, "emoteAnimation");
			if (animation != null && animation == AnimationID.EMOTE_BECKON) { return player(true, false, 1, 2, 5, 0, 0); }
			Facing facing = animation != null && (animation == AnimationID.EMOTE_DANCE || animation == AnimationID.EMOTE_BLOW_KISS) ? Facing.AWAY : Facing.PLAYER;
			return new ScenePlan(false, false, 0, 8, c.getHoldTicks(), 0, 0, facing, null, null, null, null, false);
		}
		if ("U01".equals(id)) { return player(true, false, 2, 3, c.getHoldTicks(), 0, 0); }
		boolean approach = !intentionalSilent && (companionDistance > 5 || !headVisible);
		Facing facing = f.containsKey("targetKey") ? Facing.TARGET : Facing.PLAYER;
		return new ScenePlan(approach, false, 3, 5, "M06".equals(id) ? executionHoldTicks : c.getHoldTicks(), 0, 0, facing, null, null,
			integer(f, "targetX"), integer(f, "targetY"), false);
	}
	private static ScenePlan player(boolean approach, boolean run, int min, int max, int hold, int release, int burst)
	{
		return new ScenePlan(approach, run, min, max, hold, release, burst, Facing.PLAYER, null, null, null, null, false);
	}
	private static Integer integer(Map<String, String> facts, String key)
	{
		String value = facts.get(key);
		return value == null ? null : Integer.valueOf(value);
	}
}

package com.malfoid.scenario;

import com.malfoid.scenario.ScenarioBatch.Hit;
import com.malfoid.scenario.ScenarioRules.CombatState;
import com.malfoid.scenario.ScenarioRules.SkillDelta;
import com.malfoid.scenario.ScenarioSnapshot.Position;
import com.malfoid.speech.SceneCandidate;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.HitsplatID;
import net.runelite.api.Skill;

/** M22/M24/M25/M27/M30 use only complete, presence-bound committed copies. */
final class SkillExpansionRules
{
	private static final Skill[] PRIMARY = {Skill.FISHING, Skill.WOODCUTTING, Skill.MINING};
	private final EnumMap<Skill, Burst> bursts = new EnumMap<>(Skill.class);
	private final Deque<TileTick> burstPositions = new ArrayDeque<>();
	private final Deque<TileTick> moving = new ArrayDeque<>();
	private final Deque<Gain> agility = new ArrayDeque<>();
	private final Map<String, SceneCandidate> issued = new HashMap<>();
	private long craftingGain = -1, smithingGain = -1, drainStart = -1;
	private long lastOwnedNpcCombat = Long.MIN_VALUE / 2, lastTick = Long.MIN_VALUE;
	private long lastSession, lastScene, lastPresence;
	private int equalLevelSamples, drainedSamples, drainXp, drainReal, agilitySamples;
	private Gain drop;
	private boolean ambiguousDrop;

	SkillExpansionRules()
	{
		for (Skill skill : PRIMARY) { bursts.put(skill, new Burst()); }
	}

	List<SceneCandidate> close(ScenarioSnapshot f, ScenarioSnapshot prior, ScenarioBatch batch, List<SkillDelta> deltas,
		CombatState combat, long lastDamage, ExpandedScenarioRules.Factory factory)
	{
		List<SceneCandidate> out = new ArrayList<>();
		if (f.tick == lastTick && f.sessionGeneration == lastSession && f.sceneRevision == lastScene
			&& f.presentSinceTick == lastPresence) { return out; }
		boolean consecutive = lastTick == Long.MIN_VALUE || f.tick == lastTick + 1
			&& f.sessionGeneration == lastSession && f.sceneRevision == lastScene && f.presentSinceTick == lastPresence;
		if (!consecutive || !continuous(f, prior) || batch.localDeath || combat == CombatState.UNKNOWN)
		{
			reset(); remember(f); return out;
		}
		remember(f);
		issued.entrySet().removeIf(entry -> !conditions(entry.getValue(), f, combat, lastDamage, false)
			|| selectedProgressInvalid(entry.getValue(), f, prior));
		boolean terminalLevel = false;
		for (SkillDelta delta : deltas)
		{
			if (delta.delta > 0 && delta.newLevel > delta.oldLevel && batch.witnessedSkills.contains(delta.skill))
			{
				terminalLevel = true;
			}
		}
		boolean terminalReady = !terminalLevel && !f.emergencySceneActive
			&& combat == CombatState.NO_CONFIRMED_EVIDENCE && f.tick - lastDamage >= 10;
		if (combat == CombatState.NO_CONFIRMED_EVIDENCE)
		{
			equality(f, prior, terminalReady, factory, out);
			burstReturn(f, prior, terminalReady, factory, out);
			movingFiremaking(f, prior, terminalReady, factory, out);
			restoration(f, prior, terminalReady, factory, out);
		}
		else { resetOrdinary(); }
		// Incoming damage at a counted Agility gain is expressly allowed in its earlier history.
		agilityAfterDrop(f, prior, batch, terminalReady, factory, out);
		return out;
	}

	private void equality(ScenarioSnapshot f, ScenarioSnapshot prior, boolean ready,
		ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		if (!unchanged(f, prior, Skill.CRAFTING) || !unchanged(f, prior, Skill.SMITHING))
		{
			craftingGain = -1; smithingGain = -1; equalLevelSamples = 0; return;
		}
		equalLevelSamples = Math.min(10, equalLevelSamples + 1);
		if (craftingGain < f.tick - 9) { craftingGain = -1; }
		if (smithingGain < f.tick - 9) { smithingGain = -1; }
		boolean craft = gain(f, prior, Skill.CRAFTING), smith = gain(f, prior, Skill.SMITHING);
		long other = craft ? smithingGain : craftingGain;
		if (ready && equalLevelSamples >= 10 && craft != smith && other >= f.tick - 9 && other < f.tick
			&& f.xp(Skill.CRAFTING) > 0 && f.xp(Skill.CRAFTING) == f.xp(Skill.SMITHING)
			&& prior.xp(Skill.CRAFTING) != prior.xp(Skill.SMITHING))
		{
			Map<String, String> facts = facts(f, null, 4);
			facts.put("matchedTotal", Integer.toString(f.xp(Skill.CRAFTING)));
			facts.put("craftingRealLevel", Integer.toString(f.level(Skill.CRAFTING)));
			facts.put("smithingRealLevel", Integer.toString(f.level(Skill.SMITHING)));
			facts.put("otherGainTick", Long.toString(other));
			emit(f, "M22", 30, 8, "progress:" + f.tick, facts, 4, factory, out);
		}
		if (craft) { craftingGain = f.tick; }
		if (smith) { smithingGain = f.tick; }
	}

	private void burstReturn(ScenarioSnapshot f, ScenarioSnapshot prior, boolean ready,
		ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		burstPositions.addLast(new TileTick(f.tick, f.player, false));
		while (!burstPositions.isEmpty() && burstPositions.peekFirst().tick < f.tick - 29) { burstPositions.removeFirst(); }
		Return selected = null;
		for (Skill skill : PRIMARY)
		{
			Burst burst = bursts.get(skill);
			if (!unchanged(f, prior, skill)) { burst.reset(); continue; }
			while (!burst.gains.isEmpty() && burst.gains.peekFirst() < f.tick - 29) { burst.gains.removeFirst(); }
			boolean positive = gain(f, prior, skill);
			if (burst.armed)
			{
				burst.include(f.player);
				if (f.tick - burst.first >= 100 || !burst.fits()) { burst.reset(); }
				else if (positive)
				{
					long gap = f.tick - burst.lastGain - 1;
					if (gap >= 40 && gap <= 59)
					{
						Return next = new Return(skill, burst, gap);
						if (selected == null || next.lastGain > selected.lastGain
							|| next.lastGain == selected.lastGain && skill.ordinal() < selected.skill.ordinal()) { selected = next; }
						burst.reset();
					}
					else { burst.lastGain = f.tick; }
				}
				else if (f.tick - burst.lastGain >= 60) { burst.reset(); }
			}
			if (positive) { burst.gains.addLast(f.tick); }
			if (!burst.armed && burst.gains.size() >= 6)
			{
				burst.first = burst.gains.peekFirst(); burst.lastGain = f.tick; burst.minX = burst.maxX = f.player.x;
				burst.minY = burst.maxY = f.player.y;
				for (TileTick sample : burstPositions) { if (sample.tick >= burst.first) { burst.include(sample.position); } }
				if (burst.fits()) { burst.armed = true; } else { burst.reset(); }
			}
		}
		if (selected != null && ready)
		{
			Map<String, String> facts = facts(f, selected.skill, 8);
			facts.put("realLevel", Integer.toString(f.level(selected.skill)));
			facts.put("quietGapTicks", Long.toString(selected.gap));
			facts.put("burstFirstTick", Long.toString(selected.first)); facts.put("preGapGainTick", Long.toString(selected.lastGain));
			facts.put("minX", Integer.toString(selected.minX)); facts.put("maxX", Integer.toString(selected.maxX));
			facts.put("minY", Integer.toString(selected.minY)); facts.put("maxY", Integer.toString(selected.maxY));
			emit(f, "M24", 24, 12, "progress:" + f.tick, facts, 5, factory, out);
		}
	}

	private void movingFiremaking(ScenarioSnapshot f, ScenarioSnapshot prior, boolean ready,
		ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		if (!unchanged(f, prior, Skill.FIREMAKING)) { moving.clear(); return; }
		boolean positive = gain(f, prior, Skill.FIREMAKING);
		moving.addLast(new TileTick(f.tick, f.player, positive));
		while (moving.size() > 40) { moving.removeFirst(); }
		if (moving.size() < 40 || !positive) { return; }
		int count = 0, distance = 0, minX = f.player.x, maxX = f.player.x, minY = f.player.y, maxY = f.player.y;
		Set<Position> tiles = new HashSet<>(); Position previous = null;
		for (TileTick sample : moving)
		{
			if (sample.positive) { count++; tiles.add(sample.position); }
			if (previous != null) { distance += previous.distance(sample.position); }
			previous = sample.position;
			minX = Math.min(minX, previous.x); maxX = Math.max(maxX, previous.x);
			minY = Math.min(minY, previous.y); maxY = Math.max(maxY, previous.y);
		}
		if (count < 8 || tiles.size() < 6 || distance < 16 || maxX - minX < 8 && maxY - minY < 8) { return; }
		if (ready)
		{
			Map<String, String> facts = facts(f, Skill.FIREMAKING, 8);
			facts.put("realLevel", Integer.toString(f.level(Skill.FIREMAKING)));
			facts.put("gainTicks", Integer.toString(count)); facts.put("gainTiles", Integer.toString(tiles.size()));
			facts.put("observedDistance", Integer.toString(distance));
			facts.put("xSpan", Integer.toString(maxX - minX)); facts.put("ySpan", Integer.toString(maxY - minY));
			facts.put("windowFirstTick", Long.toString(moving.peekFirst().tick));
			emit(f, "M25", 22, 12, "progress:" + f.tick, facts, 5, factory, out);
		}
		moving.clear();
	}

	private void restoration(ScenarioSnapshot f, ScenarioSnapshot prior, boolean ready,
		ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		int real = f.level(Skill.MINING), current = f.boosted(Skill.MINING);
		if (!unchanged(f, prior, Skill.MINING) || f.xp(Skill.MINING) != prior.xp(Skill.MINING)
			|| current < 0 || prior.boosted(Skill.MINING) < 0)
		{
			resetDrain(); return;
		}
		if (drainStart >= 0)
		{
			if (f.tick - drainStart >= 30 || real != drainReal || f.xp(Skill.MINING) != drainXp || current > real)
			{
				resetDrain(); return;
			}
			if (current < real) { drainedSamples = Math.min(30, drainedSamples + 1); return; }
			if (drainedSamples >= 10 && ready)
			{
				Map<String, String> facts = facts(f, Skill.MINING, 4);
				facts.put("realLevel", Integer.toString(real)); facts.put("restoredXp", Integer.toString(drainXp));
				facts.put("drainStartTick", Long.toString(drainStart)); facts.put("drainedTicks", Integer.toString(drainedSamples));
				emit(f, "M27", 23, 8, "progress:" + f.tick, facts, 4, factory, out);
			}
			resetDrain(); return;
		}
		if (prior.boosted(Skill.MINING) >= real && current < real)
		{
			drainStart = f.tick; drainedSamples = 1; drainXp = f.xp(Skill.MINING); drainReal = real;
		}
	}

	private void agilityAfterDrop(ScenarioSnapshot f, ScenarioSnapshot prior, ScenarioBatch batch, boolean ready,
		ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		for (Hit hit : batch.hits)
		{
			if (!hit.local && hit.mine && hit.npcKey != null && (DamageTypes.hpDamage(hit.type) && hit.amount > 0
				|| hit.type == HitsplatID.BLOCK_ME && hit.amount == 0)) { lastOwnedNpcCombat = f.tick; }
		}
		if (!unchanged(f, prior, Skill.AGILITY) || f.realHp <= 0 || f.realHp != prior.realHp
			|| prior.currentHp <= 0 || f.currentHp <= 0)
		{
			resetAgility(); return;
		}
		agilitySamples = Math.min(20, agilitySamples + 1);
		while (!agility.isEmpty() && agility.peekFirst().tick < f.tick - 19) { agility.removeFirst(); }
		if (drop != null && drop.tick < f.tick - 19) { drop = null; ambiguousDrop = false; }
		if (!gain(f, prior, Skill.AGILITY)) { return; }
		long hitId = Long.MAX_VALUE;
		for (Hit hit : batch.hits)
		{
			if (hit.local && hit.witnessed && DamageTypes.hpDamage(hit.type) && hit.amount > 0) { hitId = Math.min(hitId, hit.id); }
		}
		Gain current = new Gain(f.tick, prior.currentHp, f.currentHp, hitId);
		agility.addLast(current); while (agility.size() > 3) { agility.removeFirst(); }
		int decrease = current.beforeHp - current.afterHp;
		if (decrease >= 5 && decrease <= 3L * f.realHp / 10)
		{
			// The authored three-gains/one-drop bound cannot retain overlapping drop choices.
			// Suppress the ambiguous episode rather than guess which older drop was newest at age 10.
			if (drop != null) { ambiguousDrop = true; }
			drop = current;
		}
		if (!ready || agilitySamples < 20 || agility.size() < 3 || drop == null || ambiguousDrop
			|| f.tick - drop.tick < 10 || lastOwnedNpcCombat >= f.tick - 19 || f.currentHp < (f.realHp + 1) / 2) { return; }
		Map<String, String> facts = facts(f, Skill.AGILITY, 6);
		facts.put("realLevel", Integer.toString(f.level(Skill.AGILITY))); facts.put("realHp", Integer.toString(f.realHp));
		facts.put("dropTick", Long.toString(drop.tick)); facts.put("priorHp", Integer.toString(drop.beforeHp));
		facts.put("observedHp", Integer.toString(drop.afterHp)); facts.put("hpDrop", Integer.toString(drop.beforeHp - drop.afterHp));
		String cause = drop.hitId == Long.MAX_VALUE ? "hp-progress:" + drop.tick : "hit:" + drop.hitId;
		emit(f, "M30", 50, 10, cause, facts, 6, factory, out);
		drop = null; ambiguousDrop = false; agility.clear();
	}

	boolean stillValid(SceneCandidate candidate, ScenarioSnapshot f, CombatState combat, long lastDamage)
	{
		if (!handles(candidate.getScenarioId())) { return true; }
		SceneCandidate retained = issued.get(candidate.getScenarioId());
		return retained != null && retained.getId() == candidate.getId() && conditions(candidate, f, combat, lastDamage, true);
	}

	boolean continuationValid(SceneCandidate candidate, ScenarioSnapshot f, CombatState combat, long lastDamage)
	{
		if (!handles(candidate.getScenarioId())) { return true; }
		SceneCandidate retained = issued.get(candidate.getScenarioId());
		return retained != null && retained.getId() == candidate.getId() && conditions(candidate, f, combat, lastDamage, false);
	}

	private static boolean handles(String id)
	{
		return "M22".equals(id) || "M24".equals(id) || "M25".equals(id) || "M27".equals(id) || "M30".equals(id);
	}

	private boolean conditions(SceneCandidate c, ScenarioSnapshot f, CombatState combat, long lastDamage, boolean deadline)
	{
		if (!healthy(f) || f.emergencySceneActive || f.tick < c.getCreatedTick() || deadline && f.tick >= c.getExpiresTick()
			|| f.sessionGeneration != c.getSessionGeneration() || f.sceneRevision != c.getSceneRevision()
			|| combat != CombatState.NO_CONFIRMED_EVIDENCE || f.tick - lastDamage < 10) { return false; }
		Map<String, String> facts = c.getConditionFacts();
		if (!Long.toString(f.presentSinceTick).equals(facts.get("witnessPresenceEpoch"))) { return false; }
		String id = c.getScenarioId();
		if ("M22".equals(id))
		{
			return number(facts, "matchedTotal") == f.xp(Skill.CRAFTING) && f.xp(Skill.CRAFTING) == f.xp(Skill.SMITHING)
				&& number(facts, "craftingRealLevel") == f.level(Skill.CRAFTING)
				&& number(facts, "smithingRealLevel") == f.level(Skill.SMITHING);
		}
		Skill skill = Skill.valueOf(facts.get("skill"));
		if (!known(f, skill) || f.level(skill) != number(facts, "realLevel")) { return false; }
		if ("M24".equals(id))
		{
			return Math.max(f.player.x, number(facts, "maxX")) - Math.min(f.player.x, number(facts, "minX")) <= 7
				&& Math.max(f.player.y, number(facts, "maxY")) - Math.min(f.player.y, number(facts, "minY")) <= 7;
		}
		if ("M27".equals(id)) { return f.boosted(skill) == f.level(skill) && f.xp(skill) == number(facts, "restoredXp"); }
		if ("M30".equals(id))
		{
			return f.realHp == number(facts, "realHp") && f.currentHp >= (f.realHp + 1) / 2 && lastOwnedNpcCombat < c.getCreatedTick();
		}
		return true;
	}

	private static boolean selectedProgressInvalid(SceneCandidate c, ScenarioSnapshot f, ScenarioSnapshot prior)
	{
		if ("M22".equals(c.getScenarioId())) { return !unchanged(f, prior, Skill.CRAFTING) || !unchanged(f, prior, Skill.SMITHING); }
		return !unchanged(f, prior, Skill.valueOf(c.getConditionFacts().get("skill")));
	}

	void reset()
	{
		resetOrdinary(); resetAgility(); issued.clear(); lastTick = Long.MIN_VALUE;
		lastOwnedNpcCombat = Long.MIN_VALUE / 2;
	}

	private void resetOrdinary()
	{
		craftingGain = -1; smithingGain = -1; equalLevelSamples = 0; resetDrain();
		for (Burst burst : bursts.values()) { burst.reset(); }
		burstPositions.clear(); moving.clear();
	}
	private void resetDrain() { drainStart = -1; drainedSamples = 0; }
	private void resetAgility() { agility.clear(); drop = null; ambiguousDrop = false; agilitySamples = 0; }
	private void remember(ScenarioSnapshot f)
	{
		lastTick = f.tick; lastSession = f.sessionGeneration; lastScene = f.sceneRevision; lastPresence = f.presentSinceTick;
	}
	private static boolean healthy(ScenarioSnapshot f)
	{
		return f != null && f.valid && f.present && !f.userHidden && !f.autoAbsent && !f.dead && f.currentHp > 0 && f.player != null;
	}
	private static boolean continuous(ScenarioSnapshot f, ScenarioSnapshot prior)
	{
		return healthy(f) && healthy(prior) && f.tick == prior.tick + 1 && f.sessionGeneration == prior.sessionGeneration
			&& f.sceneRevision == prior.sceneRevision && f.presentSinceTick == prior.presentSinceTick
			&& f.worldViewId == prior.worldViewId && prior.tick >= f.presentSinceTick && f.player.distance(prior.player) <= 2;
	}
	private static boolean known(ScenarioSnapshot f, Skill skill) { return f.xp(skill) >= 0 && f.level(skill) > 0; }
	private static boolean unchanged(ScenarioSnapshot f, ScenarioSnapshot prior, Skill skill)
	{
		return known(f, skill) && known(prior, skill) && f.level(skill) == prior.level(skill) && f.xp(skill) >= prior.xp(skill);
	}
	private static boolean gain(ScenarioSnapshot f, ScenarioSnapshot prior, Skill skill) { return f.xp(skill) > prior.xp(skill); }
	private static int number(Map<String, String> facts, String key) { return Integer.parseInt(facts.get(key)); }
	private static Map<String, String> facts(ScenarioSnapshot f, Skill skill, int approach)
	{
		Map<String, String> facts = new HashMap<>(); facts.put("actualRegion", Integer.toString(f.player.region()));
		facts.put("witnessedPresent", "true"); facts.put("witnessPresenceEpoch", Long.toString(f.presentSinceTick));
		facts.put("occurredTick", Long.toString(f.tick)); facts.put("maximumApproachTicks", Integer.toString(approach));
		if (skill != null) { facts.put("skill", skill.name()); facts.put("skillSet", skill.name()); }
		return facts;
	}
	private void emit(ScenarioSnapshot f, String id, int priority, int life, String cause, Map<String, String> facts, int hold,
		ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		SceneCandidate candidate = factory.create(f, id, priority, life, cause, facts, false, hold);
		issued.put(id, candidate); out.add(candidate);
	}

	private static final class TileTick
	{
		final long tick; final Position position; final boolean positive;
		TileTick(long tick, Position position, boolean positive) { this.tick = tick; this.position = position; this.positive = positive; }
	}
	private static final class Gain
	{
		final long tick, hitId; final int beforeHp, afterHp;
		Gain(long tick, int beforeHp, int afterHp, long hitId)
		{
			this.tick = tick; this.beforeHp = beforeHp; this.afterHp = afterHp; this.hitId = hitId;
		}
	}
	private static final class Burst
	{
		final Deque<Long> gains = new ArrayDeque<>(); boolean armed; long first, lastGain;
		int minX, maxX, minY, maxY;
		void include(Position p)
		{
			minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y);
		}
		boolean fits() { return maxX - minX <= 7 && maxY - minY <= 7; }
		void reset() { gains.clear(); armed = false; }
	}
	private static final class Return
	{
		final Skill skill; final long first, lastGain, gap; final int minX, maxX, minY, maxY;
		Return(Skill skill, Burst b, long gap)
		{
			this.skill = skill; first = b.first; lastGain = b.lastGain; this.gap = gap;
			minX = b.minX; maxX = b.maxX; minY = b.minY; maxY = b.maxY;
		}
	}
}

package com.malfoid.scenario;

import com.malfoid.motion.MotionObservation;
import com.malfoid.scenario.ScenarioRules.CombatState;
import com.malfoid.scenario.ScenarioRules.SkillDelta;
import com.malfoid.scenario.ScenarioSnapshot.Position;
import com.malfoid.speech.SceneCandidate;
import com.malfoid.speech.SpeechCancellationReceipt;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/** Genuine terminal route facts; no search, visual interpolation, or callback can invent an arrival. */
final class TravelContinuationRules
{
	private final Map<String, RouteWitness> issued = new HashMap<>();
	private long lastTick = Long.MIN_VALUE, lastSession, lastScene, lastPresence, lastPlacement = -1, lastCompletion = -1;
	private long lastCancelledExecution = -1;
	private long motionWitnessSinceTick = Long.MIN_VALUE;
	private CancelledInterestObservation pendingInterest;

	List<SceneCandidate> close(ScenarioSnapshot f, ScenarioSnapshot prior, ScenarioBatch batch, List<SkillDelta> deltas,
		CombatState combat, long lastDamage, ExpandedScenarioRules.Factory factory)
	{
		List<SceneCandidate> out = new ArrayList<>();
		if (f.tick == lastTick && f.sessionGeneration == lastSession && f.sceneRevision == lastScene
			&& f.presentSinceTick == lastPresence) { return out; }
		boolean consecutive = lastTick == Long.MIN_VALUE || f.tick == lastTick + 1 && f.sessionGeneration == lastSession
			&& f.sceneRevision == lastScene && f.presentSinceTick == lastPresence && f.placementGeneration == lastPlacement;
		if (!consecutive || !continuous(f, prior) || batch.localDeath || suppressed(f, combat))
		{
			reset(); motionWitnessSinceTick = f.tick + 1;
			if (f.cancelledInterest != null && f.cancelledInterest.cancellation != null)
			{
				lastCancelledExecution = f.cancelledInterest.cancellation.getExecutionId();
			}
			remember(f); return out;
		}
		remember(f);
		issued.entrySet().removeIf(entry -> !conditions(entry.getValue(), f, combat, false));
		cancelledInterest(f, factory, out);
		MotionObservation completion = f.motionCompletion;
		if (!freshCompletion(f, completion) || completion.requestId == lastCompletion) { return out; }
		lastCompletion = completion.requestId;
		if (!completion.fixedGoal) { return out; }
		if (completion.physicalBlock
			&& completion.previouslyLegalEdge && completion.changedEdgeAfterBlock
			&& completion.blockedTick >= completion.startedTick && completion.blockedTick >= f.presentSinceTick
			&& completion.completedTick > completion.blockedTick && completion.completedTick - completion.blockedTick <= 12
			&& f.tick - completion.blockedTick < 20 && completion.lastCompletedEdgeTick > completion.blockedTick
			&& adjacentFailedEdge(completion))
		{
			emit(f, "M61", 19, completion, factory, out);
		}
		int chord = Math.max(Math.abs(completion.goalWorldX - completion.startWorldX), Math.abs(completion.goalWorldY - completion.startWorldY));
		// D.3 idle shifts cannot supply twelve edges; their M63 runtime lane remains closed.
		if ((completion.purpose == MotionObservation.Purpose.ROAM || completion.purpose == MotionObservation.Purpose.APPROACH_PLAYER)
			&& chord >= 1 && chord <= 4
			&& completion.completedEdges >= 12 && completion.completedEdges <= 24
			&& completion.completedTick - completion.startedTick <= 12)
		{
			emit(f, "M63", 15, completion, factory, out);
		}
		return out;
	}

	private void cancelledInterest(ScenarioSnapshot f, ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		CancelledInterestObservation current = f.cancelledInterest;
		if (!interestCurrent(current, f) || f.tick - current.lossTick > 16 || current.lossTick < motionWitnessSinceTick
			|| current.inspectionPath.startedTick < motionWitnessSinceTick || !pendingReturnCurrent(current, f))
		{
			if (current != null && current.cancellation != null) { lastCancelledExecution = current.cancellation.getExecutionId(); }
			else if (pendingInterest != null) { lastCancelledExecution = pendingInterest.cancellation.getExecutionId(); }
			pendingInterest = null; return;
		}
		if (current.cancellation.getExecutionId() == lastCancelledExecution) { return; }
		if (pendingInterest == null)
		{
			if (current.lossTick < f.tick - 1) { return; }
			pendingInterest = current;
		}
		else if (!sameInterest(pendingInterest, current) || pendingInterest.returnRequestId >= 0
			&& pendingInterest.returnRequestId != current.returnRequestId)
		{
			lastCancelledExecution = pendingInterest.cancellation.getExecutionId(); pendingInterest = null; return;
		}
		else { pendingInterest = current; }
		MotionObservation returned = f.motionCompletion;
		if (!freshReturn(f, current, returned)) { return; }
		lastCancelledExecution = current.cancellation.getExecutionId(); pendingInterest = null;
		Map<String, String> facts = terminalFacts(f, returned, 12);
		facts.put("historicalObjectName", current.historicalName); facts.put("targetLossReason", current.lossReason.name());
		facts.put("cancelledInspectionId", Long.toString(current.inspectionCandidate.getId()));
		facts.put("cancelledInspectionRequestId", Long.toString(current.inspectionPath.requestId));
		facts.put("cancelledExecutionId", Long.toString(current.cancellation.getExecutionId())); facts.put("targetLossTick", Long.toString(current.lossTick));
		SceneCandidate c = factory.create(f, "M62", 14, 10, "interest-return:" + current.inspectionCandidate.getId()
			+ ":" + current.cancellation.getExecutionId(), facts, false, 4);
		issued.put("M62", new RouteWitness(c, returned, current)); out.add(c);
	}

	private static boolean interestCurrent(CancelledInterestObservation interest, ScenarioSnapshot f)
	{
		if (interest == null || !interest.known || interest.inspectionArrived || interest.inspectionCandidate == null
			|| interest.inspectionPath == null || interest.cancellation == null || interest.lossReason == null
			|| interest.targetKey == null || interest.historicalName == null || interest.targetKey.isEmpty()
			|| ScenarioRules.objectKind(interest.historicalName) == null || interest.presentSinceTick != f.presentSinceTick
			|| interest.placementGeneration != f.placementGeneration || interest.worldViewId != f.worldViewId || interest.plane != f.player.plane
			|| interest.lossTick < f.presentSinceTick || interest.lossTick > f.tick) { return false; }
		SceneCandidate selected = interest.inspectionCandidate; MotionObservation path = interest.inspectionPath;
		SpeechCancellationReceipt cancellation = interest.cancellation; Map<String, String> facts = selected.getConditionFacts();
		return "M08".equals(selected.getScenarioId()) && selected.getSessionGeneration() == f.sessionGeneration
			&& selected.getSceneRevision() == f.sceneRevision && selected.getCreatedTick() >= f.presentSinceTick
			&& interest.lossTick < selected.getExpiresTick() && TravelExpansionRules.sameCandidate(selected, cancellation.getCandidate())
			&& cancellation.getReason() == SpeechCancellationReceipt.Reason.INSPECTION_TARGET_LOST
			&& cancellation.isPrePaintAttempt() && !cancellation.isGenuinePainted()
			&& interest.targetKey.equals(facts.get("targetKey")) && interest.historicalName.equals(facts.get("objectName"))
			&& Long.toString(f.presentSinceTick).equals(facts.get("witnessPresenceEpoch"))
			&& path.known && !path.ordinary && path.purpose == MotionObservation.Purpose.OTHER
			&& path.sourceCandidateId == selected.getId() && path.legalGoal && path.fixedGoal
			&& path.status == MotionObservation.Status.MOVING && path.completedTick < 0 && path.completedEdges >= 0 && path.completedEdges <= 8
			&& path.completedRunEdges == 0 && (path.completedEdges == 0 || path.lastCompletedEdgeTick >= path.startedTick && path.lastCompletedEdgeTick <= interest.lossTick)
			&& path.plannedSteps >= 1 && path.plannedSteps <= 8 && path.requestId >= 0 && path.startedTick >= selected.getCreatedTick()
			&& path.startedTick <= interest.lossTick && path.placementGeneration == interest.placementGeneration
			&& path.worldViewId == interest.worldViewId && path.plane == interest.plane
			&& Integer.toString(path.goalWorldX).equals(facts.get("targetX")) && Integer.toString(path.goalWorldY).equals(facts.get("targetY"));
	}

	private static boolean pendingReturnCurrent(CancelledInterestObservation interest, ScenarioSnapshot f)
	{
		if (interest.returnRequestId < 0) { return true; }
		MotionObservation current = f.motion;
		return current != null && current.known && current.ordinary && current.legalGoal
			&& current.purpose == MotionObservation.Purpose.APPROACH_PLAYER && current.sourceCandidateId == interest.inspectionCandidate.getId()
			&& current.requestId == interest.returnRequestId && current.requestId != interest.inspectionPath.requestId
			&& current.startedTick >= interest.lossTick && current.startedTick <= f.tick
			&& (current.status == MotionObservation.Status.MOVING || current.status == MotionObservation.Status.ARRIVED)
			&& current.placementGeneration == interest.placementGeneration && current.worldViewId == interest.worldViewId && current.plane == interest.plane;
	}

	private static boolean sameInterest(CancelledInterestObservation a, CancelledInterestObservation b)
	{
		MotionObservation x = a.inspectionPath, y = b.inspectionPath;
		return TravelExpansionRules.sameCandidate(a.inspectionCandidate, b.inspectionCandidate)
			&& a.cancellation.getExecutionId() == b.cancellation.getExecutionId() && a.cancellation.getIssuedPacketToken() == b.cancellation.getIssuedPacketToken()
			&& a.lossTick == b.lossTick && a.lossReason == b.lossReason && a.targetKey.equals(b.targetKey) && a.historicalName.equals(b.historicalName)
			&& a.presentSinceTick == b.presentSinceTick && a.placementGeneration == b.placementGeneration && a.worldViewId == b.worldViewId && a.plane == b.plane
			&& x.requestId == y.requestId && x.startedTick == y.startedTick && x.completedTick == y.completedTick && x.completedEdges == y.completedEdges
			&& x.sourceCandidateId == y.sourceCandidateId && x.completedRunEdges == y.completedRunEdges && x.lastCompletedEdgeTick == y.lastCompletedEdgeTick
			&& x.plannedSteps == y.plannedSteps && x.goalWorldX == y.goalWorldX && x.goalWorldY == y.goalWorldY
			&& x.startWorldX == y.startWorldX && x.startWorldY == y.startWorldY;
	}

	private static boolean freshReturn(ScenarioSnapshot f, CancelledInterestObservation interest, MotionObservation returned)
	{
		return returned != null && returned.known && returned.ordinary && returned.legalGoal
			&& returned.purpose == MotionObservation.Purpose.APPROACH_PLAYER && returned.sourceCandidateId == interest.inspectionCandidate.getId()
			&& returned.status == MotionObservation.Status.ARRIVED && returned.requestId >= 0 && returned.requestId == interest.returnRequestId
			&& returned.requestId != interest.inspectionPath.requestId && returned.completedTick == f.tick
			&& returned.startedTick >= interest.lossTick && returned.startedTick <= returned.completedTick
			&& returned.completedTick - interest.lossTick <= 16 && returned.completedEdges >= 1 && returned.completedEdges <= 24
			&& returned.completedRunEdges == 0
			&& returned.lastCompletedEdgeTick >= returned.startedTick && returned.lastCompletedEdgeTick <= returned.completedTick
			&& returned.arrivalDistance >= 2 && returned.arrivalDistance <= 5
			&& returned.worldViewId == interest.worldViewId && returned.placementGeneration == interest.placementGeneration && returned.plane == interest.plane
			&& matchingCurrent(f, returned);
	}

	private static boolean adjacentFailedEdge(MotionObservation completion)
	{
		int dx = Math.abs(completion.blockedToWorldX - completion.blockedFromWorldX);
		int dy = Math.abs(completion.blockedToWorldY - completion.blockedFromWorldY);
		return dx <= 1 && dy <= 1 && dx + dy > 0;
	}

	private boolean freshCompletion(ScenarioSnapshot f, MotionObservation completion)
	{
		return completion != null && completion.known && completion.ordinary && completion.legalGoal && completion.requestId >= 0
			&& (completion.purpose == MotionObservation.Purpose.ROAM || completion.purpose == MotionObservation.Purpose.CATCHUP
				|| completion.purpose == MotionObservation.Purpose.APPROACH_PLAYER && completion.sourceCandidateId >= 0)
			&& completion.status == MotionObservation.Status.ARRIVED && completion.completedTick == f.tick
			&& completion.startedTick >= f.presentSinceTick && completion.startedTick >= motionWitnessSinceTick
			&& completion.startedTick <= completion.completedTick
			&& completion.completedEdges > 0 && completion.completedEdges <= 24
			&& completion.lastCompletedEdgeTick >= completion.startedTick && completion.lastCompletedEdgeTick <= completion.completedTick
			&& completion.arrivalDistance >= 2 && completion.arrivalDistance <= 5
			&& completion.placementGeneration == f.placementGeneration && completion.worldViewId == f.worldViewId
			&& completion.plane == f.player.plane && matchingCurrent(f, completion);
	}

	/** A fixed goal may not be replaced while this terminal opportunity waits for admission. */
	private static boolean matchingCurrent(ScenarioSnapshot f, MotionObservation original)
	{
		MotionObservation current = f.motion;
		return TravelExpansionRules.sameCompletion(original, current)
			&& current.placementGeneration == f.placementGeneration && current.worldViewId == f.worldViewId && current.plane == f.player.plane
			&& new Position(original.goalWorldX, original.goalWorldY, original.plane).equals(f.companion)
			&& f.player.distance(f.companion) >= 2 && f.player.distance(f.companion) <= 5;
	}

	boolean stillValid(SceneCandidate c, ScenarioSnapshot f, CombatState combat, long lastDamage)
	{
		return valid(c, f, combat, true);
	}
	boolean continuationValid(SceneCandidate c, ScenarioSnapshot f, CombatState combat, long lastDamage)
	{
		return valid(c, f, combat, false);
	}
	long motionRequestId(SceneCandidate c)
	{
		RouteWitness retained = issued.get(c.getScenarioId());
		return retained != null && TravelExpansionRules.sameCandidate(c, retained.candidate) ? retained.completion.requestId : -1;
	}
	private boolean valid(SceneCandidate c, ScenarioSnapshot f, CombatState combat, boolean deadline)
	{
		if (!("M61".equals(c.getScenarioId()) || "M62".equals(c.getScenarioId()) || "M63".equals(c.getScenarioId()))) { return true; }
		RouteWitness retained = issued.get(c.getScenarioId());
		return retained != null && TravelExpansionRules.sameCandidate(c, retained.candidate) && conditions(retained, f, combat, deadline);
	}
	private static boolean conditions(RouteWitness witness, ScenarioSnapshot f, CombatState combat, boolean deadline)
	{
		SceneCandidate c = witness.candidate;
		if (!healthy(f) || suppressed(f, combat) || f.tick < c.getCreatedTick()
			|| deadline && (f.tick >= c.getExpiresTick() || f.tick - f.presentSinceTick < 10)
			|| f.sessionGeneration != c.getSessionGeneration() || f.sceneRevision != c.getSceneRevision()
			|| !Long.toString(f.presentSinceTick).equals(c.getConditionFacts().get("witnessPresenceEpoch"))
			|| f.player.distance(f.companion) < 2 || f.player.distance(f.companion) > 5) { return false; }
		if ("M61".equals(c.getScenarioId()) && f.tick - witness.completion.blockedTick >= 20) { return false; }
		if (witness.interest != null && (!interestCurrent(f.cancelledInterest, f) || !sameInterest(witness.interest, f.cancelledInterest)
			|| witness.interest.returnRequestId != f.cancelledInterest.returnRequestId)) { return false; }
		return matchingCurrent(f, witness.completion) || TravelExpansionRules.ownedHold(c, f, witness.completion);
	}

	private static boolean healthy(ScenarioSnapshot f)
	{
		return f != null && f.valid && f.present && f.presentSinceTick >= 0 && f.tick >= f.presentSinceTick
			&& !f.userHidden && !f.autoAbsent && !f.dead && f.currentHp > 0 && f.player != null && f.companion != null
			&& f.player.plane >= 0 && f.player.plane <= 3 && f.companion.plane == f.player.plane
			&& f.placementGeneration >= 0 && f.worldViewId != Integer.MIN_VALUE;
	}
	private static boolean suppressed(ScenarioSnapshot f, CombatState combat)
	{
		return f.emergencySceneActive || f.inventoryBlocked || !f.interactionKnown || f.interactionPresent
			|| combat != CombatState.NO_CONFIRMED_EVIDENCE;
	}
	private static boolean continuous(ScenarioSnapshot f, ScenarioSnapshot prior)
	{
		return healthy(f) && healthy(prior) && f.tick == prior.tick + 1 && f.sessionGeneration == prior.sessionGeneration
			&& f.sceneRevision == prior.sceneRevision && f.presentSinceTick == prior.presentSinceTick && prior.tick >= f.presentSinceTick
			&& f.topLevel == prior.topLevel && f.instanced == prior.instanced && f.player.distance(prior.player) <= 2
			&& f.placementGeneration == prior.placementGeneration && f.worldViewId == prior.worldViewId;
	}
	private void remember(ScenarioSnapshot f)
	{
		lastTick = f.tick; lastSession = f.sessionGeneration; lastScene = f.sceneRevision;
		lastPresence = f.presentSinceTick; lastPlacement = f.placementGeneration;
	}
	private void emit(ScenarioSnapshot f, String id, int priority, MotionObservation completion,
		ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		Map<String, String> facts = terminalFacts(f, completion, 4);
		facts.put("blockedTick", Long.toString(completion.blockedTick));
		SceneCandidate c = factory.create(f, id, priority, 10, "route:" + completion.requestId, facts, false, 4);
		issued.put(id, new RouteWitness(c, completion, null)); out.add(c);
	}
	private static Map<String, String> terminalFacts(ScenarioSnapshot f, MotionObservation completion, int approach)
	{
		Map<String, String> facts = new HashMap<>(); facts.put("actualRegion", Integer.toString(f.player.region()));
		facts.put("witnessedPresent", "true"); facts.put("witnessPresenceEpoch", Long.toString(f.presentSinceTick));
		facts.put("settlingNotBeforeTick", Long.toString(f.presentSinceTick + 10)); facts.put("occurredTick", Long.toString(f.tick));
		facts.put("maximumApproachTicks", Integer.toString(approach)); facts.put("requestId", Long.toString(completion.requestId));
		facts.put("completionTick", Long.toString(completion.completedTick)); facts.put("completedEdges", Integer.toString(completion.completedEdges));
		facts.put("goalWorldX", Integer.toString(completion.goalWorldX)); facts.put("goalWorldY", Integer.toString(completion.goalWorldY));
		facts.put("placementGeneration", Long.toString(completion.placementGeneration)); facts.put("worldViewId", Integer.toString(completion.worldViewId));
		return facts;
	}
	void reset()
	{
		issued.clear(); lastTick = Long.MIN_VALUE; lastCompletion = -1; lastPlacement = -1; lastCancelledExecution = -1;
		motionWitnessSinceTick = Long.MIN_VALUE; pendingInterest = null;
	}
	void reset(long invalidThroughTick)
	{
		reset(); motionWitnessSinceTick = invalidThroughTick + 1;
	}
	private static final class RouteWitness
	{
		final SceneCandidate candidate; final MotionObservation completion; final CancelledInterestObservation interest;
		RouteWitness(SceneCandidate candidate, MotionObservation completion, CancelledInterestObservation interest)
		{
			this.candidate = candidate; this.completion = completion; this.interest = interest;
		}
	}
}

package com.malfoid.scenario;

import com.malfoid.motion.MotionObservation;
import com.malfoid.motion.MotionHoldReceipt;
import com.malfoid.scenario.ScenarioRules.CombatState;
import com.malfoid.scenario.ScenarioRules.SkillDelta;
import com.malfoid.scenario.ScenarioSnapshot.Position;
import com.malfoid.speech.SceneCandidate;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Skill;

/** Finite witnessed travel patterns; only native completed-edge receipts prove her travel. */
final class TravelExpansionRules
{
	private final Deque<TileTick> positions = new ArrayDeque<>(), corner = new ArrayDeque<>();
	private final Deque<Endpoint> endpoints = new ArrayDeque<>();
	private final Deque<Run> runs = new ArrayDeque<>();
	private final List<Position> cycle = new ArrayList<>();
	private final Deque<Heading> headings = new ArrayDeque<>();
	private final Deque<Arrival> arrivals = new ArrayDeque<>();
	private final Deque<MotionObservation> wanderings = new ArrayDeque<>();
	private final Map<String, SceneCandidate> issued = new HashMap<>();
	private final Map<String, MotionObservation> motionWitnesses = new HashMap<>();
	private long lastTick = Long.MIN_VALUE, lastSession, lastScene, lastPresence;
	private long cycleStart, pauseStart = -1, headingStart, outsideTick = -1, witnessedArrivalTick = -1;
	private long lastCompletion = Long.MIN_VALUE, placement = Long.MIN_VALUE;
	private long motionWitnessSinceTick = Long.MIN_VALUE;
	private int cycleIndex, dwell, stillTicks, quietTicks, insideTicks, headingBin = -1, headingTicks, headingDirection;
	private boolean cycleSealed, quietConsumed, progressQuiet;
	private int movement;
	private MotionObservation catchup;
	private int catchupMoving;

	List<SceneCandidate> close(ScenarioSnapshot f, ScenarioSnapshot prior, ScenarioBatch batch, List<SkillDelta> deltas,
		CombatState combat, long lastDamage, ExpandedScenarioRules.Factory factory)
	{
		List<SceneCandidate> out = new ArrayList<>();
		if (f.tick == lastTick && f.sessionGeneration == lastSession && f.sceneRevision == lastScene
			&& f.presentSinceTick == lastPresence) { return out; }
		boolean consecutive = lastTick == Long.MIN_VALUE || f.tick == lastTick + 1
			&& f.sessionGeneration == lastSession && f.sceneRevision == lastScene && f.presentSinceTick == lastPresence;
		if (!consecutive || !continuous(f, prior) || batch.localDeath || combat != CombatState.NO_CONFIRMED_EVIDENCE || held(f))
		{
			boolean retainPause = quietConsumed && f.present && !f.userHidden && !f.autoAbsent && !f.dead && !batch.localDeath
				&& f.sessionGeneration == lastSession && f.sceneRevision == lastScene && f.presentSinceTick == lastPresence;
			reset(); motionWitnessSinceTick = f.tick + 1; quietConsumed = retainPause; remember(f); return out;
		}
		if (f.motion != null && f.motion.known && (f.motion.status == MotionObservation.Status.RECOVERED
			|| placement != Long.MIN_VALUE && placement != f.motion.placementGeneration))
		{
			reset(); motionWitnessSinceTick = f.tick + 1; remember(f); placement = f.motion.placementGeneration; return out;
		}
		remember(f);
		movement = f.player.distance(prior.player);
		progressQuiet = noProgress(f, prior);
		if (movement == 0)
		{
			dwell = Math.min(121, dwell + 1); stillTicks = Math.min(120, stillTicks + 1);
			if (pauseStart < 0) { pauseStart = f.tick; }
		}
		else
		{
			dwell = 1; stillTicks = 0; pauseStart = -1; quietTicks = 0; quietConsumed = false;
		}
		if (dwell == 0) { dwell = 1; }
		issued.entrySet().removeIf(entry -> !conditions(entry.getValue(), f, combat, false));
		motionWitnesses.keySet().retainAll(issued.keySet());
		positions.addLast(new TileTick(f.tick, f.player, movement));
		while (positions.size() > 120) { positions.removeFirst(); }
		boolean ready = !f.emergencySceneActive;
		shuttle(f, ready, factory, out);
		circuit(f, ready, factory, out);
		retrace(f, ready, factory, out);
		startsAndStops(f, ready, factory, out);
		travelPause(f, ready, factory, out);
		regionArrival(f, prior);
		facing(f, ready, factory, out);
		quietPause(f, ready, factory, out);
		nativeTravel(f, ready, factory, out);
		return out;
	}

	private void shuttle(ScenarioSnapshot f, boolean ready, ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		while (!endpoints.isEmpty() && f.tick - endpoints.peekFirst().firstTick >= 50) { endpoints.removeFirst(); }
		if (dwell != 2 || !endpoints.isEmpty() && endpoints.peekLast().position.equals(f.player)) { return; }
		if (endpoints.size() >= 2)
		{
			Endpoint[] records = endpoints.toArray(new Endpoint[0]);
			Position a = records[0].position, b = records[1].position;
			if (!f.player.equals(a) && !f.player.equals(b)) { endpoints.clear(); }
		}
		if (!endpoints.isEmpty())
		{
			int separation = endpoints.peekLast().position.distance(f.player);
			if (separation < 2 || separation > 4) { endpoints.clear(); }
		}
		endpoints.addLast(new Endpoint(f.tick - 1, f.player));
		while (endpoints.size() > 5) { endpoints.removeFirst(); }
		if (endpoints.size() != 5) { return; }
		List<Endpoint> e = new ArrayList<>(endpoints);
		if (!e.get(0).position.equals(e.get(2).position) || !e.get(0).position.equals(e.get(4).position)
			|| !e.get(1).position.equals(e.get(3).position)) { return; }
		if (ready)
		{
			Map<String, String> facts = facts(f, 8); facts.put("windowFirstTick", Long.toString(e.get(0).firstTick));
			facts.put("endpointDistance", Integer.toString(e.get(0).position.distance(e.get(1).position)));
			emit(f, "M52", 17, 12, pattern(f), facts, 4, factory, out);
		}
		Endpoint terminal = endpoints.peekLast(); endpoints.clear(); endpoints.addLast(terminal);
	}

	private void circuit(ScenarioSnapshot f, boolean ready, ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		if (cycle.isEmpty() || f.tick - cycleStart >= 64) { seedCycle(f); return; }
		if (movement == 0) { return; }
		Position start = cycle.get(0);
		if (!cycleSealed)
		{
			if (f.player.equals(start))
			{
				if (cycle.size() >= 4) { cycleSealed = true; cycleIndex = 1; } else { seedCycle(f); }
			}
			else if (cycle.contains(f.player) || cycle.size() == 8) { seedCycle(f); }
			else { cycle.add(f.player); }
			return;
		}
		Position expected = cycleIndex == cycle.size() ? start : cycle.get(cycleIndex);
		if (!f.player.equals(expected)) { seedCycle(f); return; }
		if (cycleIndex < cycle.size()) { cycleIndex++; return; }
		if (ready)
		{
			Map<String, String> facts = facts(f, 8); facts.put("cycleVertices", Integer.toString(cycle.size()));
			facts.put("windowFirstTick", Long.toString(cycleStart));
			emit(f, "M53", 16, 12, pattern(f), facts, 6, factory, out);
		}
		seedCycle(f);
	}

	private void seedCycle(ScenarioSnapshot f)
	{
		cycle.clear(); cycle.add(f.player); cycleStart = f.tick; cycleSealed = false; cycleIndex = 0;
	}

	private void retrace(ScenarioSnapshot f, boolean ready, ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		while (!corner.isEmpty() && f.tick - corner.peekFirst().tick >= 50) { corner.removeFirst(); }
		if (corner.isEmpty() || movement > 0) { corner.addLast(new TileTick(f.tick, f.player, movement)); }
		while (corner.size() > 9) { corner.removeFirst(); }
		if (movement == 0 || corner.size() != 9) { return; }
		List<TileTick> p = new ArrayList<>(corner);
		Position a = p.get(0).position, b = p.get(1).position, c = p.get(2).position;
		int abX = b.x - a.x, abY = b.y - a.y, bcX = c.x - b.x, bcY = c.y - b.y;
		if (Math.abs(abX) + Math.abs(abY) != 1 || Math.abs(bcX) + Math.abs(bcY) != 1
			|| abX * bcX + abY * bcY != 0 || p.get(5).tick - p.get(4).tick - 1 > 4) { return; }
		Position[] expected = {a, b, c, b, a, b, c, b, a};
		for (int i = 0; i < expected.length; i++) { if (!expected[i].equals(p.get(i).position)) { return; } }
		if (ready)
		{
			Map<String, String> facts = facts(f, 6); facts.put("windowFirstTick", Long.toString(p.get(0).tick));
			facts.put("betweenTracesStillTicks", Long.toString(p.get(5).tick - p.get(4).tick - 1));
			emit(f, "M54", 16, 10, pattern(f), facts, 4, factory, out);
		}
		corner.clear(); corner.addLast(p.get(8));
	}

	private void startsAndStops(ScenarioSnapshot f, boolean ready, ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		boolean moving = movement > 0;
		if (runs.isEmpty() || runs.peekLast().moving != moving) { runs.addLast(new Run(f.tick, moving)); }
		else { runs.peekLast().length = Math.min(5, runs.peekLast().length + 1); }
		while (runs.size() > 6) { runs.removeFirst(); }
		while (!runs.isEmpty() && f.tick - runs.peekFirst().tick >= 36) { runs.removeFirst(); }
		if (runs.size() != 6 || moving || runs.peekLast().length != 2) { return; }
		List<Run> r = new ArrayList<>(runs);
		for (int i = 0; i < r.size(); i++)
		{
			Run run = r.get(i); boolean expectedMove = (i & 1) == 0;
			if (run.moving != expectedMove || run.length < (expectedMove ? 1 : 2) || run.length > (expectedMove ? 3 : 4)) { return; }
		}
		if (ready)
		{
			Map<String, String> facts = facts(f, 4); facts.put("windowFirstTick", Long.toString(r.get(0).tick));
			facts.put("currentStillStartTick", Long.toString(r.get(5).tick));
			emit(f, "M55", 15, 8, pattern(f), facts, 4, factory, out);
		}
	}

	private void travelPause(ScenarioSnapshot f, boolean ready, ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		if (stillTicks != 12 || positions.size() < 76) { return; }
		List<TileTick> history = tail(76); int moves = 0;
		int minX = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE, minY = Integer.MAX_VALUE, maxY = Integer.MIN_VALUE;
		for (int i = 0; i < 64; i++)
		{
			TileTick p = history.get(i); if (p.movement > 0) { moves++; }
			minX = Math.min(minX, p.position.x); maxX = Math.max(maxX, p.position.x);
			minY = Math.min(minY, p.position.y); maxY = Math.max(maxY, p.position.y);
		}
		if (moves < 24 || maxX - minX < 12 && maxY - minY < 12) { return; }
		if (ready)
		{
			Map<String, String> facts = facts(f, 8); facts.put("windowFirstTick", Long.toString(history.get(0).tick));
			facts.put("movingSamples", Integer.toString(moves)); facts.put("xSpan", Integer.toString(maxX - minX));
			facts.put("ySpan", Integer.toString(maxY - minY)); facts.put("pauseStartTick", Long.toString(pauseStart));
			emit(f, "M56", 14, 12, quietCause(), facts, 8, factory, out);
		}
	}

	private void regionArrival(ScenarioSnapshot f, ScenarioSnapshot prior)
	{
		witnessedArrivalTick = -1;
		while (!arrivals.isEmpty() && f.tick - arrivals.peekFirst().tick > 2400) { arrivals.removeFirst(); }
		if (!f.topLevel || f.instanced || f.player.plane != 0) { outsideTick = -1; insideTicks = 0; return; }
		if (f.player.region() != 12850) { outsideTick = f.tick; insideTicks = 0; return; }
		if (insideTicks == 0 && prior.topLevel && !prior.instanced && prior.player.plane == 0
			&& prior.player.region() != 12850 && prior.tick >= f.presentSinceTick) { outsideTick = prior.tick; }
		if (outsideTick < f.presentSinceTick || outsideTick < 0) { return; }
		insideTicks = Math.min(5, insideTicks + 1);
		if (insideTicks == 4) { witnessedArrivalTick = f.tick; }
	}

	/** Decorates the same M10 cause/deadline; it never creates an extra arrival scene. */
	SceneCandidate decorateArrival(ScenarioSnapshot f, SceneCandidate original, ExpandedScenarioRules.Factory factory)
	{
		if (!"M10".equals(original.getScenarioId()) || witnessedArrivalTick != f.tick || held(f) || f.emergencySceneActive) { return original; }
		String cause = original.getCausalToken();
		for (Arrival arrival : arrivals) { if (arrival.cause.equals(cause)) { return original; } }
		arrivals.addLast(new Arrival(f.tick, cause)); while (arrivals.size() > 3) { arrivals.removeFirst(); }
		if (arrivals.size() < 3) { return original; }
		Map<String, String> facts = new HashMap<>(original.getConditionFacts());
		facts.put("witnessedArrivalCount", "3"); facts.put("firstArrivalTick", Long.toString(arrivals.peekFirst().tick));
		facts.put("outsideWitnessTick", Long.toString(outsideTick)); facts.put("maximumApproachTicks", "12");
		facts.put("witnessPresenceEpoch", Long.toString(f.presentSinceTick));
		facts.putIfAbsent("settlingNotBeforeTick", Long.toString(f.presentSinceTick + 10));
		SceneCandidate decorated = new SceneCandidate(original.getId(), "M57", original.getPriority(), original.getCreatedTick(),
			original.getExpiresTick(), original.getSessionGeneration(), original.getSceneRevision(), cause, facts, original.isIntentionalSilent(), 4);
		issued.put("M57", decorated); return decorated;
	}

	private void facing(ScenarioSnapshot f, boolean ready, ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		if (movement > 0 || f.observedFacing < 0) { resetFacing(); return; }
		while (!headings.isEmpty() && f.tick - headings.peekFirst().firstTick >= 32) { headings.removeFirst(); headingDirection = 0; }
		int bin = cardinal(f.observedFacing);
		if (bin < 0) { headingBin = -1; headingTicks = 0; return; }
		if (bin == headingBin) { headingTicks = Math.min(3, headingTicks + 1); }
		else { headingBin = bin; headingTicks = 1; headingStart = f.tick; }
		if (headingTicks != 2 || !headings.isEmpty() && headings.peekLast().bin == bin) { return; }
		if (!headings.isEmpty())
		{
			int difference = (bin - headings.peekLast().bin + 4) & 3;
			int direction = difference == 1 ? 1 : difference == 3 ? -1 : 0;
			boolean repeated = false; for (Heading h : headings) { if (h.bin == bin) { repeated = true; } }
			if (repeated || direction == 0 || headingDirection != 0 && direction != headingDirection) { headings.clear(); headingDirection = 0; }
			else { headingDirection = direction; }
		}
		headings.addLast(new Heading(headingStart, bin));
		if (headings.size() != 4) { return; }
		if (ready)
		{
			Map<String, String> facts = facts(f, 6); facts.put("windowFirstTick", Long.toString(headings.peekFirst().firstTick));
			facts.put("headingDirection", Integer.toString(headingDirection)); facts.put("headingCount", "4");
			emit(f, "M59", 16, 10, pattern(f), facts, 4, factory, out);
		}
		headings.clear(); headingDirection = 0;
	}

	private static int cardinal(int orientation)
	{
		int angle = orientation & 2047;
		for (int bin = 0; bin < 4; bin++)
		{
			int difference = Math.abs(angle - bin * 512); difference = Math.min(difference, 2048 - difference);
			if (difference <= 32) { return bin; }
		}
		return -1;
	}

	private void quietPause(ScenarioSnapshot f, boolean ready, ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		if (movement != 0 || !progressQuiet || !f.interactionKnown || f.interactionPresent) { quietTicks = 0; return; }
		quietTicks = Math.min(120, quietTicks + 1);
		if (quietTicks != 120 || quietConsumed) { return; }
		quietConsumed = true;
		if (ready)
		{
			Map<String, String> facts = facts(f, 8); facts.put("windowFirstTick", Long.toString(f.tick - 119));
			facts.put("pauseStartTick", Long.toString(pauseStart));
			emit(f, "M70", 13, 12, quietCause(), facts, 12, factory, out);
		}
	}

	private void nativeTravel(ScenarioSnapshot f, boolean ready, ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		MotionObservation current = f.motion, completion = f.motionCompletion;
		if (current == null || !current.known || current.plane != f.player.plane || current.worldViewId != f.worldViewId
			|| current.placementGeneration != f.placementGeneration || !current.ordinary || !current.legalGoal
			|| current.purpose == MotionObservation.Purpose.OTHER
			|| current.status != MotionObservation.Status.MOVING && current.status != MotionObservation.Status.ARRIVED)
		{
			catchup = null; wanderings.clear(); return;
		}
		if (placement != Long.MIN_VALUE && placement != current.placementGeneration)
		{
			catchup = null; wanderings.clear(); issued.remove("M51"); issued.remove("M58"); issued.remove("M60");
		}
		placement = current.placementGeneration;
		if (catchup != null)
		{
			int distance = f.player.distance(f.companion);
			if (f.tick - catchup.completedTick >= 12 || current.placementGeneration != catchup.placementGeneration
				|| current.worldViewId != catchup.worldViewId || movement < 1 || movement > 2 || distance < 2 || distance > 5)
			{
				catchup = null;
			}
			else if (++catchupMoving == 6)
			{
				if (ready)
				{
					Map<String, String> facts = motionFacts(f, catchup, 6); facts.put("movingSamples", "6");
					emitMotion(f, "M51", 18, 12, catchupCause(catchup), facts, 6, catchup, factory, out);
				}
				catchup = null;
			}
		}
		while (!wanderings.isEmpty() && f.tick - wanderings.peekFirst().completedTick >= 60) { wanderings.removeFirst(); }
		if (!freshCompletion(f, current, completion) || completion.requestId == lastCompletion) { return; }
		lastCompletion = completion.requestId;
		if (completion.purpose == MotionObservation.Purpose.CATCHUP && completion.startDistance >= 10)
		{
			int distance = f.player.distance(f.companion);
			if (distance < 2 || distance > 5) { return; }
			if (stillTicks >= 4 && completion.lastCompletedEdgeTick > Math.max(pauseStart, f.tick - 12))
			{
				if (ready)
				{
					Map<String, String> facts = motionFacts(f, completion, 4); facts.put("pauseStartTick", Long.toString(pauseStart));
					facts.put("stationarySamples", Integer.toString(Math.min(12, stillTicks)));
					emitMotion(f, "M60", 18, 10, catchupCause(completion), facts, 6, completion, factory, out);
				}
				catchup = null;
			}
			else if (completion.completedRunEdges >= 2) { catchup = completion; catchupMoving = 0; }
		}
		if (completion.purpose != MotionObservation.Purpose.ROAM || !completion.fixedGoal || f.player.plane < 1 || f.player.plane > 3) { return; }
		for (MotionObservation roaming : wanderings) { if (roaming.requestId == completion.requestId) { return; } }
		wanderings.addLast(completion); while (wanderings.size() > 3) { wanderings.removeFirst(); }
		if (wanderings.size() != 3 || positions.size() < 60) { return; }
		List<TileTick> history = tail(60); Set<Position> goals = new HashSet<>();
		for (MotionObservation roaming : wanderings)
		{
			if (roaming.completedTick < history.get(0).tick || roaming.placementGeneration != placement || roaming.worldViewId != current.worldViewId) { return; }
			goals.add(new Position(roaming.goalWorldX, roaming.goalWorldY, roaming.plane));
		}
		if (goals.size() != 3) { return; }
		int minX = f.player.x, maxX = f.player.x, minY = f.player.y, maxY = f.player.y;
		for (TileTick p : history)
		{
			minX = Math.min(minX, p.position.x); maxX = Math.max(maxX, p.position.x);
			minY = Math.min(minY, p.position.y); maxY = Math.max(maxY, p.position.y);
		}
		if (maxX - minX > 2 || maxY - minY > 2) { return; }
		if (ready)
		{
			Map<String, String> facts = motionFacts(f, completion, 4); facts.put("wanderCount", "3");
			facts.put("windowFirstTick", Long.toString(history.get(0).tick));
			facts.put("minX", Integer.toString(minX)); facts.put("maxX", Integer.toString(maxX));
			facts.put("minY", Integer.toString(minY)); facts.put("maxY", Integer.toString(maxY));
			emitMotion(f, "M58", 14, 12, "wander:" + completion.requestId, facts, 6, completion, factory, out);
		}
		wanderings.clear();
	}

	private boolean freshCompletion(ScenarioSnapshot f, MotionObservation current, MotionObservation completed)
	{
		return completed != null && completed.known && completed.ordinary && completed.legalGoal && completed.requestId >= 0
			&& completed.status == MotionObservation.Status.ARRIVED && completed.completedTick == f.tick
			&& completed.startedTick >= f.presentSinceTick && completed.startedTick >= motionWitnessSinceTick
			&& completed.startedTick <= completed.completedTick
			&& completed.completedEdges > 0 && completed.completedEdges <= 24 && completed.completedRunEdges >= 0
			&& completed.completedRunEdges <= completed.completedEdges && completed.lastCompletedEdgeTick >= completed.startedTick
			&& completed.lastCompletedEdgeTick <= completed.completedTick && completed.arrivalDistance >= 2 && completed.arrivalDistance <= 5
			&& completed.plane == f.player.plane && completed.placementGeneration == current.placementGeneration
			&& completed.placementGeneration == f.placementGeneration && completed.worldViewId == f.worldViewId
			&& completed.worldViewId == current.worldViewId && current.ordinary && current.legalGoal && current.purpose != MotionObservation.Purpose.OTHER
			&& (current.status == MotionObservation.Status.MOVING || current.status == MotionObservation.Status.ARRIVED)
			&& (completed.requestId == current.requestId || current.startedTick >= completed.completedTick);
	}

	private static boolean failed(MotionObservation motion)
	{
		return motion.status == MotionObservation.Status.BLOCKED || motion.status == MotionObservation.Status.TARGET_LOST
			|| motion.status == MotionObservation.Status.INVALIDATED || motion.status == MotionObservation.Status.RECOVERED
			|| motion.status == MotionObservation.Status.SCENE_UNAVAILABLE;
	}

	boolean stillValid(SceneCandidate c, ScenarioSnapshot f, CombatState combat, long lastDamage)
	{
		return valid(c, f, combat, true);
	}
	boolean continuationValid(SceneCandidate c, ScenarioSnapshot f, CombatState combat, long lastDamage)
	{
		return valid(c, f, combat, false);
	}
	long motionRequestId(SceneCandidate c)
	{
		SceneCandidate retained = issued.get(c.getScenarioId());
		MotionObservation receipt = motionWitnesses.get(c.getScenarioId());
		return sameCandidate(c, retained) && receipt != null ? receipt.requestId : -1;
	}
	private boolean valid(SceneCandidate c, ScenarioSnapshot f, CombatState combat, boolean deadline)
	{
		if (!handles(c.getScenarioId())) { return true; }
		SceneCandidate retained = issued.get(c.getScenarioId());
		return sameCandidate(c, retained) && conditions(retained, f, combat, deadline);
	}
	private static boolean handles(String id)
	{
		return "M51".equals(id) || "M52".equals(id) || "M53".equals(id) || "M54".equals(id) || "M55".equals(id)
			|| "M56".equals(id) || "M57".equals(id) || "M58".equals(id) || "M59".equals(id) || "M60".equals(id) || "M70".equals(id);
	}
	private boolean conditions(SceneCandidate c, ScenarioSnapshot f, CombatState combat, boolean deadline)
	{
		if (!healthy(f) || held(f) || f.emergencySceneActive || combat != CombatState.NO_CONFIRMED_EVIDENCE
			|| deadline && f.tick - f.presentSinceTick < 10
			|| f.tick < c.getCreatedTick() || deadline && f.tick >= c.getExpiresTick()
			|| f.sessionGeneration != c.getSessionGeneration() || f.sceneRevision != c.getSceneRevision()
			|| f.player.distance(f.companion) >= 10) { return false; }
		Map<String, String> facts = c.getConditionFacts();
		if (!Long.toString(f.presentSinceTick).equals(facts.get("witnessPresenceEpoch"))) { return false; }
		String id = c.getScenarioId();
		boolean ownCommitted = !deadline && f.activeSceneCandidateId == c.getId() && f.activeSceneCommitted;
		if ("M57".equals(id)) { return f.topLevel && !f.instanced && f.player.plane == 0 && f.player.region() == 12850; }
		if ("M51".equals(id) || "M58".equals(id) || "M60".equals(id))
		{
			boolean ownHold = ownedHold(c, f, motionWitnesses.get(id));
			if (f.motion == null || !f.motion.known || failed(f.motion) && !ownHold
				|| !ownHold && (!f.motion.ordinary || !f.motion.legalGoal || f.motion.purpose == MotionObservation.Purpose.OTHER
					|| f.motion.status != MotionObservation.Status.MOVING && f.motion.status != MotionObservation.Status.ARRIVED)
				|| f.motion.placementGeneration != f.placementGeneration || f.motion.worldViewId != f.worldViewId || f.motion.plane != f.player.plane
				|| !Long.toString(f.motion.placementGeneration).equals(facts.get("placementGeneration"))
				|| !Integer.toString(f.motion.worldViewId).equals(facts.get("worldViewId"))
				|| f.player.distance(f.companion) < 2 || f.player.distance(f.companion) > 5) { return false; }
		}
		if ("M51".equals(id)) { return ownCommitted || movement >= 1 && movement <= 2; }
		if ("M58".equals(id))
		{
			return f.player.plane >= 1 && f.player.plane <= 3 && f.player.x >= number(facts, "minX") && f.player.x <= number(facts, "maxX")
				&& f.player.y >= number(facts, "minY") && f.player.y <= number(facts, "maxY");
		}
		if ("M60".equals(id) && ownCommitted) { return true; }
		if (!Integer.toString(f.player.x).equals(facts.get("playerX")) || !Integer.toString(f.player.y).equals(facts.get("playerY"))) { return false; }
		if ("M55".equals(id))
		{
			return !runs.isEmpty() && !runs.peekLast().moving && runs.peekLast().length >= 2 && runs.peekLast().length <= 4
				&& Long.toString(runs.peekLast().tick).equals(facts.get("currentStillStartTick"));
		}
		return !"M70".equals(id) || progressQuiet && f.interactionKnown && !f.interactionPresent;
	}

	/** Only a genuine completion admitted by this candidate can authorize its own stationary hold. */
	static boolean ownedHold(SceneCandidate c, ScenarioSnapshot f, MotionObservation original)
	{
		MotionHoldReceipt hold = f.motionHold;
		if (!healthy(f) || f.sessionGeneration != c.getSessionGeneration() || f.sceneRevision != c.getSceneRevision()
			|| !Long.toString(f.presentSinceTick).equals(c.getConditionFacts().get("witnessPresenceEpoch"))
			|| original == null || hold == null || f.activeSceneCandidateId != c.getId() || hold.candidateId != c.getId()
			|| hold.requestId != original.requestId || !sameCompletion(original, hold.completion) || !hold.legalStanding
			|| hold.admittedTick < c.getCreatedTick() || hold.admittedTick >= c.getExpiresTick()
			|| hold.heldTick < hold.admittedTick || hold.heldTick > f.tick
			|| hold.mode != MotionHoldReceipt.Mode.HOLD && (hold.mode != MotionHoldReceipt.Mode.NORMAL_RESUME || f.tick - hold.heldTick > 1)
			|| hold.placementGeneration != original.placementGeneration || hold.placementGeneration != f.placementGeneration
			|| hold.worldViewId != original.worldViewId || hold.worldViewId != f.worldViewId || hold.plane != f.player.plane
			|| original.plane != hold.plane || original.startedTick < f.presentSinceTick || original.completedTick > c.getCreatedTick()
			|| original.completedTick < original.startedTick || original.completedEdges <= 0
			|| f.motion == null || f.motion.status != MotionObservation.Status.INVALIDATED || !f.motion.known
			|| !f.motion.ordinary || !f.motion.legalGoal || f.motion.purpose == MotionObservation.Purpose.OTHER
			|| f.motion.placementGeneration != hold.placementGeneration || f.motion.worldViewId != hold.worldViewId
			|| f.motion.plane != hold.plane) { return false; }
		Position standing = new Position(hold.worldX, hold.worldY, hold.plane);
		int distance = standing.distance(f.player);
		return standing.equals(f.companion) && distance >= 2 && distance <= 5;
	}

	static boolean sameCompletion(MotionObservation a, MotionObservation b)
	{
		return a != null && b != null && a.known && b.known && a.status == MotionObservation.Status.ARRIVED
			&& b.status == MotionObservation.Status.ARRIVED && a.ordinary && b.ordinary && a.legalGoal && b.legalGoal
			&& a.requestId == b.requestId && a.placementGeneration == b.placementGeneration && a.worldViewId == b.worldViewId
			&& a.plane == b.plane && a.purpose == b.purpose && a.startedTick == b.startedTick && a.completedTick == b.completedTick
			&& a.sourceCandidateId == b.sourceCandidateId
			&& a.lastCompletedEdgeTick == b.lastCompletedEdgeTick && a.completedEdges == b.completedEdges
			&& a.completedRunEdges == b.completedRunEdges && a.startWorldX == b.startWorldX && a.startWorldY == b.startWorldY
			&& a.goalWorldX == b.goalWorldX && a.goalWorldY == b.goalWorldY && a.startDistance == b.startDistance
			&& a.arrivalDistance == b.arrivalDistance && a.fixedGoal == b.fixedGoal && a.physicalBlock == b.physicalBlock
			&& a.previouslyLegalEdge == b.previouslyLegalEdge && a.changedEdgeAfterBlock == b.changedEdgeAfterBlock
			&& a.blockedTick == b.blockedTick && a.blockedFromWorldX == b.blockedFromWorldX && a.blockedFromWorldY == b.blockedFromWorldY
			&& a.blockedToWorldX == b.blockedToWorldX && a.blockedToWorldY == b.blockedToWorldY;
	}

	static boolean sameCandidate(SceneCandidate candidate, SceneCandidate retained)
	{
		return retained != null && candidate.getId() == retained.getId() && candidate.getScenarioId().equals(retained.getScenarioId())
			&& candidate.getCreatedTick() == retained.getCreatedTick() && candidate.getExpiresTick() == retained.getExpiresTick()
			&& candidate.getSessionGeneration() == retained.getSessionGeneration() && candidate.getSceneRevision() == retained.getSceneRevision()
			&& candidate.getCausalToken().equals(retained.getCausalToken()) && candidate.getConditionFacts().equals(retained.getConditionFacts())
			&& candidate.getHoldTicks() == retained.getHoldTicks() && candidate.isIntentionalSilent() == retained.isIntentionalSilent();
	}

	private static boolean noProgress(ScenarioSnapshot f, ScenarioSnapshot prior)
	{
		for (Skill skill : Skill.values())
		{
			if (skill == Skill.OVERALL) { continue; }
			if (f.xp(skill) < 0 || prior.xp(skill) < 0 || f.xp(skill) != prior.xp(skill)) { return false; }
		}
		return true;
	}
	private static boolean held(ScenarioSnapshot f) { return f.inventoryBlocked || !f.interactionKnown || f.interactionPresent; }
	private static boolean healthy(ScenarioSnapshot f)
	{
		return f != null && f.valid && f.present && f.presentSinceTick >= 0 && f.tick >= f.presentSinceTick
			&& !f.userHidden && !f.autoAbsent && !f.dead && f.currentHp > 0 && f.player != null && f.companion != null
			&& f.player.plane >= 0 && f.player.plane <= 3 && f.companion.plane == f.player.plane;
	}
	private static boolean continuous(ScenarioSnapshot f, ScenarioSnapshot prior)
	{
		return healthy(f) && healthy(prior) && f.tick == prior.tick + 1 && f.sessionGeneration == prior.sessionGeneration
			&& f.sceneRevision == prior.sceneRevision && f.presentSinceTick == prior.presentSinceTick && prior.tick >= f.presentSinceTick
			&& f.topLevel == prior.topLevel && f.instanced == prior.instanced && f.player.distance(prior.player) <= 2;
	}
	private List<TileTick> tail(int count)
	{
		List<TileTick> history = new ArrayList<>(positions); return history.subList(history.size() - count, history.size());
	}
	private void remember(ScenarioSnapshot f)
	{
		lastTick = f.tick; lastSession = f.sessionGeneration; lastScene = f.sceneRevision; lastPresence = f.presentSinceTick;
	}
	private static int number(Map<String, String> facts, String key) { return Integer.parseInt(facts.get(key)); }
	private static String pattern(ScenarioSnapshot f) { return "travel:" + f.tick; }
	private String quietCause() { return "pause:" + pauseStart; }
	private static String catchupCause(MotionObservation motion) { return "catchup:" + motion.requestId; }
	private static Map<String, String> facts(ScenarioSnapshot f, int approach)
	{
		Map<String, String> facts = new HashMap<>(); facts.put("actualRegion", Integer.toString(f.player.region()));
		facts.put("playerX", Integer.toString(f.player.x)); facts.put("playerY", Integer.toString(f.player.y));
		facts.put("observedPlane", Integer.toString(f.player.plane)); facts.put("witnessedPresent", "true");
		facts.put("witnessPresenceEpoch", Long.toString(f.presentSinceTick)); facts.put("occurredTick", Long.toString(f.tick));
		facts.put("settlingNotBeforeTick", Long.toString(f.presentSinceTick + 10));
		facts.put("maximumApproachTicks", Integer.toString(approach)); return facts;
	}
	private static Map<String, String> motionFacts(ScenarioSnapshot f, MotionObservation motion, int approach)
	{
		Map<String, String> facts = facts(f, approach); facts.put("requestId", Long.toString(motion.requestId));
		facts.put("placementGeneration", Long.toString(motion.placementGeneration)); facts.put("worldViewId", Integer.toString(motion.worldViewId));
		facts.put("completionTick", Long.toString(motion.completedTick)); facts.put("completedEdges", Integer.toString(motion.completedEdges));
		facts.put("completedRunEdges", Integer.toString(motion.completedRunEdges)); return facts;
	}
	private void emit(ScenarioSnapshot f, String id, int priority, int life, String cause, Map<String, String> facts, int hold,
		ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		SceneCandidate c = factory.create(f, id, priority, life, cause, facts, false, hold); issued.put(id, c); out.add(c);
	}
	private void emitMotion(ScenarioSnapshot f, String id, int priority, int life, String cause, Map<String, String> facts, int hold,
		MotionObservation completion, ExpandedScenarioRules.Factory factory, List<SceneCandidate> out)
	{
		emit(f, id, priority, life, cause, facts, hold, factory, out); motionWitnesses.put(id, completion);
	}
	void reset()
	{
		positions.clear(); corner.clear(); endpoints.clear(); runs.clear(); cycle.clear(); resetFacing(); arrivals.clear(); wanderings.clear(); issued.clear(); motionWitnesses.clear();
		lastTick = Long.MIN_VALUE; pauseStart = -1; outsideTick = -1; witnessedArrivalTick = -1; lastCompletion = Long.MIN_VALUE; placement = Long.MIN_VALUE;
		motionWitnessSinceTick = Long.MIN_VALUE;
		dwell = 0; stillTicks = 0; quietTicks = 0; insideTicks = 0; quietConsumed = false; progressQuiet = false; catchup = null; catchupMoving = 0;
	}
	void reset(long invalidThroughTick)
	{
		reset(); motionWitnessSinceTick = invalidThroughTick + 1;
	}
	private void resetFacing() { headings.clear(); headingBin = -1; headingTicks = 0; headingDirection = 0; }
	private static final class TileTick
	{
		final long tick; final Position position; final int movement;
		TileTick(long tick, Position position, int movement) { this.tick = tick; this.position = position; this.movement = movement; }
	}
	private static final class Endpoint
	{
		final long firstTick; final Position position;
		Endpoint(long firstTick, Position position) { this.firstTick = firstTick; this.position = position; }
	}
	private static final class Run
	{
		final long tick; final boolean moving; int length = 1;
		Run(long tick, boolean moving) { this.tick = tick; this.moving = moving; }
	}
	private static final class Heading
	{
		final long firstTick; final int bin;
		Heading(long firstTick, int bin) { this.firstTick = firstTick; this.bin = bin; }
	}
	private static final class Arrival
	{
		final long tick; final String cause;
		Arrival(long tick, String cause) { this.tick = tick; this.cause = cause; }
	}
}

package com.malfoid.speech;

import com.malfoid.presence.ModalOcclusionSnapshot;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.Consumer;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Local overhead only. Head projection and ordered native text are copied by the client thread. */
public final class MalfoidSpeechOverlay extends Overlay
{
    private final SpeechDirector director;
    private final ClientThread clientThread;
    private final Consumer<Throwable> failure;
    private volatile RenderSnapshot snapshot;

    public MalfoidSpeechOverlay(SpeechDirector director, ClientThread clientThread, Consumer<Throwable> failure)
    {
        this.director = director;
        this.clientThread = clientThread;
        this.failure = failure;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    /** Must run on the client thread; no mutable Player/Model/WorldView is retained by paint. */
    public synchronized void publish(Point headAnchor, Rectangle viewport, Rectangle playerStatusZone, long frameId)
    {
        publish(headAnchor, viewport, playerStatusZone, frameId, null, 0, null);
    }

    public synchronized void publish(Point headAnchor, Rectangle viewport, Rectangle playerStatusZone, long frameId,
        String playerOverheadText, int playerOverheadCycles, Point playerTextBaseline)
    {
        publish(headAnchor, viewport, playerStatusZone, frameId, playerOverheadText, playerOverheadCycles,
            playerTextBaseline, ModalOcclusionSnapshot.CLEAR);
    }

    public synchronized void publish(Point headAnchor, Rectangle viewport, Rectangle playerStatusZone, long frameId,
        String playerOverheadText, int playerOverheadCycles, Point playerTextBaseline, ModalOcclusionSnapshot modalOcclusion)
    {
        List<NativeOverheadText> nativeTexts = Collections.emptyList();
        if (playerOverheadCycles > 0)
        {
            nativeTexts = playerOverheadText == null || playerTextBaseline == null
                || playerOverheadText.codePointCount(0, playerOverheadText.length()) > 256 ? null
                : Collections.singletonList(new NativeOverheadText(playerTextBaseline.x, playerTextBaseline.y, playerOverheadText));
        }
        publish(headAnchor, viewport, frameId, nativeTexts, modalOcclusion);
    }

    /** Native texts are ordered local player, other players, then NPCs; Malfoid is placed last. */
    public synchronized void publish(Point headAnchor, Rectangle viewport, long frameId,
        List<NativeOverheadText> nativeTexts, ModalOcclusionSnapshot modalOcclusion)
    {
        snapshot = new RenderSnapshot(director.getPacket(), headAnchor, viewport,
            frameId, director.getTick(), nativeTexts, modalOcclusion);
    }

    public synchronized void clear()
    {
        RenderSnapshot old = snapshot;
        snapshot = null;
        if (old != null && old.packet != null)
        {
            old.packet.markUndrawable(old.frameId);
        }
    }

    public boolean isDrawable()
    {
        RenderSnapshot current = snapshot;
        SpeechPacket.PresentationObservation observation = current == null || current.packet == null
            ? null : current.packet.getObservation();
        long now = director.now();
        return observation != null && observation.isDrawable()
            && now - observation.getLastPaintNanos() <= 100_000_000L
            && now - observation.getLifetimeEndNanos() < 0;
    }

    public boolean isHeadVisible()
    {
        RenderSnapshot current = snapshot;
        return current != null && current.anchor != null && current.viewport != null
            && current.viewport.contains(current.anchor) && current.modalOcclusion.isKnown()
            && !current.modalOcclusion.intersects(new Rectangle(current.anchor.x, current.anchor.y, 1, 1));
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        RenderSnapshot attempted = snapshot;
        long attemptedGeneration = attempted == null || attempted.packet == null ? director.getSessionGeneration()
            : attempted.packet.getCandidate().getSessionGeneration();
        try
        {
            paintSafely(graphics, attempted);
        }
        catch (Throwable error)
        {
            if (attempted != null && attempted.packet != null)
            {
                attempted.packet.revoke(true);
            }
            clearIfCurrent(attempted);
            // Failure handling itself must not escape another plugin's frame.
            try
            {
                clientThread.invokeLater(() -> {
                    if (director.getSessionGeneration() != attemptedGeneration) { return; }
                    try { failure.accept(error); }
                    catch (Throwable ignored) { /* The composition root normally logs/switches off. */ }
                });
            }
            catch (Throwable ignored)
            {
                // The frame is still contained if the client has already shut down.
            }
        }
        return null;
    }

    private synchronized void clearIfCurrent(RenderSnapshot attempted)
    {
        if (snapshot == attempted) { clear(); }
    }

    private void paintSafely(Graphics2D graphics, RenderSnapshot current)
    {
        if (current == null || current.packet == null)
        {
            return;
        }
        SpeechPacket packet = current.packet;
        long now = director.now();
        if (current.anchor == null || current.viewport == null || current.viewport.width <= 0
            || current.viewport.height <= 0 || current.nativeTexts == null
            || !current.viewport.contains(current.anchor) || !current.modalOcclusion.isKnown()
            || current.modalOcclusion.intersects(new Rectangle(current.anchor.x, current.anchor.y, 1, 1))
            || !packet.canPaint(now))
        {
            packet.markUndrawable(current.frameId);
            return;
        }
        Font oldFont = graphics.getFont();
        Color oldColor = graphics.getColor();
        Composite oldComposite = graphics.getComposite();
        try
        {
            graphics.setFont(FontManager.getRunescapeBoldFont());
            FontMetrics metrics = graphics.getFontMetrics();
            OverheadLayout layout = OverheadLayout.create(packet.getText(), metrics, current.anchor,
                current.viewport, current.nativeTexts);
            if (layout == null || current.modalOcclusion.intersects(layout.bounds)
                || graphics.getClip() != null && !graphics.getClip().contains(layout.bounds))
            {
                packet.markUndrawable(current.frameId);
                return;
            }
            long paintedAt = director.now();
            graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, packet.alpha(paintedAt)));
            SpeechPacket.PaintReceipt receipt = packet.paint(paintedAt, current.tick, current.frameId, () -> {
                for (int index = 0; index < layout.lines.size(); index++)
                {
                    String line = layout.lines.get(index);
                    int x = layout.centerX - metrics.stringWidth(line) / 2;
                    int y = layout.firstBaselineY + index * metrics.getHeight();
                    graphics.setColor(Color.BLACK);
                    graphics.drawString(line, x + 1, y + 1);
                    graphics.setColor(Color.YELLOW);
                    graphics.drawString(line, x, y);
                }
            });
            if (receipt != null)
            {
                // invokeLater cannot execute a director mutation inside render.
                clientThread.invokeLater(() -> {
                    try { director.acknowledge(packet, receipt); }
                    catch (Throwable error) {
                        if (director.getSessionGeneration() != packet.getCandidate().getSessionGeneration()) { return; }
                        try { failure.accept(error); }
                        catch (Throwable ignored) { /* Frame/client-thread boundary is fail closed. */ }
                    }
                });
            }
        }
        finally
        {
            graphics.setFont(oldFont);
            graphics.setColor(oldColor);
            graphics.setComposite(oldComposite);
        }
    }

    private static final class RenderSnapshot
    {
        private final SpeechPacket packet;
        private final Point anchor;
        private final Rectangle viewport;
        private final long frameId;
        private final long tick;
        private final List<NativeOverheadText> nativeTexts;
        private final ModalOcclusionSnapshot modalOcclusion;

        private RenderSnapshot(SpeechPacket packet, Point anchor, Rectangle viewport,
            long frameId, long tick, List<NativeOverheadText> nativeTexts,
            ModalOcclusionSnapshot modalOcclusion)
        {
            this.packet = packet;
            this.anchor = anchor == null ? null : new Point(anchor);
            this.viewport = viewport == null ? null : new Rectangle(viewport);
            this.frameId = frameId;
            this.tick = tick;
            this.nativeTexts = nativeTexts == null ? null : Collections.unmodifiableList(new ArrayList<>(
                nativeTexts.subList(0, Math.min(nativeTexts.size(), NativeOverheadText.MAX_NATIVE_TEXTS))));
            this.modalOcclusion = modalOcclusion == null ? ModalOcclusionSnapshot.UNKNOWN : modalOcclusion;
        }
    }
}

package com.malfoid.speech;

import java.util.Objects;

/** One client-thread copy of a native actor's overhead text and head projection. */
public final class NativeOverheadText
{
    public static final int MAX_NATIVE_TEXTS = 50;

    private final int centerX;
    private final int baselineY;
    private final String text;

    public NativeOverheadText(int centerX, int baselineY, String text)
    {
        this.centerX = centerX;
        this.baselineY = baselineY;
        this.text = Objects.requireNonNull(text);
    }

    public int getCenterX() { return centerX; }
    public int getBaselineY() { return baselineY; }
    public String getText() { return text; }
}

package com.malfoid.speech;

import java.awt.FontMetrics;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** The client's ordered overhead-text overlap rule, followed by complete-paint bounds. */
final class OverheadLayout
{
    final int centerX;
    final int baselineY;
    final int firstBaselineY;
    final List<String> lines;
    final Rectangle bounds;

    private OverheadLayout(int centerX, int baselineY, int firstBaselineY, List<String> lines, Rectangle bounds)
    {
        this.centerX = centerX;
        this.baselineY = baselineY;
        this.firstBaselineY = firstBaselineY;
        this.lines = Collections.unmodifiableList(lines);
        this.bounds = bounds;
    }

    static OverheadLayout create(String text, FontMetrics metrics, Point anchor, Rectangle viewport,
        List<NativeOverheadText> nativeTexts)
    {
        if (anchor == null || viewport == null || viewport.width <= 0 || viewport.height <= 0
            || !viewport.contains(anchor) || nativeTexts == null)
        {
            return null;
        }
        List<String> lines = wrap(text, metrics, Math.min(280, viewport.width - 4));
        int width = 0;
        for (String line : lines) { width = Math.max(width, metrics.stringWidth(line)); }
        int fontAscent = metrics.getAscent();
        int ascent = (lines.size() - 1) * metrics.getHeight() + fontAscent;
        if (lines.isEmpty() || width <= 0 || fontAscent <= 0 || width + 1L > viewport.width)
        {
            return null;
        }
        int halfWidth = width / 2;
        int centerX = Math.max(viewport.x + halfWidth,
            Math.min(anchor.x, viewport.x + viewport.width - width + halfWidth - 1));
        int nativeCount = Math.min(nativeTexts.size(), NativeOverheadText.MAX_NATIVE_TEXTS);
        List<PlacedText> earlier = new ArrayList<>(nativeCount);
        for (int index = 0; index < nativeCount; index++)
        {
            NativeOverheadText nativeText = nativeTexts.get(index);
            if (nativeText == null) { return null; }
            int nativeHalfWidth = metrics.stringWidth(nativeText.getText()) / 2;
            long baseline = stack(nativeText.getCenterX(), nativeText.getBaselineY(), nativeHalfWidth, fontAscent, earlier);
            earlier.add(new PlacedText(nativeText.getCenterX(), baseline, nativeHalfWidth, fontAscent));
        }
        long baseline = stack(centerX, anchor.y, halfWidth, ascent, earlier);
        long top = baseline - ascent;
        long bottom = baseline + metrics.getDescent() + 1L;
        if (top < viewport.y || bottom > (long) viewport.y + viewport.height
            || baseline < Integer.MIN_VALUE || baseline > Integer.MAX_VALUE)
        {
            return null;
        }
        Rectangle bounds = new Rectangle(centerX - halfWidth, (int) top, width + 1, (int) (bottom - top));
        return new OverheadLayout(centerX, (int) baseline,
            (int) baseline - (lines.size() - 1) * metrics.getHeight(), lines, bounds);
    }

    private static List<String> wrap(String text, FontMetrics metrics, int maximumWidth)
    {
        List<String> result = new ArrayList<>();
        StringBuilder line = new StringBuilder();
        for (String word : text.split("(?U)\\s+"))
        {
            if (line.length() > 0 && metrics.stringWidth(line + " " + word) > maximumWidth)
            {
                result.add(line.toString());
                line.setLength(0);
            }
            if (line.length() > 0) { line.append(' '); }
            line.append(word);
        }
        if (line.length() > 0) { result.add(line.toString()); }
        return result;
    }

    private static long stack(int x, long y, int halfWidth, int ascent, List<PlacedText> earlier)
    {
        boolean overlap;
        do
        {
            overlap = false;
            for (PlacedText previous : earlier)
            {
                if (y + 2 > previous.y - previous.ascent && y - ascent < previous.y + 2
                    && (long) x - halfWidth < (long) previous.x + previous.halfWidth
                    && (long) x + halfWidth > (long) previous.x - previous.halfWidth
                    && previous.y - previous.ascent < y)
                {
                    y = previous.y - previous.ascent;
                    overlap = true;
                }
            }
        }
        while (overlap);
        return y;
    }

    private static final class PlacedText
    {
        private final int x, halfWidth, ascent;
        private final long y;

        private PlacedText(int x, long y, int halfWidth, int ascent)
        {
            this.x = x;
            this.y = y;
            this.halfWidth = halfWidth;
            this.ascent = ascent;
        }
    }
}

package com.malfoid.speech;

import com.malfoid.scenario.PersonalMilestones.Proof;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

/** A copied, generation-bound opportunity. No RuneLite objects cross this boundary. */
public final class SceneCandidate
{
    private final long id;
    private final String scenarioId;
    private final int priority;
    private final long createdTick;
    private final long expiresTick;
    private final long sessionGeneration;
    private final long sceneRevision;
    private final String causalToken;
    private final Map<String, String> conditionFacts;
    private final boolean intentionalSilent;
    private final int holdTicks;
    private final int rebindCount;
    private final Proof milestone;

    public SceneCandidate(long id, String scenarioId, int priority, long createdTick,
        long expiresTick, long sessionGeneration, long sceneRevision, String causalToken,
        Map<String, String> conditionFacts, boolean intentionalSilent, int holdTicks)
    {
        this(id, scenarioId, priority, createdTick, expiresTick, sessionGeneration, sceneRevision,
            causalToken, conditionFacts, intentionalSilent, holdTicks, 0, null);
    }

    public SceneCandidate(long id, String scenarioId, int priority, long createdTick,
        long expiresTick, long sessionGeneration, long sceneRevision, String causalToken,
        Map<String, String> conditionFacts, boolean intentionalSilent, int holdTicks,
        Proof milestone)
    {
        this(id, scenarioId, priority, createdTick, expiresTick, sessionGeneration, sceneRevision,
            causalToken, conditionFacts, intentionalSilent, holdTicks, 0, milestone);
    }

    private SceneCandidate(long id, String scenarioId, int priority, long createdTick,
        long expiresTick, long sessionGeneration, long sceneRevision, String causalToken,
        Map<String, String> conditionFacts, boolean intentionalSilent, int holdTicks, int rebindCount,
        Proof milestone)
    {
        if (expiresTick <= createdTick || holdTicks < 0 || holdTicks > 40)
        {
            throw new IllegalArgumentException("Invalid candidate duration");
        }
        if (milestone != null && (!milestone.ruleId.equals(scenarioId)
            || milestone.sessionGeneration != sessionGeneration
            || milestone.sceneRevision != sceneRevision
            || milestone.originalDeadline != expiresTick
            || milestone.occurrenceTick > createdTick
            || milestone.presenceEpoch > milestone.occurrenceTick))
        {
            throw new IllegalArgumentException("Additional context does not own candidate");
        }
        this.id = id;
        this.scenarioId = Objects.requireNonNull(scenarioId);
        this.priority = priority;
        this.createdTick = createdTick;
        this.expiresTick = expiresTick;
        this.sessionGeneration = sessionGeneration;
        this.sceneRevision = sceneRevision;
        this.causalToken = Objects.requireNonNull(causalToken);
        this.conditionFacts = Collections.unmodifiableMap(new HashMap<>(conditionFacts));
        this.intentionalSilent = intentionalSilent;
        this.holdTicks = holdTicks;
        this.rebindCount = rebindCount;
        this.milestone = milestone;
    }

    public long getId() { return id; }
    public String getScenarioId() { return scenarioId; }
    public int getPriority() { return priority; }
    public long getCreatedTick() { return createdTick; }
    public long getExpiresTick() { return expiresTick; }
    public long getSessionGeneration() { return sessionGeneration; }
    public long getSceneRevision() { return sceneRevision; }
    public String getCausalToken() { return causalToken; }
    public Map<String, String> getConditionFacts() { return conditionFacts; }
    public boolean isIntentionalSilent() { return intentionalSilent; }
    public int getHoldTicks() { return holdTicks; }
    public int getRebindCount() { return rebindCount; }
    public Proof getMilestone() { return milestone; }

    SceneCandidate unboundForLoading()
    {
        Map<String, String> facts = new HashMap<>(conditionFacts);
        facts.remove("burntShrimpPresent");
        return new SceneCandidate(id, "M04", priority, createdTick, expiresTick, sessionGeneration,
            -1, causalToken, facts, intentionalSilent, holdTicks, rebindCount, milestone);
    }

    SceneCandidate rebound(long newSceneRevision)
    {
        return new SceneCandidate(id, scenarioId, priority, createdTick, expiresTick, sessionGeneration,
            newSceneRevision, causalToken, conditionFacts, intentionalSilent, holdTicks, rebindCount + 1, milestone);
    }

    SceneCandidate updateRequestedStreak(SceneCandidate newer)
    {
        return new SceneCandidate(newer.id, scenarioId, priority, createdTick, expiresTick, sessionGeneration,
            sceneRevision, causalToken, newer.conditionFacts, newer.intentionalSilent, newer.holdTicks, rebindCount, milestone);
    }
    public boolean isRequested() { return "U01".equals(scenarioId); }
    public boolean isEmergency() { return "M01".equals(scenarioId) || "M02".equals(scenarioId); }
    public boolean isMilestone99()
    {
        return ("M04".equals(scenarioId) || "M48".equals(scenarioId))
            && "99".equals(conditionFacts.getOrDefault("newRealLevel", conditionFacts.get("newLevel")));
    }
}

package com.malfoid.speech;

/** An OWN execution cancellation, copied only after its issued capability is revoked. */
public final class SpeechCancellationReceipt
{
    public enum Reason { DEPENDENT_OUTFIT_REVISION_CHANGED, INSPECTION_TARGET_LOST }

    private final SceneCandidate candidate;
    private final Reason reason;
    private final long cancelledAtTick;
    private final long issuedPacketToken;
    private final long executionId;
    private final boolean genuinePainted;
    private final boolean prePaintAttempt;

    SpeechCancellationReceipt(SceneCandidate candidate, Reason reason, long cancelledAtTick,
        long executionId, long issuedPacketToken, boolean genuinePainted, boolean prePaintAttempt)
    {
        this.candidate = candidate;
        this.reason = reason;
        this.cancelledAtTick = cancelledAtTick;
        this.issuedPacketToken = issuedPacketToken;
        this.executionId = executionId;
        this.genuinePainted = genuinePainted;
        this.prePaintAttempt = prePaintAttempt;
    }

    public SceneCandidate getCandidate() { return candidate; }
    public long getCandidateId() { return candidate.getId(); }
    public String getScenarioId() { return candidate.getScenarioId(); }
    public String getCausalToken() { return candidate.getCausalToken(); }
    public long getSessionGeneration() { return candidate.getSessionGeneration(); }
    public long getSceneRevision() { return candidate.getSceneRevision(); }
    public long getCancelledAtTick() { return cancelledAtTick; }
    public Reason getReason() { return reason; }
    public long getIssuedPacketToken() { return issuedPacketToken; }
    public long getExecutionId() { return executionId; }
    public boolean isGenuinePainted() { return genuinePainted; }
    public boolean isPrePaintAttempt() { return prePaintAttempt; }
}

package com.malfoid.speech;

import com.malfoid.dialogue.DialogueCatalog;
import com.malfoid.dialogue.DialogueLine;
import java.util.ArrayDeque;
