    public SpeechPacket.PresentationObservation getPresentationObservation()
    {
        SpeechPacket current = packet;
        return current == null ? null : current.getObservation();
    }

    private void startNext()
    {
        if (!present || active != null)
        {
            return;
        }
        pending.removeIf(candidate -> !valid(candidate));
        for (int index = 0; index < pending.size();)
        {
            SceneCandidate next = pending.get(index);
            if (!settlingReady(next))
            {
                index++;
                continue;
            }
            boolean emote = isEmote(next);
            if (!emote && guard.hasPendingReservation())
            {
                index++;
                continue;
            }
            pending.remove(index);
            String key = catalogue.repeatKey(next.getScenarioId());
            if (!emote && !guard.interactionEligible(key))
            {
                continue;
            }
            FrozenChoice retainedChoice = retainedChoices.remove(next.getId());
            boolean deferredScenery = isLivingWorldScenery(next);
            ActivityTone tone = null;
            int holdTicks = next.getHoldTicks();
            if ("M06".equals(next.getScenarioId()))
            {
                int toneDraw = sceneRandom.nextInt(100);
                tone = toneDraw < 50 ? ActivityTone.RESTLESS : toneDraw < 80 ? ActivityTone.AMUSED : ActivityTone.QUIET;
                holdTicks = 6 + sceneRandom.nextInt(7);
            }
            int silentPercent = "M06".equals(next.getScenarioId()) ? 0 : catalogue.getSilencePercent(next.getScenarioId());
            boolean quietChoice = deferredScenery || emote || (retainedChoice == null
                ? next.isIntentionalSilent() || !showSpeech || tone == ActivityTone.QUIET || silentPercent == 100
                    || silentPercent > 0 && random.nextInt(100) < silentPercent
                : retainedChoice.silent || !showSpeech);
            DialogueLine line = quietChoice ? null : retainedChoice != null && retainedChoice.line != null
                ? retainedChoice.line : chooseLine(next);
            if (line != null && (!line.isEnabled() || !line.matches(next.getConditionFacts())
                || !guard.textEligible(line.getNormalizedText()) || !lineValidator.test(next, line.getId())))
            {
                line = null;
            }
            boolean silent = line == null;
            Long fingerprint = silent ? null : catalogue.situationFingerprint(next);
            SpeechGuard.Reservation admission = emote ? null
                : guard.reserve(key, line == null ? null : line.getNormalizedText(), fingerprint);
            if (!emote && admission == null)
            {
                // Unsettled paint accounting is a fail-closed guard, never a speculative release.
                continue;
            }
            active = next;
            activityTone = tone;
            executionHoldTicks = holdTicks;
            selectedLine = line;
            reservation = admission;
            livingWorldArrivalChosen = !deferredScenery;
            intentionalSilent = silent;
            arrived = false;
            arrivalCommitted = false;
            continuationCancelled = false;
            holdUntilTick = Long.MAX_VALUE;
            originalWatchStartTick = Long.MIN_VALUE;
            holdCompleted = false;
            completionNotified = false;
            cancellationNotified = false;
            executionGenuinePainted = false;
            executionIssuedPacketToken = -1;
            executionId = ++nextExecutionId;
            releaseStartedTick = 0;
            releaseUntilTick = 0;
            int maximumApproach = maximumApproachTicks(next);
            approachDeadline = Math.min(next.getExpiresTick(), tick + maximumApproach);
            trace.accept("scene start " + next.getScenarioId() + (silent ? " silent" : " speech"));
            return;
        }
    }

    private DialogueLine chooseLine(SceneCandidate candidate)
    {
        selectedTalkBag = null;
        Long fingerprint = catalogue.situationFingerprint(candidate);
        if (catalogue.isSituation(candidate.getScenarioId()) && !guard.situationEligible(fingerprint))
        {
            return null;
        }
        List<DialogueLine> eligible = new ArrayList<>();
        List<DialogueLine> talkPool = new ArrayList<>();
        for (DialogueLine line : catalogue.getLines(candidate.getScenarioId()))
        {
            if (line.isEnabled() && line.isOverhead() && line.matches(candidate.getConditionFacts()))
            {
                if (candidate.isRequested()) { talkPool.add(line); }
                if (guard.textEligible(line.getNormalizedText()) && lineValidator.test(candidate, line.getId()))
                {
                    eligible.add(line);
                }
            }
        }
        if (candidate.isRequested() && "1".equals(candidate.getConditionFacts().get("talkStreak")))
        {
            String selectedGroup = null;
            for (String group : new String[] {"combatConfirmed", "playerHpAtMostPercent"})
            {
                for (DialogueLine line : talkPool)
                {
                    if (line.getConditions().containsKey(group))
                    {
                        selectedGroup = group;
                        break;
                    }
                }
                if (selectedGroup != null) { break; }
            }
            if (selectedGroup == null && "true".equals(candidate.getConditionFacts().get("localNight")))
            {
                selectedGroup = random.nextInt(4) == 0 ? "localNight" : null;
            }
            String group = selectedGroup;
            List<DialogueLine> grouped = new ArrayList<>();
            for (DialogueLine line : eligible)
            {
                if (group == null ? line.getConditions().size() <= 1 : line.getConditions().containsKey(group))
                {
                    grouped.add(line);
                }
            }
            // A guard-empty preferred conditional pool falls back only to generic first answers.
            if (grouped.isEmpty() && group != null)
            {
                group = null;
                for (DialogueLine line : eligible)
                {
                    if (line.getConditions().size() <= 1) { grouped.add(line); }
                }
            }
            String poolGroup = group;
            talkPool.removeIf(line -> poolGroup == null ? line.getConditions().size() > 1
                : !line.getConditions().containsKey(poolGroup));
            eligible = grouped;
        }
        if (eligible.isEmpty())
        {
            return null;
        }
        if (candidate.isRequested()) { return chooseTalkLine(talkPool, eligible); }
        if ("M09".equals(candidate.getScenarioId()) || "F03".equals(candidate.getScenarioId()))
        {
            return chooseOwnerPool(candidate.getScenarioId(), eligible);
        }
        if (isLivingWorld(candidate))
        {
            if (eligible.size() > 1)
            {
                String last = lastLivingWorldLines.get(candidate.getScenarioId());
                eligible.removeIf(line -> line.getId().equals(last));
            }
            return eligible.get(random.nextInt(eligible.size()));
        }
        List<DialogueLine> preferred = new ArrayList<>(eligible);
        preferred.removeIf(line -> recentLines.contains(line.getId()));
        List<DialogueLine> pool = preferred.isEmpty() ? eligible : preferred;
        return pool.get(random.nextInt(pool.size()));
    }

    private DialogueLine chooseOwnerPool(String scenario, List<DialogueLine> eligible)
    {
        boolean chooseOwner = random.nextInt(2) == 0;
        List<DialogueLine> pool = new ArrayList<>();
        for (DialogueLine line : eligible)
        {
            boolean owner = "M09".equals(scenario)
                ? "M09-H01".equals(line.getId()) || "M09-H02".equals(line.getId())
                : "F03-01".equals(line.getId());
            if (owner == chooseOwner) { pool.add(line); }
        }
        return pool.isEmpty() ? null : pool.get(random.nextInt(pool.size()));
    }

    private DialogueLine chooseTalkLine(List<DialogueLine> pool, List<DialogueLine> eligible)
    {
        // Conditions identify the pool; temporary text cooldowns never create a new bag.
        List<String> ids = new ArrayList<>();
        for (DialogueLine line : pool) { ids.add(line.getId()); }
        Collections.sort(ids);
        TalkBag bag = talkBags.computeIfAbsent(ids, ignored -> new TalkBag());
        if (bag.remaining.isEmpty())
        {
            bag.remaining.addAll(ids);
            Collections.shuffle(bag.remaining, random);
            if (ids.size() > 1 && bag.remaining.get(0).equals(bag.lastPainted))
            {
                Collections.swap(bag.remaining, 0, 1 + random.nextInt(ids.size() - 1));
            }
        }
        for (String id : bag.remaining)
        {
            if (ids.size() > 1 && bag.remaining.size() == ids.size() && id.equals(bag.lastPainted)) { continue; }
            for (DialogueLine line : eligible)
            {
                if (id.equals(line.getId()))
                {
                    selectedTalkBag = bag;
                    return line;
                }
            }
        }
        return null;
    }

    private boolean valid(SceneCandidate candidate)
    {
        return present && candidate.getSessionGeneration() == generation && candidate.getSceneRevision() == revision
            && tick >= candidate.getCreatedTick() && tick < candidate.getExpiresTick()
            && maximumApproachTicks(candidate) > 0
            && catalogue.hasValidOriginalContext(candidate)
            && (candidate.isRequested() || candidateValidator.test(candidate));
    }

    private int maximumApproachTicks(SceneCandidate candidate)
    {
        int contractMaximum = "M02".equals(candidate.getScenarioId()) ? 20
            : "M07".equals(candidate.getScenarioId()) ? 6 : 12;
        String copiedMaximum = candidate.getConditionFacts().get("maximumApproachTicks");
        if (copiedMaximum == null) { return contractMaximum; }
        try
        {
            int value = Integer.parseInt(copiedMaximum);
            return value >= 1 && value <= 20 ? Math.min(value, contractMaximum) : 0;
        }
        catch (NumberFormatException ignored)
        {
            return 0;
        }
    }

    private boolean mayPreempt(SceneCandidate newcomer)
    {
        if (isLivingWorld(active) && !isLivingWorld(newcomer)) { return true; }
        if (newcomer.isEmergency())
        {
            return newcomer.getPriority() > active.getPriority();
        }
        if (newcomer.isRequested())
        {
            return active.getPriority() < 85;
        }
        return (newcomer.isMilestone99() || "M05".equals(newcomer.getScenarioId()))
            && active.getPriority() < newcomer.getPriority() && (packet == null || !packet.isPainted());
    }

    private boolean startAllowed(SceneCandidate candidate)
    {
        return candidate != null && valid(candidate) && showSpeech
            && settlingReady(candidate)
            && (!busy || candidate.isRequested() || candidate.isEmergency())
            && (!isLivingWorld(candidate) || packet != null && packet.isPainted() || livingWorldSpacingReady())
            && (!candidate.isRequested() || lastPaint == null || tick - lastPaint.getPaintedAtTick() >= 2)
            && (selectedLine == null || packet != null && packet.isPainted()
                || lineValidator.test(candidate, selectedLine.getId()))
            && complaintPaintWindow(candidate);
    }

    private boolean settlingReady(SceneCandidate candidate)
    {
        String notBefore = candidate.getConditionFacts().get("settlingNotBeforeTick");
        if (candidate.getPriority() >= 50 || notBefore == null)
        {
            return true;
        }
        try
        {
            return tick >= Long.parseLong(notBefore);
        }
        catch (NumberFormatException ignored)
        {
            return false;
        }
    }

    private boolean complaintPaintWindow(SceneCandidate candidate)
    {
        if (!"M07".equals(candidate.getScenarioId()))
        {
            return true;
        }
        try
        {
            long parentTick = Long.parseLong(candidate.getConditionFacts().get("parentFirstPaintTick"));
            return tick - parentTick >= 8 && tick - parentTick < 20;
        }
        catch (NumberFormatException | NullPointerException ignored)
        {
            return false;
        }
    }

    private void publishPacket()
    {
        if (packet != null || !startAllowed(active) || selectedLine == null)
        {
            return;
        }
        long earliest = active.isEmergency() || active.isRequested() ? clock.getAsLong() : guard.earliestOrdinaryPaint();
        packet = new SpeechPacket(active, selectedLine, reservation, earliest);
        executionIssuedPacketToken = reservation.getToken();
        packet.setStartAllowed(startAllowed(active));
    }

    /** Scenery's single probability and line draw belong to the real inspection arrival. */
    private void chooseLivingWorldArrival()
    {
        if (livingWorldArrivalChosen) { return; }
        livingWorldArrivalChosen = true;
        guard.retireNoPaint(reservation);
        reservation = null;
        boolean speak = random.nextInt(100) < 50;
        DialogueLine line = speak && showSpeech && !busy && livingWorldSpacingReady()
            ? chooseLine(active) : null;
        SpeechGuard.Reservation admission = line == null ? null : guard.reserve(
            catalogue.repeatKey(active.getScenarioId()), line.getNormalizedText(), catalogue.situationFingerprint(active));
        selectedLine = admission == null ? null : line;
        reservation = admission;
        intentionalSilent = selectedLine == null;
    }

    private void commitSilentArrival()
    {
        if (!arrivalCommitted)
        {
            if (isLivingWorld(active)) { guard.retireNoPaint(reservation); }
            else if (!isEmote(active)) { guard.settleSilentArrival(reservation); }
            arrivalCommitted = true;
            if (!"M01".equals(active.getScenarioId())) { holdUntilTick = tick + executionHoldTicks; }
            silentArrivalListener.accept(active);
        }
    }

    private void settlePaint(SpeechPacket issued)
    {
        SpeechPacket.PaintReceipt receipt = issued.getFirstPaint();
        if (receipt != null && active != null && receipt.getAdmissionToken() == executionIssuedPacketToken
            && active.getId() == receipt.getCandidate().getId()
            && active.getSessionGeneration() == receipt.getCandidate().getSessionGeneration()
            && active.getSceneRevision() == receipt.getCandidate().getSceneRevision()
            && active.getCausalToken().equals(receipt.getCandidate().getCausalToken()))
        {
            executionGenuinePainted = true;
        }
        if (receipt == null || receipt.getAdmissionToken() == settledAdmissionToken)
        {
            return;
        }
        boolean settled = guard.settlePaint(issued.getReservation(), receipt.getPaintedAtNanos());
        if (!settled)
        {
            return;
        }
        settledAdmissionToken = receipt.getAdmissionToken();
        if (receipt.getCandidate().getSessionGeneration() != generation)
        {
            return;
        }
        if (receipt.getCandidate().isRequested() && selectedTalkBag != null)
        {
            selectedTalkBag.remaining.remove(receipt.getLineId());
            selectedTalkBag.lastPainted = receipt.getLineId();
        }
        recentLines.remove(receipt.getLineId());
        recentLines.addLast(receipt.getLineId());
        while (recentLines.size() > 5)
        {
            recentLines.removeFirst();
        }
        lastPaint = receipt;
        if (isLivingWorld(receipt.getCandidate()))
        {
            lastLivingWorldPaintTick = receipt.getPaintedAtTick();
            lastLivingWorldLines.put(receipt.getCandidate().getScenarioId(), receipt.getLineId());
        }
        firstPaintListener.accept(receipt);
        trace.accept("speech painted " + receipt.getLineId());
        if (active != null && active.getId() == receipt.getCandidate().getId())
        {
            arrivalCommitted = true;
            if (!"M01".equals(active.getScenarioId()))
            {
                holdUntilTick = receipt.getPaintedAtTick() + executionHoldTicks;
            }
        }
    }

    private void muteExecution()
    {
        if (isEmote(active)) { return; }
        if (packet != null)
        {
            packet.revoke(true);
            settlePaint(packet);
            if (packet.isPainted())
            {
                packet = null;
                return;
            }
        }
        guard.retireNoPaint(reservation);
        reservation = guard.reserve(catalogue.repeatKey(active.getScenarioId()), null, null);
        packet = null;
        selectedLine = null;
        selectedTalkBag = null;
        intentionalSilent = true;
        if (arrived)
        {
            commitSilentArrival();
        }
    }

    private void updateRequestedExecution(SceneCandidate newer)
    {
        SceneCandidate updated = active.updateRequestedStreak(newer);
        boolean turnAway = newer.isIntentionalSilent();
        if (packet != null && packet.isPainted() && !turnAway)
        {
            settlePaint(packet);
            // A new request updates its streak; the already readable sentence keeps its hold.
            active = updated;
            return;
        }
        if (packet != null)
        {
            packet.revoke(true);
            settlePaint(packet);
        }
        guard.retireNoPaint(reservation);
        active = updated;
        executionHoldTicks = updated.getHoldTicks();
        packet = null;
        selectedTalkBag = null;
        selectedLine = turnAway || !showSpeech ? null : chooseLine(active);
        intentionalSilent = selectedLine == null;
        reservation = guard.reserve(null, selectedLine == null ? null : selectedLine.getNormalizedText(), null);
        arrivalCommitted = false;
        continuationCancelled = false;
        if (turnAway)
        {
            // Repeated latched commands repeat only this bounded turn, never another utterance.
            arrived = true;
            commitSilentArrival();
        }
        else if (arrived)
        {
            if (intentionalSilent) { commitSilentArrival(); }
            else { publishPacket(); }
        }
    }

    private boolean canRetainLevel(SceneCandidate candidate)
    {
        if (!("M04".equals(candidate.getScenarioId()) || "M48".equals(candidate.getScenarioId()))
            || candidate.getRebindCount() != 0 || candidate.getSessionGeneration() != generation
            || tick >= candidate.getExpiresTick() || !"true".equals(candidate.getConditionFacts().get("witnessedPresent")))
        {
            return false;
        }
        try
        {
            Map<String, String> facts = candidate.getConditionFacts();
            long occurred = Long.parseLong(facts.get("occurredTick"));
            long witnessEpoch = Long.parseLong(facts.get("witnessPresenceEpoch"));
            long notBefore = Long.parseLong(facts.get("settlingNotBeforeTick"));
            return witnessEpoch <= occurred && occurred <= candidate.getCreatedTick() && notBefore >= witnessEpoch
                && candidate.getExpiresTick() <= occurred + 10;
        }
        catch (NumberFormatException | NullPointerException ignored)
        {
            return false;
        }
    }

    private void pruneRetained()
    {
        pending.removeIf(candidate -> tick >= candidate.getExpiresTick());
        retainedChoices.keySet().removeIf(id -> pending.stream().noneMatch(candidate -> candidate.getId() == id));
        if (pending.isEmpty())
        {
            loadingSuspended = false;
            resumeStable = 0;
        }
    }

    private static final class FrozenChoice
    {
        private final DialogueLine line;
        private final boolean silent;
        private FrozenChoice(DialogueLine line, boolean silent) { this.line = line; this.silent = silent; }
    }

    private static final class TalkBag
    {
        private final List<String> remaining = new ArrayList<>();
        private String lastPainted;
    }

    private static boolean isEmote(SceneCandidate candidate)
    {
        return "E01".equals(candidate.getScenarioId());
    }

    private void cancelActive(boolean hard, boolean retry)
    {
        if (active == null)
        {
            return;
        }
        if (packet != null)
        {
            packet.revoke(hard);
            settlePaint(packet);
        }
        if (!arrivalCommitted)
        {
            guard.retireNoPaint(reservation);
            if (retry && !isEmote(active) && !isLivingWorld(active))
            {
                retryUntil.put(catalogue.repeatKey(active.getScenarioId()), tick + 5);
            }
        }
        boolean expiredWithoutPaint = !hard && !arrivalCommitted && tick >= active.getExpiresTick();
        trace.accept((expiredWithoutPaint ? "scene expired " : "scene cancel ") + active.getScenarioId());
        clearActive();
    }

    private void finishHoldOrRelease()
    {
        if (!holdCompleted)
        {
            holdCompleted = true;
            if (!completionNotified)
            {
                completionNotified = true;
                completionListener.accept(active);
            }
            if (active.isEmergency())
            {
                releaseStartedTick = tick;
                releaseUntilTick = tick + 10;
                trace.accept("scene release " + active.getScenarioId());
                return;
            }
        }
        if (tick < releaseUntilTick) { return; }
        trace.accept("scene complete " + active.getScenarioId());
        clearActive();
    }

    private void clearActive()
    {
        active = null;
        selectedLine = null;
        selectedTalkBag = null;
        reservation = null;
        packet = null;
        intentionalSilent = false;
        arrived = false;
        arrivalCommitted = false;
        continuationCancelled = false;
        originalWatchStartTick = Long.MIN_VALUE;
        holdCompleted = false;
        completionNotified = false;
        cancellationNotified = false;
        executionGenuinePainted = false;
        executionIssuedPacketToken = -1;
        activityTone = null;
        executionHoldTicks = 0;
        livingWorldArrivalChosen = false;
        releaseStartedTick = 0;
        releaseUntilTick = 0;
    }
}

package com.malfoid.speech;

import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Random;
import java.util.function.LongSupplier;

/** Anonymous process-lifetime admission/settlement; it retains no game or account facts. */
public final class SpeechGuard
{
    private static final long SECOND = 1_000_000_000L;
    private static final long SITUATION_LIFETIME = 5_400L * SECOND;
    private static SpeechGuard processGuard;
    private final LongSupplier clock;
    private final Random random;
    private final Map<String, Stamp> texts = new HashMap<>();
    private final Map<String, Stamp> interactions = new HashMap<>();
    private final LinkedHashMap<Long, Long> situations = new LinkedHashMap<>();
    private int maximumTextKeys;
    private int maximumInteractionKeys;
    private long nextToken;
    private Reservation pending;
    private boolean hasLatestPaint;
    private long latestPaint;

    public SpeechGuard(LongSupplier clock, Random random, int maximumTextKeys, int maximumInteractionKeys)
    {
        this.clock = clock;
        this.random = random;
        this.maximumTextKeys = maximumTextKeys;
        this.maximumInteractionKeys = maximumInteractionKeys;
    }

    public static synchronized SpeechGuard processLifetime(LongSupplier clock, Random random,
        int maximumTextKeys, int maximumInteractionKeys)
    {
        if (processGuard == null)
        {
            processGuard = new SpeechGuard(clock, random, maximumTextKeys, maximumInteractionKeys);
        }
        else
        {
            // A validated resource refresh can enlarge the finite authored universe.
            processGuard.maximumTextKeys = Math.max(processGuard.maximumTextKeys, maximumTextKeys);
            processGuard.maximumInteractionKeys = Math.max(processGuard.maximumInteractionKeys, maximumInteractionKeys);
        }
        return processGuard;
    }

    public synchronized boolean interactionEligible(String key)
    {
        prune(clock.getAsLong());
        return keyEligible(interactions, key, maximumInteractionKeys)
            && (pending == null || key == null || !key.equals(pending.interactionKey));
    }

    public synchronized boolean textEligible(String key)
    {
        prune(clock.getAsLong());
        return keyEligible(texts, key, maximumTextKeys)
            && (pending == null || key == null || !key.equals(pending.textKey));
    }

    public synchronized boolean situationEligible(Long fingerprint)
    {
        prune(clock.getAsLong());
        return fingerprint != null && !situations.containsKey(fingerprint);
    }

    public synchronized Reservation reserve(String interactionKey, String textKey, Long fingerprint)
    {
        prune(clock.getAsLong());
        if (pending != null || !keyEligible(interactions, interactionKey, maximumInteractionKeys)
            || !keyEligible(texts, textKey, maximumTextKeys))
        {
            return null;
        }
        pending = new Reservation(++nextToken, interactionKey, textKey, fingerprint);
        return pending;
    }

    /** Actual first paint owns one shared sample, even when its narrative session ended. */
    public synchronized boolean settlePaint(Reservation reservation, long paintedAt)
    {
        if (!isPending(reservation))
        {
            return false;
        }
        long duration = (30L + random.nextInt(31)) * SECOND;
        commit(interactions, reservation.interactionKey, paintedAt, duration);
        commit(texts, reservation.textKey, paintedAt, duration);
        if (!hasLatestPaint || paintedAt - latestPaint > 0)
        {
            latestPaint = paintedAt;
            hasLatestPaint = true;
        }
        if (reservation.fingerprint != null && !situations.containsKey(reservation.fingerprint))
        {
            pruneSituations(clock.getAsLong());
            if (situations.size() == 256)
            {
                situations.remove(situations.keySet().iterator().next());
            }
            situations.put(reservation.fingerprint, paintedAt);
        }
        pending = null;
        return true;
    }

    public synchronized boolean settleSilentArrival(Reservation reservation)
    {
        if (!isPending(reservation))
        {
            return false;
        }
        // Requested muted conversation has no automatic repeat key and needs no draw.
        if (reservation.interactionKey != null)
        {
            commit(interactions, reservation.interactionKey, clock.getAsLong(), (30L + random.nextInt(31)) * SECOND);
        }
        pending = null;
        return true;
    }

    public synchronized void retireNoPaint(Reservation reservation)
    {
        if (isPending(reservation))
        {
            pending = null;
        }
    }

    public synchronized long earliestOrdinaryPaint()
    {
        return hasLatestPaint ? latestPaint + 2L * SECOND : clock.getAsLong();
    }

    public synchronized boolean handoffEligible()
    {
        return !hasLatestPaint || clock.getAsLong() - latestPaint >= 2L * SECOND;
    }

    public synchronized int textCount() { prune(clock.getAsLong()); return texts.size(); }
    public synchronized int interactionCount() { prune(clock.getAsLong()); return interactions.size(); }
    public synchronized int situationCount() { prune(clock.getAsLong()); return situations.size(); }
    public synchronized boolean hasPendingReservation() { return pending != null; }

    private boolean isPending(Reservation reservation)
    {
        return reservation != null && pending != null && reservation.token == pending.token;
    }

    private static boolean keyEligible(Map<String, Stamp> records, String key, int maximum)
    {
        return key == null || (!records.containsKey(key) && records.size() < maximum);
    }

    private static void commit(Map<String, Stamp> records, String key, long at, long duration)
    {
        if (key == null)
        {
            return;
        }
        Stamp existing = records.get(key);
        if (existing == null || (at + duration) - (existing.at + existing.duration) > 0)
        {
            records.put(key, new Stamp(at, duration));
        }
    }

    private void prune(long now)
    {
        texts.values().removeIf(stamp -> now - stamp.at >= stamp.duration);
        interactions.values().removeIf(stamp -> now - stamp.at >= stamp.duration);
        pruneSituations(now);
    }

    private void pruneSituations(long now)
    {
        Iterator<Map.Entry<Long, Long>> iterator = situations.entrySet().iterator();
        while (iterator.hasNext())
        {
            if (now - iterator.next().getValue() >= SITUATION_LIFETIME)
            {
                iterator.remove();
            }
        }
    }

    public static final class Reservation
    {
        private final long token;
        private final String interactionKey;
        private final String textKey;
        private final Long fingerprint;

        private Reservation(long token, String interactionKey, String textKey, Long fingerprint)
        {
            this.token = token;
            this.interactionKey = interactionKey;
            this.textKey = textKey;
            this.fingerprint = fingerprint;
        }

        public long getToken() { return token; }
    }

    private static final class Stamp
    {
        private final long at;
        private final long duration;

        private Stamp(long at, long duration)
        {
            this.at = at;
            this.duration = duration;
        }
    }
}

package com.malfoid.speech;

import com.malfoid.dialogue.DialogueLine;

/** One bounded issued capability. Its lock linearizes first paint against revocation. */
public final class SpeechPacket
{
    private final SceneCandidate candidate;
    private final DialogueLine line;
    private final SpeechGuard.Reservation reservation;
    private final long earliestPaint;
    private final long holdNanos;
    private boolean hardRevoked;
    private boolean continuationAllowed = true;
    private boolean startAllowed = true;
    private PaintReceipt firstPaint;
    private PresentationObservation observation;

    SpeechPacket(SceneCandidate candidate, DialogueLine line, SpeechGuard.Reservation reservation, long earliestPaint)
    {
        this.candidate = candidate;
        this.line = line;
        this.reservation = reservation;
        this.earliestPaint = earliestPaint;
        int points = line.getText().codePointCount(0, line.getText().length());
        this.holdNanos = Math.max(3_000, Math.min(7_000, 2_000 + 60 * points)) * 1_000_000L;
    }

    public String getText() { return line.getText(); }
    public String getLineId() { return line.getId(); }
    public String getEmotion() { return line.getEmotion(); }
    public SceneCandidate getCandidate() { return candidate; }
    SpeechGuard.Reservation getReservation() { return reservation; }

    public synchronized PaintReceipt paint(long now, long tick, long frameId, Runnable draw)
    {
        if (!canPaint(now))
        {
            markUndrawable(frameId);
            return null;
        }
        // Keep the capability lock through the real draw. Revoked-before-claim never draws;
        // claimed-before-revoke settles either the successful draw or the explicit failure.
        draw.run();
        PaintReceipt receipt = null;
        if (firstPaint == null)
        {
            firstPaint = new PaintReceipt(candidate, line.getId(), reservation.getToken(), now, tick);
            receipt = firstPaint;
        }
        observation = new PresentationObservation(candidate.getId(), candidate.getSessionGeneration(),
            candidate.getSceneRevision(), frameId, now, firstPaint.getPaintedAtNanos() + holdNanos + 500_000_000L, true);
        return receipt;
    }

    public synchronized boolean canPaint(long now)
    {
        return !hardRevoked && now - earliestPaint >= 0
            && (firstPaint != null ? now - firstPaint.getPaintedAtNanos() < holdNanos + 500_000_000L
                : continuationAllowed && startAllowed);
    }

    public synchronized float alpha(long now)
    {
        if (firstPaint == null)
        {
            return 1f;
        }
        long afterHold = now - firstPaint.getPaintedAtNanos() - holdNanos;
        return afterHold <= 0 ? 1f : Math.max(0f, 1f - afterHold / 500_000_000f);
    }

    public synchronized void setStartAllowed(boolean allowed) { startAllowed = allowed; }

    public synchronized void revoke(boolean hard)
    {
        continuationAllowed = false;
        hardRevoked |= hard;
        if (hard || firstPaint == null)
        {
            markUndrawable(observation == null ? -1 : observation.getFrameId());
        }
    }

    public synchronized void markUndrawable(long frameId)
    {
        observation = new PresentationObservation(candidate.getId(), candidate.getSessionGeneration(),
            candidate.getSceneRevision(), frameId, observation == null ? 0 : observation.getLastPaintNanos(),
            firstPaint == null ? 0 : firstPaint.getPaintedAtNanos() + holdNanos + 500_000_000L, false);
    }

    public synchronized boolean isPainted() { return firstPaint != null; }
    public synchronized boolean isContinuationAllowed() { return continuationAllowed && !hardRevoked; }
    public synchronized PaintReceipt getFirstPaint() { return firstPaint; }
    public synchronized PresentationObservation getObservation() { return observation; }
    public synchronized boolean isFinished(long now)
    {
        return hardRevoked || firstPaint != null && now - firstPaint.getPaintedAtNanos() >= holdNanos + 500_000_000L;
    }

    public static final class PaintReceipt
    {
        private final SceneCandidate candidate;
        private final String lineId;
        private final long admissionToken;
        private final long paintedAtNanos;
        private final long paintedAtTick;

        private PaintReceipt(SceneCandidate candidate, String lineId, long admissionToken, long paintedAtNanos, long paintedAtTick)
        {
            this.candidate = candidate;
            this.lineId = lineId;
            this.admissionToken = admissionToken;
            this.paintedAtNanos = paintedAtNanos;
            this.paintedAtTick = paintedAtTick;
        }

        public SceneCandidate getCandidate() { return candidate; }
        public String getLineId() { return lineId; }
        public long getAdmissionToken() { return admissionToken; }
        public long getPaintedAtNanos() { return paintedAtNanos; }
        public long getPaintedAtTick() { return paintedAtTick; }
    }

    public static final class PresentationObservation
    {
        private final long candidateId;
        private final long sessionGeneration;
        private final long sceneRevision;
        private final long frameId;
        private final long lastPaintNanos;
        private final long lifetimeEndNanos;
        private final boolean drawable;

        private PresentationObservation(long candidateId, long sessionGeneration, long sceneRevision,
            long frameId, long lastPaintNanos, long lifetimeEndNanos, boolean drawable)
        {
            this.candidateId = candidateId;
            this.sessionGeneration = sessionGeneration;
            this.sceneRevision = sceneRevision;
            this.frameId = frameId;
            this.lastPaintNanos = lastPaintNanos;
            this.lifetimeEndNanos = lifetimeEndNanos;
            this.drawable = drawable;
        }

        public long getCandidateId() { return candidateId; }
        public long getSessionGeneration() { return sessionGeneration; }
        public long getSceneRevision() { return sceneRevision; }
        public long getFrameId() { return frameId; }
        public long getLastPaintNanos() { return lastPaintNanos; }
        public long getLifetimeEndNanos() { return lifetimeEndNanos; }
        public boolean isDrawable() { return drawable; }
    }
}

package com.malfoid.world;

import com.malfoid.speech.SceneCandidate;
import com.malfoid.speech.SpeechPacket;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import java.util.function.LongSupplier;

/** Copied creature opportunities. NativeActor remains the sole owner of physical effects. */
public final class LivingWorldCreatures
{
    /** Same finite identity bound as the native active-view intake; full means silent until reset. */
    public static final int MAX_WIZARD_IDENTITIES = 256;
    public static final class Sighting
    {
        public final String key;
        public final LivingWorldData.CreatureGroup group;
        public final int worldX, worldY, plane, distance;

        public Sighting(String key, LivingWorldData.CreatureGroup group, int worldX, int worldY, int plane, int distance)
        {
            this.key = key; this.group = group; this.worldX = worldX; this.worldY = worldY;
            this.plane = plane; this.distance = distance;
        }
    }

    private final Random random;
    private final LongSupplier candidateIds;
    private final Map<String, Long> lastAttempt = new HashMap<>();
    private final Set<String> wizardsSeen = new HashSet<>();
    private long generation = Long.MIN_VALUE, revision = Long.MIN_VALUE, previousTick = Long.MIN_VALUE;
    private String priorGroup, lastFondArrivalKey;
    private long lastSafetyBegin = Long.MIN_VALUE, lastFondArrivalTick = Long.MIN_VALUE;
    private Sighting current, wizardLook;
    private String petKey;
    private int petTicks;
    private boolean petAttempted;
    private long lastPetPaint = Long.MIN_VALUE;

    public LivingWorldCreatures(Random random, LongSupplier candidateIds)
    {
        this.random = random; this.candidateIds = candidateIds;
    }

    public SceneCandidate observe(long tick, long sessionGeneration, long sceneRevision, boolean known,
        boolean reactionAllowed, boolean speechAllowed, List<Sighting> creatures,
        String safetyGroup, long safetyBeginTick, String fondArrivalKey, long fondArrivalTick)
    {
        if (generation != sessionGeneration) { resetSession(); generation = sessionGeneration; }
        if (revision != sceneRevision || previousTick != Long.MIN_VALUE && tick != previousTick + 1)
        {
            resetObservation();
        }
        revision = sceneRevision; previousTick = tick; wizardLook = null;
        if (!known)
        {
            // UNKNOWN revokes the current capability; it does not prove the encounter ended.
            current = null;
            petTicks = 0;
            return null;
        }
        boolean petMatured = observePet(creatures);
        current = nearestFirstGroup(creatures);
        String groupId = current == null ? null : current.group.id;
        boolean firstSight = groupId != null && !groupId.equals(priorGroup);
        priorGroup = groupId;
        if (current == null) { return null; }

        LivingWorldData.Behaviour behaviour = current.group.behaviour;
        int chance, spacing = 0;
        boolean event;
        switch (behaviour)
        {
            case AFRAID:
            case AFRAID_AT_DISTANCE:
            case WARY:
                event = groupId.equals(safetyGroup) && safetyBeginTick >= 0 && safetyBeginTick != lastSafetyBegin;
                if (event) { lastSafetyBegin = safetyBeginTick; }
                chance = behaviour == LivingWorldData.Behaviour.AFRAID_AT_DISTANCE ? 60 : 50;
                break;
            case DISGUSTED:
                event = firstSight; chance = 50; spacing = 300;
                break;
            case FOND:
                event = current.key.equals(fondArrivalKey) && fondArrivalTick == tick
                    && (!current.key.equals(lastFondArrivalKey) || fondArrivalTick != lastFondArrivalTick);
                if (event) { lastFondArrivalKey = fondArrivalKey; lastFondArrivalTick = fondArrivalTick; }
                chance = 50; spacing = 300;
                break;
            case LOOKS_THEM_OVER:
                if (current.group.localPlayersFollower)
                {
                    event = petMatured && current.key.equals(petKey);
                    chance = 50; spacing = 1500;
                    if (event && reactionAllowed) { wizardLook = current; }
                    break;
                }
                event = !wizardsSeen.contains(current.key) && wizardsSeen.size() < MAX_WIZARD_IDENTITIES;
                if (event) { wizardsSeen.add(current.key); }
                chance = 40; spacing = 500;
                if (event && reactionAllowed) { wizardLook = current; }
                break;
            case SPEAKS_ONLY:
                event = firstSight; chance = 30; spacing = 500;
                break;
            default: return null;
        }
        // Empty WORLD F01/F02 groups leave their higher-priority E.5/E.9 speech untouched.
        if (!event || current.group.lines.isEmpty()) { return null; }
        boolean pet = current.group.localPlayersFollower;
        Long prior = pet ? lastPetPaint == Long.MIN_VALUE ? null : lastPetPaint : lastAttempt.get(groupId);
        if (prior != null && tick - prior < spacing) { return null; }
        if (!pet) { lastAttempt.put(groupId, tick); }
        if (!speechAllowed || random.nextInt(100) >= chance) { return null; }
        Map<String, String> facts = new HashMap<>();
        facts.put("livingWorld", "CREATURE"); facts.put("creatureGroup", groupId);
        facts.put("creatureKey", current.key);
        facts.put("creatureX", Integer.toString(current.worldX));
        facts.put("creatureY", Integer.toString(current.worldY));
        facts.put("creaturePlane", Integer.toString(current.plane));
        return new SceneCandidate(candidateIds.getAsLong(), groupId, -100, tick, tick + 1,
            sessionGeneration, sceneRevision, "world-creature:" + groupId + ":" + current.key + ":" + tick,
            facts, false, 0);
    }

    public Sighting getWizardLook() { return wizardLook; }
    public Sighting getCurrent() { return current; }
    public int getWizardIdentityCount() { return wizardsSeen.size(); }

    private boolean observePet(List<Sighting> creatures)
    {
        Sighting pet = null;
        for (Sighting sighting : creatures)
        {
            if (sighting != null && sighting.group != null && sighting.group.localPlayersFollower
                && sighting.key != null && sighting.distance >= 0 && sighting.distance <= 6)
            {
                pet = sighting;
                break;
            }
        }
        if (pet == null) { petKey = null; petTicks = 0; petAttempted = false; return false; }
        if (!pet.key.equals(petKey)) { petKey = pet.key; petTicks = 0; petAttempted = false; }
        if (petTicks < 20) { petTicks++; }
        if (petTicks != 20 || petAttempted) { return false; }
        petAttempted = true;
        return true;
    }

    /** Only a settled real first paint starts the pet's 1,500-tick speech spacing. */
    public void onPaint(SpeechPacket.PaintReceipt receipt)
    {
        if (receipt == null || receipt.getCandidate().getSessionGeneration() != generation
            || !"CR-PET".equals(receipt.getCandidate().getScenarioId())
            || !"CREATURE".equals(receipt.getCandidate().getConditionFacts().get("livingWorld"))) { return; }
        lastPetPaint = Math.max(lastPetPaint, receipt.getPaintedAtTick());
    }

    public boolean matches(SceneCandidate candidate)
    {
        return current != null && candidate.getSessionGeneration() == generation
            && candidate.getSceneRevision() == revision && current.group.id.equals(candidate.getScenarioId())
            && current.key.equals(candidate.getConditionFacts().get("creatureKey"));
    }

    private static Sighting nearestFirstGroup(List<Sighting> creatures)
    {
        Sighting best = null;
        for (Sighting creature : creatures)
        {
            if (creature == null || creature.group == null || creature.key == null || creature.distance > 6
                || creature.distance < 0) { continue; }
            if (best == null || creature.group.ordinal < best.group.ordinal
                || creature.group.ordinal == best.group.ordinal && (creature.distance < best.distance
                    || creature.distance == best.distance && creature.key.compareTo(best.key) < 0))
            {
                best = creature;
            }
        }
        return best;
    }

    public void resetObservation()
    {
        current = wizardLook = null; priorGroup = null;
        lastFondArrivalKey = null; lastFondArrivalTick = Long.MIN_VALUE;
        previousTick = Long.MIN_VALUE;
        petTicks = 0;
    }

    public void resetSession()
    {
        resetObservation(); lastAttempt.clear(); wizardsSeen.clear();
        lastSafetyBegin = Long.MIN_VALUE;
        petKey = null; petAttempted = false; lastPetPaint = Long.MIN_VALUE;
        generation = revision = Long.MIN_VALUE;
    }
}

package com.malfoid.world;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/** The exact authored Addendum F data. Counts and predicates come from the resource. */
public final class LivingWorldData
{
    public static final String RESOURCE = "/com/malfoid/living-world.json";
    public static final String SHA256 = "e2341361aa78dcf20bac43516a7829b4dddb04107c3fd8d8b1022a9ef3e11477";
    public enum Behaviour { AFRAID, AFRAID_AT_DISTANCE, WARY, DISGUSTED, FOND, LOOKS_THEM_OVER, SPEAKS_ONLY }

    public final List<PlaceGroup> places, placeKinds;
    public final List<CreatureGroup> creatures;
    public final List<SceneryGroup> scenery;
    public final List<Moment> moments;
    public final int lineCount;
    private final Map<Integer, PlaceGroup> regions;
    private final Map<String, Group> groups;
    private final Map<String, SceneryGroup> objectNames;
    private final int kindAreaCount;

    private LivingWorldData(List<PlaceGroup> places, List<PlaceGroup> kinds, List<CreatureGroup> creatures,
        List<SceneryGroup> scenery, List<Moment> moments, Map<Integer, PlaceGroup> regions, Map<String, Group> groups,
        Map<String, SceneryGroup> objectNames, int lineCount, int kindAreaCount)
    {
        this.places = immutable(places); placeKinds = immutable(kinds); this.creatures = immutable(creatures);
        this.scenery = immutable(scenery); this.moments = immutable(moments); this.regions = Collections.unmodifiableMap(regions);
        this.groups = Collections.unmodifiableMap(groups); this.objectNames = Collections.unmodifiableMap(objectNames);
        this.lineCount = lineCount;
        this.kindAreaCount = kindAreaCount;
    }

    public static LivingWorldData load(Class<?> resourceOwner) throws IOException
    {
        try (InputStream input = resourceOwner.getResourceAsStream(RESOURCE))
        {
            if (input == null) { throw new IOException("Missing bundled " + RESOURCE); }
            return parse(input.readAllBytes());
        }
    }

    public static LivingWorldData parse(byte[] bytes) throws IOException { return parse(bytes, SHA256); }

    // A future built pin changes the resource/pin, never the observer or entry-count logic.
    static LivingWorldData parse(byte[] bytes, String builtHash) throws IOException
    {
        if (bytes == null || builtHash == null || !builtHash.equals(sha256(bytes)))
        {
            throw new IOException("Living-world resource hash mismatch");
        }
        try
        {
            JsonObject root = new JsonParser().parse(new String(bytes, StandardCharsets.UTF_8)).getAsJsonObject();
            require(integer(root, "schemaVersion") == 1, "Unsupported living-world schema");
            JsonObject lineRules = root.getAsJsonObject("lineRules");
            int maximumCharacters = integer(lineRules, "maximumCharacters");
            require(maximumCharacters > 0, "Invalid line length rule");
            Set<String> emotions = new HashSet<>(strings(lineRules, "emotions", false));
            require(!emotions.isEmpty(), "Missing line emotions");
            Set<String> lineIds = new HashSet<>();
            Map<String, Group> groups = new LinkedHashMap<>();
            List<PlaceGroup> places = new ArrayList<>(), kinds = new ArrayList<>();
            int kindAreaCount = 0;
            Map<Integer, PlaceGroup> namedRegions = new HashMap<>(), kindRegions = new HashMap<>();
            for (JsonElement element : array(root, "places"))
            {
                JsonObject entry = element.getAsJsonObject();
                PlaceGroup group = new PlaceGroup(id(entry), string(entry, "name"), false,
                    facts(entry), lines(entry, lineIds, emotions, maximumCharacters));
                addGroup(groups, group); places.add(group);
                addRegions(namedRegions, entry, group);
            }
            for (JsonElement element : array(root, "placeKinds"))
            {
                JsonObject entry = element.getAsJsonObject();
                PlaceGroup group = new PlaceGroup(id(entry), null, true,
                    facts(entry), lines(entry, lineIds, emotions, maximumCharacters));
                addGroup(groups, group); kinds.add(group);
                for (JsonElement area : array(entry, "places"))
                {
                    JsonObject place = area.getAsJsonObject(); string(place, "name");
                    addRegions(kindRegions, place, group);
                    kindAreaCount++;
                }
            }
            Map<Integer, PlaceGroup> regions = new HashMap<>(kindRegions);
            regions.putAll(namedRegions); // Authored named places take precedence over kinds.
            Map<String, JsonObject> creatureEntries = new LinkedHashMap<>();
            for (JsonElement element : array(root, "creatures"))
            {
                JsonObject entry = element.getAsJsonObject();
                require(creatureEntries.put(id(entry), entry) == null, "Duplicate creature ID");
            }
            List<CreatureGroup> creatures = new ArrayList<>();
            Set<String> prioritySeen = new HashSet<>();
            for (String key : strings(root, "creaturePriority", false))
            {
                JsonObject entry = creatureEntries.get(key);
                require(entry != null && prioritySeen.add(key), "Invalid creature priority");
                CreatureGroup group = new CreatureGroup(key, creatures.size(),
                    Behaviour.valueOf(string(entry, "behaviour")),
                    lines(entry, lineIds, emotions, maximumCharacters),
                    strings(entry, "equals", true), strings(entry, "startsWith", true),
                    strings(entry, "endsWith", true), strings(entry, "containsWord", true),
                    strings(entry, "neverIfContainsWord", true),
                    entry.has("minimumCombatLevel") ? nonnegative(entry, "minimumCombatLevel") : 0,
                    entry.has("endsWithAtCombatLevel") ? entry.getAsJsonObject("endsWithAtCombatLevel") : null,
                    entry.has("localPlayersFollower") && bool(entry, "localPlayersFollower"));
                addGroup(groups, group); creatures.add(group);
            }
            require(prioritySeen.equals(creatureEntries.keySet()), "Missing creature priority");
            List<SceneryGroup> scenery = new ArrayList<>();
            Map<String, SceneryGroup> objectNames = new HashMap<>();
            for (JsonElement element : array(root, "scenery"))
            {
                JsonObject entry = element.getAsJsonObject();
                SceneryGroup group = new SceneryGroup(id(entry), facts(entry),
                    lines(entry, lineIds, emotions, maximumCharacters), strings(entry, "objectNames", false));
                addGroup(groups, group); scenery.add(group);
                require(!group.objectNames.isEmpty(), "Missing scenery name");
                for (String name : group.objectNames)
                {
                    require(name.equals(normalizeName(name)), "Scenery names must be normalized");
                    require(objectNames.put(name, group) == null, "Ambiguous scenery name");
                }
            }
            List<Moment> moments = new ArrayList<>();
            for (JsonElement element : array(root, "moments"))
            {
                JsonObject entry = element.getAsJsonObject();
                Moment moment = new Moment(id(entry), string(entry, "fact"), facts(entry),
                    lines(entry, lineIds, emotions, maximumCharacters),
                    optionalNonnegative(entry, "playerHpAbovePercent"), optionalNonnegative(entry, "playerHpAtMostPercent"),
                    optionalNonnegative(entry, "timesLatelyAtMost"), optionalNonnegative(entry, "timesLatelyAtLeast"));
                addGroup(groups, moment); moments.add(moment);
            }
            require(lineIds.size() == integer(lineRules, "lineCount"), "Living-world line count mismatch");
            return new LivingWorldData(places, kinds, creatures, scenery, moments, regions, groups, objectNames,
                lineIds.size(), kindAreaCount);
        }
        catch (RuntimeException failure)
        {
            throw new IOException("Invalid living-world resource", failure);
        }
    }

    public PlaceGroup place(int regionId) { return regions.get(regionId); }
    public Group group(String id) { return groups.get(id); }
    public int regionCount() { return regions.size(); }
    public int kindAreaCount() { return kindAreaCount; }
    public SceneryGroup scenery(String rawName) { return objectNames.get(normalizeName(rawName)); }

    /** Used inside the existing single bounded NPC pass; it retains no NPC or name. */
    public CreatureGroup creature(String rawName, int combatLevel)
    {
        String name = normalizeName(rawName);
        if (name.isEmpty()) { return null; }
        for (CreatureGroup group : creatures)
        {
            if (group.matches(name, combatLevel)) { return group; }
        }
        return null;
    }

    public static String normalizeName(String raw)
    {
        if (raw == null) { return ""; }
        return raw.replaceAll("<[^>]*>", "").toLowerCase(Locale.ROOT);
    }

    public static boolean containsWord(String name, String word)
    {
        for (int start = name.indexOf(word); start >= 0; start = name.indexOf(word, start + 1))
        {
            int end = start + word.length();
            if ((start == 0 || !wordCharacter(name.charAt(start - 1)))
                && (end == name.length() || !wordCharacter(name.charAt(end)))) { return true; }
        }
        return false;
    }

    private static boolean wordCharacter(char value) { return Character.isLetterOrDigit(value) || value == '_'; }

    public static class Group
    {
        public final String id;
        public final List<String> facts;
        public final List<Line> lines;
        private Group(String id, List<String> facts, List<Line> lines)
        {
            this.id = id; this.facts = immutable(facts); this.lines = immutable(lines);
        }
    }

    public static final class PlaceGroup extends Group
    {
        public final String name;
        public final boolean kind;
        private PlaceGroup(String id, String name, boolean kind, List<String> facts, List<Line> lines)
        {
            super(id, facts, lines); this.name = name; this.kind = kind;
            require(!lines.isEmpty(), "Missing place lines");
        }
    }

    public static final class CreatureGroup extends Group
    {
        public final int ordinal;
        public final Behaviour behaviour;
        public final boolean localPlayersFollower;
        private final List<String> equals, starts, ends, words, vetoes;
        private final int minimumCombatLevel, suffixMinimum;
        private final String combatSuffix;
        private CreatureGroup(String id, int ordinal, Behaviour behaviour, List<Line> lines,
            List<String> equals, List<String> starts, List<String> ends, List<String> words,
            List<String> vetoes, int minimumCombatLevel, JsonObject suffix, boolean localPlayersFollower)
        {
            super(id, Collections.emptyList(), lines); this.ordinal = ordinal; this.behaviour = behaviour;
            this.localPlayersFollower = localPlayersFollower;
            this.equals = immutable(equals); this.starts = immutable(starts); this.ends = immutable(ends);
            this.words = immutable(words); this.vetoes = immutable(vetoes); this.minimumCombatLevel = minimumCombatLevel;
            combatSuffix = suffix == null ? null : string(suffix, "suffix");
            suffixMinimum = suffix == null ? 0 : nonnegative(suffix, "minimumCombatLevel");
            require(combatSuffix == null || combatSuffix.equals(normalizeName(combatSuffix)),
                "Creature suffix must be normalized");
            boolean hasNamePredicate = !equals.isEmpty() || !starts.isEmpty() || !ends.isEmpty()
                || !words.isEmpty() || combatSuffix != null;
            require(localPlayersFollower ? !hasNamePredicate && vetoes.isEmpty() && minimumCombatLevel == 0 : hasNamePredicate,
                "Invalid creature identity or name predicate");
            for (List<String> predicates : java.util.Arrays.asList(equals, starts, ends, words, vetoes))
            {
                for (String predicate : predicates)
                {
                    require(predicate.equals(normalizeName(predicate)), "Creature predicates must be normalized");
                }
            }
        }
        private boolean matches(String name, int combatLevel)
        {
            if (localPlayersFollower) { return false; }
            for (String word : vetoes) { if (containsWord(name, word)) { return false; } }
            if (combatLevel < minimumCombatLevel) { return false; }
            if (equals.contains(name)) { return true; }
            for (String prefix : starts) { if (name.startsWith(prefix)) { return true; } }
            for (String suffix : ends) { if (name.endsWith(suffix)) { return true; } }
            for (String word : words) { if (containsWord(name, word)) { return true; } }
            return combatSuffix != null && combatLevel >= suffixMinimum && name.endsWith(combatSuffix);
        }
    }

    public static final class SceneryGroup extends Group
    {
        public final List<String> objectNames;
        private SceneryGroup(String id, List<String> facts, List<Line> lines, List<String> names)
        {
            super(id, facts, lines); objectNames = immutable(names);
            require(!lines.isEmpty(), "Missing scenery lines");
        }
    }

    public static final class Moment extends Group
    {
        public final String fact, logicalKey;
        public final Integer playerHpAbovePercent, playerHpAtMostPercent, timesLatelyAtMost, timesLatelyAtLeast;
        private Moment(String id, String fact, List<String> facts, List<Line> lines,
            Integer hpAbove, Integer hpAtMost, Integer timesAtMost, Integer timesAtLeast)
        {
            super(id, facts, lines); this.fact = fact;
            playerHpAbovePercent = hpAbove; playerHpAtMostPercent = hpAtMost;
            timesLatelyAtMost = timesAtMost; timesLatelyAtLeast = timesAtLeast;
            require(!facts.isEmpty() && !lines.isEmpty(), "Missing moment facts or lines");
            require("WILDERNESS_ENTERED".equals(fact) || "WILDERNESS_LEFT".equals(fact)
                || "BACK_AFTER_PLAYER_COMBAT".equals(fact) || "KEPT_WAITING".equals(fact)
                || "KEPT_BACK_BY_BEAST".equals(fact), "Unknown moment fact");
            require(hpAbove == null || hpAbove < 100, "Invalid moment HP lower bound");
            require(hpAtMost == null || hpAtMost <= 100, "Invalid moment HP upper bound");
            require(hpAbove == null || hpAtMost == null || hpAbove < hpAtMost, "Empty moment HP range");
            require(timesAtLeast == null || timesAtMost == null || timesAtLeast <= timesAtMost,
                "Empty moment repetition range");
            logicalKey = "W-AFTER-PVP-HURT".equals(id) ? "W-AFTER-PVP"
                : "G-WAITING-LONG".equals(id) ? "G-WAITING" : id;
            require(!"W-AFTER-PVP".equals(logicalKey) || "BACK_AFTER_PLAYER_COMBAT".equals(fact),
                "Invalid after-combat moment alias");
            require(!"G-WAITING".equals(logicalKey) || "KEPT_WAITING".equals(fact),
                "Invalid waiting moment alias");
        }
        public boolean matches(int hpPercent, int timesLately)
        {
            return matchesHp(hpPercent, 100) && matchesTimesLately(timesLately);
        }
        public boolean matchesHp(int currentHp, int realHp)
        {
            if (playerHpAbovePercent == null && playerHpAtMostPercent == null) { return true; }
            return currentHp >= 0 && realHp > 0
                && (playerHpAbovePercent == null || 100L * currentHp > (long) playerHpAbovePercent * realHp)
                && (playerHpAtMostPercent == null || 100L * currentHp <= (long) playerHpAtMostPercent * realHp);
        }
        public boolean matchesTimesLately(int timesLately)
        {
            if (timesLatelyAtMost == null && timesLatelyAtLeast == null) { return true; }
            return timesLately >= 0 && (timesLatelyAtMost == null || timesLately <= timesLatelyAtMost)
                && (timesLatelyAtLeast == null || timesLately >= timesLatelyAtLeast);
        }
    }

    public static final class Line
    {
        public final String id, text, emotion;
        private Line(String id, String text, String emotion) { this.id = id; this.text = text; this.emotion = emotion; }
    }

    private static List<Line> lines(JsonObject entry, Set<String> ids, Set<String> emotions, int maximum)
    {
        List<Line> result = new ArrayList<>();
        for (JsonElement element : array(entry, "lines"))
        {
            JsonObject line = element.getAsJsonObject(); String id = id(line), text = string(line, "text");
            String emotion = string(line, "emotion");
            require(ids.add(id), "Duplicate living-world line ID");
            require(text.codePointCount(0, text.length()) <= maximum && !text.contains("\n") && !text.contains("\r"),
                "Invalid living-world line length");
            require(emotions.contains(emotion), "Unknown living-world emotion");
            result.add(new Line(id, text, emotion));
        }
        return result;
    }
    private static List<String> facts(JsonObject entry) { return strings(entry, "facts", false); }
    private static List<String> strings(JsonObject object, String key, boolean optional)
    {
        if (optional && !object.has(key)) { return Collections.emptyList(); }
        List<String> result = new ArrayList<>();
        for (JsonElement element : array(object, key))
        {
            require(element.isJsonPrimitive() && element.getAsJsonPrimitive().isString(), "Expected string " + key);
            String value = element.getAsString(); require(!value.isEmpty(), "Empty " + key); result.add(value);
        }
        return result;
    }
    private static JsonArray array(JsonObject object, String key) { return object.getAsJsonArray(key); }
    private static String id(JsonObject object) { return string(object, "id"); }
    private static String string(JsonObject object, String key)
    {
        JsonElement value = object.get(key);
        require(value != null && value.isJsonPrimitive() && value.getAsJsonPrimitive().isString(), "Expected string " + key);
        String text = value.getAsString(); require(!text.isEmpty(), "Empty " + key); return text;
    }
    private static int integer(JsonObject object, String key)
    {
        JsonElement value = object.get(key);
        require(value != null && value.isJsonPrimitive() && value.getAsJsonPrimitive().isNumber(), "Expected integer " + key);
        return value.getAsBigDecimal().intValueExact();
    }
    private static int nonnegative(JsonObject object, String key)
    {
        int value = integer(object, key); require(value >= 0, "Negative " + key); return value;
    }
    private static Integer optionalNonnegative(JsonObject object, String key)
    {
        return object.has(key) ? nonnegative(object, key) : null;
    }
    private static boolean bool(JsonObject object, String key)
    {
        JsonElement value = object.get(key);
        require(value != null && value.isJsonPrimitive() && value.getAsJsonPrimitive().isBoolean(), "Expected boolean " + key);
        return value.getAsBoolean();
    }
    private static void addGroup(Map<String, Group> groups, Group group)
    {
        require(groups.put(group.id, group) == null, "Duplicate living-world group ID");
    }
    private static void addRegions(Map<Integer, PlaceGroup> regions, JsonObject entry, PlaceGroup group)
    {
        JsonArray ids = array(entry, "regionIds"); require(ids.size() > 0, "Missing place regions");
        for (JsonElement element : ids)
        {
            require(element.isJsonPrimitive() && element.getAsJsonPrimitive().isNumber(), "Invalid region ID");
            int region = element.getAsBigDecimal().intValueExact(); require(region >= 0 && region <= 65535, "Invalid region ID");
            PlaceGroup prior = regions.put(region, group); require(prior == null || prior == group, "Ambiguous place region");
        }
    }
    static String sha256(byte[] bytes)
    {
        try
        {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(bytes); StringBuilder result = new StringBuilder(64);
            for (byte value : digest) { result.append(String.format(Locale.ROOT, "%02x", value & 255)); }
            return result.toString();
        }
        catch (NoSuchAlgorithmException impossible) { throw new IllegalStateException(impossible); }
    }
    private static <T> List<T> immutable(List<T> values) { return Collections.unmodifiableList(new ArrayList<>(values)); }
    private static void require(boolean condition, String message) { if (!condition) { throw new IllegalArgumentException(message); } }
}

package com.malfoid.world;

import com.malfoid.speech.SceneCandidate;
import com.malfoid.speech.SpeechPacket;
import java.util.HashMap;
import java.util.Map;
import java.util.Random;
import java.util.function.LongSupplier;

/** F.7's local, session-only facts. An ineligible fact is consumed on its own tick. */
public final class LivingWorldMoments
{
    private final LivingWorldData data;
    private final Random random;
    private final LongSupplier candidateIds;
    private final Map<String, Long> lastPaint = new HashMap<>();
    private long generation = Long.MIN_VALUE, previousTick = Long.MIN_VALUE, issuedId = -1;
    private boolean insideKnown, inside, diedInside, playerCombatAbsent, diedDuringCombat;
    private int sameInsideTicks, keptBackTicks;
    private boolean keptBackOffered;
    private long returnedSince = -1;

    public LivingWorldMoments(LivingWorldData data, Random random, LongSupplier candidateIds)
    {
        this.data = data; this.random = random; this.candidateIds = candidateIds;
    }

    public SceneCandidate observe(long tick, long sessionGeneration, long sceneRevision,
        boolean present, long presentSinceTick, boolean combatAbsence, boolean alive,
        boolean wildernessSampleAllowed, boolean wildernessInside, int currentHp, int realHp, boolean eligible)
    {
        if (generation != sessionGeneration) { resetSession(); generation = sessionGeneration; }
        if (tick == previousTick) { return null; }
        previousTick = tick; issuedId = -1;
        if (combatAbsence) { onPlayerCombatAbsence(); }
        String fact = null;
        if (present && playerCombatAbsent)
        {
            playerCombatAbsent = false;
            returnedSince = diedDuringCombat ? -1 : presentSinceTick;
        }
        if (!present && !combatAbsence) { returnedSince = -1; }
        if (returnedSince >= 0 && tick - returnedSince >= 10)
        {
            if (tick - returnedSince == 10 && alive && !diedDuringCombat)
            {
                fact = "BACK_AFTER_PLAYER_COMBAT";
            }
            returnedSince = -1;
        }
        if (wildernessSampleAllowed)
        {
            String wildernessFact = sampleWilderness(wildernessInside);
            if (fact == null) { fact = wildernessFact; }
        }
        return fact == null || !eligible ? null
            : offerFact(fact, tick, sessionGeneration, sceneRevision, currentHp, realHp, 0);
    }

    private String sampleWilderness(boolean current)
    {
        if (!insideKnown)
        {
            insideKnown = true; inside = current; sameInsideTicks = 1; diedInside = false;
            return null;
        }
        if (inside == current)
        {
            sameInsideTicks = Math.min(200, sameInsideTicks + 1);
            return null;
        }
        String fact = current && sameInsideTicks >= 50 ? "WILDERNESS_ENTERED"
            : !current && sameInsideTicks >= 200 && !diedInside ? "WILDERNESS_LEFT" : null;
        inside = current; sameInsideTicks = 1; diedInside = false;
        return fact;
    }

    public void onPlayerCombatAbsence()
    {
        if (!playerCombatAbsent) { diedDuringCombat = false; }
        playerCombatAbsent = true; returnedSince = -1;
    }

    public void onLocalDeath()
    {
        if (insideKnown && inside) { diedInside = true; }
        if (playerCombatAbsent || returnedSince >= 0) { diedDuringCombat = true; returnedSince = -1; }
    }

    /** G.4 calls this only when a real native cycle first enters the impatient loop. */
    public SceneCandidate offerWaiting(long tick, long sessionGeneration, long sceneRevision, int timesLately,
        boolean eligible)
    {
        if (generation != sessionGeneration) { resetSession(); generation = sessionGeneration; }
        return eligible ? offerFact("KEPT_WAITING", tick, sessionGeneration, sceneRevision, 1, 1, timesLately) : null;
    }

    /**
     * H.7: she has stopped short because he stands by a creature she fears. The fact exists from the fourth tick in a
     * row of that. Unlike a crossing it is still true a moment later, so it waits for its turn: it is offered once, on
     * the first of those ticks on which a line may be offered, and not again until she has stopped being kept back.
     */
    public SceneCandidate observeKeptBack(long tick, long sessionGeneration, long sceneRevision, boolean keptBack,
        boolean eligible)
    {
        if (generation != sessionGeneration) { resetSession(); generation = sessionGeneration; }
        if (!keptBack) { keptBackTicks = 0; keptBackOffered = false; return null; }
        if (keptBackTicks < 4) { keptBackTicks++; }
        if (keptBackTicks < 4 || keptBackOffered || !eligible) { return null; }
        keptBackOffered = true;
        return offerFact("KEPT_BACK_BY_BEAST", tick, sessionGeneration, sceneRevision, 1, 1, 0);
    }

    private SceneCandidate offerFact(String fact, long tick, long sessionGeneration, long sceneRevision,
        int currentHp, int realHp, int timesLately)
    {
        for (LivingWorldData.Moment moment : data.moments)
        {
            if (!fact.equals(moment.fact) || !moment.matchesHp(currentHp, realHp)
                || !moment.matchesTimesLately(timesLately)) { continue; }
            Long painted = lastPaint.get(moment.logicalKey);
            int spacing = "BACK_AFTER_PLAYER_COMBAT".equals(fact) ? 300
                : "KEPT_WAITING".equals(fact) ? 0 : "KEPT_BACK_BY_BEAST".equals(fact) ? 500 : 1500;
            if (painted != null && tick - painted < spacing) { return null; }
            int chance = "WILDERNESS_LEFT".equals(fact) ? 40
                : "BACK_AFTER_PLAYER_COMBAT".equals(fact) || "KEPT_BACK_BY_BEAST".equals(fact) ? 60 : 50;
            if (random.nextInt(100) >= chance) { return null; }
            Map<String, String> facts = new HashMap<>();
            facts.put("livingWorld", "MOMENT"); facts.put("momentEntry", moment.id);
            facts.put("momentFact", fact);
            issuedId = candidateIds.getAsLong();
            return new SceneCandidate(issuedId, moment.id, -100, tick, tick + 1, sessionGeneration, sceneRevision,
                "world-moment:" + fact + ":" + tick, facts, false, 0);
        }
        return null;
    }

    public boolean matches(SceneCandidate candidate, long tick)
    {
        LivingWorldData.Group group = data.group(candidate.getScenarioId());
        return group instanceof LivingWorldData.Moment && candidate.getId() == issuedId
            && candidate.getCreatedTick() == tick && candidate.getSessionGeneration() == generation
            && ((LivingWorldData.Moment) group).fact.equals(candidate.getConditionFacts().get("momentFact"))
            && group.id.equals(candidate.getConditionFacts().get("momentEntry"));
    }

    public void onPaint(SpeechPacket.PaintReceipt receipt)
    {
        if (receipt == null || receipt.getCandidate().getSessionGeneration() != generation
            || !"MOMENT".equals(receipt.getCandidate().getConditionFacts().get("livingWorld"))) { return; }
        LivingWorldData.Group group = data.group(receipt.getCandidate().getScenarioId());
        if (!(group instanceof LivingWorldData.Moment)) { return; }
        for (LivingWorldData.Line line : group.lines)
        {
            if (line.id.equals(receipt.getLineId()))
            {
                String key = ((LivingWorldData.Moment) group).logicalKey;
                lastPaint.put(key, Math.max(lastPaint.getOrDefault(key, Long.MIN_VALUE), receipt.getPaintedAtTick()));
                return;
            }
        }
    }

    public void resetSession()
    {
        generation = previousTick = Long.MIN_VALUE; issuedId = -1; lastPaint.clear();
        insideKnown = inside = diedInside = playerCombatAbsent = diedDuringCombat = false;
        keptBackTicks = 0; keptBackOffered = false;
        sameInsideTicks = 0; returnedSince = -1;
    }
}

package com.malfoid.world;

import com.malfoid.speech.SceneCandidate;
import com.malfoid.speech.SpeechPacket;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Random;
import java.util.function.LongSupplier;

/** Session-only place arrivals from copied committed observations. Retains no client objects. */
public final class LivingWorldPlaces
{
    private final LivingWorldData data;
    private final Random random;
    private final LongSupplier candidateIds;
    private final Map<String, Long> arrivalTicks = new HashMap<>();
    private boolean sessionKnown, baselineEstablished, placePainted;
    private long sessionGeneration, sceneRevision, lastCommittedTick = -1, lastPlacePaintTick;
    private String pendingEntry, previousArrival;
    private int consecutiveTicks;

    public LivingWorldPlaces(LivingWorldData data, Random random, LongSupplier candidateIds)
    {
        this.data = Objects.requireNonNull(data);
        this.random = Objects.requireNonNull(random);
        this.candidateIds = Objects.requireNonNull(candidateIds);
    }

    /**
     * Eligibility includes PRESENT age, combat, UI, pending reactions and the shared living-world cap.
     * An ineligible arrival is still consumed; it is never saved for later speech.
     */
    public SceneCandidate observe(long tick, long generation, long revision, int regionId,
        boolean committed, boolean present, boolean eligible)
    {
        if (!sessionKnown || generation != sessionGeneration)
        {
            resetSession();
            sessionKnown = true;
            sessionGeneration = generation;
            sceneRevision = revision;
        }
        else if (revision != sceneRevision)
        {
            resetObservation();
            sceneRevision = revision;
        }
        if (!committed || !present)
        {
            resetObservation();
            return null;
        }
        if (lastCommittedTick != -1 && tick != lastCommittedTick + 1)
        {
            resetObservation();
        }
        lastCommittedTick = tick;
        LivingWorldData.PlaceGroup group = data.place(regionId);
        if (group == null)
        {
            pendingEntry = null;
            consecutiveTicks = 0;
            return null;
        }
        if (!group.id.equals(pendingEntry))
        {
            pendingEntry = group.id;
            consecutiveTicks = 1;
        }
        else if (consecutiveTicks < 5)
        {
            consecutiveTicks++;
        }
        if (consecutiveTicks != 5 || group.id.equals(previousArrival))
        {
            return null;
        }

        Long previousTick = arrivalTicks.put(group.id, tick);
        previousArrival = group.id;
        if (!baselineEstablished)
        {
            baselineEstablished = true;
            return null;
        }
        if (!eligible || previousTick != null && tick - previousTick < 1500
            || placePainted && tick - lastPlacePaintTick < 300 || random.nextDouble() >= 0.6)
        {
            return null;
        }
        Map<String, String> facts = new HashMap<>();
        facts.put("livingWorld", "PLACE");
        facts.put("placeEntry", group.id);
        return new SceneCandidate(candidateIds.getAsLong(), group.id, -100, tick, tick + 1,
            generation, revision, "PLACE_ARRIVAL:" + group.id + ":" + tick, facts, false, 0);
    }

    /** Scene/absence invalidation clears only unfinished evidence, never arrival or paint memory. */
    public void resetObservation()
    {
        pendingEntry = null;
        consecutiveTicks = 0;
        lastCommittedTick = -1;
    }

    public void resetSession()
    {
        resetObservation();
        arrivalTicks.clear();
        previousArrival = null;
        baselineEstablished = false;
        placePainted = false;
        sessionKnown = false;
    }

    public void onPaint(SpeechPacket.PaintReceipt receipt)
    {
        if (receipt == null || !sessionKnown) { return; }
        SceneCandidate candidate = receipt.getCandidate();
        if (candidate.getSessionGeneration() != sessionGeneration
            || !"PLACE".equals(candidate.getConditionFacts().get("livingWorld"))
            || !candidate.getScenarioId().equals(candidate.getConditionFacts().get("placeEntry"))) { return; }
        firstPaint(candidate.getScenarioId(), receipt.getLineId(), receipt.getPaintedAtTick());
    }

    /** Called only for an actual first paint; merely offering or admitting a line starts no cooldown. */
    public void firstPaint(String groupId, String lineId, long tick)
    {
        LivingWorldData.Group group = data.group(groupId);
        if (!(group instanceof LivingWorldData.PlaceGroup) || placePainted && tick < lastPlacePaintTick) { return; }
        for (LivingWorldData.Line line : group.lines)
        {
            if (line.id.equals(lineId))
            {
                placePainted = true;
                lastPlacePaintTick = tick;
                return;
            }
        }
    }
}

package com.malfoid.world;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Random;

/** G.4's committed stationary count and bounded history of actual native impatient loops. */
public final class LivingWorldWaiting
{
    public static final int MAX_RECENT_EMOTES = 8;
    private final Random random;
    private final Deque<Long> loops = new ArrayDeque<>(MAX_RECENT_EMOTES);
    private long generation = Long.MIN_VALUE, revision = Long.MIN_VALUE, previousTick = Long.MIN_VALUE;
    private long lastEnd = Long.MIN_VALUE, requestedAt = -1;
    private int x, y, plane, stillTicks;
    private boolean havePoint, active, loopStarted;

    public LivingWorldWaiting(Random random) { this.random = random; }

    /** Zero means no request. A fact is consumed even if its one chance draw is silent. */
    public int observe(long tick, long sessionGeneration, long sceneRevision, boolean known,
        int playerX, int playerY, int playerPlane, boolean eligible)
    {
        if (generation != sessionGeneration) { resetSession(); generation = sessionGeneration; }
        if (tick == previousTick) { return 0; }
        if (revision != sceneRevision || previousTick != Long.MIN_VALUE && tick != previousTick + 1)
        {
            havePoint = false; stillTicks = 0;
        }
        revision = sceneRevision; previousTick = tick;
        if (!known) { havePoint = false; stillTicks = 0; return 0; }
        if (havePoint && x == playerX && y == playerY && plane == playerPlane) { stillTicks = Math.min(150, stillTicks + 1); }
        else { stillTicks = 1; }
        havePoint = true; x = playerX; y = playerY; plane = playerPlane;
        if (stillTicks < 150 || !eligible || active || lastEnd != Long.MIN_VALUE && tick - lastEnd < 400) { return 0; }
        stillTicks = 0;
        if (random.nextInt(100) >= 50) { return 0; }
        active = true; loopStarted = false; requestedAt = tick;
        return 8 + random.nextInt(9);
    }

    public boolean isActive() { return active; }
    public void requestRejected() { active = loopStarted = false; requestedAt = -1; }
    public boolean playerStillOnTile(int playerX, int playerY, int playerPlane)
    { return havePoint && x == playerX && y == playerY && plane == playerPlane; }

    public int onLoopStarted(long tick)
    {
        if (!active || loopStarted || tick < requestedAt) { return 0; }
        loopStarted = true;
        while (!loops.isEmpty() && tick - loops.peekFirst() >= 3000) { loops.removeFirst(); }
        // The 400-tick end spacing permits at most eight loop starts in this window.
        if (loops.size() < MAX_RECENT_EMOTES) { loops.addLast(tick); }
        return loops.size();
    }

    public void onEmoteEnded(long tick)
    {
        if (!active || tick < requestedAt) { return; }
        lastEnd = Math.max(lastEnd, tick); active = loopStarted = false; requestedAt = -1;
    }

    public int getRecentEmoteCount() { return loops.size(); }
    public long getLastEndTick() { return lastEnd; }

    public void resetSession()
    {
        generation = revision = previousTick = lastEnd = Long.MIN_VALUE;
        requestedAt = -1; havePoint = active = loopStarted = false; stillTicks = 0; loops.clear();
    }
}

package com.malfoid.world;

import java.util.HashSet;
import java.util.Set;

/** Physical scenery visits survive scene reloads and presence changes, but never a session reset. */
public final class SceneryVisits
{
    public static final int MAX_VISITS = 512;
    private final Set<String> objects = new HashSet<>();
    private final Set<String> kinds = new HashSet<>();

    public boolean canVisit(String objectKey) { return objectKey != null && objects.size() < MAX_VISITS && !objects.contains(objectKey); }
    public boolean unseenKind(String kind) { return !kinds.contains(kind); }
    public int objectCount() { return objects.size(); }
    public int kindCount() { return kinds.size(); }

    /** Duplicate arrival callbacks confirm the existing mark; capacity never evicts an earlier visit. */
    public boolean arrived(String objectKey, String kind)
    {
        if (objectKey == null) { return false; }
        if (objects.contains(objectKey)) { return true; }
        if (objects.size() >= MAX_VISITS) { return false; }
        objects.add(objectKey);
        kinds.add(kind);
        return true;
    }

    public void resetSession() { objects.clear(); kinds.clear(); }
}

package com.malfoid.world;

import com.malfoid.speech.SceneCandidate;
import com.malfoid.speech.SpeechPacket;
import java.util.Random;

/** G.3 observes genuine first paints and the authored silent fourth-answer arrival. */
public final class SpeechPostureTriggers
{
    private final Random random;
    private long lastPaintToken = -1, lastTalkAccepted = -1, talkUntil = -1, holdUntil = -1;
    private long heldCandidate = -1;
    private boolean talkFolded;
    private SpeechPacket readablePacket;
    private String gesture;
    private long gestureUntil = -1;

    /** H.6: an emote of her own asked for by a line that has just been painted. */
    public static final class GestureRequest
    {
        public final String name;
        public final long untilTick;
        GestureRequest(String name, long untilTick) { this.name = name; this.untilTick = untilTick; }
    }

    public SpeechPostureTriggers(Random random) { this.random = random; }

    public void onTalkAccepted(long tick)
    {
        if (lastTalkAccepted >= 0 && tick - lastTalkAccepted >= 50) { talkFolded = false; }
        lastTalkAccepted = tick;
        if (talkFolded) { talkUntil = tick + 50; }
    }

    public void onFourthAnswerArrival(SceneCandidate candidate, long tick, boolean allowed)
    {
        if (allowed && "U01".equals(candidate.getScenarioId())
            && "4".equals(candidate.getConditionFacts().get("talkStreak")))
        {
            talkFolded = true; talkUntil = (lastTalkAccepted >= 0 ? lastTalkAccepted : tick) + 50;
        }
    }

    public void onPaint(SpeechPacket.PaintReceipt receipt, SpeechPacket packet, int holdTicks,
        boolean allowed, boolean sceneWalks)
    {
        onPaint(receipt, packet, holdTicks, allowed, sceneWalks, false);
    }

    /** `gestures`: her model has the emotes of her own (H.6). Without them every draw is as it was under Addendum G. */
    public void onPaint(SpeechPacket.PaintReceipt receipt, SpeechPacket packet, int holdTicks,
        boolean allowed, boolean sceneWalks, boolean gestures)
    {
        if (receipt == null || packet == null || receipt != packet.getFirstPaint()
            || receipt.getAdmissionToken() == lastPaintToken) { return; }
        lastPaintToken = receipt.getAdmissionToken();
        String scenario = receipt.getCandidate().getScenarioId();
        if (!allowed || "M01".equals(scenario) || "M02".equals(scenario)) { return; }
        long tick = receipt.getPaintedAtTick();
        if ("M09".equals(scenario) && ("Hmph.".equals(packet.getText()) || "...Hmph.".equals(packet.getText())))
        {
            heldCandidate = receipt.getCandidate().getId(); holdUntil = tick + holdTicks; readablePacket = null;
        }
        else if ("U01".equals(scenario) && "3".equals(receipt.getCandidate().getConditionFacts().get("talkStreak")))
        {
            talkFolded = true; talkUntil = (lastTalkAccepted >= 0 ? lastTalkAccepted : tick) + 50;
        }
        else if ("U01-G28".equals(receipt.getLineId()))
        {
            heldCandidate = receipt.getCandidate().getId(); holdUntil = tick + 4; readablePacket = null;
        }
        else if (!sceneWalks && "INDIGNANT".equals(packet.getEmotion()))
        {
            // One draw, as before: a quarter fold her arms (G.3). With the emotes of her own, a fifth more put her
            // hands on her hips for as long as the line holds, and an exclamation may be stamped.
            int draw = random.nextInt(100);
            if (draw < 25) { readablePacket = packet; heldCandidate = -1; holdUntil = -1; }
            else if (gestures && draw < 45) { gesture = "HANDS_ON_HIPS"; gestureUntil = tick + Math.max(4, holdTicks); }
            else if (gestures && draw < 60 && packet.getText() != null && packet.getText().endsWith("!"))
            {
                gesture = "STOMP"; gestureUntil = tick;
            }
        }
        else if (gestures && !sceneWalks && "TEASING".equals(packet.getEmotion()) && random.nextInt(100) < 22)
        {
            gesture = "HAIR_FLICK"; gestureUntil = tick;
        }
        else if (gestures && !sceneWalks && "CURIOUS".equals(packet.getEmotion()) && random.nextInt(100) < 25)
        {
            gesture = "PEER"; gestureUntil = tick + Math.max(4, holdTicks);
        }
    }

    /** The emote the last painted line asked for, once. */
    public GestureRequest consumeGesture()
    {
        if (gesture == null) { return null; }
        GestureRequest request = new GestureRequest(gesture, gestureUntil);
        gesture = null; gestureUntil = -1;
        return request;
    }

    public boolean shouldFold(long tick, long now, SceneCandidate active, boolean allowed)
    {
        if (!allowed || active != null && ("M01".equals(active.getScenarioId()) || "M02".equals(active.getScenarioId())))
        {
            clearPosture(); return false;
        }
        if (talkFolded && tick >= talkUntil) { talkFolded = false; }
        if (readablePacket != null && (!readablePacket.isPainted() || !readablePacket.canPaint(now)))
        {
            readablePacket = null;
        }
        return talkFolded || active != null && active.getId() == heldCandidate && tick < holdUntil
            || readablePacket != null && active != null && readablePacket.getCandidate().getId() == active.getId();
    }

    private void clearPosture()
    {
        gesture = null; gestureUntil = -1;
        talkFolded = false; talkUntil = holdUntil = -1; heldCandidate = -1; readablePacket = null;
    }

    public void resetSession()
    {
        clearPosture(); lastPaintToken = lastTalkAccepted = -1;
    }
}

