            assertEquals(duration, f.actor.getImpatientDurationTicks());
            assertEquals(-1, f.actor.consumeImpatientLoopStartTick());
            int loop = 73, end = loop + (duration * 30 + 39) / 40 * 40;
            long tick = 3;
