        DialogueLine line = catalogue.getLine("F03-01");
        assertTrue(line.isEnabled());
        assertEquals("Where are you taking me, Potter?!", line.getText());
        assertTrue(line.getConditions().isEmpty());
        Map<String, String> facts = new HashMap<>();
        facts.put("runWindowStartTick", "1");
        facts.put("runWindowTiles", "60");
        facts.put("runWorldViewId", "-1");
        facts.put("witnessPresenceEpoch", "1");
        SceneCandidate candidate = new SceneCandidate(1, "F03", 30, 50, 62, 1, 1,
            "run:1", facts, false, 4);
        assertTrue(line.matches(facts));
        assertTrue(catalogue.hasValidOriginalContext(candidate));
        assertNull(catalogue.situationFingerprint(candidate));
        JsonObject binding = runtime().getAsJsonObject("situationSpeechPolicy")
            .getAsJsonObject("byLogicalKey").getAsJsonObject("F03");
        assertEquals("MOMENT", binding.get("repeatClass").getAsString());
        assertEquals("NOT_APPLICABLE", binding.getAsJsonObject("subjectBinding").get("type").getAsString());
    }

    @Test
    public void producerRunFactsCannotBecomeCatalogueTextConditions() throws Exception
    {
        for (String fact : new String[] {"runWindowStartTick", "runWindowTiles", "runWorldViewId", "witnessPresenceEpoch"})
        {
            JsonObject runtime = runtime();
            entry(runtime, "F03-01").getAsJsonObject("conditions").addProperty(fact, "1");
            assertRejected(runtime);
        }
    }

    private byte[] resourceBytes(String path) throws IOException
    {
        try (InputStream input = getClass().getResourceAsStream(path))
        {
            assertNotNull(input);
            return input.readAllBytes();
        }
    }

    private static String sha256(byte[] bytes) throws Exception
    {
        StringBuilder hex = new StringBuilder();
        for (byte value : MessageDigest.getInstance("SHA-256").digest(bytes))
        {
            hex.append(String.format("%02x", value & 255));
        }
        return hex.toString();
    }

    private static String[] forbiddenWords()
    {
        return new String[] {"ensemble", "attire", "headpiece", "garment", "wardrobe", "overhaul", "triumphant"};
    }

    private JsonObject runtime() throws IOException { return readJson("/com/malfoid/dialogue.json"); }

    private JsonObject readJson(String path) throws IOException
    {
        try (InputStream input = getClass().getResourceAsStream(path))
        {
            assertNotNull(input);
            return new JsonParser().parse(new InputStreamReader(input, StandardCharsets.UTF_8)).getAsJsonObject();
        }
    }

    private static JsonObject entry(JsonObject runtime, String id)
    {
        for (JsonElement element : runtime.getAsJsonArray("entries"))
        {
            JsonObject line = element.getAsJsonObject();
            if (id.equals(line.get("id").getAsString())) { return line; }
        }
        throw new AssertionError("Missing line " + id);
    }

    private static void assertRejected(JsonObject runtime) throws Exception
    {
        try
        {
            DialogueCatalog.read(new ByteArrayInputStream(runtime.toString().getBytes(StandardCharsets.UTF_8)));
            fail("Invalid dialogue loaded");
        }
        catch (IOException expected) { }
    }
}

package com.malfoid.interaction;

import java.awt.Rectangle;
import org.junit.Test;

import static org.junit.Assert.*;

public class MenuPolicyTest
{
	private final Rectangle viewport = new Rectangle(30, 60, 500, 400);
	private final Rectangle clickbox = new Rectangle(80, 100, 30, 70);

	@Test
	public void menuNeedsPresentPlacementSceneWalkAndExactClickboxHit()
	{
		assertTrue(MenuPolicy.mayOpen(true, true, true, false, 90, 110, viewport, clickbox));
		assertFalse(MenuPolicy.mayOpen(false, true, true, false, 90, 110, viewport, clickbox));
		assertFalse(MenuPolicy.mayOpen(true, false, true, false, 90, 110, viewport, clickbox));
		assertFalse(MenuPolicy.mayOpen(true, true, false, false, 90, 110, viewport, clickbox));
		assertFalse(MenuPolicy.mayOpen(true, true, true, true, 90, 110, viewport, clickbox));
		assertFalse(MenuPolicy.mayOpen(true, true, true, false, 79, 110, viewport, clickbox));
		assertFalse(MenuPolicy.mayOpen(true, true, true, false, 90, 110, viewport, null));
	}

	@Test
	public void viewportOffsetsAreAppliedIndependently()
	{
		Rectangle overhang = new Rectangle(0, 0, 100, 100);
		assertFalse(MenuPolicy.mayOpen(true, true, true, false, 40, 50, viewport, overhang));
		assertTrue(MenuPolicy.mayOpen(true, true, true, false, 40, 70, viewport, overhang));
	}

	@Test
	public void animationAndWalkingDoNotInvalidateAnOpenedMenuButPlacementOrLifecycleDoes()
	{
		MenuPolicy.Lease opened = new MenuPolicy.Lease(3, 7, 5, 19);
		for (int poseRevision = 0; poseRevision < 100; poseRevision++)
		{
			assertTrue(opened.isCurrent(3, 7, 5, 19, true));
		}
		assertFalse(opened.isCurrent(4, 7, 5, 19, true));
		assertFalse(opened.isCurrent(3, 8, 5, 19, true));
		assertFalse(opened.isCurrent(3, 7, 6, 19, true));
		assertFalse(opened.isCurrent(3, 7, 5, 20, true));
		assertFalse(opened.isCurrent(3, 7, 5, 19, false));
	}
}

package com.malfoid.interaction;

import org.junit.Test;

import static org.junit.Assert.*;

public class NoticeLedgerTest
{
	@Test
	public void repeatedRequestsQueueEachSessionNoticeOnce()
	{
		NoticeLedger ledger = new NoticeLedger("fixture");
		for (int duplicate = 0; duplicate < 100; duplicate++)
		{
			for (NoticeLedger.Notice notice : NoticeLedger.Notice.values())
			{
				ledger.request(notice);
			}
		}
		int deliveries = 0;
		while (ledger.next(true, false, true) != null) { deliveries++; }
		assertEquals(5, deliveries);
		ledger.resetSession();
		ledger.request(NoticeLedger.Notice.N02);
		assertNotNull(ledger.next(true, false, true));
	}

	@Test
	public void tutorialSuppressionRetainsOnePendingIntro()
	{
		NoticeLedger ledger = new NoticeLedger("fixture");
		ledger.request(NoticeLedger.Notice.N01);
		for (int cycle = 0; cycle < 100; cycle++)
		{
			assertNull(ledger.next(false, false, true));
		}
		NoticeLedger.Delivery intro = ledger.next(true, false, true);
		assertNotNull(intro);
		assertNull(ledger.next(true, false, true));
		assertFalse(ledger.acknowledgeIntro("unrelated", intro.getNotice().getText()));
		assertTrue(ledger.acknowledgeIntro(intro.getSender(), intro.getNotice().getText()));
		assertFalse(ledger.acknowledgeIntro(intro.getSender(), intro.getNotice().getText()));
	}

	@Test
	public void suppressionAfterQueueDefersAndRevokesTheOldReceipt()
	{
		NoticeLedger ledger = new NoticeLedger("fixture");
		ledger.request(NoticeLedger.Notice.N01);
		NoticeLedger.Delivery old = ledger.next(true, false, true);
		ledger.deferTutorialIntro();
		assertFalse(ledger.acknowledgeIntro(old.getSender(), old.getNotice().getText()));
		NoticeLedger.Delivery retry = ledger.next(true, false, true);
		assertNotEquals(old.getSender(), retry.getSender());
		assertTrue(ledger.acknowledgeIntro(retry.getSender(), retry.getNotice().getText()));
	}

	@Test
