package com.malfoid.motion;

import com.malfoid.motion.CreatureAwareness.Behaviour;
import com.malfoid.motion.CreatureAwareness.Classification;
import com.malfoid.motion.CreatureAwareness.Creature;
import com.malfoid.motion.CreatureAwareness.Sample;
import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.*;

public class CreatureAwarenessTest
{
    @Test public void namesUseExactlyTheAuthoredTagStrippedPredicates()
    {
        for (String name : new String[]{"Rat", "<col=00ff00>Giant rat</col>", "Scurrius-rat"})
            assertEquals("F01", CreatureAwareness.classifyFear(CreatureAwareness.normalizeName(name), 0).groupId);
        for (String name : new String[]{"wolf", "werewolf", "white wolf", "bear", "grizzly bear", "hellhound", "giant spider", "spider",
            "scorpion", "king scorpion", "snake", "swamp snake", "crocodile", "desert crocodile", "bat", "giant bat",
            "jackal", "guard dog", "wild dog", "terror dog", "shadow hound", "jaguar", "spined larupia", "horned graahk",
            "sabre-toothed kyatt"})
            assertEquals(name, "F02", CreatureAwareness.classifyFear(name, 1).groupId);
        for (String name : new String[]{"ratcatcher", "brat", "rats", "wolf cub", "bear cub", "spiders", "hellhounds",
            "scorpions", "snakes", "crocodiles", "bats", "batman", "snake charmer", "bat (pet)", "jaguar warrior", "stray dog", "dog"})
            assertNull(name, CreatureAwareness.classifyFear(name, 30));
    }

    @Test public void nearSixIsInclusiveAndNearestRatOrBeastWinsDespiteTablePriority()
    {
        CreatureAwareness a = new CreatureAwareness();
        Creature wolf = creature("wolf", "wolf", 0, 1), rat = creature("rat", "rat", 6, 0);
        a.commit(sample(1, true, wolf, rat), 0, 0);
        assertEquals("F02", a.getGroupId()); assertEquals("wolf", a.getTarget().key); assertEquals(1, a.getBeginTick());
        assertEquals(Behaviour.AFRAID, a.getTarget().classification.behaviour);
        a.commit(sample(2, true, creature("wolf", "wolf", 5, 0), creature("rat", "rat", 1, 0)), 0, 0);
        assertEquals("F01", a.getGroupId()); assertEquals(1, a.getBeginTick());
        assertEquals("The original nearest creature selects the one speech key", "F02", a.getBeginCreature().classification.groupId);
        Creature outside = creature("far", "rat", 7, 0);
        CreatureAwareness b = new CreatureAwareness(); b.commit(sample(1, true, outside), 0, 0); assertNull(b.getGroupId());
    }

    @Test public void changingFearKindOrReturningBeforeFiveKnownCalmTicksKeepsTheEpisode()
    {
        CreatureAwareness a = new CreatureAwareness(); a.commit(sample(1, true, creature("rat", "rat", 2, 0)), 0, 0);
        for (int tick = 2; tick <= 5; tick++) { a.commit(sample(tick, true), 0, 0); }
        a.commit(sample(6, true, creature("bear", "bear", 6, 0)), 0, 0);
        assertEquals("F02", a.getGroupId()); assertEquals(1, a.getBeginTick()); assertEquals("rat", a.getBeginCreature().key);
        a.commit(sample(7, true, creature("bear", "bear", 8, 0)), 0, 0); assertEquals(0, a.getQuietTicks());
        for (int tick = 8; tick <= 12; tick++) { a.commit(sample(tick, true), 0, 0); }
        assertFalse(a.isKeepingAway());
        a.commit(sample(13, true, creature("bear", "bear", 1, 0)), 0, 0);
        assertEquals(13, a.getBeginTick()); assertEquals("F02", a.getBeginCreature().classification.groupId);
    }

    @Test public void eightTileRetentionAndFiveKnownQuietTicksSuppressLowerGroups()
    {
        CreatureAwareness a = new CreatureAwareness(); a.commit(sample(1, true, creature("rat", "rat", 6, 0)), 0, 0);
        a.commit(sample(2, true, creature("rat", "rat", 8, 0)), 0, 0); assertTrue(a.isKeepingAway());
        Creature cat = new Creature("cat", new Classification("CR-FOND", 5, Behaviour.FOND, 0, 0), "cat", 0, 1, 0, 0);
        for (int tick = 3; tick <= 6; tick++) { a.commit(sample(tick, true, cat), 0, 0); assertTrue(a.isKeepingAway()); }
        a.commit(sample(7, true, cat), 0, 0); assertFalse(a.isKeepingAway()); assertTrue(a.didEndKeepingAway());
        assertEquals("CR-FOND", a.getGroupId());
    }

    @Test public void unknownAndMissingCommitNeverProveTheEnding()
    {
        CreatureAwareness a = new CreatureAwareness(); a.commit(sample(1, true, creature("rat", "rat", 2, 0)), 0, 0);
        a.commit(sample(2, true), 0, 0); a.commit(sample(3, true), 0, 0); a.commit(sample(4, false), 0, 0);
        assertTrue(a.isKeepingAway()); assertEquals(0, a.getQuietTicks());
        a.commit(sample(7, true), 0, 0); assertTrue(a.isKeepingAway()); assertEquals(1, a.getQuietTicks());
        for (int tick = 8; tick <= 10; tick++) { a.commit(sample(tick, true), 0, 0); assertTrue(a.isKeepingAway()); }
        a.commit(sample(11, true), 0, 0); assertFalse(a.isKeepingAway()); assertTrue(a.didEndKeepingAway());
    }

    @Test public void dragonBandAndHigherPriorityRatUseTheSameState()
    {
        Classification dragon = new Classification("CR-DRAGON", 1, Behaviour.AFRAID, 2, 3);
        CreatureAwareness a = new CreatureAwareness();
        a.commit(sample(1, true, new Creature("dragon", dragon, "green dragon", 79, 4, 0, 0)), 0, 0);
        assertEquals(2, a.getTarget().classification.minPlayerDistance); assertEquals(3, a.getTarget().classification.maxPlayerDistance);
        a.commit(sample(2, true, creature("rat", "rat", 5, 0)), 0, 0);
        assertEquals("F01", a.getGroupId()); assertEquals(2, a.getBeginTick());
        a.commit(sample(3, true, creature("other-rat", "rat", 1, 0)), 0, 0);
        assertEquals("Changing nearest rat does not begin a new kind", 2, a.getBeginTick());
    }

    private static Creature creature(String key, String name, int x, int y)
    { return new Creature(key, CreatureAwareness.classifyFear(name, 30), name, 30, x, y, 0); }
    private static Sample sample(long tick, boolean known, Creature... creatures)
    { return new Sample(tick, 0, 0, 0, 0, known, Arrays.asList(creatures)); }
}

package com.malfoid.motion;

import org.junit.Test;
import static org.junit.Assert.*;

public class FollowCollisionTest
{
    @Test public void aStepInsideTwoTilesMayOnlyKeepOrIncreaseSeparation()
    {
        assertTrue(FollowCollision.allowsStep(3, 6, 4, 6, 6, 6));
        assertFalse(FollowCollision.allowsStep(4, 6, 5, 6, 6, 6));
        assertFalse(FollowCollision.allowsStep(5, 6, 6, 6, 6, 6));
        assertTrue(FollowCollision.allowsStep(5, 6, 4, 6, 6, 6));
        assertTrue(FollowCollision.allowsStep(4, 6, 4, 5, 6, 6));
    }

    @Test public void theSingleSearchCannotTakeAnInnerRingShortcutToALegalOuterGoal()
    {
        RoutePlanner.Collision open = new RoutePlanner.Collision()
        {
            @Override public boolean isLegal(int x, int y) { return x >= 0 && y >= 0 && x <= 12 && y <= 12 && (x != 6 || y != 6); }
            @Override public boolean canTravel(int x, int y, int dx, int dy) { return isLegal(x + dx, y + dy); }
        };
        RoutePlanner.Goal goal = new RoutePlanner.Goal()
        {
            @Override public double score(int x, int y, int steps) { return x == 8 && y == 6 ? 1 : -1; }
            @Override public int distance(int x, int y) { return MotionMath.distance(x, y, 8, 6); }
        };
        RoutePlanner.Node previous = new RoutePlanner.Node(4, 6);
        RoutePlanner.Result route = new RoutePlanner().plan(new FollowCollision(open, 6, 6), previous, goal);
        assertEquals(RoutePlanner.Status.ROUTE, route.status);
        assertTrue(route.steps.size() > 4);
        assertTrue(route.visited <= 625);
        for (RoutePlanner.Node next : route.steps)
        {
            assertTrue(FollowCollision.allowsStep(previous.x, previous.y, next.x, next.y, 6, 6));
            assertTrue(MotionMath.distance(next.x, next.y, 6, 6) >= 2);
            previous = next;
        }
        assertEquals(new RoutePlanner.Node(8, 6), previous);
    }
}

package com.malfoid.motion;

import org.junit.Test;
import static org.junit.Assert.*;

public class InspectionRoutesTest
{
    private static final RoutePlanner.Collision OPEN = new RoutePlanner.Collision()
    {
        public boolean isLegal(int x, int y) { return true; }
        public boolean canTravel(int x, int y, int dx, int dy) { return true; }
    };

    @Test public void exactlyEightLegalEdgesProvesTheNeighborButNineDoesNot()
    {
        RoutePlanner planner = new RoutePlanner();
        RoutePlanner.Result eight = planner.plan(OPEN, new RoutePlanner.Node(0, 0),
            InspectionRoutes.besideFootprint(9, 0, 9, 0, 0, 0));
        assertEquals(RoutePlanner.Status.ROUTE, eight.status);
        assertEquals(8, eight.steps.size());
        RoutePlanner.Node stand = eight.steps.get(7);
        assertEquals(1, MotionMath.footprintDistance(stand.x, stand.y, 9, 0, 9, 0));
        RoutePlanner.Result nine = planner.plan(OPEN, new RoutePlanner.Node(0, 0),
            InspectionRoutes.besideFootprint(10, 0, 10, 0, 0, 0));
        assertNotEquals(RoutePlanner.Status.ROUTE, nine.status);
        assertNotEquals(RoutePlanner.Status.AT_GOAL, nine.status);
    }

    @Test public void aNearbyObjectBehindALongWallHasNoGeometricProof()
    {
        RoutePlanner.Collision wall = new RoutePlanner.Collision()
        {
            public boolean isLegal(int x, int y) { return x != 1 || y >= 7; }
            public boolean canTravel(int x, int y, int dx, int dy)
            {
                return isLegal(x + dx, y + dy) && (dx == 0 || dy == 0
                    || isLegal(x + dx, y) && isLegal(x, y + dy));
            }
        };
        RoutePlanner.Result result = new RoutePlanner().plan(wall, new RoutePlanner.Node(0, 0),
            InspectionRoutes.besideFootprint(3, 0, 3, 0, 0, 0));
        assertNotEquals(RoutePlanner.Status.ROUTE, result.status);
        assertNotEquals(RoutePlanner.Status.AT_GOAL, result.status);
        assertTrue(result.visited <= 625);
    }

    @Test public void alreadyBesideFootprintAllowsZeroStepsButPlayerAndInteriorAreExcluded()
    {
        RoutePlanner.Goal goal = InspectionRoutes.besideFootprint(1, 1, 3, 3, 0, 1);
        assertTrue(goal.score(0, 2, 0) >= 0);
        assertEquals(-1, goal.score(0, 1, 0), 0);
        assertEquals(-1, goal.score(2, 2, 0), 0);
        RoutePlanner.Result result = new RoutePlanner().plan(OPEN, new RoutePlanner.Node(0, 2), goal);
        assertEquals(RoutePlanner.Status.AT_GOAL, result.status);
        assertTrue(result.steps.isEmpty());
    }
}

package com.malfoid.motion;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

/** Master spec H.2: she never walks near a creature she is afraid of, and never through one. */
public class KeepAwayTest
{
    private static final RoutePlanner.Collision OPEN = new RoutePlanner.Collision()
    {
        @Override public boolean isLegal(int x, int y) { return x >= 0 && y >= 0 && x <= 40 && y <= 40; }
        @Override public boolean canTravel(int x, int y, int dx, int dy) { return isLegal(x + dx, y + dy); }
    };

    private static RoutePlanner.Goal tile(int goalX, int goalY)
    {
        return new RoutePlanner.Goal()
        {
            @Override public double score(int x, int y, int steps) { return x == goalX && y == goalY ? 1 : -1; }
            @Override public int distance(int x, int y) { return MotionMath.distance(x, y, goalX, goalY); }
        };
    }

    @Test public void theGroundRoundABeastIsThreeTilesAndRoundARatOne()
    {
        KeepAway bear = new KeepAway.Builder().add(20, 20, 1, KeepAway.BEAST_RADIUS).build();
        assertTrue(bear.inside(20, 20));
        assertTrue(bear.inside(22, 18));
        assertTrue(bear.inside(23, 20));
        assertFalse(bear.inside(24, 20));
        assertFalse(bear.inside(20, 16));
        KeepAway rat = new KeepAway.Builder().add(20, 20, 1, KeepAway.RAT_RADIUS).build();
        assertTrue(rat.inside(21, 21));
        assertFalse(rat.inside(22, 20));
        assertTrue(KeepAway.NONE.isEmpty());
        assertFalse(KeepAway.NONE.inside(20, 20));
    }

    @Test public void aLargeCreatureIsMeasuredFromEveryTileItStandsOn()
    {
        KeepAway hound = new KeepAway.Builder().add(20, 20, 2, KeepAway.BEAST_RADIUS).build();
        assertTrue(hound.inside(24, 24));
        assertFalse(hound.inside(25, 21));
        assertTrue(hound.inside(17, 20));
        assertFalse(hound.inside(16, 20));
    }

    @Test public void sheMayNotStepInButMayAlwaysStepFurtherOut()
    {
        KeepAway bear = new KeepAway.Builder().add(20, 20, 1, KeepAway.BEAST_RADIUS).build();
        assertFalse(bear.allowsStep(24, 20, 23, 20));      // from outside to inside
        assertFalse(bear.allowsStep(23, 20, 23, 21));      // along the inside, no farther away
        assertFalse(bear.allowsStep(23, 20, 22, 20));      // towards it
        assertTrue(bear.allowsStep(22, 20, 23, 20));       // away, still inside
        assertTrue(bear.allowsStep(23, 20, 24, 20));       // away and out
        assertTrue(bear.allowsStep(20, 20, 21, 21));       // off the very tile it stands on
        assertTrue(bear.allowsStep(24, 20, 24, 21));       // round the outside
    }

    @Test public void aRouteGoesRoundTheBeastAndNeverNearerThanFourTiles()
    {
        KeepAway bear = new KeepAway.Builder().add(20, 20, 1, KeepAway.BEAST_RADIUS).build();
        RoutePlanner.Node start = new RoutePlanner.Node(16, 20);
        RoutePlanner.Result direct = new RoutePlanner().plan(OPEN, start, tile(24, 20));
        assertEquals(8, direct.steps.size());              // without the rule she would walk straight through it
        RoutePlanner.Result round = new RoutePlanner().plan(bear.over(OPEN), start, bear.over(tile(24, 20)));
        assertEquals(RoutePlanner.Status.ROUTE, round.status);
        assertEquals("Six steps longer than the straight way", 14, round.steps.size());
        for (RoutePlanner.Node step : round.steps)
        {
            assertTrue(MotionMath.distance(step.x, step.y, 20, 20) >= 4);
        }
        assertEquals(new RoutePlanner.Node(24, 20), round.steps.get(round.steps.size() - 1));
        assertEquals(-1, bear.firstRefused(start, round.steps));
        assertTrue(bear.firstRefused(start, direct.steps) >= 0);
    }

    @Test public void aTileBesideTheBeastIsNeverChosenSoSheStopsShortOfIt()
    {
        KeepAway bear = new KeepAway.Builder().add(20, 20, 1, KeepAway.BEAST_RADIUS).build();
        // He stands beside the bear; the only place asked for is the tile between them.
        RoutePlanner.Result result = new RoutePlanner().plan(bear.over(OPEN), new RoutePlanner.Node(14, 20), bear.over(tile(21, 20)));
        assertEquals(RoutePlanner.Status.FRONTIER, result.status);
        RoutePlanner.Node last = result.steps.get(result.steps.size() - 1);
        assertEquals(4, MotionMath.distance(last.x, last.y, 20, 20));
        for (RoutePlanner.Node step : result.steps) { assertFalse(bear.inside(step.x, step.y)); }
    }

    @Test public void whenOneComesToHerTheOnlyWayIsOut()
    {
        KeepAway bear = new KeepAway.Builder().add(20, 20, 1, KeepAway.BEAST_RADIUS).build();
        RoutePlanner.Goal anywhereClear = new RoutePlanner.Goal()
        {
            @Override public double score(int x, int y, int steps) { return 1d / (1 + steps); }
            @Override public int distance(int x, int y) { return 0; }
        };
        RoutePlanner.Result result = new RoutePlanner().plan(bear.over(OPEN), new RoutePlanner.Node(21, 20), bear.over(anywhereClear));
        assertEquals(RoutePlanner.Status.ROUTE, result.status);
        assertEquals(3, result.steps.size());
        int before = 1;
        for (RoutePlanner.Node step : result.steps)
        {
            int now = MotionMath.distance(step.x, step.y, 20, 20);
            assertTrue(now > before);
            before = now;
        }
        assertEquals(4, before);
    }

    @Test public void aRouteAlreadyChosenIsRefusedFromTheStepABeastHasWalkedOnto()
    {
        KeepAway bear = new KeepAway.Builder().add(20, 20, 1, KeepAway.BEAST_RADIUS).build();
        List<RoutePlanner.Node> steps = new ArrayList<>(Arrays.asList(new RoutePlanner.Node(15, 20), new RoutePlanner.Node(16, 20),
            new RoutePlanner.Node(17, 20), new RoutePlanner.Node(18, 20), new RoutePlanner.Node(19, 20)));
        assertEquals(2, bear.firstRefused(new RoutePlanner.Node(14, 20), steps));
        assertEquals(-1, KeepAway.NONE.firstRefused(new RoutePlanner.Node(14, 20), steps));
    }

    @Test public void givingWayThreeTimesLeavesOnlyTheTilesItStandsOn()
    {
        KeepAway squeezed = new KeepAway.Builder().add(20, 20, 1, KeepAway.BEAST_RADIUS - KeepAway.MAX_RELAX).build();
        assertTrue(squeezed.inside(20, 20));
        assertFalse(squeezed.inside(21, 20));
        assertTrue(squeezed.allowsStep(19, 20, 21, 21));
        assertFalse(squeezed.allowsStep(19, 20, 20, 20));
        KeepAway ratSqueezed = new KeepAway.Builder().add(20, 20, 1, KeepAway.RAT_RADIUS - KeepAway.MAX_RELAX).build();
        assertTrue(ratSqueezed.inside(20, 20));
        assertFalse(ratSqueezed.inside(21, 20));
    }
}

package com.malfoid.motion;

import org.junit.Test;
import static org.junit.Assert.*;

public class MotionRecorderTest
{
    @Test public void onlyCompletedOwnedEdgesCanProduceAnImmutableExactArrival()
    {
        MotionRecorder recorder = new MotionRecorder();
        plan(recorder, MotionObservation.Purpose.CATCHUP, 1, 3, false, route(3, false));
        recorder.arrive(2, 3203, 3200, 3, true);
        assertNull(recorder.completion());
        recorder.segmentStarted();
        recorder.completedEdge(2, 3200, 3200, 3201, 3200, true);
        recorder.completedEdge(2, 3201, 3200, 3202, 3200, true);
        recorder.completedEdge(3, 3202, 3200, 3203, 3200, false);
        recorder.arrive(3, 3202, 3200, 3, true);
        assertNull(recorder.completion());
        recorder.arrive(3, 3203, 3200, 3, true);
        MotionObservation receipt = recorder.completion();
        assertEquals(MotionObservation.Status.ARRIVED, receipt.status);
        assertEquals(3, receipt.completedTick);
        assertEquals(3, receipt.completedEdges);
        assertEquals(2, receipt.completedRunEdges);
        assertEquals(3, receipt.lastCompletedEdgeTick);
        assertTrue(receipt.ordinary);
        plan(recorder, MotionObservation.Purpose.ROAM, 4, 2, false, route(2, false));
        assertNotEquals(receipt.requestId, recorder.current().requestId);
        assertSame(receipt, recorder.completion());
        assertEquals(MotionObservation.Status.ARRIVED, receipt.status);
    }

    @Test public void aFrontierNeverBecomesAnArrival()
    {
        MotionRecorder recorder = new MotionRecorder();
        RoutePlanner.Result result = route(40, false);
        assertEquals(RoutePlanner.Status.FRONTIER, result.status);
        plan(recorder, MotionObservation.Purpose.CATCHUP, 1, 12, false, result);
        recorder.segmentStarted();
        recorder.completedEdge(2, 3200, 3200, 3212, 3200, true);
        recorder.arrive(2, 3212, 3200, 3, true);
        assertFalse(recorder.current().legalGoal);
        assertNull(recorder.completion());
    }

    @Test public void physicalBlockAndActualChangedEdgeRemainBoundedAndKeepTheFixedGoal()
    {
        MotionRecorder recorder = new MotionRecorder();
        plan(recorder, MotionObservation.Purpose.ROAM, 1, 3, false, route(3, false));
        long id = recorder.current().requestId;
        recorder.blocked(2, 3200, 3200, 3201, 3200);
        plan(recorder, MotionObservation.Purpose.ROAM, 3, 3, false, route(3, true));
        assertEquals(id, recorder.current().requestId);
        assertTrue(recorder.current().fixedGoal);
        assertTrue(recorder.current().physicalBlock);
        assertTrue(recorder.current().previouslyLegalEdge);
        assertFalse(recorder.current().changedEdgeAfterBlock);
        recorder.segmentStarted();
        recorder.completedEdge(4, 3200, 3200, 3201, 3199, false);
        assertTrue(recorder.current().changedEdgeAfterBlock);
        recorder.arrive(5, 3203, 3200, 3, true);
        assertTrue(recorder.completion().changedEdgeAfterBlock);
        recorder.commit(22);
        assertFalse(recorder.current().physicalBlock);
        assertEquals(-1, recorder.current().blockedTick);
    }

    @Test public void aReplacementCannotClaimAnAlreadyCommittedEdgeAndResetDropsReceipts()
    {
        MotionRecorder recorder = new MotionRecorder();
        plan(recorder, MotionObservation.Purpose.CATCHUP, 1, 3, false, route(3, false));
        recorder.segmentStarted();
        recorder.cancel(MotionObservation.Status.INVALIDATED);
        plan(recorder, MotionObservation.Purpose.ROAM, 2, 2, true, route(2, false));
        recorder.completedEdge(3, 3200, 3200, 3201, 3200, true);
        assertEquals(0, recorder.current().completedEdges);
        assertFalse(recorder.current().known);
        recorder.clear();
        assertNull(recorder.current());
        assertNull(recorder.completion());
    }

    @Test public void countersCapAtTwentyFourAndFurtherTravelBecomesUnknown()
    {
        MotionRecorder recorder = new MotionRecorder();
        plan(recorder, MotionObservation.Purpose.CATCHUP, 1, 3, false, route(3, false));
        recorder.segmentStarted();
        for (int i = 0; i < 25; i++) recorder.completedEdge(2, 3200 + i, 3200, 3201 + i, 3200, true);
        assertEquals(24, recorder.current().completedEdges);
        assertEquals(24, recorder.current().completedRunEdges);
        assertFalse(recorder.current().known);
        recorder.arrive(2, 3203, 3200, 3, true);
        assertNull(recorder.recentCompletion(recorder.current().requestId, 2));
    }

    @Test public void genuineRecentCompletionsAreBoundedByCountAndAgeAndNeverRebuiltFromInvalidation()
    {
        MotionRecorder recorder = new MotionRecorder();
        MotionObservation first = null;
        for (int tick = 1; tick <= 25; tick++)
        {
            plan(recorder, MotionObservation.Purpose.CATCHUP, tick, 1, false, route(1, false));
            recorder.segmentStarted();
            recorder.completedEdge(tick, 3200, 3200, 3201, 3200, true);
            recorder.arrive(tick, 3201, 3200, 3, true);
            if (tick == 1) first = recorder.completion();
        }
        assertNull(recorder.recentCompletion(first.requestId, 25));
        MotionObservation last = recorder.completion();
        assertSame(last, recorder.recentCompletion(last.requestId, 25));
        recorder.cancel(MotionObservation.Status.INVALIDATED);
        assertEquals(MotionObservation.Status.INVALIDATED, recorder.current().status);
        assertSame(last, recorder.recentCompletion(last.requestId, 25));
        recorder.clearRecentCompletions();
        assertNull(recorder.recentCompletion(last.requestId, 25));
        assertSame(last, recorder.completion());
        recorder.clear();
        assertNull(recorder.completion());
    }

    @Test public void authoredOtherRoutesAreNeverEligibleForOrdinaryAdmission()
    {
        MotionRecorder recorder = new MotionRecorder();
        plan(recorder, MotionObservation.Purpose.OTHER, 1, 1, false, route(1, false));
        recorder.segmentStarted();
        recorder.completedEdge(2, 3200, 3200, 3201, 3200, false);
        recorder.arrive(2, 3201, 3200, 3, true);
        assertNotNull(recorder.completion());
        assertNull(recorder.recentCompletion(recorder.completion().requestId, 2));
    }

    @Test public void anEmptyAtGoalDecisionCannotRearmAnInvalidatedArrival()
    {
        MotionRecorder recorder = new MotionRecorder();
        plan(recorder, MotionObservation.Purpose.CATCHUP, 1, 1, false, route(1, false));
        recorder.segmentStarted();
        recorder.completedEdge(2, 3200, 3200, 3201, 3200, true);
        recorder.arrive(2, 3201, 3200, 3, true);
        MotionObservation original = recorder.completion();
        recorder.cancel(MotionObservation.Status.INVALIDATED);
        recorder.clearRecentCompletions();
        recorder.plan(MotionObservation.Purpose.CATCHUP, 0, 3, 7, -1, 0, 3201, 3200, 3201, 3200, 3,
            false, route(0, false));
        assertEquals(MotionObservation.Status.INVALIDATED, recorder.current().status);
        recorder.arrive(4, 3201, 3200, 3, true);
        assertSame(original, recorder.completion());
        assertEquals(2, recorder.completion().completedTick);
        assertNull(recorder.recentCompletion(original.requestId, 4));
    }

    @Test public void aKeyedSourceIsImmutableAndCannotReuseAnotherSourcesRequestOrCommittedEdge()
    {
        MotionRecorder recorder = new MotionRecorder();
        recorder.plan(MotionObservation.Purpose.OTHER, 700L, 2, 1, 7, -1, 0,
            3200, 3200, 3203, 3200, 12, false, route(3, false));
        MotionObservation inspection = recorder.current();
        assertEquals(700, inspection.sourceCandidateId);
        assertFalse(inspection.ordinary);
        recorder.segmentStarted();
        recorder.cancel(MotionObservation.Status.INVALIDATED);
        recorder.plan(MotionObservation.Purpose.APPROACH_PLAYER, 700L, 1, 2, 7, -1, 0,
            3200, 3200, 3202, 3200, 8, true, route(2, false));
        MotionObservation returning = recorder.current();
        assertEquals(700, returning.sourceCandidateId);
        assertTrue(returning.ordinary);
        assertNotEquals(inspection.requestId, returning.requestId);
        recorder.completedEdge(3, 3200, 3200, 3201, 3200, false);
        assertEquals(0, recorder.current().completedEdges);
        recorder.segmentStarted();
        recorder.completedEdge(3, 3201, 3200, 3202, 3200, false);
        recorder.arrive(3, 3202, 3200, 3, true);
        assertEquals(700, recorder.completion().sourceCandidateId);
        assertEquals(1, recorder.completion().completedEdges);
        assertEquals(MotionObservation.Status.MOVING, returning.status);
        recorder.plan(MotionObservation.Purpose.APPROACH_PLAYER, 701L, 1, 4, 7, -1, 0,
            3200, 3200, 3202, 3200, 8, false, route(2, false));
        assertNotEquals(returning.requestId, recorder.current().requestId);
        assertEquals(701, recorder.current().sourceCandidateId);
        long otherSourceRequest = recorder.current().requestId;
        recorder.plan(MotionObservation.Purpose.APPROACH_PLAYER, 702L, 1, 5, 7, -1, 0,
            3200, 3200, 3202, 3200, 8, false, route(2, false));
        assertNotEquals(otherSourceRequest, recorder.current().requestId);
        assertEquals(702, recorder.current().sourceCandidateId);
        plan(recorder, MotionObservation.Purpose.OTHER, 5, 2, false, route(2, false));
        assertEquals(-1, recorder.current().sourceCandidateId);
    }

    private static void plan(MotionRecorder recorder, MotionObservation.Purpose purpose, long tick,
        int goal, boolean oldSegment, RoutePlanner.Result result)
    {
        recorder.plan(purpose, 0, tick, 7, -1, 0, 3200, 3200, 3200 + goal, 3200, 12, oldSegment, result);
    }

    private static RoutePlanner.Result route(int goal, boolean blocked)
    {
        return new RoutePlanner().plan(new RoutePlanner.Collision()
        {
            public boolean isLegal(int x, int y) { return !blocked || x != 1 || y != 0; }
            public boolean canTravel(int x, int y, int dx, int dy) { return isLegal(x + dx, y + dy); }
        }, new RoutePlanner.Node(0, 0), new RoutePlanner.Goal()
        {
            public double score(int x, int y, int steps) { return x == goal && y == 0 ? 1 : -1; }
            public int distance(int x, int y) { return MotionMath.distance(x, y, goal, 0); }
        });
    }
}

package com.malfoid.motion;

import org.junit.Test;
import static org.junit.Assert.*;
import static com.malfoid.motion.WholeBoundsVisibility.Visibility.*;

public class RecoveryPolicyTest
{
    @Test public void threeIneffectivePlansAndFiveOffScreenCommitsAreBothNeededAtTwelve()
    {
        RecoveryPolicy policy = new RecoveryPolicy();
        for (int tick = 1; tick <= 3; tick++) policy.recordPlan(tick, true, false);
        for (int tick = 1; tick <= 4; tick++)
        {
            policy.commit(12, OFF_SCREEN, false, true, true, true);
            assertFalse(policy.offScreenEligible(tick, 12));
        }
        policy.commit(12, OFF_SCREEN, false, true, true, true);
        assertTrue(policy.offScreenEligible(5, 12));
        assertFalse(policy.offScreenEligible(5, 11));
        assertFalse(policy.confirmOrigin(VISIBLE, false));
        assertEquals(0, policy.getOffScreenTicks());
        assertFalse(policy.offScreenEligible(6, 12));
    }

    @Test public void equalSpeedLargeGapCanRecoverAfterFiveKnownOffScreenTicks()
    {
        RecoveryPolicy policy = new RecoveryPolicy();
        for (int tick = 1; tick <= 5; tick++) policy.commit(16, OFF_SCREEN, true, false, true, true);
        assertTrue(policy.offScreenEligible(5, 16));
        assertTrue(policy.confirmOrigin(OFF_SCREEN, false));
        policy.relocated(5);
        for (int tick = 6; tick <= 10; tick++) policy.commit(16, OFF_SCREEN, false, false, true, true);
        assertFalse(policy.offScreenEligible(64, 16));
        assertTrue(policy.offScreenEligible(65, 16));
    }

    @Test public void unknownOrVisibleOriginResetsTheOffScreenWitness()
    {
        RecoveryPolicy policy = new RecoveryPolicy();
        for (int tick = 0; tick < 5; tick++) policy.commit(16, OFF_SCREEN, false, false, true, true);
        assertTrue(policy.offScreenEligible(5, 16));
        policy.commit(16, UNKNOWN, false, false, true, true);
        assertFalse(policy.offScreenEligible(6, 16));
        for (int tick = 0; tick < 4; tick++) policy.commit(16, OFF_SCREEN, false, false, true, true);
        assertFalse(policy.offScreenEligible(10, 16));
        policy.commit(16, VISIBLE, false, false, true, true);
        assertEquals(0, policy.getOffScreenTicks());
    }

    @Test public void p15RequiresFiftyConfirmedBlockedTicksWithoutProgress()
    {
        RecoveryPolicy policy = new RecoveryPolicy();
        for (int tick = 1; tick < 50; tick++) policy.commit(4, VISIBLE, false, true, true, true);
        assertFalse(policy.stuckEligible(49));
        policy.commit(4, VISIBLE, false, true, true, true);
        assertTrue(policy.stuckEligible(50));
        assertTrue(policy.confirmOrigin(VISIBLE, true));
        policy.commit(4, VISIBLE, true, true, true, true);
        assertFalse(policy.stuckEligible(51));
        for (int tick = 0; tick < 100; tick++) policy.commit(4, VISIBLE, false, false, true, true);
        assertFalse(policy.stuckEligible(200));
        for (int tick = 0; tick < 49; tick++) policy.commit(4, VISIBLE, false, true, true, true);
        policy.recordPlan(250, false, true);
        assertEquals(0, policy.getBlockedTicks());
        policy.commit(4, VISIBLE, false, true, true, false);
        assertEquals(0, policy.getBlockedTicks());
    }

    @Test public void ineffectiveSearchesBackOffButLegalProgressAndMeaningfulChangeResume()
    {
        RecoveryPolicy policy = new RecoveryPolicy();
        for (int tick = 1; tick <= 3; tick++) policy.recordPlan(tick, true, false);
        assertFalse(policy.mayPlan(7, true));
        assertTrue(policy.mayPlan(8, true));
        assertFalse(policy.mayPlan(8, false));
        assertTrue(policy.mayPlan(33, false));
        policy.commit(16, OFF_SCREEN, true, false, true, true);
        assertTrue(policy.mayPlan(4, false));
        policy.recordPlan(4, false, true);
        assertEquals(0, policy.getIneffectivePlans());
    }
}

