package com.malfoid.motion;

import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.*;

public class RouteMotionTest
{
    private static final RoutePlanner.Collision OPEN = new RoutePlanner.Collision()
    {
        public boolean isLegal(int x, int y) { return true; }
        public boolean canTravel(int x, int y, int dx, int dy) { return true; }
    };

    @Test public void walkUsesThirtyDistinctCyclesAndDoesNotDoubleAdvance()
    {
        RouteMotion motion = new RouteMotion();
        motion.place(10, 10, 0);
        motion.setRoute(Arrays.asList(new RoutePlanner.Node(11, 10)), false);
        for (int cycle = 1; cycle < 30; cycle++)
        {
            motion.advance(cycle, OPEN);
            double x = motion.getX();
            motion.advance(cycle, OPEN);
            assertEquals(x, motion.getX(), 0);
            assertEquals(new RoutePlanner.Node(10, 10), motion.completedNode());
        }
        motion.advance(30, OPEN);
        assertEquals(new RoutePlanner.Node(11, 10), motion.completedNode());
        assertFalse(motion.isMoving());
        assertEquals(11 * 128 + 64, motion.getX(), 0);
        motion.advance(31, OPEN);
        assertEquals(11 * 128 + 64, motion.getX(), 0);
    }

    @Test public void runFollowsTwoSegmentsInsteadOfCuttingTheCorner()
    {
        RouteMotion motion = new RouteMotion();
        motion.place(10, 10, 0);
        motion.setRoute(Arrays.asList(new RoutePlanner.Node(11, 10), new RoutePlanner.Node(11, 11)), true);
        for (int cycle = 1; cycle <= 15; cycle++)
        {
            motion.advance(cycle, OPEN);
            assertEquals(10 * 128 + 64, motion.getY(), 0);
        }
        assertEquals(new RoutePlanner.Node(11, 10), motion.completedNode());
        for (int cycle = 16; cycle <= 30; cycle++)
        {
            motion.advance(cycle, OPEN);
            assertEquals(11 * 128 + 64, motion.getX(), 0);
        }
        assertEquals(new RoutePlanner.Node(11, 11), motion.completedNode());
    }

    @Test public void secondRunEdgeIsRevalidatedAfterTheFirstCompletes()
    {
        RouteMotion motion = new RouteMotion();
        motion.place(0, 0, 0);
        motion.setRoute(Arrays.asList(new RoutePlanner.Node(1, 0), new RoutePlanner.Node(2, 0)), true);
        for (int cycle = 1; cycle <= 15; cycle++) motion.advance(cycle, OPEN);
        RoutePlanner.Collision changed = new RoutePlanner.Collision()
        {
            public boolean isLegal(int x, int y) { return x != 2; }
            public boolean canTravel(int x, int y, int dx, int dy) { return x + dx != 2; }
        };
        motion.advance(16, changed);
        assertTrue(motion.isBlocked());
        assertFalse(motion.isMoving());
        assertEquals(new RoutePlanner.Node(1, 0), motion.completedNode());
    }

    @Test public void replanningAndStoppingPreserveACommittedShortSegment()
    {
        RouteMotion motion = new RouteMotion();
        motion.place(0, 0, 0);
        motion.setRoute(Arrays.asList(new RoutePlanner.Node(1, 0), new RoutePlanner.Node(2, 0)), false);
        motion.advance(1, OPEN);
        motion.stop();
        for (int cycle = 2; cycle <= 30; cycle++) motion.advance(cycle, OPEN);
        assertEquals(new RoutePlanner.Node(1, 0), motion.completedNode());
        assertFalse(motion.isMoving());
        motion.advance(1000, OPEN);
        assertEquals(192, motion.getX(), 0);
    }

    @Test public void stallAdvancesOnlyOneValidatedCycle()
    {
        RouteMotion motion = new RouteMotion();
        motion.place(0, 0, 0);
        motion.setRoute(Arrays.asList(new RoutePlanner.Node(1, 0)), false);
        motion.advance(1000, OPEN);
        assertEquals(64 + 128d / 30, motion.getX(), .000001);
        assertEquals(new RoutePlanner.Node(0, 0), motion.completedNode());
    }

    @Test public void runBurstDemotionFinishesOnlyTheCommittedRunEdgeBeforeWalking()
    {
        RouteMotion motion = new RouteMotion();
        motion.place(0, 0, 0);
        motion.setRoute(Arrays.asList(new RoutePlanner.Node(1, 0), new RoutePlanner.Node(2, 0)), true);
        for (int cycle = 1; cycle <= 7; cycle++) motion.advance(cycle, OPEN);
        motion.setRunning(false);
        assertTrue(motion.isRunning());
        for (int cycle = 8; cycle <= 15; cycle++) motion.advance(cycle, OPEN);
        assertEquals(new RoutePlanner.Node(1, 0), motion.completedNode());
        motion.advance(16, OPEN);
        assertFalse(motion.isRunning());
        for (int cycle = 17; cycle < 45; cycle++) motion.advance(cycle, OPEN);
        assertEquals(new RoutePlanner.Node(1, 0), motion.completedNode());
        motion.advance(45, OPEN);
        assertEquals(new RoutePlanner.Node(2, 0), motion.completedNode());
        assertFalse(motion.isMoving());
    }
}

package com.malfoid.motion;

import org.junit.Test;
import static org.junit.Assert.*;

public class RoutePlannerLimitObservationTest
{
    @Test public void actualBoundExhaustionKeepsItsRawBudgetStatusAndLimitFlag()
    {
        RoutePlanner.Result result = new RoutePlanner().plan(open(), new RoutePlanner.Node(50, 50), unsuitable());
        assertEquals(RoutePlanner.Status.BUDGET_EXHAUSTED, result.status);
        assertTrue(result.searchLimited);
        assertEquals(625, result.visited);
        assertTrue(result.steps.isEmpty());
    }

    @Test public void anActuallyClosedPocketIsBlockedWithoutAComputationalLimit()
    {
        RoutePlanner.Collision pocket = new RoutePlanner.Collision()
        {
            @Override public boolean isLegal(int x, int y) { return x >= 49 && x <= 51 && y >= 49 && y <= 51; }
            @Override public boolean canTravel(int x, int y, int dx, int dy) { return isLegal(x + dx, y + dy); }
        };
        RoutePlanner.Result result = new RoutePlanner().plan(pocket, new RoutePlanner.Node(50, 50), unsuitable());
        assertEquals(RoutePlanner.Status.BLOCKED, result.status);
        assertFalse(result.searchLimited);
        assertEquals(9, result.visited);
    }

    @Test public void aRealRouteCanAlsoHaveAnExpansionLimitWithoutBecomingABudgetFailure()
    {
        RoutePlanner.Goal goal = new RoutePlanner.Goal()
        {
            @Override public double score(int x, int y, int steps) { return x == 51 && y == 50 ? 1 : -1; }
            @Override public int distance(int x, int y) { return MotionMath.distance(x, y, 51, 50); }
        };
        RoutePlanner.Result result = new RoutePlanner().plan(open(), new RoutePlanner.Node(50, 50), goal);
        assertEquals(RoutePlanner.Status.ROUTE, result.status);
        assertTrue(result.searchLimited);
        assertEquals(1, result.steps.size());
        assertEquals(new RoutePlanner.Node(51, 50), result.steps.get(0));
    }

    @Test public void anUnavailableStartHasNeitherAnExpansionNorALimit()
    {
        RoutePlanner.Result result = new RoutePlanner().plan(null, new RoutePlanner.Node(50, 50), unsuitable());
        assertEquals(RoutePlanner.Status.SCENE_UNAVAILABLE, result.status);
        assertFalse(result.searchLimited);
        assertEquals(0, result.visited);
    }

    private static RoutePlanner.Collision open()
    {
        return new RoutePlanner.Collision()
        {
            @Override public boolean isLegal(int x, int y) { return true; }
            @Override public boolean canTravel(int x, int y, int dx, int dy) { return true; }
        };
    }

    private static RoutePlanner.Goal unsuitable()
    {
        return new RoutePlanner.Goal()
        {
            @Override public double score(int x, int y, int steps) { return -1; }
            @Override public int distance(int x, int y) { return 1; }
        };
    }
}

package com.malfoid.motion;

import org.junit.Test;
import static org.junit.Assert.*;

public class RoutePlannerTest
{
    private static RoutePlanner.Goal goal(int gx, int gy)
    {
        return new RoutePlanner.Goal()
        {
            public double score(int x, int y, int steps) { return x == gx && y == gy ? 1 : -1; }
            public int distance(int x, int y) { return MotionMath.distance(x, y, gx, gy); }
        };
    }

    @Test public void openExpansionHasAnExactBoundAndDeterministicAdjacentPath()
    {
        RoutePlanner planner = new RoutePlanner();
        RoutePlanner.Collision open = new RoutePlanner.Collision()
        {
            public boolean isLegal(int x, int y) { return true; }
            public boolean canTravel(int x, int y, int dx, int dy) { return true; }
        };
        RoutePlanner.Result first = planner.plan(open, new RoutePlanner.Node(0, 0), goal(12, 12));
        RoutePlanner.Result second = planner.plan(open, new RoutePlanner.Node(0, 0), goal(12, 12));
        assertEquals(625, first.visited);
        assertEquals(RoutePlanner.Status.ROUTE, first.status);
        assertEquals(first.steps, second.steps);
        assertEquals(12, first.steps.size());
        RoutePlanner.Node prior = new RoutePlanner.Node(0, 0);
        for (RoutePlanner.Node node : first.steps)
        {
            assertEquals(1, MotionMath.distance(node.x, node.y, prior.x, prior.y));
            prior = node;
        }
    }

    @Test public void unreachableAndOutOfWindowGoalsNeverClaimArrival()
    {
        RoutePlanner.Collision wall = new RoutePlanner.Collision()
        {
            public boolean isLegal(int x, int y) { return x < 2; }
            public boolean canTravel(int x, int y, int dx, int dy) { return x + dx < 2; }
        };
        RoutePlanner.Result blocked = new RoutePlanner().plan(wall, new RoutePlanner.Node(0, 0), goal(3, 0));
        assertEquals(RoutePlanner.Status.FRONTIER, blocked.status);
        assertTrue(blocked.steps.size() <= 24);
        assertTrue(blocked.visited <= 625);
        RoutePlanner.Result far = new RoutePlanner().plan(wall, new RoutePlanner.Node(0, 0), goal(100, 100));
        assertNotEquals(RoutePlanner.Status.AT_GOAL, far.status);
        assertNotEquals(RoutePlanner.Status.ROUTE, far.status);
    }

    @Test public void missingOrFullyEnclosedCollisionReturnsNoRoute()
    {
        RoutePlanner planner = new RoutePlanner();
        assertEquals(RoutePlanner.Status.SCENE_UNAVAILABLE, planner.plan(null, new RoutePlanner.Node(0, 0), goal(1, 1)).status);
        RoutePlanner.Collision closed = new RoutePlanner.Collision()
        {
            public boolean isLegal(int x, int y) { return x == 0 && y == 0; }
            public boolean canTravel(int x, int y, int dx, int dy) { return false; }
        };
        RoutePlanner.Result result = planner.plan(closed, new RoutePlanner.Node(0, 0), goal(1, 1));
        assertEquals(RoutePlanner.Status.BLOCKED, result.status);
        assertEquals(1, result.visited);
        assertTrue(result.steps.isEmpty());
    }

    @Test public void longWallOutsideTheSearchWindowDoesNotProvePhysicalBlockage()
    {
        RoutePlanner.Collision longWall = new RoutePlanner.Collision()
        {
            public boolean isLegal(int x, int y) { return x != 1 || y > 12; }
            public boolean canTravel(int x, int y, int dx, int dy)
            {
                return isLegal(x + dx, y + dy) && (dx == 0 || dy == 0
                    || isLegal(x + dx, y) && isLegal(x, y + dy));
            }
        };
        RoutePlanner.Result result = new RoutePlanner().plan(longWall, new RoutePlanner.Node(0, 0), goal(3, 0));
        assertEquals(RoutePlanner.Status.BUDGET_EXHAUSTED, result.status);
        assertTrue(result.steps.isEmpty());
        assertTrue(result.visited <= 625);
    }

    @Test public void bearingsAndTurnQuantizationAgreeAtTheWrap()
    {
        assertEquals(0, MotionMath.bearing(0, -1));
        assertEquals(512, MotionMath.bearing(-1, 0));
        assertEquals(1024, MotionMath.bearing(0, 1));
        assertEquals(1536, MotionMath.bearing(1, 0));
        assertEquals(16, MotionMath.turn(2032, 48));
        assertEquals(2032, MotionMath.turn(16, 1968));
        boolean[] headings = new boolean[2048];
        for (int orientation = 0; orientation < 2048; orientation++)
        {
            int applied = MotionMath.quantize(orientation);
            headings[applied] = true;
            assertTrue(Math.abs(((applied - orientation + 1024) & 2047) - 1024) <= 16);
        }
        int distinct = 0;
        for (boolean heading : headings) if (heading) distinct++;
        assertEquals(64, distinct);
        assertEquals(0, MotionMath.cameraBearing(0));
        assertEquals(1536, MotionMath.cameraBearing(512));
        assertEquals(1024, MotionMath.cameraBearing(1024));
        assertEquals(512, MotionMath.cameraBearing(1536));
    }

    @Test public void expensiveCourtesyOnlyRefinesEightReachableCandidates()
    {
        int[] refined = {0};
        RoutePlanner.Collision open = new RoutePlanner.Collision()
        {
            public boolean isLegal(int x, int y) { return true; }
            public boolean canTravel(int x, int y, int dx, int dy) { return true; }
        };
        RoutePlanner.Goal scored = new RoutePlanner.Goal()
        {
            public double score(int x, int y, int steps) { return 1d / (steps + 1); }
            public int distance(int x, int y) { return 0; }
            public double refineScore(int x, int y, int steps, double score)
            {
                refined[0]++;
                return score;
            }
        };
        RoutePlanner.Result result = new RoutePlanner().plan(open, new RoutePlanner.Node(0, 0), scored);
        assertEquals(RoutePlanner.Status.AT_GOAL, result.status);
        assertEquals(8, refined[0]);
    }

    @Test public void combatFootprintsIncludeEveryAdjacentTile()
    {
        for (int size : new int[]{1, 3})
        {
            int minX = 10, minY = 10, maxX = minX + size - 1, maxY = minY + size - 1;
            assertEquals(0, MotionMath.footprintDistance(minX, minY, minX, minY, maxX, maxY));
            assertEquals(1, MotionMath.footprintDistance(minX - 1, minY - 1, minX, minY, maxX, maxY));
            assertEquals(1, MotionMath.footprintDistance(maxX + 1, maxY + 1, minX, minY, maxX, maxY));
            assertEquals(2, MotionMath.footprintDistance(maxX + 2, maxY + 1, minX, minY, maxX, maxY));
        }
    }
}

package com.malfoid.motion;

import net.runelite.api.CollisionData;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.WorldView;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class SceneCollisionTest
{
    private static WorldView view(int[][] flags)
    {
        WorldView view = mock(WorldView.class);
        CollisionData data = mock(CollisionData.class);
        when(view.getId()).thenReturn(0);
        when(view.getBaseX()).thenReturn(3200);
        when(view.getBaseY()).thenReturn(3200);
        when(view.getSizeX()).thenReturn(8);
        when(view.getSizeY()).thenReturn(8);
        when(view.getPlane()).thenReturn(0);
        when(data.getFlags()).thenReturn(flags);
        when(view.getCollisionMaps()).thenReturn(new CollisionData[]{data});
        return view;
    }

    @Test public void cardinalAndDiagonalWallsUseMovementMasks()
    {
        int[][] flags = new int[8][8];
        SceneCollision collision = new SceneCollision(view(flags), 0, -1, -1);
        int[] dx = {-1, 1, 0, 0, -1, -1, 1, 1};
        int[] dy = {0, 0, -1, 1, -1, 1, -1, 1};
        int[] masks = {CollisionDataFlag.BLOCK_MOVEMENT_EAST, CollisionDataFlag.BLOCK_MOVEMENT_WEST,
            CollisionDataFlag.BLOCK_MOVEMENT_NORTH, CollisionDataFlag.BLOCK_MOVEMENT_SOUTH,
            CollisionDataFlag.BLOCK_MOVEMENT_NORTH_EAST, CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_EAST,
            CollisionDataFlag.BLOCK_MOVEMENT_NORTH_WEST, CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_WEST};
        for (int direction = 0; direction < dx.length; direction++)
        {
            assertTrue(collision.canTravel(3, 3, dx[direction], dy[direction]));
            flags[3 + dx[direction]][3 + dy[direction]] = masks[direction];
            assertFalse(collision.canTravel(3, 3, dx[direction], dy[direction]));
            flags[3 + dx[direction]][3 + dy[direction]] = 0;
        }
    }

    @Test public void everyDiagonalSideWallIsRechecked()
    {
        int[][] flags = new int[8][8];
        SceneCollision collision = new SceneCollision(view(flags), 0, -1, -1);
        for (int dx : new int[]{-1, 1})
        {
            for (int dy : new int[]{-1, 1})
            {
                flags[3 + dx][3] = dx < 0 ? CollisionDataFlag.BLOCK_MOVEMENT_EAST : CollisionDataFlag.BLOCK_MOVEMENT_WEST;
                assertFalse(collision.canTravel(3, 3, dx, dy));
                flags[3 + dx][3] = 0;
                flags[3][3 + dy] = dy < 0 ? CollisionDataFlag.BLOCK_MOVEMENT_NORTH : CollisionDataFlag.BLOCK_MOVEMENT_SOUTH;
                assertFalse(collision.canTravel(3, 3, dx, dy));
                flags[3][3 + dy] = 0;
                assertTrue(collision.canTravel(3, 3, dx, dy));
            }
        }
    }

    @Test public void fullTilesAndThePlayerCannotBeChosen()
    {
        int[][] flags = new int[8][8];
        SceneCollision collision = new SceneCollision(view(flags), 0, 4, 3);
        assertFalse(collision.isLegal(4, 3));
        assertFalse(collision.canTravel(3, 3, 1, 0));
        flags[3][4] = CollisionDataFlag.BLOCK_MOVEMENT_FULL;
        assertFalse(collision.isLegal(3, 4));
        assertFalse(collision.canTravel(3, 3, 0, 1));
        assertFalse(collision.canTravel(3, 3, 0, 0));
    }

    @Test public void shortNullAndMissingPlaneDataNeverReachTheNativeHelper()
    {
        int[][] flags = new int[5][];
        flags[0] = new int[1];
        flags[3] = new int[8];
        flags[4] = new int[1];
        SceneCollision collision = new SceneCollision(view(flags), 0, -1, -1);
        assertFalse(collision.canTravel(3, 3, 1, 1));
        assertFalse(collision.canTravel(3, 3, -1, 0));
        assertFalse(collision.canTravel(0, 0, -1, 0));
        assertFalse(new SceneCollision(view(flags), 2, -1, -1).isAvailable());
        assertFalse(new SceneCollision(null, 0, -1, -1).contains(0, 0));
    }

    @Test public void aDistantMissingCellIsUnknownAndCannotBecomePhysicalBlockage()
    {
        int[][] flags = new int[8][8];
        flags[7] = null;
        SceneCollision unknown = new SceneCollision(view(flags), 0, -1, -1);
        assertFalse(unknown.isAvailable());
        RoutePlanner.Goal goal = new RoutePlanner.Goal()
        {
            @Override public double score(int x, int y, int steps) { return x == 5 && y == 3 ? 1 : -1; }
            @Override public int distance(int x, int y) { return MotionMath.distance(x, y, 5, 3); }
        };
        assertEquals(RoutePlanner.Status.SCENE_UNAVAILABLE,
            new RoutePlanner().plan(unknown, new RoutePlanner.Node(3, 3), goal).status);
        flags[7] = new int[7];
        assertFalse(new SceneCollision(view(flags), 0, -1, -1).isAvailable());
        flags[7] = new int[8];
        for (int[] row : flags) java.util.Arrays.fill(row, CollisionDataFlag.BLOCK_MOVEMENT_FULL);
        flags[3][3] = 0;
        SceneCollision known = new SceneCollision(view(flags), 0, -1, -1);
        assertTrue(known.isAvailable());
        assertEquals(RoutePlanner.Status.BLOCKED,
            new RoutePlanner().plan(known, new RoutePlanner.Node(3, 3), goal).status);
    }
}

package com.malfoid.motion;

import org.junit.Test;
import static org.junit.Assert.*;
import static com.malfoid.motion.WholeBoundsVisibility.Visibility.*;

public class WholeBoundsVisibilityTest
{
    private static final WholeBoundsVisibility.Bounds CHARACTER = new WholeBoundsVisibility.Bounds(-30, -190, -20, 30, -1, 20);
    private static final WholeBoundsVisibility.Projector FLAT = (x, y, z, out) ->
    {
        out[0] = x; out[1] = z; out[2] = 100;
        return true;
    };

    @Test public void footOutsideWithHeadStillVisibleDoesNotQualify()
    {
        assertEquals(VISIBLE, WholeBoundsVisibility.classify(CHARACTER, 0, 0, 250, 0, FLAT, 0, 0, 300, 300, 100));
    }

    @Test public void unionPartlyEnteringTheViewportBlocksRecovery()
    {
        assertEquals(VISIBLE, WholeBoundsVisibility.classify(CHARACTER, 175, 0, 0, 0, FLAT, 0, 0, 300, 300, 100));
        assertEquals(OFF_SCREEN, WholeBoundsVisibility.classify(CHARACTER, 190, 0, 0, 0, FLAT, 0, 0, 300, 300, 100));
        assertEquals(VISIBLE, WholeBoundsVisibility.classify(CHARACTER, 190, 0, 0, 512, FLAT, 0, 0, 350, 300, 100));
    }

    @Test public void nearPlaneCrossingAndUnknownProjectionDefer()
    {
        WholeBoundsVisibility.Projector crossing = (x, y, z, out) ->
        {
            out[0] = x; out[1] = z; out[2] = 50 + y;
            return true;
        };
        assertEquals(UNKNOWN, WholeBoundsVisibility.classify(CHARACTER, 1000, 0, 0, 0, crossing, 0, 0, 300, 300, 100));
        WholeBoundsVisibility.Projector behind = (x, y, z, out) ->
        {
            out[0] = x; out[1] = z; out[2] = 49;
            return true;
        };
        assertEquals(OFF_SCREEN, WholeBoundsVisibility.classify(CHARACTER, 0, 0, 0, 0, behind, 0, 0, 300, 300, 100));
        WholeBoundsVisibility.Projector unknown = (x, y, z, out) ->
        {
            out[0] = Double.NaN; out[1] = 0; out[2] = 100;
            return true;
        };
        assertEquals(UNKNOWN, WholeBoundsVisibility.classify(CHARACTER, 1000, 0, 0, 0, unknown, 0, 0, 300, 300, 100));
        assertEquals(UNKNOWN, WholeBoundsVisibility.classify(CHARACTER, 0, 0, 0, 0, null, 0, 0, 300, 300, 100));
    }

    @Test public void unequalViewportOffsetsAndRoundingMarginAreHonoured()
    {
        assertEquals(VISIBLE, WholeBoundsVisibility.classify(CHARACTER, 183, 0, 0, 0, FLAT, 30, 70, 300, 300, 100));
        assertEquals(OFF_SCREEN, WholeBoundsVisibility.classify(CHARACTER, 190, 0, 0, 0, FLAT, 30, 70, 300, 300, 100));
        assertEquals(UNKNOWN, WholeBoundsVisibility.classify(CHARACTER, 190, 0, 0, 0, FLAT, 30, 70, 0, 300, 100));
    }
}

