	private static Replay equality()
	{
		Replay r = new Replay(0); r.frame.xp[Skill.CRAFTING.ordinal()] = 56770; r.frame.xp[Skill.SMITHING.ordinal()] = 56750;
		r.waitTicks(12); return r;
