			moving.startedTick = oldStart; moving.completedTick = moving.lastCompletedEdgeTick = -1; moving.status = Status.MOVING;
			r.frame.motion = moving.build(); r.next();
			if (interruption == 0) { r.frame.targetUnknown = true; }
